export default JSON.parse("{\"K01\":[\"بِالْوَاو وَفِي الْأَعْرَاف ﴿فكلا﴾ بِالْفَاءِ ﴿اسكن﴾ فِي الْآيَتَيْنِ لَيْسَ بِأَمْر بِالسُّكُونِ الَّذِي هُوَ ضد الْحَرَكَة وَإِنَّمَا الَّذِي فِي الْبَقَرَة من السّكُون الَّذِي مَعْنَاهُ الْإِقَامَة\",1,\"1:70\"],\"K02\":[\"قدم الشَّفَاعَة فِي هَذِه الْآيَة وَأخر الْعدْل وَقدم الْعدْل فِي الْآيَة الْأُخْرَى من هَذِه السُّورَة وَأخر الشَّفَاعَة وَإِنَّمَا قدم الشَّفَاعَة قطعا لطمع من زعم أَن آبَاءَهُم تشفع لَهُم\",1,\"1:71\"],\"K03\":[\"بِغَيْر وَاو هُنَا على الْبَدَل من ﴿يسومونكم﴾ وَفِي الْأَعْرَاف ﴿يقتلُون﴾ وَفِي إِبْرَاهِيم ﴿ويذبحون﴾ بِالْوَاو لِأَن مَا فِي هَذِه السُّورَة والأعراف من كَلَام الله تَعَالَى فَلم يرد تعداد المحن عَلَيْهِم\",1,\"1:72\"],\"K04\":[\"بِالْفَاءِ وَفِي الْأَعْرَاف بِالْوَاو لِأَن الدُّخُول سريع الِانْقِضَاء فيتبعه الْأكل وَفِي الْأَعْرَاف ﴿وَإِذ قيل لَهُم اسكنوا﴾ الْمَعْنى أقِيمُوا فِيهَا وَذَلِكَ ممتد فَذكر بِالْوَاو أَي اجْمَعُوا بَين الْأكل\",1,\"1:72\"],\"K05\":[\"فِي هَذِه السُّورَة وَفِي آل عمرَان ﴿وَيقْتلُونَ النَّبِيين بِغَيْر حق﴾ وفيهَا وَفِي النِّسَاء ﴿وقتلهم الْأَنْبِيَاء بِغَيْر حق﴾ لِأَن مَا فِي الْبَقَرَة إِشَارَة إِلَى الْحق الَّذِي أذن الله أَن تقتل النَّفس بِهِ\",1,\"1:74\"],\"K06\":[\"وَفِي آل عمرَان ﴿أَيَّامًا معدودات﴾ لِأَن الأَصْل فِي الْجمع إِذا كَانَ واحده مذكرا أَن يقْتَصر فِي الْوَصْف على التَّأْنِيث نَحْو قَوْله ﴿سرر مَرْفُوعَة وأكواب مَوْضُوعَة ونمارق مصفوفة وزرابي مبثوثة﴾:\",1,\"1:76\"],\"K07\":[\"فِي هَذِه السُّورَة وَفِي آل عمرَان ﴿علينا﴾ لِأَن ﴿إِلَى﴾ للانتهاء إِلَى الشَّيْء من أَي جِهَة كَانَت والكتب منتهية\",1,\"1:79\"],\"K08\":[\"فِي هَذِه السُّورَة وَفِي الْمَائِدَة ولقمان ﴿مَا وجدنَا﴾ لِأَن ألفيت يتَعَدَّى إِلَى مفعولين تَقول ألفيت زيدا قَائِما وألفيت عمرا على كَذَا وَوجدت يتَعَدَّى مرّة إِلَى مفعول وَاحِد تَقول وجدت الضَّالة\",1,\"1:80\"],\"K09\":[\"بالإظهار فِي هَذِه السُّورَة وَكَذَلِكَ فِي الْأَنْفَال وَفِي الْحَشْر بِالْإِدْغَامِ لِأَن الثَّانِي من المثلين إِذا تحرّك بحركة لَازِمَة وَجب إدغام الأول فِي الثَّانِي أَلا ترى أَنَّك تَقول ارْدُدْ لَهُ بالإظهار\",1,\"1:97\"],\"K10\":[\"كرر الْآيَة إِحْدَى وَثَلَاثِينَ مرّة ثَمَانِيَة مِنْهَا ذكرت عقيب آيَات فِيهَا تعداد عجائب خلق الله وبدائع صنعه ومبدأ الْخلق ومعادهم ثمَّ سَبْعَة مِنْهَا عقيب آيَات فِيهَا ذكر النَّار\",1,\"1:231\"],\"I01\":[\"الجواب بالإبتداء، وكان الأول مع الثاني بمعنى الشرط والجزاء\",1,\"1:222\"],\"I04\":[\"فالجواب عنها كالجواب في الخطايا والخطيئات، لأنه لما أسند الفعل إلى نفسه تعالى كان اللفظ بالأشرف الأكرم، فذكر معه الإنعام الأجسم، وهو أن يأكلوا رغدا\",1,\"1:237\"],\"I05\":[\"والجواب عن ذلك: أن الآية الأولى في سورة البقرة خبر عن قوم عرفوا وعرفت أفعالهم ومضت أزمتهم وأحوالهم، فلما شهروا شهر فعلهم بوقوعه منهم.\",1,\"1:246\"],\"I06\":[\"فالجواب أن يقال: إذا أورد الحكيم تقدست أسماؤه آية على لفظة مخصوصة ثم أعادها في موضع آخر من القرآن، وقد غير فيها لفظة عما كانت عليه في الأولى فلا بد من حكمة هناك تطلب، وإن أدركتموها فقد ظفرتم\",1,\"1:250\"],\"I08\":[\"والجواب عن ذلك من وجهين: أحدهما: أن يقال: إن الدعوة الأولى وقعت، ولم يكن المكان قد جعل بلدا، فكأنه قال: رب اجعل هذا الوادي بلدا آمنا\",1,\"1:282\"],\"I09\":[\"والجواب المختصر المشار به إلى الفرق بين الموضعين في إلى وعلى: أن أول الآية التي اختصت بها على (قل آمنا بالله..) وأول الآية التي اختصت بها إلى: (قولوا آمنا بالله..) وشرح ذلك: أن على موضوعة لكون الشيء فوق الشيء\",1,\"1:299\"],\"I10\":[\"فالجواب عنها أن يقال: إن لقوله: (يعلمون) رتبة ليست لقوله (يعقلون)، وإذا وقفت على ما بينها سهلت عليك معرفة ما أوجب فقول القائل: يعلم، معناه: يدرك الشيء على ما هو به مع سكون إليه، وقوله: يعقل\",1,\"1:312\"],\"K-001\":[\"فِيمَن جعل ﴿بِسم الله الرَّحْمَن الرَّحِيم﴾ آيَة من الْفَاتِحَة وَفِي تكراره قَولَانِ قَالَ عَليّ بن عِيسَى إِنَّمَا كرر للتوكيد وَأنْشد قَول الشَّاعِر\",1,\"1:65\"],\"K-003\":[\"كرر ﴿الصِّرَاط﴾ لعِلَّة تقرب مِمَّا ذكرت فِي ﴿الرَّحْمَن الرَّحِيم﴾ وَذَلِكَ أَن الصِّرَاط هُوَ الْمَكَان\",1,\"1:66\"],\"K-005\":[\"هَذِه الْآيَة تَتَكَرَّر فِي أَوَائِل سِتّ سور فَهِيَ من الْمُتَشَابه لفظا وَذهب جمَاعَة من الْمُفَسّرين إِلَى أَن قَوْله ﴿وَأخر متشابهات﴾ هِيَ هَذِه الْحُرُوف الْوَاقِعَة فِي أَوَائِل السُّور\",1,\"1:66\"],\"K-006\":[\"وَفِي يس ﴿وَسَوَاء﴾ بِزِيَادَة وَاو لِأَن مَا فِي الْبَقَرَة جملَة هِيَ خبر عَن اسْم إِن وَمَا فِي يس جملَة عطفت بِالْوَاو على جملَة\",0,\"1:67\"],\"K-007\":[\"لَيْسَ فِي الْقُرْآن غَيره تكْرَار الْعَامِل مَعَ حرف الْعَطف لَا يكون إِلَّا للتَّأْكِيد وَهَذِه حِكَايَة كَلَام الْمُنَافِقين وهم أكدوا كَلَامهم نفيا للريبة وإبعادا للتُّهمَةِ\",1,\"1:67\"],\"K-009\":[\"بِزِيَادَة ﴿من﴾ فِي هَذِه السُّورَة وَفِي غَيرهَا ﴿بِسُورَة مثله﴾ لِأَن ﴿من﴾ تدل على التَّبْعِيض وَلما كَانَت هَذِه السُّورَة سَنَام الْقُرْآن وأوله بعد الْفَاتِحَة حسن دُخُول ﴿من﴾ فِيهَا ليعلم أَن التحدي\",1,\"1:69\"],\"K-010\":[\"ذكر هَذِه الْخلال فِي هَذِه السُّورَة جملَة ثمَّ ذكرهَا فِي سَائِر السُّور مفصلا فَقَالَ فِي الْأَعْرَاف ﴿إِلَّا إِبْلِيس لم يكن من الساجدين﴾ وَفِي الْحجر ﴿إِلَّا إِبْلِيس أَبى أَن يكون مَعَ الساجدين﴾\",1,\"1:70\"],\"K-012\":[\"كرر الْأَمر بالهبوط لِأَن الأول من الْجنَّة وَالثَّانِي من السَّمَاء\",0,\"1:71\"],\"K-013\":[\"وَفِي طه ﴿فَمن اتبع﴾ تبع وَاتبع بِمَعْنى وَإِنَّمَا اخْتَار فِي طه ﴿اتبع﴾ مُوَافقَة لقَوْله تَعَالَى ﴿يتبعُون الدَّاعِي﴾\",0,\"1:71\"],\"K-015\":[\"بِغَيْر وَاو هُنَا على الْبَدَل من ﴿يسومونكم﴾ وَفِي الْأَعْرَاف ﴿يقتلُون﴾ وَفِي إِبْرَاهِيم ﴿ويذبحون﴾ بِالْوَاو لِأَن مَا فِي هَذِه السُّورَة والأعراف من كَلَام الله تَعَالَى فَلم يرد تعداد المحن عَلَيْهِم\",1,\"1:72\"],\"K-016\":[\"هَهُنَا وَفِي الْأَعْرَاف وَقَالَ فِي آل عمرَان ﴿وَلَكِن أنفسهم يظْلمُونَ﴾\",1,\"1:72\"],\"K-017\":[\"بِالْفَاءِ وَفِي الْأَعْرَاف بِالْوَاو لِأَن الدُّخُول سريع الِانْقِضَاء فيتبعه الْأكل وَفِي الْأَعْرَاف ﴿وَإِذ قيل لَهُم اسكنوا﴾ الْمَعْنى أقِيمُوا فِيهَا وَذَلِكَ ممتد فَذكر بِالْوَاو أَي اجْمَعُوا بَين الْأكل\",1,\"1:72\"],\"K-018\":[\"وَفِي الْأَعْرَاف ﴿فانبجست﴾ لِأَن الانفجار انصباب المَاء بِكَثْرَة والانبجاس ظُهُور المَاء وَكَانَ فِي هَذِه السُّورَة ﴿كلوا وَاشْرَبُوا﴾ فَذكر بِلَفْظ بليغ وَفِي الْأَعْرَاف ﴿كلوا من طَيّبَات مَا رزقناكم﴾\",1,\"1:74\"],\"K-019\":[\"فِي هَذِه السُّورَة وَفِي آل عمرَان ﴿وَيقْتلُونَ النَّبِيين بِغَيْر حق﴾ وفيهَا وَفِي النِّسَاء ﴿وقتلهم الْأَنْبِيَاء بِغَيْر حق﴾ لِأَن مَا فِي الْبَقَرَة إِشَارَة إِلَى الْحق الَّذِي أذن الله أَن تقتل النَّفس بِهِ\",1,\"1:74\"],\"K-020\":[\"وَقَالَ فِي الْحَج ﴿وَالصَّابِئِينَ وَالنَّصَارَى﴾ وَقَالَ فِي الْمَائِدَة ﴿والصابئون وَالنَّصَارَى﴾ لِأَن النَّصَارَى مقدمون على الصابئين فِي الرُّتْبَة لأَنهم أهل كتاب فَقَدمهُمْ فِي الْبَقَرَة\",1,\"1:75\"],\"K-022\":[\"﴿وَلنْ يَتَمَنَّوْهُ﴾ وَفِي الْجُمُعَة ﴿وَلَا يتمنونه﴾ لِأَن دَعوَاهُم فِي هَذِه السُّورَة بَالِغَة قَاطِعَة وَهِي كَون الْجنَّة ﴿لَهُم﴾ بِصفة الخلوص فَبَالغ فِي الرَّد عَلَيْهِم بلن وَهُوَ أبلغ أَلْفَاظ النَّفْي\",1,\"1:76\"],\"K-024\":[\"وَفِي غَيرهَا ﴿لَا يعْقلُونَ﴾ ﴿لَا يعلمُونَ﴾ لأَنهم بَين نَاقض عهد وجاحد حق إِلَّا الْقَلِيل مِنْهُم عبد الله بن سَلام وَأَصْحَابه\",1,\"1:76\"],\"K-026\":[\"وَفِي إِبْرَاهِيم ﴿هَذَا الْبَلَد آمنا﴾ لِأَن ﴿هَذَا﴾ هُنَا إِشَارَة إِلَى الْمَذْكُور فِي قَوْله ﴿بواد غير ذِي زرع﴾ قبل بِنَاء الْكَعْبَة\",1,\"1:78\"],\"K-028\":[\"هَذِه الْآيَة مكررة ثَلَاث مَرَّات قيل إِن الأولى لنسخ الْقبْلَة وَالثَّانيَِة للسبب وَهُوَ قَوْله ﴿وَإنَّهُ للحق من رَبك﴾ وَالثَّالِثَة لِلْعِلَّةِ وَهُوَ قَوْله ﴿لِئَلَّا يكون للنَّاس عَلَيْكُم حجَّة﴾\",1,\"1:79\"],\"K-029\":[\"لَيْسَ فِي هَذِه ﴿من بعد ذَلِك﴾ وَفِي غَيرهَا ﴿من بعد ذَلِك﴾ لِأَن قبله هُنَا ﴿من بعد مَا بَيناهُ﴾ فَلَو أعَاد الْتبس\",0,\"1:80\"],\"K-030\":[\"خص الْعقل بِالذكر لِأَن بِهِ يتَوَصَّل إِلَى معرفَة الْآيَات وَمثله فِي الرَّعْد والنحل والنور وَالروم\",0,\"1:80\"],\"K-031\":[\"فِي هَذِه السُّورَة وَفِي الْمَائِدَة ولقمان ﴿مَا وجدنَا﴾ لِأَن ألفيت يتَعَدَّى إِلَى مفعولين تَقول ألفيت زيدا قَائِما وألفيت عمرا على كَذَا وَوجدت يتَعَدَّى مرّة إِلَى مفعول وَاحِد تَقول وجدت الضَّالة\",1,\"1:80\"],\"K-032\":[\"فِي هَذِه السُّورَة وَفِي الْمَائِدَة ولقمان ﴿مَا وجدنَا﴾ لِأَن ألفيت يتَعَدَّى إِلَى مفعولين تَقول ألفيت زيدا قَائِما وألفيت عمرا على كَذَا وَوجدت يتَعَدَّى مرّة إِلَى مفعول وَاحِد تَقول وجدت الضَّالة\",1,\"1:80\"],\"K-033\":[\"قدم ﴿بِهِ﴾ فِي هَذِه السُّورَة وأخرها فِي الْمَائِدَة والأنعام والنحل لِأَن تَقْدِيم الْبَاء الأَصْل فَإِنَّهَا تجْرِي مجْرى الْهمزَة وَالتَّشْدِيد فِي التَّعَدِّي فَكَانَت كحرف من الْفِعْل\",1,\"1:81\"],\"K-034\":[\"وَفِي السُّور الثَّلَاث بحذفها لِأَنَّهُ لما قَالَ فِي الْموضع الأول ﴿فَلَا إِثْم عَلَيْهِ﴾ صَرِيحًا كَانَ نفي الْإِثْم فِي غَيره تضمينا لِأَن قَوْله ﴿ غَفُور رَحِيم﴾ يدل على أَنه لَا إِثْم عَلَيْهِ\",0,\"1:81\"],\"K-035\":[\"فِي هَذِه السُّورَة خلاف سُورَة الْأَنْعَام فَإِن فِيهَا ﴿فَإِن رَبك غَفُور رَحِيم﴾ لِأَن لفظ الرب تكَرر فِي الْأَنْعَام مَرَّات وَلِأَن فِي الْأَنْعَام قَوْله ﴿وَهُوَ الَّذِي أنشأ جنَّات معروشات﴾ الْآيَة\",1,\"1:82\"],\"K-036\":[\"الْآيَة فِي السُّورَة على هَذَا النسق وَفِي آل عمرَان\",1,\"1:82\"],\"K-037\":[\"خص السّمع بِالذكر لما فِي الْآيَة من قَوْله ﴿فَمن بدله بعد مَا سَمعه﴾ ليَكُون مطابقا وَقَالَ فِي الْآيَة الْأُخْرَى بعْدهَا ﴿إِن الله غَفُور رَحِيم﴾ لقَوْله قبله ﴿فَلَا إِثْم عَلَيْهِ﴾ فَهُوَ مُطَابق معنى لَهُ\",0,\"1:83\"],\"K-038\":[\"قيد بقوله ﴿مِنْكُم﴾ وَكَذَلِكَ ﴿فَمن كَانَ مِنْكُم مَرِيضا أَو بِهِ أَذَى من رَأسه﴾\",1,\"1:83\"],\"K-039\":[\"وَقَالَ بعده ﴿تِلْكَ حُدُود الله فَلَا تعتدوها﴾ لِأَن الْحَد الأول نهى وَهُوَ قَوْله ﴿وَلَا تباشروهن وَأَنْتُم عاكفون فِي الْمَسَاجِد﴾ وَمَا كَانَ من الْحُدُود نهيا أَمر بترك المقاربة وَالْحَد الثَّانِي أَمر\",1,\"1:83\"],\"K-040\":[\"جَمِيع مَا جَاءَ فِي الْقُرْآن من السُّؤَال وَقع عقبه الْجَواب بِغَيْر الْفَاء إِلَّا فِي قَوْله ﴿ويسألونك عَن الْجبَال فَقل ينسفها رَبِّي﴾\",1,\"1:83\"],\"K-041\":[\"فِي هَذِه السُّورَة وَفِي الْأَنْفَال ﴿وَيكون الدّين كُله لله﴾ لِأَن الْقِتَال فِي هَذِه السُّورَة مَعَ أهل مَكَّة وَفِي الْأَنْفَال مَعَ جَمِيع الْكفَّار فقيده بقوله ﴿كُله﴾\",0,\"1:84\"],\"K-042\":[\"وَقَالَ فِي آل عمرَان ﴿أم حسبتم أَن تدْخلُوا الْجنَّة وَلما يعلم الله الَّذين جاهدوا مِنْكُم وَيعلم الصابرين﴾\",1,\"1:84\"],\"K-043\":[\"وَفِي آخر السُّورَة ﴿لَعَلَّكُمْ تتفكرون﴾ وَمثله فِي الْأَنْعَام لِأَنَّهُ لما بَين فِي الأول مفعول التفكر وَهُوَ قَوْله ﴿فِي الدُّنْيَا وَالْآخِرَة﴾ حذفه مِمَّا بعده للْعلم بِهِ\",1,\"1:84\"],\"K-043b\":[\"بِفَتْح التَّاء وَالثَّانِي بضَمهَا لِأَن الأول من نكحت وَالثَّانِي من أنكحت وَهُوَ يتَعَدَّى إِلَى مفعولين وَالْمَفْعُول الأول فِي الْآيَة الْمُشْركين وَالثَّانِي مَحْذُوف\",1,\"1:85\"],\"K-046\":[\"وَفِي الطَّلَاق ﴿ذَلِكُم يوعظ بِهِ من كَانَ يُؤمن﴾ الْكَاف فِي ذَلِك لمُجَرّد الْخطاب لَا مَحل لَهُ من الْإِعْرَاب فَجَاز الِاخْتِصَار على التَّوْحِيد وَجَاز إجراؤه على عدد المخاطبين\",1,\"1:85\"],\"K-047\":[\"وَقَالَ فِي الْآيَة الْأُخْرَى من مَعْرُوف لِأَن تَقْدِير الأول فِيمَا فعلن بِأَمْر الله وَهُوَ الْمَعْرُوف وَالثَّانِي فِيمَا فعلن فِي أَنْفسهنَّ فعلا من أفعالهن مَعْرُوفا أَي جَازَ\",1,\"1:86\"],\"K-050\":[\"﴿يغْفر﴾ مقدم فِي هَذِه السُّورَة وَغَيرهَا إِلَّا فِي الْمَائِدَة فَإِن فِيهَا ﴿يعذب من يَشَاء وَيغْفر﴾ لِأَنَّهَا نزلت بعْدهَا فِي حق السَّارِق والسارقة وعذابهما يَقع فِي الدُّنْيَا\",1,\"1:87\"],\"K-051\":[\"أَو السُّورَة وَفِي آخرهَا ﴿إِنَّك لَا تخلف الميعاد﴾ فَعدل من الْخطاب إِلَى لفظ الْغَيْبَة فِي أول السُّورَة وَاسْتمرّ على الْخطاب فِي آخرهَا لِأَن مَا فِي أول السُّورَة لَا يتَّصل بالْكلَام الأول كاتصال مَا فِي آخرهَا\",1,\"1:88\"],\"K-054\":[\"ثمَّ كرر فِي هَذِه\",1,\"1:88\"],\"K-055\":[\"قدم فِي هَذِه السُّورَة ذكر الْكبر وَأخر ذكر الْمَرْأَة وَقَالَ فِي سُورَة مَرْيَم ﴿وَكَانَت امْرَأَتي عاقرا وَقد بلغت من الْكبر عتيا﴾\",1,\"1:89\"],\"K-056\":[\"وَفِي مَرْيَم ﴿قَالَ رب أَنى يكون لي غُلَام﴾ لِأَن فِي هَذِه السُّورَة تقدم ذكر الْمَسِيح وَهُوَ وَلَدهَا وَفِي مَرْيَم تقدم ذكر الْغُلَام حَيْثُ قَالَ ﴿لأهب لَك غُلَاما زكيا﴾\",0,\"1:89\"],\"K-057\":[\"وَفِي الْمَائِدَة ﴿فتنفخ فِيهَا﴾ قيل الضَّمِير فِي هَذِه السُّورَة يعود إِلَى الطير وَقيل إِلَى الطين وَقيل إِلَى المهيأ وَقيل إِلَى الْكَاف فَإِنَّهُ فِي معنى مثل وَفِي الْمَائِدَة يعود إِلَى الْهَيْئَة\",1,\"1:89\"],\"K-058\":[\"ذكر فِي هَذِه الْآيَة مرَّتَيْنِ وَقَالَ فِي الْمَائِدَة ﴿بإذني﴾ أَربع مَرَّات لِأَن مَا فِي هَذِه السُّورَة كَلَام عِيسَى فَمَا يتَصَوَّر أَن يكون من فعل الْبشر أَضَافَهُ إِلَى نَفسه\",1,\"1:90\"],\"K-059\":[\"وَكَذَلِكَ فِي مَرْيَم ﴿رَبِّي وربكم﴾ وَفِي الزخرف فِي هَذِه الْقِصَّة ﴿إِن الله هُوَ رَبِّي وربكم﴾ بِزِيَادَة هُوَ\",1,\"1:91\"],\"K-060\":[\"فِي هَذِه السُّورَة وَفِي الْمَائِدَة ﴿بأننا﴾ لِأَن مَا فِي الْمَائِدَة أول كَلَام الحواريين فجَاء على الأَصْل وَمَا فِي هَذِه السُّورَة تكْرَار لكلامهم فَجَاز فِيهِ التَّخْفِيف لِأَن التَّخْفِيف فرع والتكرار فرع\",1,\"1:91\"],\"K-061\":[\"فِي هَذِه السُّورَة وَفِي الْبَقَرَة ﴿فَلَا تكونن﴾ لِأَن مَا فِي هَذِه السُّورَة جَاءَ على الأَصْل وَلم يكن فِيهَا مَا أوجب إِدْخَال نون التوكيد فِي الْكَلِمَة بِخِلَاف سُورَة الْبَقَرَة\",1,\"1:91\"],\"K-062\":[\"فِي هَذِه السُّورَة وَفِي الْبَقَرَة ﴿قل إِن هدى الله هُوَ الْهدى﴾ لِأَن الْهدى فِي هَذِه السُّورَة هُوَ الدّين وَقد تقدم فِي قَوْله ﴿لمن تبع دينكُمْ﴾ وَهدى الله الْإِسْلَام\",1,\"1:92\"],\"K-063\":[\"لَيْسَ هَهُنَا بِهِ وَلَا وَاو الْعَطف وَفِي الْأَعْرَاف ﴿من آمن بِهِ وتبغونها﴾ بِزِيَادَة بِهِ وواو الْعَطف لِأَن الْقيَاس آمن بِهِ كَمَا فِي الْأَعْرَاف لَكِنَّهَا حذفت فِي هَذِه\",1,\"1:92\"],\"K-064\":[\"هَهُنَا بِإِثْبَات ﴿لكم﴾ وَتَأْخِير ﴿بِهِ﴾ وَحذف ﴿إِن الله﴾ وَفِي الْأَنْفَال بِحَذْف لكم وَتَقْدِيم بِهِ وَإِثْبَات إِن الله لِأَن الْبُشْرَى هُنَا للمخاطبين فَبين وَقَالَ لكم\",1,\"1:92\"],\"K-065\":[\"بِزِيَادَة الْوَاو لِأَن الِاتِّصَال بِمَا قبلهَا أَكثر من غَيرهَا وَتَقْدِيره وَنعم أجر العاملين الْمَغْفِرَة والجنات وَالْخُلُود\",0,\"1:93\"],\"K-066\":[\"بِزِيَادَة الْأَنْفس وَفِي غَيرهَا ﴿رَسُولا مِنْكُم﴾ لِأَنَّهُ سُبْحَانَهُ من على الْمُؤمنِينَ بِهِ فَجعله من أنفسهم ليَكُون مُوجب الْمِنَّة أظهر وَكَذَلِكَ قَوْله ﴿لقد جَاءَكُم رَسُول من أَنفسكُم﴾ لما\",1,\"1:93\"],\"K-066b\":[\"بِزِيَادَة الْأَنْفس وَفِي غَيرهَا ﴿رَسُولا مِنْكُم﴾ لِأَنَّهُ سُبْحَانَهُ من على الْمُؤمنِينَ بِهِ فَجعله من أنفسهم ليَكُون مُوجب الْمِنَّة أظهر وَكَذَلِكَ قَوْله ﴿لقد جَاءَكُم رَسُول من أَنفسكُم﴾ لما\",1,\"1:93\"],\"K-067\":[\"هَهُنَا بباء وَاحِدَة إِلَّا فِي قِرَاءَة ابْن عَامر وَفِي فاطر ﴿بِالْبَيِّنَاتِ وبالزبر وبالكتاب﴾ بِثَلَاثَة باءات لِأَنَّهُ فِي هَذِه السُّورَة وَقع فِي كَلَام مَبْنِيّ على الِاخْتِصَار\",1,\"1:94\"],\"K-068\":[\"هَهُنَا وَفِي غَيرهَا ﴿ومأواهم جَهَنَّم﴾ لِأَن مَا قبلهَا فِي هَذِه السُّورَة ﴿لَا يغرنك تقلب الَّذين كفرُوا فِي الْبِلَاد﴾ ﴿مَتَاع قَلِيل﴾ أَي ذَلِك مَتَاع فِي الدُّنْيَا قَلِيل والقليل يدل على تراخ وَإِن صغر وَقل\",1,\"1:94\"],\"K-070\":[\"بِالْوَاو وَفِي بَرَاءَة ﴿ذَلِك﴾ بِغَيْر وَاو لِأَن الْجُمْلَة إِذا وَقعت بعد جملَة أَجْنَبِيَّة لَا تحسن إِلَّا بِحرف الْعَطف وَإِن كَانَ فِي الْجُمْلَة الثَّانِيَة مَا يعود إِلَى الأولى حسن إِثْبَات حرف الْعَطف\",1,\"1:95\"],\"K-071\":[\"فِي أول السُّورَة وَبعدهَا ﴿محصنات غير مسافحات وَلَا متخذات أخدان﴾ وَفِي الْمَائِدَة ﴿محصنين غير مسافحين وَلَا متخذي أخدان﴾ لِأَن فِي هَذِه السُّورَة وَقع فِي حق الْأَحْرَار الْمُسلمين فاقتصر على لفظ ﴿غير مسافحين﴾\",1,\"1:95\"],\"K-072\":[\"فِي هَذِه السُّورَة وَزَاد فِي الْمَائِدَة ﴿مِنْهُ﴾ لِأَن الْمَذْكُور فِي هَذِه بعض أَحْكَام الْوضُوء وَالتَّيَمُّم فَحسن الْحَذف وَالْمَذْكُور فِي الْمَائِدَة جَمِيع أحكامهما فَحسن الْإِثْبَات وَالْبَيَان\",0,\"1:96\"],\"K-073\":[\"ختم الْآيَة مرّة بقوله ﴿فقد افترى﴾ وَمرَّة بقوله ﴿فقد ضل﴾ لِأَن الأول نزل فِي الْيَهُود وهم الَّذين افتروا على الله مَا لَيْسَ فِي كِتَابهمْ وَالثَّانِي نزل فِي الْكفَّار وَلم يكن لَهُم كتاب فَكَانَ ضلالهم أَشد\",0,\"1:96\"],\"K-074\":[\"وَفِي غَيرهَا ﴿يَا أهل الْكتاب﴾ الخ لِأَنَّهُ سُبْحَانَهُ استخف بهم فِي هَذِه الْآيَة وَبَالغ ثمَّ ختم بالطمس ورد الْوُجُوه على الأدبار واللعن وبأنها كلهَا وَاقعَة بهم\",0,\"1:96\"],\"K-075\":[\"ثمَّ فِي الْآيَات الْأُخْرَى ﴿دَرَجَات﴾ و٣ ١٦٣ و٤ ٩٦ و٦ ٨٣ ١٣٢ لِأَن الأولى فِي الدُّنْيَا وَالثَّانِي فِي الْجنَّة وَقيل الأولى الْمنزلَة وَالثَّانيَِة الْمنزل وَهُوَ دَرَجَات وَقيل الأولى على القاعدين بِعُذْر\",1,\"1:97\"],\"K-076\":[\"بالإظهار فِي هَذِه السُّورَة وَكَذَلِكَ فِي الْأَنْفَال وَفِي الْحَشْر بِالْإِدْغَامِ لِأَن الثَّانِي من المثلين إِذا تحرّك بحركة لَازِمَة وَجب إدغام الأول فِي الثَّانِي أَلا ترى أَنَّك تَقول ارْدُدْ لَهُ بالإظهار\",1,\"1:97\"],\"K-077\":[\"بالإظهار فِي هَذِه السُّورَة وَكَذَلِكَ فِي الْأَنْفَال وَفِي الْحَشْر بِالْإِدْغَامِ لِأَن الثَّانِي من المثلين إِذا تحرّك بحركة لَازِمَة وَجب إدغام الأول فِي الثَّانِي أَلا ترى أَنَّك تَقول ارْدُدْ لَهُ بالإظهار\",1,\"1:97\"],\"K-078\":[\"فِي هَذِه السُّورَة وَفِي الْأَحْزَاب ﴿إِن تبدوا شَيْئا﴾ لِأَن فِي هَذِه السُّورَة وَقع الْخَبَر فِي مُقَابلَة السوء فِي قَوْله ﴿لَا يحب الله الْجَهْر بالسوء﴾ والمقابلة اقْتَضَت أَن يكون بِإِزَاءِ السوء الْخَيْر\",1,\"1:98\"],\"K-079\":[\"وَسَائِر مَا فِي هَذِه السُّورَة ﴿مَا فِي السَّمَاوَات وَمَا فِي الأَرْض﴾ لِأَن الله سُبْحَانَهُ ذكر أهل الأَرْض فِي هَذِه الْآيَة تبعا لأهل السَّمَوَات وَلم يفردهم بِالذكر لانضمام المخاطبين إِلَيْهِم\",1,\"1:99\"],\"K-080\":[\"بِغَيْر وَاو لِأَن الأول لما اتَّصل بِمَا بعده وَهُوَ قَوْله ﴿فِي النِّسَاء﴾ وَصله بِمَا قبله بواو الْعَطف والعائد جَمِيعًا وَالثَّانِي لما انْفَصل عَمَّا بعده اقْتصر من الِاتِّصَال على الْعَائِد وَهُوَ ضمير\",1,\"1:99\"],\"K-081\":[\"بِحَذْف الْيَاء وَكَذَلِكَ ﴿واخشون وَلَا تشتروا﴾ وَفِي الْبَقَرَة وَغَيرهَا ﴿واخشوني﴾ بالإثبات لِأَن الْإِثْبَات هُوَ الأَصْل وحذفت الْيَاء من ﴿واخشون الْيَوْم﴾ من الْخط لما حذفت من اللَّفْظ وحذفت من\",1,\"1:99\"],\"K-082\":[\"ثمَّ أعَاد فَقَالَ ﴿وَاتَّقوا الله إِن الله خَبِير بِمَا تَعْمَلُونَ﴾ لِأَن الأول وَقع على النِّيَّة وَهِي بِذَات الصُّدُور وَالثَّانِي على الْعَمَل وَعَن ابْن كثير أَن الأولى نزلت فِي الْيَهُود وَلَيْسَ بتكرار\",0,\"1:100\"],\"K-083\":[\"وَقَالَ فِي الْفَتْح ﴿وعد الله الَّذين آمنُوا وَعمِلُوا الصَّالِحَات مِنْهُم مغْفرَة وَأَجرا عَظِيما﴾ رفع مَا فِي هَذِه السُّورَة مُوَافقَة لفواصل الْآي وَنصب مَا فِي فتح مُوَافقَة للفواصل أَيْضا\",1,\"1:100\"],\"K-084\":[\"وَقَالَ فِي الْفَتْح ﴿وعد الله الَّذين آمنُوا وَعمِلُوا الصَّالِحَات مِنْهُم مغْفرَة وَأَجرا عَظِيما﴾ رفع مَا فِي هَذِه السُّورَة مُوَافقَة لفواصل الْآي وَنصب مَا فِي فتح مُوَافقَة للفواصل أَيْضا\",1,\"1:100\"],\"K-085\":[\"كرر لِأَن الأولى فِي الْيَهُود وَالثَّانيَِة فِي حق النَّصَارَى وَالْمعْنَى لم ينالو مِنْهُ نَصِيبا وَقيل مَعْنَاهُ ونسوا نَصِيبا وَقيل مَعْنَاهُ تركُوا بعض مَا أمروا بِهِ\",0,\"1:101\"],\"K-086\":[\"ثمَّ كررها فَقَالَ ﴿يَا أهل الْكتاب﴾ لِأَن الأولى نزلت فِي الْيَهُود حِين كتموا صفة مُحَمَّد ﷺ وَآيَة الرَّجْم من التَّوْرَاة وَالنَّصَارَى حِين كتموا بِشَارَة عِيسَى بِمُحَمد ﷺ فِي الْإِنْجِيل\",1,\"1:101\"],\"K-087\":[\"ثمَّ كرر فَقَالَ ﴿وَللَّه ملك السَّمَاوَات وَالْأَرْض وَمَا بَينهمَا وَإِلَيْهِ الْمصير﴾ كرر لِأَن الأولى نزلت فِي النَّصَارَى حِين قَالُوا ﴿إِن الله هُوَ الْمَسِيح ابْن مَرْيَم﴾ فَقَالَ\",1,\"1:102\"],\"K-088\":[\"ثمَّ كرر فَقَالَ ﴿وَللَّه ملك السَّمَاوَات وَالْأَرْض وَمَا بَينهمَا وَإِلَيْهِ الْمصير﴾ كرر لِأَن الأولى نزلت فِي النَّصَارَى حِين قَالُوا ﴿إِن الله هُوَ الْمَسِيح ابْن مَرْيَم﴾ فَقَالَ\",1,\"1:102\"],\"K-089\":[\"كَرَّرَه ثَلَاث مَرَّات وَختم الأولى بقوله ﴿فَأُولَئِك هم الْكَافِرُونَ﴾ وَالثَّانيَِة بقوله ﴿فَأُولَئِك هم الظَّالِمُونَ﴾ وَالثَّالِثَة بقوله ﴿فَأُولَئِك هم الْفَاسِقُونَ﴾ قيل لِأَن الأولى نزلت فِي حكام الْمُسلمين\",1,\"1:103\"],\"K-090\":[\"كرر لِأَن النَّصَارَى اخْتلفت أَقْوَالهم فَقَالَت اليعقوبية إِن الله تَعَالَى رُبمَا تجلى فِي بعض الْأَزْمَان فِي شخص فتجلى يَوْمئِذٍ فِي شخص عِيسَى فظهرت مِنْهُ المعجزات وَقَالَت الملكية إِن الله اسْم يجمع أَبَا\",1,\"1:103\"],\"K-092\":[\"وَفِي الشُّعَرَاء ﴿فقد كذبُوا فسيأتيهم﴾ لِأَن سُورَة الْأَنْعَام مُتَقَدّمَة\",1,\"1:104\"],\"K-093\":[\"فِي بعض الْمَوَاضِع بِغَيْر وَاو كَمَا فِي هَذِه السُّورَة وَفِي بَعْضهَا بِالْوَاو وَفِي بَعْضهَا بِالْفَاءِ هَذِه الْكَلِمَة تَأتي فِي الْقُرْآن على\",1,\"1:104\"],\"K-094\":[\"فِي هَذِه السُّورَة فَحسب وَفِي غَيرهَا ﴿سِيرُوا فِي الأَرْض فانظروا﴾ لِأَن ثمَّ للتراخي وَالْفَاء للتعقيب وَفِي هَذِه السُّورَة تقدم ذكر الْقُرُون فِي قَوْله ﴿كم أهلكنا من قبلهم من قرن﴾ ثمَّ قَالَ\",1,\"1:105\"],\"K-095\":[\"لَيْسَ بتكرار لِأَن الأول فِي حق الْكفَّار وَالثَّانِي فِي حق أهل الْكتاب\",0,\"1:106\"],\"K-096\":[\"وَقَالَ فِي يُونُس ﴿فَمن أظلم﴾ وَختم الْآيَة بقوله ﴿إِنَّه لَا يفلح المجرمون﴾ لِأَن الْآيَات الَّتِي تقدّمت فِي هَذِه السُّورَة عطف بَعْضهَا على بعض بِالْوَاو وَهُوَ قَوْله\",1,\"1:106\"],\"K-097\":[\"وَفِي يُونُس ﴿يَسْتَمِعُون﴾ لِأَن مَا فِي هَذِه السُّورَة نزل فِي أبي سُفْيَان وَالنضْر بن الْحَارِث وَعتبَة وَشَيْبَة وَأُميَّة وَأبي بن خلف\",1,\"1:106\"],\"K-098\":[\"ثمَّ أعَاد فَقَالَ ﴿وَلَو ترى إِذْ وقفُوا على رَبهم﴾ لأَنهم أَنْكَرُوا النَّار فِي الْقِيَامَة وأنكروا جَزَاء الله ونكاله فَقَالَ فِي الأولى ﴿إِذْ وقفُوا على النَّار﴾\",1,\"1:107\"],\"K-099\":[\"لَيْسَ غَيره وَفِي غَيرهَا بِزِيَادَة ﴿نموت ونحيا﴾ لِأَن مَا فِي هَذِه السُّورَة عِنْد كثير من الْمُفَسّرين مُتَّصِل بقوله\",1,\"1:107\"],\"K-100\":[\"قدم اللّعب على اللَّهْو فِي هَذِه السُّورَة فِي موضِعين وَكَذَلِكَ فِي سورتي الْقِتَال وَالْحَدِيد\",1,\"1:107\"],\"K-101\":[\"ثمَّ قَالَ ﴿قل أَرَأَيْتكُم إِن أَتَاكُم عَذَاب الله بَغْتَة﴾ وَلَيْسَ لَهما ثَالِث وَقَالَ فِيمَا بَينهمَا ﴿قل أَرَأَيْتُم﴾ وَكَذَلِكَ فِي غَيرهَا\",1,\"1:108\"],\"K-102\":[\"فِي هَذِه السُّورَة وَفِي الْأَعْرَاف ﴿يضرعون﴾ بِالْإِدْغَامِ لِأَن هَهُنَا وَافق مَا بعده وَهُوَ قَوْله ﴿جَاءَهُم بأسنا تضرعوا﴾ ومستقبل تضرعوا يَتَضَرَّعُونَ لَا غير\",0,\"1:109\"],\"K-103\":[\"مُكَرر لِأَن التَّقْدِير انْظُر كَيفَ نصرف الْآيَات ثمَّ هم يصدفون عَنْهَا فَلَا تعرض عَنْهُم بل تكررها لَهُم لَعَلَّهُم يفقهُونَ\",0,\"1:109\"],\"K-104\":[\"فكرر لكم وَقَالَ فِي هود ﴿وَلَا أَقُول إِنِّي ملك﴾ فَلم يُكَرر لكم لِأَن فِي هود تقدم ﴿إِنِّي لكم نَذِير﴾ وعقبه ﴿وَمَا نرى لكم﴾ وَبعده ﴿أَن أنصح لكم﴾ فَلَمَّا تكَرر لكم فِي الْقِصَّة أَربع مَرَّات اكْتفى بذلك\",0,\"1:109\"],\"K-105\":[\"فِي هَذِه السُّورَة وَفِي سُورَة يُوسُف عليه السلام ﴿إِن هُوَ إِلَّا ذكر للْعَالمين﴾ منون لِأَن فِي هَذِه السُّورَة تقدم ﴿بعد الذكرى﴾ ﴿وَلَكِن ذكرى﴾ فَكَانَ الذكرى أليق بهَا\",0,\"1:110\"],\"K-106\":[\"فِي هَذِه السُّورَة وَفِي آل عمرَان ﴿وَتخرج الْحَيّ من الْمَيِّت وَتخرج الْمَيِّت من الْحَيّ﴾ وَكَذَلِكَ فِي الرّوم وَيُونُس ﴿يخرج الْحَيّ من الْمَيِّت وَيخرج الْمَيِّت من الْحَيّ﴾ لِأَن مَا فِي هَذِه السُّورَة\",1,\"1:110\"],\"K-107\":[\"ثمَّ قَالَ ﴿قد فصلنا الْآيَات لقوم يفقهُونَ﴾ وَقَالَ بعدهمَا ﴿إِن فِي ذَلِك لآيَات لقوم يُؤمنُونَ﴾\",1,\"1:111\"],\"K-108\":[\"وَفِي غَيرهَا ﴿خَلقكُم﴾ و٤ ١ و٦ ٢ و٧ ١٨٩\",1,\"1:111\"],\"K-109\":[\"وَفِي الْآيَة الْأُخْرَى ﴿متشابها وَغير متشابه﴾ لِأَن أَكثر مَا جَاءَ فِي الْقُرْآن من هَاتين الْكَلِمَتَيْنِ جَاءَ بِلَفْظ التشابه نَحْو قَوْله ﴿وَأتوا بِهِ متشابها﴾ ﴿إِن الْبَقر تشابه علينا﴾ ﴿تشابهت قُلُوبهم﴾\",1,\"1:112\"],\"K-110\":[\"فِي هَذِه السُّورَة وَفِي الْمُؤمن ﴿خَالق كل شَيْء لَا إِلَه إِلَّا هُوَ﴾ لِأَن فِيهَا قبله ذكر الشُّرَكَاء والبنين وَالْبَنَات فَدفع قَول قَائِله بقوله ﴿لَا إِلَه إِلَّا هُوَ﴾ ثمَّ قَالَ ﴿خَالق كل شَيْء﴾\",1,\"1:112\"],\"K-111\":[\"وَقَالَ فِي الْآيَة الْأُخْرَى من هَذِه السُّورَة ﴿وَلَو شَاءَ الله مَا فَعَلُوهُ فذرهم وَمَا يفترون﴾ لِأَن قَوْله ﴿وَلَو شَاءَ رَبك﴾ وَقع عقيب آيَات فِيهَا\",1,\"1:113\"],\"K-112\":[\"وَفِي ﴿ن والقلم﴾ ﴿إِن رَبك هُوَ أعلم بِمن ضل عَن سَبيله﴾ بِزِيَادَة الْبَاء وَلَفظ الْمَاضِي لِأَن إِثْبَات الْبَاء هُوَ الأَصْل كَمَا فِي ﴿ن والقلم﴾\",1,\"1:113\"],\"K-113\":[\"بِالْفَاءِ حَيْثُ وَقع وَفِي هود ﴿سَوف تعلمُونَ﴾ بِغَيْر فَاء لِأَنَّهُ تقدم فِي هَذِه السُّورَة وَغَيرهَا ﴿قل﴾ فَأَمرهمْ أَمر وَعِيد بقوله ﴿اعْمَلُوا﴾ أَي\",1,\"1:114\"],\"K-114\":[\"وَقَالَ فِي النَّحْل ﴿وَقَالَ الَّذين أشركوا لَو شَاءَ الله مَا عَبدنَا من دونه من شَيْء نَحن وَلَا آبَاؤُنَا وَلَا حرمنا من دونه من شَيْء﴾ فَزَاد من ﴿دونه﴾ مرَّتَيْنِ\",1,\"1:114\"],\"K-115\":[\"وَقَالَ فِي سُبْحَانَ ﴿نَحن نرزقهم وَإِيَّاكُم﴾ على الضِّدّ لِأَن التَّقْدِير من إملاق بكم نَحن نرزقكم وإياهم وَفِي سُبْحَانَ خشيَة إملاق يَقع بهم نَحن نرزقهم وَإِيَّاكُم\",0,\"1:114\"],\"K-116\":[\"وَفِي الثَّانِيَة ﴿لَعَلَّكُمْ تذكرُونَ﴾ وَفِي الثَّالِثَة ﴿لَعَلَّكُمْ تَتَّقُون﴾ لِأَن الْآيَة الأولى مُشْتَمِلَة على خَمْسَة أَشْيَاء كلهَا عِظَام جسام فَكَانَت الْوَصِيَّة بهَا من أبلغ الْوَصَايَا\",1,\"1:114\"],\"K-117\":[\"فِي هَذِه السُّورَة وَفِي يُونُس وَالْمَلَائِكَة ﴿جعلكُمْ خلائف فِي الأَرْض﴾ لِأَن فِي هَذَا الْعشْر\",1,\"1:115\"],\"K-118\":[\"وَقَالَ فِي الْأَعْرَاف ﴿إِن رَبك لسريع الْعقَاب وَإنَّهُ لغَفُور رَحِيم﴾ لِأَن مَا فِي هَذِه السُّورَة وَقع بعد قَوْله ﴿من جَاءَ بِالْحَسَنَة فَلهُ عشر أَمْثَالهَا﴾ وَقَوله ﴿وَهُوَ الَّذِي جعلكُمْ خلائف الأَرْض﴾\",1,\"1:115\"],\"K-119\":[\"فِي هَذِه السُّورَة وَفِي ص ﴿قَالَ يَا إِبْلِيس مَا مَنعك﴾ وَفِي الْحجر ﴿قَالَ يَا إِبْلِيس مَا لَك﴾ بِزِيَادَة ﴿يَا إِبْلِيس﴾ فِي السورتين لِأَن خطابه قرب من ذكره فِي هَذِه السُّورَة\",1,\"1:116\"],\"K-120\":[\"وَفِي ص ﴿أَن تسْجد﴾ وَفِي الْحجر ﴿مَا لَك أَلا تكون﴾ فَزَاد فِي هَذِه السُّورَة ﴿لَا﴾ وللمفسرين فِي ﴿لَا﴾ أَقْوَال قَالَ بَعضهم ﴿لَا﴾ صلَة كَمَا فِي قَوْله ﴿لِئَلَّا يعلم﴾\",1,\"1:116\"],\"K-121\":[\"وَفِي الْحجر وص ﴿رب فأنظرني﴾ لِأَنَّهُ سُبْحَانَهُ لما اقْتصر فِي السُّؤَال على\",1,\"1:117\"],\"K-122\":[\"فِي هَذِه السُّورَة وَفِي السورتين ﴿قَالَ فَإنَّك﴾ لِأَن الْجَواب يبْنى على السُّؤَال وَلما خلا فِي هَذِه السُّورَة عَن الْفَاء خلا الْجَواب عَنهُ وَلما ثبتَتْ الْفَاء فِي السُّؤَال فِي السورتين ثبتَتْ فِي الْجَواب\",1,\"1:118\"],\"K-123\":[\"فِي هَذِه السُّورَة وَفِي ص ﴿فبعزتك لأغوينهم﴾ وَفِي الْحجر ﴿رب بِمَا أغويتني﴾ لِأَن مَا فِي هَذِه السُّورَة مُوَافق لما قبله فِي الِاقْتِصَار على الْخطاب دون النداء\",1,\"1:118\"],\"K-126\":[\"بِالْفَاءِ حَيْثُ وَقع إِلَّا فِي يُونُس فَإِنَّهُ هُنَا جملَة عطفت على جملَة بَينهمَا اتِّصَال وَتعقب فَكَانَ الْموضع مَوضِع الْفَاء وَمَا فِي يُونُس يَأْتِي فِي مَوْضِعه\",0,\"1:119\"],\"K-127\":[\"مَا فِي هَذِه السُّورَة جَاءَ على الْقيَاس وَتَقْدِيره وهم كافرون بِالآخِرَة فَقدم بِالآخِرَة تَصْحِيحا\",1,\"1:119\"],\"K-128\":[\"فِي هَذِه السُّورَة وَفِي الرّوم بِلَفْظ الْمُسْتَقْبل وَفِي الْفرْقَان وفاطر بِلَفْظ الْمَاضِي لِأَن مَا قبلهَا فِي هَذِه السُّورَة ذكر الْخَوْف والطمع وَهُوَ قَوْله ﴿وادعوه خوفًا وَطَمَعًا﴾\",1,\"1:119\"],\"K-129\":[\"فِي هَذِه السُّورَة بِغَيْر وَاو وَفِي هود وَالْمُؤمنِينَ وَلَقَد بِالْوَاو لِأَنَّهُ لم يتَقَدَّم فِي هَذِه السُّورَة ذكر رَسُول فَيكون هَذَا عطفا عَلَيْهِ بل هُوَ اسْتِئْنَاف كَلَام\",1,\"1:120\"],\"K-130\":[\"بِالْفَاءِ فِي هَذِه السُّورَة وَكَذَلِكَ فِي الْمُؤمنِينَ فِي قصَّة نوح ﴿فَقَالَ﴾ وَفِي هود فِي قصَّة نوح ﴿إِنِّي لكم﴾ بِغَيْر ﴿قَالَ﴾ وَفِي هَذِه السُّورَة فِي قصَّة عَاد بِغَيْر\",1,\"1:121\"],\"K-131\":[\"بِغَيْر فَاء فِي قصَّة نوح وَهود فِي هَذِه السُّورَة وَفِي سُورَة هود وَالْمُؤمنِينَ فَقَالَ بِالْفَاءِ لِأَن مَا فِي هَذِه السُّورَة فِي السورتين لَا يَلِيق بِالْجَوَابِ\",1,\"1:121\"],\"K-132\":[\"فِي قصَّة نوح وَقَالَ فِي قصَّة هود ﴿وَأَنا لكم نَاصح أَمِين﴾ لِأَن مَا فِي هَذِه الْآيَة ﴿أبلغكم﴾ بِلَفْظ الْمُسْتَقْبل فعطف عَلَيْهِ ﴿أنصح لكم﴾ كَمَا فِي الْآيَة الْأُخْرَى ﴿لقد أبلغتكم رسالات رَبِّي وَنَصَحْت لكم﴾\",1,\"1:121\"],\"K-133\":[\"فِي قصَّة نوح وَهود بِلَفْظ الْمُسْتَقْبل وَفِي قصَّة صَالح وَشُعَيْب ﴿أبلغتكم﴾ بِلَفْظ الْمَاضِي لِأَن فِي قصَّة نوح وَهود وَقع فِي ابْتِدَاء الرسَالَة وَفِي قصَّة صَالح وَشُعَيْب وَقع فِي آخر الرسَالَة\",1,\"1:122\"],\"K-134\":[\"فِي جَمِيع الْقَصَص إِلَّا فِي قصَّة صَالح فَإِن فِيهَا ﴿رِسَالَة﴾ على الْوَاحِدَة لِأَنَّهُ سُبْحَانَهُ حكى عَنْهُم بعد الْإِيمَان بِاللَّه وَالتَّقوى أَشْيَاء أمروا قَومهمْ بهَا إِلَّا فِي قصَّة صَالح\",1,\"1:122\"],\"K-135\":[\"وَفِي يُونُس ﴿فَكَذبُوهُ فنجيناه وَمن مَعَه فِي الْفلك﴾ لِأَن أنجينا ونجينا للتعدي لَكِن التَّشْدِيد يدل على الْكَثْرَة وَالْمُبَالغَة فَكَانَ فِي يُونُس ﴿وَمن مَعَه﴾\",1,\"1:122\"],\"K-136\":[\"وَفِي هود ﴿وَلَا تمسوها بِسوء فيأخذكم عَذَاب قريب﴾ وَفِي الشُّعَرَاء ﴿وَلَا تمسوها بِسوء فيأخذكم عَذَاب يَوْم عَظِيم﴾ لِأَنَّهُ فِي هَذِه السُّورَة بَالغ فِي الْوَعْظ فَبَالغ فِي الْوَعيد فَقَالَ ﴿عَذَاب أَلِيم﴾\",1,\"1:123\"],\"K-137\":[\"على الْوحدَة وَقَالَ ﴿وَأخذت الَّذين ظلمُوا الصَّيْحَة فَأَصْبحُوا فِي دِيَارهمْ جاثمين﴾ حَيْثُ ذكر الرجفة وَهِي الزلزلة وحد الدَّار وَحَيْثُ ذكر الصَّيْحَة جمع لِأَن الصَّيْحَة كَانَت من السَّمَاء فبلوغها أَكثر\",1,\"1:123\"],\"K-138\":[\"فِي هَذِه السُّورَة ﴿نزل﴾ وَفِي غَيرهَا ﴿أنزل﴾ لِأَن أفعل كَمَا ذكرت آنِفا للتعدي وَفعل للتعدي والتكثير فَذكر فِي الْموضع الأول بِلَفْظ الْمُبَالغَة ليجري مجري ذكر الْجُمْلَة وَالتَّفْصِيل وَذكر الْجِنْس\",1,\"1:123\"],\"K-139\":[\"فِي هَذِه السُّورَة وَفِي غَيرهَا ﴿من الْجبَال﴾ لِأَن فِي هَذِه السُّورَة تقدمه ﴿من سهولها قصورا﴾ فَاكْتفى بذلك\",0,\"1:123\"],\"K-140\":[\"فِي هَذِه السُّورَة وَفِي غَيرهَا ﴿فسَاء مطر الْمُنْذرين﴾ لِأَن فِي هَذِه السُّورَة وَافق مَا بعده وَهُوَ قَوْله ﴿فَانْظُر كَيفَ كَانَ عَاقِبَة المفسدين﴾\",0,\"1:124\"],\"K-141\":[\"بالاستفهام وَهُوَ اسْتِفْهَام تقريع وتوبيخ وإنكار وَقَالَ بعده ﴿إِنَّكُم لتأتون الرِّجَال﴾ فَزَاد مَعَ الِاسْتِفْهَام ﴿إِن﴾ لِأَن التقريع والتوبيخ وَالْإِنْكَار فِي الثَّانِي أَكثر وَمثله فِي النَّمْل ﴿أتأتون﴾\",1,\"1:124\"],\"K-142\":[\"فِي هَذِه السُّورَة بِلَفْظ الِاسْم وَفِي النَّمْل ﴿قوم تجهلون﴾ بِلَفْظ الْفِعْل لِأَن كل إِسْرَاف جهل وكل جهل إِسْرَاف ثمَّ ختم الْآيَة بِلَفْظ الِاسْم مُوَافقَة لرءوس الْآيَات الَّتِي تقدّمت\",1,\"1:124\"],\"K-143\":[\"بِالْوَاو فِي هَذِه السُّورَة وَفِي غَيرهَا ﴿فَمَا﴾ بِالْفَاءِ لِأَن مَا قبله اسْم وَالْفَاء للتعقيب والتعقيب يكون مَعَ الْأَفْعَال فَقَالَ فِي النَّمْل ﴿تجهلون﴾ ﴿فَمَا كَانَ﴾\",1,\"1:125\"],\"K-144\":[\"فِي هَذِه السُّورَة وَفِي النَّمْل ﴿قدرناها من الغابرين﴾ أَي كَانَت فِي علم الله من الغابرين فقدرناها من الغابرين وعَلى وزن قَول الْخَطِيب قدرناها من الغابرين فَصَارَت من الغابرين وَكَانَ بِمَعْنى صَار وَقد\",1,\"1:125\"],\"K-145\":[\"فِي هَذِه السُّورَة وَفِي يُونُس ﴿بِمَا كذبُوا بِهِ﴾ لِأَن أول الْقِصَّة فِي هَذِه السُّورَة ﴿وَلَو أَن أهل الْقرى آمنُوا﴾ وَفِي الْآيَة ﴿وَلَكِن كذبُوا فأخذناهم﴾ وَلَيْسَ بعْدهَا الْبَاء\",1,\"1:125\"],\"K-146\":[\"هَهُنَا وَفِي يُونُس ﴿نطبع﴾ بالنُّون لِأَن فِي هَذِه السُّورَة قدم ذكر الله سُبْحَانَهُ بِالصَّرِيحِ وَالْكِنَايَة فَجمع بَينهمَا فَقَالَ ﴿ونطبع على قُلُوبهم﴾ بالنُّون وَختم الْآيَة بِالصَّرِيحِ\",1,\"1:126\"],\"K-147\":[\"وَفِي الشُّعَرَاء ﴿قَالَ للملإ حوله﴾ لِأَن التَّقْدِير فِي هَذِه الْآيَة قَالَ الْمَلأ من قوم فِرْعَوْن وَفرْعَوْن بعض لبَعض فَحذف فِرْعَوْن لاشتمال الْمَلأ من آل فِرْعَوْن على اسْمه كَمَا قَالَ\",1,\"1:126\"],\"K-148\":[\"وَفِي الشُّعَرَاء ﴿من أَرْضكُم بسحره﴾ لِأَن الْآيَة الأولى فِي هَذِه السُّورَة بنيت على الِاقْتِصَار وَكَذَلِكَ الْآيَة الثَّانِيَة وَلِأَن لفظ السَّاحر يدل على السحر\",0,\"1:127\"],\"K-149\":[\"وَفِي الشُّعَرَاء ﴿وَابعث﴾ لِأَن الْإِرْسَال يُفِيد معنى الْبَعْث ويتضمن نوعا من الْعُلُوّ لِأَنَّهُ يكون من فَوق فخصت هَذِه السُّورَة بِهِ لما الْتبس ليعلم أَن الْمُخَاطب بِهِ فِرْعَوْن دون غَيره\",0,\"1:127\"],\"K-150\":[\"وَفِي الشُّعَرَاء ﴿بِكُل سحار﴾ لِأَنَّهُ رَاعى مَا قبله فِي هَذِه السُّورَة وَهُوَ قَوْله ﴿إِن هَذَا لساحر عليم﴾ وراعى فِي الشُّعَرَاء الإِمَام فَإِنَّهُ فِيهِ ﴿بِكُل سحار﴾ بِالْألف\",1,\"1:127\"],\"K-151\":[\"وَفِي الشُّعَرَاء ﴿فَلَمَّا جَاءَ السَّحَرَة قَالُوا لفرعون﴾ لِأَن الْقيَاس فِي هَذِه السُّورَة فَلَمَّا جَاءَ السَّحَرَة فِرْعَوْن قَالُوا أَو فَقَالُوا لَا بُد من ذَلِك لَكِن أضمر فِيهِ ﴿فَلَمَّا﴾ فَحسن حذف الْفَاء\",1,\"1:127\"],\"K-152\":[\"وَفِي الشُّعَرَاء ﴿إِذا لمن المقربين﴾ لِأَن إِذا فِي هَذِه السُّورَة مضمرة مقدرَة لِأَن إِذا جَزَاء وَمَعْنَاهُ إِن غلبتم قربتكم وَرفعت منزلتكم وَخص هَذِه السُّورَة بالإضمار اختصارا\",0,\"1:127\"],\"K-153\":[\"وَفِي طه ﴿إِمَّا أَن تلقي وَإِمَّا أَن نَكُون أول من ألْقى﴾ رَاعى فِي السورتين أَو أخر\",1,\"1:128\"],\"K-154\":[\"وَفِي السورتين ﴿آمنتم لَهُ﴾ لِأَن الضَّمِير هُنَا يعود إِلَى رب الْعَالمين وَهُوَ الْمُؤمن بِهِ سُبْحَانَهُ وَفِي\",1,\"1:128\"],\"K-155\":[\"وَفِي السورتين ﴿قَالَ آمنتم﴾ لِأَن هَذِه السُّورَة متعقبة على السورتين فَصرحَ فِي الأولى وكنى فِي الْأُخْرَيَيْنِ وَهُوَ الْقيَاس قَالَ الْخَطِيب لِأَن فِي هَذِه السُّورَة بعد عَن ذكر فِرْعَوْن بآيَات فَصرحَ\",1,\"1:129\"],\"K-156\":[\"وَفِي السورتين ﴿ولأصلبنكم﴾ لِأَن ثمَّ تدل على أَن الصلب يَقع بعد التقطيع وَإِذا دلّ فِي الأولى علم فِي غَيرهَا وَلِأَن مَوضِع الْوَاو تصلح لَهُ ثمَّ\",0,\"1:129\"],\"K-157\":[\"وَفِي الشُّعَرَاء ﴿لَا ضير إِنَّا إِلَى رَبنَا منقلبون﴾ بِزِيَادَة ﴿لَا ضير﴾ لِأَن هَذِه السُّورَة اختصرت فِيهَا هَذِه الْقِصَّة وأشبعت فِي الشُّعَرَاء وَذكر فِيهَا أول أَحْوَال مُوسَى مَعَ فِرْعَوْن إِلَى آخرهَا\",1,\"1:129\"],\"K-158\":[\"بِغَيْر وَاو على الْبَدَل وَقد سبق\",0,\"1:129\"],\"K-159\":[\"بِإِثْبَات الْيَاء على\",1,\"1:129\"],\"K-160\":[\"بِإِثْبَات الْيَاء على\",1,\"1:129\"],\"K-161\":[\"ذكرت فِي الْمُتَشَابه وَلَيْسَت مِنْهُ لِأَنَّهَا من الْخَوْف ﴿وخفية﴾ من قَوْله تَعَالَى ﴿تَدعُونَهُ تضرعا وخفية﴾ من خَفِي الشَّيْء إِذا استتر\",0,\"1:131\"],\"K-162\":[\"وَقَوله ﴿وَمن يُشَاقق الله﴾ وَقَوله ﴿وَيكون الدّين كُله لله﴾ وَقد سبق قَوْله ﴿كدأب آل فِرْعَوْن وَالَّذين من قبلهم كفرُوا بآيَات الله﴾ ثمَّ قَالَ بعد آيَة\",1,\"1:131\"],\"K-163\":[\"وَقَوله ﴿وَمن يُشَاقق الله﴾ وَقَوله ﴿وَيكون الدّين كُله لله﴾ وَقد سبق قَوْله ﴿كدأب آل فِرْعَوْن وَالَّذين من قبلهم كفرُوا بآيَات الله﴾ ثمَّ قَالَ بعد آيَة\",1,\"1:131\"],\"K-164\":[\"فِي هَذِه السُّورَة بِتَقْدِيم ﴿بِأَمْوَالِهِمْ وأنفسهم﴾ وَفِي بَرَاءَة بِتَقْدِيم ﴿فِي سَبِيل الله﴾ لِأَن فِي هَذِه السُّورَة تقدم ذكر المَال وَالْفِدَاء\",1,\"1:132\"],\"K-165\":[\"لَيْسَ بتكرار لِأَن الأول للمكان وَالثَّانِي للزمان وَقد تقدم ذكرهمَا فِي قَوْله ﴿فسيحوا فِي الأَرْض أَرْبَعَة أشهر﴾\",0,\"1:133\"],\"K-166\":[\"لَيْسَ بتكرار لِأَن الأول فِي الْكفَّار وَالثَّانِي فِي الْيَهُود فِيمَن حمل قَوْله ﴿اشْتَروا بآيَات الله ثمنا قَلِيلا﴾ على التَّوْرَاة وَقيل هما فِي الْكفَّار وَجَزَاء الأول تخلية سبيلهم\",1,\"1:133\"],\"K-167\":[\"ثمَّ ذكر بعده ﴿كَيفَ وَإِن يظهروا عَلَيْكُم لَا يرقبوا فِيكُم إِلَّا وَلَا ذمَّة﴾ وَاقْتصر عَلَيْهِ فَذهب بَعضهم إِلَى أَنه تكْرَار للتَّأْكِيد وَاكْتفى بِذكر ﴿كَيفَ﴾ عَن الْجُمْلَة بعده لدلَالَة الأولى عَلَيْهِ\",1,\"1:133\"],\"K-168\":[\"وَقَوله ﴿لَا يرقبون فِي مُؤمن إِلَّا وَلَا ذمَّة﴾ الأول للْكفَّار وَالثَّانِي للْيَهُود وَقيل ذكر الأول وَجعل جَزَاء للشّرط ثمَّ أعَاد ذَلِك تقبيحا لَهُم\",1,\"1:134\"],\"K-169\":[\"إِنَّمَا قدم فِي سَبِيل الله فِي هَذِه السُّورَة لموافقة قَوْله قبله ﴿وَجَاهدُوا فِي سَبِيل الله﴾ وَقد سبق ذكره فِي الْأَنْفَال وَقد جَاءَ بعده فِي موضِعين\",1,\"1:134\"],\"K-170\":[\"بِزِيَادَة بَاء وَبعده ﴿إِنَّهُم كفرُوا بِاللَّه وَرَسُوله وماتوا﴾ بِغَيْر بَاء فيهمَا لِأَن الْكَلَام فِي الْآيَة الأولى إِيجَاب بعد نفي وَهُوَ الْغَايَة فِي بَاب التَّأْكِيد\",1,\"1:134\"],\"K-171\":[\"بِالْفَاءِ وَقَالَ فِي الْآيَة الْأُخْرَى ﴿وَلَا تعجبك أَمْوَالهم﴾ بِالْوَاو لِأَن الْفَاء تَتَضَمَّن معنى الْجَزَاء وَالْفِعْل الَّذِي قبله مُسْتَقْبل يتَضَمَّن معنى الشَّرْط\",1,\"1:134\"],\"K-172\":[\"بِزِيَادَة ﴿لَا﴾ وَقَالَ فِي الْأُخْرَى ﴿وَأَوْلَادهمْ﴾ بِغَيْر لَا لِأَنَّهُ لما أكد الْكَلَام الأول بِالْإِيجَابِ بعد النَّفْي وَهُوَ الْغَايَة\",1,\"1:135\"],\"K-173\":[\"وَقَالَ فِي الْأُخْرَى ﴿أَن يعذبهم﴾ لِأَن ﴿إِن﴾ فِي هَذِه الْآيَة مقدرَة وَهِي الناصبة للْفِعْل فَصَارَ فِي الْكَلَام هَهُنَا زِيَادَة كزيادة الْبَاء وَلَا فِي الْآيَة\",0,\"1:135\"],\"K-174\":[\"وَفِي الْآيَة الْأُخْرَى ﴿فِي الدُّنْيَا﴾ لِأَن الدُّنْيَا صفة الْحَيَاة فِي الْآيَتَيْنِ فَأثْبت الْمَوْصُوف وَالصّفة فِي الأولى وَحذف بِذكرِهِ فِي الأولى وَلَيْسَ الْآيَتَانِ مكررتين لِأَن الأولى فِي قوم\",1,\"1:135\"],\"K-175\":[\"وَفِي الصَّفّ ﴿ليطفئوا﴾ هَذِه الْآيَة تشبه قَوْله ﴿إِنَّمَا يُرِيد الله أَن يعذبهم﴾ و﴿ليعذبهم﴾ حذف اللَّام من الْآيَة الأولى لِأَن مُرَادهم إطفاء نور الله بأفواههم\",1,\"1:136\"],\"K-176\":[\"هَذِه الْكَلِمَات تقع على وَجْهَيْن أَحدهمَا ﴿ذَلِك الْفَوْز﴾ بِغَيْر ﴿هُوَ﴾ وَهُوَ فِي الْقُرْآن فِي سِتَّة مَوَاضِع فِي بَرَاءَة موضعان وَفِي يُونُس وَالْمُؤمن وَالدُّخَان وَالْحَدِيد\",1,\"1:136\"],\"K-177\":[\"ثمَّ قَالَ بعده ﴿وطبع الله﴾ لِأَن قَوْله ﴿وطبع﴾ مَحْمُول على رَأس الْمِائَة وَهُوَ قَوْله ﴿وَإِذا أنزلت سُورَة﴾ مَبْنِيّ للْمَجْهُول وَالثَّانِي مَحْمُول على مَا تقدم من ذكر الله تَعَالَى مَرَّات\",1,\"1:137\"],\"K-178\":[\"وَقَالَ فِي الْأُخْرَى ﴿فسيرى الله عَمَلكُمْ وَرَسُوله والمؤمنون وستردون﴾ لِأَن الأولى فِي الْمُنَافِقين وَلَا يطلع على ضمائرهم إِلَّا الله تَعَالَى ثمَّ رَسُوله بإطلاع الله إِيَّاه عَلَيْهَا كَقَوْلِه\",1,\"1:137\"],\"K-179\":[\"وَفِي الْأُخْرَى ﴿إِلَّا كتب لَهُم﴾ لِأَن الْآيَة الأولى مُشْتَمِلَة على مَا هُوَ من عَمَلهم وَهُوَ\",0,\"1:138\"],\"K-180\":[\"وَفِي هود ﴿إِلَى الله مرجعكم﴾ لِأَن مَا فِي هَذِه السُّورَة خطاب للْمُؤْمِنين والكافرين جَمِيعًا يدل عَلَيْهِ قَوْله بعده ﴿ليجزي الَّذين آمنُوا وَعمِلُوا الصَّالِحَات بِالْقِسْطِ وَالَّذين كفرُوا﴾ الْآيَة\",1,\"1:138\"],\"K-182\":[\"بِالْوَاو لِأَنَّهُ مَعْطُوف على قَوْله ﴿ظلمُوا﴾ من قَوْله ﴿لما ظلمُوا وجاءتهم رسلهم بِالْبَيِّنَاتِ﴾ وَفِي غَيرهَا بِالْفَاءِ للتعقيب\",0,\"1:139\"],\"K-183\":[\"بِالْفَاءِ لموافقة مَا قبلهَا وَقد سبق فِي الْأَنْعَام\",0,\"1:139\"],\"K-184\":[\"سبق فِي الْأَعْرَاف\",0,\"1:139\"],\"K-185\":[\"فِي هَذِه السُّورَة وَفِي غَيرهَا ﴿فِيمَا هم فِيهِ يَخْتَلِفُونَ﴾ بِزِيَادَة ﴿هم﴾ لِأَن فِي هَذِه السُّورَة تقدم ﴿فَاخْتَلَفُوا﴾ فَاكْتفى بِهِ عَن إِعَادَة الضَّمِير\",1,\"1:139\"],\"K-186\":[\"فِي هَذِه السُّورَة وَفِي غَيرهَا ﴿فِيمَا هم فِيهِ يَخْتَلِفُونَ﴾ بِزِيَادَة ﴿هم﴾ لِأَن فِي هَذِه السُّورَة تقدم ﴿فَاخْتَلَفُوا﴾ فَاكْتفى بِهِ عَن إِعَادَة الضَّمِير\",1,\"1:139\"],\"K-187\":[\"بِالْألف لِأَنَّهُ فِي مُقَابلَة ﴿أنجيتنا﴾\",0,\"1:140\"],\"K-188\":[\"وَفِي هود ﴿بِعشر سور مثله﴾ لِأَن مَا فِي هَذِه السُّورَة تَقْدِيره سُورَة مثل سُورَة يُونُس فالمضاف\",1,\"1:140\"],\"K-189\":[\"فِي هَذِه السُّورَة وَكَذَلِكَ فِي هود وَفِي الْبَقَرَة ﴿شهداءكم﴾ لِأَنَّهُ لما زَاد فِي هود السُّور زَاد فِي المدعوين وَلِهَذَا قَالَ فِي سُبْحَانَ\",1,\"1:140\"],\"K-190\":[\"بِلَفْظ الْجمع وَبعده ﴿وَمِنْهُم من ينظر إِلَيْك﴾ بِلَفْظ الْمُفْرد لِأَن المستمع إِلَى الْقُرْآن كالمستمع إِلَى النَّبِي ﷺ بِخِلَاف النّظر فَكَانَ فِي المستمعين كَثْرَة فَجمع ليطابق اللَّفْظ الْمَعْنى\",1,\"1:140\"],\"K-192\":[\"لِأَن التَّقْدِير فِيهَا لكل أمة أجل فَلَا يَسْتَأْخِرُونَ سَاعَة إِذا جَاءَ أَجلهم فَكَانَ هَذَا فِيمَن قتل ببدر وَالْمعْنَى لم يستأخروا\",0,\"1:141\"],\"K-193\":[\"ذكر بِلَفْظ ﴿مَا﴾ فِي هَذِه الْآيَة وَلم يكرره لِأَن معنى ﴿مَا﴾ هَهُنَا المَال فَذكر بِلَفْظ ﴿مَا﴾ دون ﴿من﴾ وَلم يكررها اكْتِفَاء بقوله قبله ﴿وَلَو أَن لكل نفس ظلمت مَا فِي الأَرْض﴾\",0,\"1:141\"],\"K-194\":[\"ذكر بِلَفْظ ﴿من﴾ وَكرر لِأَن هَذِه الْآيَة نزلت فِي قوم آذوا رَسُول الله صلى\",1,\"1:141\"],\"K-195\":[\"ذكر بِلَفْظ ﴿مَا﴾ وَكرر لِأَن بعض الْكفَّار قَالُوا ﴿اتخذ الله ولدا﴾ فَقَالَ سُبْحَانَهُ ﴿لَهُ مَا فِي السَّمَاوَات وَمَا فِي الأَرْض﴾ فَكَانَ الْموضع مَوضِع ﴿مَا﴾ وَمَوْضِع التّكْرَار للتَّأْكِيد والتخصيص\",0,\"1:141\"],\"K-196\":[\"وَمثله فِي النَّمْل وَفِي الْبَقَرَة ويوسف وَالْمُؤمن ﴿وَلَكِن أَكثر النَّاس لَا يشكرون﴾ لِأَن فِي هَذِه السُّورَة تقدم ﴿وَلَكِن أَكْثَرهم لَا يعلمُونَ﴾ فوافقه وَفِي غَيرهَا جَاءَ بِلَفْظ الصَّرِيح\",1,\"1:141\"],\"K-197\":[\"وَمثله فِي النَّمْل وَفِي الْبَقَرَة ويوسف وَالْمُؤمن ﴿وَلَكِن أَكثر النَّاس لَا يشكرون﴾ لِأَن فِي هَذِه السُّورَة تقدم ﴿وَلَكِن أَكْثَرهم لَا يعلمُونَ﴾ فوافقه وَفِي غَيرهَا جَاءَ بِلَفْظ الصَّرِيح\",1,\"1:141\"],\"K-198\":[\"وَمثله فِي النَّمْل وَفِي الْبَقَرَة ويوسف وَالْمُؤمن ﴿وَلَكِن أَكثر النَّاس لَا يشكرون﴾ لِأَن فِي هَذِه السُّورَة تقدم ﴿وَلَكِن أَكْثَرهم لَا يعلمُونَ﴾ فوافقه وَفِي غَيرهَا جَاءَ بِلَفْظ الصَّرِيح\",1,\"1:141\"],\"K-199\":[\"بِغَيْر وَاو وَلَو لِأَنَّهُ اكْتفى بِالْفَاءِ عَن الْوَاو العاطف وَمثله فِي الْبَقَرَة على قِرَاءَة ابْن عَامر ﴿قَالُوا اتخذ الله ولدا﴾\",0,\"1:142\"],\"K-200\":[\"سبق وَمثله فِي الْأَنْبِيَاء وَالشعرَاء\",0,\"1:142\"],\"K-201\":[\"سبق وَقَوله ﴿نطبع على﴾ قد سبق\",0,\"1:142\"],\"K-202\":[\"بِالْجمعِ وَفِي غَيرهَا ﴿ملئه﴾ لِأَن الضَّمِير فِي هَذِه السُّورَة يعود إِلَى الذُّرِّيَّة وَقيل يعود إِلَى الْقَوْم وَفِي غَيرهَا يعود إِلَى فِرْعَوْن\",0,\"1:142\"],\"K-203\":[\"وَفِي النَّمْل ﴿من الْمُسلمين﴾ لِأَن مَا قبله فِي هَذِه السُّورَة ﴿الْمُؤمنِينَ﴾ فوافقه وَفِي النَّمْل وَافق مَا قبله وَهُوَ قَوْله ﴿فهم مُسلمُونَ﴾ وَقد تقدم فِي يُونُس ﴿وَأمرت أَن أكون من الْمُسلمين﴾\",0,\"1:142\"],\"K-204\":[\"بِحَذْف النُّون وَالْجمع وَفِي الْقَصَص ﴿فَإِن لم﴾ بِإِثْبَات النُّون ﴿لَك فَاعْلَم﴾ على الْوَاحِد عدت هَذِه الْآيَة من الْمُتَشَابه فِي فصلين أَحدهمَا حذف النُّون من ﴿فَإِن لم﴾ فِي هَذِه السُّورَة\",1,\"1:143\"],\"K-205\":[\"سبق\",0,\"1:143\"],\"K-206\":[\"وَفِي النَّحْل ﴿هم الخاسرون﴾ لِأَن هَؤُلَاءِ صدوا عَن سَبِيل الله وصدوا غَيرهم فضلوا فهم الأخسرون يُضَاعف لَهُم الْعَذَاب وَفِي النَّحْل صدوا\",1,\"1:143\"],\"K-207\":[\"بِالْفَاءِ وَبعده ﴿فَقَالَ الْمَلأ﴾ بِالْفَاءِ وَهُوَ الْقيَاس وَقد سبق\",0,\"1:144\"],\"K-208\":[\"وَبعده ﴿وآتاني مِنْهُ رَحْمَة﴾\",1,\"1:144\"],\"K-209\":[\"فِي قصَّة نوح وَفِي غَيرهَا ﴿أجرا إِن أجري﴾ لِأَن فِي قصَّة نوح وَقع بعْدهَا ﴿خَزَائِن﴾ وَلَفظ المَال بالخزائن أليق قَوْله ﴿وَلَا أَقُول إِنِّي ملك﴾\",1,\"1:144\"],\"K-210\":[\"فِي قصَّة نوح وَفِي غَيرهَا ﴿أجرا إِن أجري﴾ لِأَن فِي قصَّة نوح وَقع بعْدهَا ﴿خَزَائِن﴾ وَلَفظ المَال بالخزائن أليق قَوْله ﴿وَلَا أَقُول إِنِّي ملك﴾\",1,\"1:144\"],\"K-211\":[\"وَفِي التَّوْبَة ﴿وَلَا تضروه شَيْئا﴾ ذكر هَذَا فِي الْمُتَشَابه وَلَيْسَ مِنْهُ لِأَن قَوْله ﴿وَلَا تضرونه شَيْئا﴾ عطف على قَوْله ﴿ويستخلف رَبِّي﴾ فَهُوَ مَرْفُوع وَفِي التَّوْبَة مَعْطُوف على ﴿يعذبكم﴾ ﴿يسْتَبْدل﴾\",1,\"1:145\"],\"K-212\":[\"فِي قصَّة هود وَشُعَيْب بِالْوَاو وَفِي قصَّة صَالح وَلُوط ﴿فَلَمَّا﴾ بِالْفَاءِ لِأَن الْعَذَاب فِي قصَّة هود وَشُعَيْب تَأَخّر عَن وَقت الْوَعيد فَإِن فِي قصَّة هود\",1,\"1:145\"],\"K-213\":[\"وَفِي قصَّة مُوسَى ﴿فِي هَذِه لعنة﴾ لِأَنَّهُ لما ذكر فِي الْآيَة الأولى الصّفة والموصوف اقْتصر فِي الثَّانِيَة على الْمَوْصُوف للْعلم والاكتفاء بِمَا قبله قَوْله ﴿إِن رَبِّي قريب مُجيب﴾ وَبعده\",1,\"1:145\"],\"K-214\":[\"وَفِي قصَّة مُوسَى ﴿فِي هَذِه لعنة﴾ لِأَنَّهُ لما ذكر فِي الْآيَة الأولى الصّفة والموصوف اقْتصر فِي الثَّانِيَة على الْمَوْصُوف للْعلم والاكتفاء بِمَا قبله قَوْله ﴿إِن رَبِّي قريب مُجيب﴾ وَبعده\",1,\"1:145\"],\"K-215\":[\"وَفِي إِبْرَاهِيم ﴿وَإِنَّا لفي شكّ مِمَّا تدعوننا إِلَيْهِ مريب﴾ لِأَنَّهُ فِي السورتين جَاءَ على الأَصْل وتدعونا خطاب مُفْرد وَفِي إِبْرَاهِيم لما وَقع بعده ﴿تدعوننا﴾ بنونين لِأَنَّهُ\",1,\"1:146\"],\"K-216\":[\"ثمَّ قَالَ ﴿وَأخذت الَّذين ظلمُوا﴾ التَّذْكِير والتأنيث حسنان لَكِن التَّذْكِير أخف فِي الأولى بِحَذْف حرف مِنْهُ وَفِي الْأُخْرَى وَافق مَا بعْدهَا وَهُوَ ﴿كَمَا بَعدت ثَمُود﴾\",1,\"1:146\"],\"K-217\":[\"فِي موضِعين فِي هَذِه السُّورَة لِأَنَّهُ اتَّصل بالصيحة وَكَانَت من السَّمَاء فازدادت على الرجفة لِأَنَّهَا الزلزلة وَهِي تخْتَص بِجُزْء من الأَرْض فَجمعت مَعَ الصَّيْحَة\",1,\"1:146\"],\"K-219\":[\"وَفِي الْقَصَص ﴿مهلك الْقرى﴾ لِأَن الله تَعَالَى نفى الظُّلم عَن نَفسه بأبلغ لفظ يسْتَعْمل فِي النَّفْي لِأَن هَذِه اللَّام لَام الْجُحُود وَتظهر بعْدهَا أَن وَلَا يَقع بعْدهَا الْمصدر وتختص بكان مَعْنَاهُ مَا\",1,\"1:147\"],\"K-220\":[\"وَفِي الْحجر ﴿بِقطع من اللَّيْل وَاتبع أدبارهم وَلَا يلْتَفت مِنْكُم أحد﴾ اسْتثْنى فِي هَذِه السُّورَة من الْأَهْل قَوْله ﴿إِلَّا امْرَأَتك﴾ وَلم يسْتَثْن فِي الْحجر اكْتِفَاء بِمَا قبله\",1,\"1:147\"],\"K-222\":[\"فِي هَذِه السُّورَة فِي موضِعين لَيْسَ بتكرار لِأَنَّهُ ذكر الأول حِين نعى إِلَيْهِ يُوسُف وَالثَّانِي لما رفع إِلَيْهِ مَا جرى على بنيامين\",0,\"1:148\"],\"K-223\":[\"وَمثلهَا فِي الْقَصَص فِي قصَّة مُوسَى وَزَاد فِيهَا ﴿واستوى﴾ لِأَن يُوسُف عليه السلام أوحى إِلَيْهِ وَهُوَ فِي الْبِئْر ومُوسَى عليه السلام أوحى إِلَيْهِ بعد أَرْبَعِينَ سنة\",1,\"1:148\"],\"K-223b\":[\"وَمثلهَا فِي الْقَصَص فِي قصَّة مُوسَى وَزَاد فِيهَا ﴿واستوى﴾ لِأَن يُوسُف عليه السلام أوحى إِلَيْهِ وَهُوَ فِي الْبِئْر ومُوسَى عليه السلام أوحى إِلَيْهِ بعد أَرْبَعِينَ سنة\",1,\"1:148\"],\"K-224\":[\"فِي هَذِه السُّورَة فِي موضِعين لَيْسَ بتكرار لِأَن الأول ذكر حِين دَعَتْهُ إِلَى المواقعة وَالثَّانِي حِين دعى إِلَى تَغْيِير حكم السّرقَة فَلَيْسَ بتكرار\",0,\"1:148\"],\"K-225\":[\"فِي الْمَوْضِعَيْنِ أَحدهمَا فِي حَضْرَة يُوسُف عليه السلام حِين نفين عَنهُ البشرية بزعمهن وَالثَّانِي بِظهْر الْغَيْب حِين نفين عَنهُ السوء فَلَيْسَ بتكرار قَوْله ﴿إِنَّا نرَاك من الْمُحْسِنِينَ﴾ فِي موضِعين\",1,\"1:148\"],\"K-226\":[\"فِي الْمَوْضِعَيْنِ أَحدهمَا فِي حَضْرَة يُوسُف عليه السلام حِين نفين عَنهُ البشرية بزعمهن وَالثَّانِي بِظهْر الْغَيْب حِين نفين عَنهُ السوء فَلَيْسَ بتكرار قَوْله ﴿إِنَّا نرَاك من الْمُحْسِنِينَ﴾ فِي موضِعين\",1,\"1:148\"],\"K-227\":[\"فِي موضِعين الأول مِنْهُمَا ذكره يُوسُف حِين عدل عَن جوابهما إِلَى دعائهما إِلَى الْإِيمَان وَالثَّانِي حِين دعياه إِلَى تَعْبِير الرُّؤْيَا لَهما تَنْبِيها على أَن الْكَلَام الأول قد تمّ\",0,\"1:149\"],\"K-228\":[\"كرر لَعَلَّ رِعَايَة لفواصل الْآي إِذْ لَو جَاءَ بِمُقْتَضى الْكَلَام لقَالَ لعَلي أرجع فيعلموا بِحَذْف النُّون على الْجَواب\",1,\"1:149\"],\"K-229\":[\"فِي أَرْبَعَة مَوَاضِع الأول يَمِين مِنْهُم أَنهم لَيْسُوا سارقين وَأَن أهل مصر بذلك عالمون وَالثَّانِي يَمِين مِنْهُم أَنَّك لَو واظبت على الْحزن تصير حرضا أَو تكون من الهالكين وَالثَّالِث يَمِين مِنْهُم أَن الله\",1,\"1:149\"],\"K-230\":[\"وَفِي الْأَنْبِيَاء ﴿وَمَا أرسلنَا قبلك﴾ بِغَيْر ﴿من﴾ لِأَن ﴿قبل﴾ اسْم للزمان السَّابِق على مَا أضيف إِلَيْهِ و﴿من﴾ تفِيد اسْتِيعَاب الطَّرفَيْنِ وَمَا فِي هَذِه السُّورَة للاستيعاب\",1,\"1:150\"],\"K-231\":[\"وَفِي الْأَنْبِيَاء ﴿وَمَا أرسلنَا قبلك﴾ بِغَيْر ﴿من﴾ لِأَن ﴿قبل﴾ اسْم للزمان السَّابِق على مَا أضيف إِلَيْهِ و﴿من﴾ تفِيد اسْتِيعَاب الطَّرفَيْنِ وَمَا فِي هَذِه السُّورَة للاستيعاب\",1,\"1:150\"],\"K-232\":[\"وَفِي الْأَعْرَاف ﴿وَالدَّار الْآخِرَة خير﴾ على الصّفة لِأَن فِي هَذِه السُّورَة تقدم ذكر السَّاعَة وَصَارَ التَّقْدِير ولدار السَّاعَة الْآخِرَة فَحذف الْمَوْصُوف\",1,\"1:150\"],\"K-233\":[\"وَفِي سُورَة لُقْمَان ﴿إِلَى أجل﴾ لَا ثَانِي لَهُ لِأَنَّك تَقول فِي الزَّمَان جرى ليَوْم كَذَا وَإِلَى يَوْم كَذَا وَالْأَكْثَر اللَّام كَمَا فِي هَذِه السُّورَة وَسورَة الْمَلَائِكَة\",1,\"1:151\"],\"K-233b\":[\"وَفِي سُورَة لُقْمَان ﴿إِلَى أجل﴾ لَا ثَانِي لَهُ لِأَنَّك تَقول فِي الزَّمَان جرى ليَوْم كَذَا وَإِلَى يَوْم كَذَا وَالْأَكْثَر اللَّام كَمَا فِي هَذِه السُّورَة وَسورَة الْمَلَائِكَة\",1,\"1:151\"],\"K-234\":[\"وَبعدهَا ﴿إِن فِي ذَلِك لآيَات لقوم يعْقلُونَ﴾ لِأَن بالتفكر فِي الْآيَات يعقل مَا جعلت الْآيَات دَلِيلا عَلَيْهِ فَهُوَ الأول الْمُؤَدِّي إِلَى الثَّانِي\",0,\"1:151\"],\"K-235\":[\"فِي هَذِه السُّورَة فِي موضِعين وَزَعَمُوا أَنه لَا ثَالِث لَهما لَيْسَ بتكرار مَحْض لِأَن المُرَاد بِالْأولِ آيَة مِمَّا اقترحوا نَحْو مَا فِي قَوْله ﴿لن نؤمن لَك حَتَّى تفجر لنا من الأَرْض ينبوعا﴾\",1,\"1:151\"],\"K-236\":[\"فِي هَذِه السُّورَة فِي موضِعين وَزَعَمُوا أَنه لَا ثَالِث لَهما لَيْسَ بتكرار مَحْض لِأَن المُرَاد بِالْأولِ آيَة مِمَّا اقترحوا نَحْو مَا فِي قَوْله ﴿لن نؤمن لَك حَتَّى تفجر لنا من الأَرْض ينبوعا﴾\",1,\"1:151\"],\"K-237\":[\"قد سبق\",0,\"1:152\"],\"K-239\":[\"وَفِي الْمَائِدَة ﴿ليفتدوا بِهِ﴾ لِأَن لَو وجوابها يتصلان بالماضي فَقَالَ فِي هَذِه السُّورَة ﴿لافتدوا بِهِ﴾ وَجَوَابه فِي الْمَائِدَة ﴿مَا تقبل مِنْهُم﴾ وَهُوَ بِلَفْظ الْمَاضِي وَقَوله ﴿ليفتدوا بِهِ﴾ عِلّة\",1,\"1:152\"],\"K-240\":[\"فِي موضِعين من هَذِه السُّورَة لَيْسَ بتكرار لِأَن الأول مُتَّصِل بقوله ﴿يصلونَ﴾ وَعطف عَلَيْهِ ﴿ويخشون﴾ وَالثَّانِي مُتَّصِل بقوله ﴿يقطعون﴾ وَعطف عَلَيْهِ ﴿ويفسدون﴾\",0,\"1:153\"],\"K-241\":[\"وَمثله فِي الْمُؤمن لَيْسَ بتكرار قَالَ ابْن عَبَّاس عيروا رَسُول الله ﷺ باشتغاله بِالنِّكَاحِ والتكثر مِنْهُ فَأنْزل الله تَعَالَى\",1,\"1:153\"],\"K-242\":[\"مَقْطُوع وَفِي سَائِر الْقُرْآن ﴿وَأما﴾ موصل وَهُوَ من اللهجات وَقد ذكر فِي مَوْضِعه\",0,\"1:153\"],\"K-243\":[\"بواو الْعَطف قد سبق وَالله أعلم\",0,\"1:153\"],\"K-244\":[\"بنُون وَاحِدَة و﴿تدعوننا﴾ بنونين على الْقيَاس وَقد سبق فِي هود قَوْله ﴿فَليَتَوَكَّل الْمُؤْمِنُونَ﴾ وَبعده ﴿فَليَتَوَكَّل المتوكلون﴾ لِأَن الْإِيمَان سَابق على التَّوَكُّل لِأَن على من صفة الْقُدْرَة\",1,\"1:153\"],\"K-245\":[\"بنُون وَاحِدَة و﴿تدعوننا﴾ بنونين على الْقيَاس وَقد سبق فِي هود قَوْله ﴿فَليَتَوَكَّل الْمُؤْمِنُونَ﴾ وَبعده ﴿فَليَتَوَكَّل المتوكلون﴾ لِأَن الْإِيمَان سَابق على التَّوَكُّل لِأَن على من صفة الْقُدْرَة\",1,\"1:153\"],\"K-246\":[\"وَقَالَ فِي الْبَقَرَة ﴿لَا يقدرُونَ على شَيْء مِمَّا كسبوا﴾ لِأَن الأَصْل مَا فِي الْبَقَرَة\",0,\"1:154\"],\"K-247\":[\"وَفِي النَّمْل ﴿وَأنزل لكم من السَّمَاء مَاء﴾ بِزِيَادَة لكم لِأَن ﴿لكم﴾ فِي هَذِه السُّورَة مَذْكُور فِي آخر الْآيَة فَاكْتفى بِذكرِهِ وَلم يكن فِي النَّمْل فِي آخرهَا فَذكر فِي أَولهَا\",1,\"1:154\"],\"K-250\":[\"هُنَا وَفِي ص وَفِي الْبَقَرَة ﴿وَإِذ قَالَ رَبك للْمَلَائكَة إِنِّي جَاعل﴾ وَلَا ثَالِث لَهما لِأَن جعل إِذا كَانَ بِمَعْنى خلق يسْتَعْمل فِي الشَّيْء يَتَجَدَّد ويتكرر كَقَوْلِه\",1,\"1:155\"],\"K-251\":[\"فِي هَذِه وَفِي ص لِأَنَّهُ لما بَالغ فِي السورتين فِي الْأَمر بِالسُّجُود وَهُوَ قَوْله ﴿فقعوا لَهُ ساجدين﴾ فِي السورتين بَالغ فِي الِامْتِثَال فيهمَا\",1,\"1:155\"],\"K-252\":[\"بِالْألف وَاللَّام وَفِي ص ﴿وَإِن عَلَيْك لَعْنَتِي﴾ بِالْإِضَافَة لِأَن الْكَلَام فِي هَذِه السُّورَة جرى على الْجِنْس من أول الْقِصَّة فِي قَوْله ﴿وَلَقَد خلقنَا الْإِنْسَان﴾ ﴿والجان خلقناه﴾ ﴿فَسجدَ الْمَلَائِكَة كلهم﴾\",1,\"1:155\"],\"K-253\":[\"وَزَاد فِي هَذِه السُّورَة ﴿إخْوَانًا﴾ لِأَنَّهَا نزلت فِي أَصْحَاب رَسُول الله ﷺ وَمَا سواهَا عَام فِي الْمُؤمنِينَ قَوْله فِي قصَّة إِبْرَاهِيم\",1,\"1:155\"],\"K-254\":[\"وَزَاد فِي هَذِه السُّورَة ﴿إخْوَانًا﴾ لِأَنَّهَا نزلت فِي أَصْحَاب رَسُول الله ﷺ وَمَا سواهَا عَام فِي الْمُؤمنِينَ قَوْله فِي قصَّة إِبْرَاهِيم\",1,\"1:155\"],\"K-255\":[\"قد سبق\",0,\"1:156\"],\"K-256\":[\"وَفِي غَيرهَا ﴿وأمطرنا عَلَيْهَا﴾ قَالَ بعض الْمُفَسّرين عَلَيْهِم أَي على أَهلهَا وَقَالَ بَعضهم على من شَذَّ من الْقرْيَة مِنْهُم\",1,\"1:156\"],\"K-257\":[\"بِالْجمعِ وَبعدهَا ﴿لآيَة للْمُؤْمِنين﴾ على التَّوْحِيد\",1,\"1:156\"],\"K-258\":[\"بِالْجمعِ وَفِي خمس مَوَاضِع ﴿إِن فِي ذَلِك لآيَة﴾ على الْوحدَة أما الْجمع فلموافقة قَوْله ﴿مسخرات﴾ فِي الْآيَتَيْنِ لتقع الْمُوَافقَة فِي اللَّفْظ وَالْمعْنَى وَأما التَّوْحِيد فلتوحيد الْمَدْلُول عَلَيْهِ\",1,\"1:157\"],\"K-259\":[\"مَا فِي هَذِه السُّورَة جَاءَ على الْقيَاس فَإِن الْفلك الْمَفْعُول الأول لترى ومواخر الْمَفْعُول الثَّانِي وَفِيه ظروف وَحقه التَّأَخُّر\",1,\"1:158\"],\"K-260\":[\"وَبعده ﴿وَقيل للَّذين اتَّقوا مَاذَا أنزل ربكُم قَالُوا خيرا﴾ إِنَّمَا رفع الأول لأَنهم أَنْكَرُوا إِنْزَال الْقُرْآن فعدلوا عَن الْجَواب فَقَالُوا ﴿أساطير الْأَوَّلين﴾ وَالثَّانِي من كَلَام الْمُتَّقِينَ\",1,\"1:159\"],\"K-261\":[\"لَيْسَ لَهُ فِي الْقُرْآن نَظِير الْفَاء للْعَطْف على فَاء التعقيب فِي قَوْله ﴿فادخلوا أَبْوَاب جَهَنَّم﴾ وَاللَّام للتَّأْكِيد يجْرِي مجْرى الْقسم مُوَافقَة لقَوْله ﴿ولنعم دَار الْمُتَّقِينَ﴾ وَلَيْسَ لَهُ نَظِير\",1,\"1:159\"],\"K-262\":[\"هُنَا وَفِي الجاثية\",1,\"1:159\"],\"K-263\":[\"هُنَا وَفِي الجاثية\",1,\"1:159\"],\"K-264\":[\"قد سبق\",0,\"1:160\"],\"K-265\":[\"قد سبق أَيْضا\",0,\"1:160\"],\"K-266\":[\"وَمثله فِي الرّوم وَفِي العنكبوت ﴿وليتمتعوا فَسَوف يعلمُونَ﴾ بِاللَّامِ وَالْيَاء أما التَّاء فِي السورتين فبإضمار القَوْل أَي قل لَهُم تمَتَّعُوا كَمَا فِي قَوْله ﴿قل تمَتَّعُوا فَإِن مصيركم إِلَى النَّار﴾\",1,\"1:160\"],\"K-267\":[\"وَفِي الْمَلَائِكَة ﴿بِمَا كسبوا مَا ترك على ظهرهَا﴾ الْهَاء فِي هَذِه\",1,\"1:160\"],\"K-267b\":[\"وَفِي الْمَلَائِكَة ﴿بِمَا كسبوا مَا ترك على ظهرهَا﴾ الْهَاء فِي هَذِه\",1,\"1:160\"],\"K-268\":[\"وَفِي الْمُؤمنِينَ ﴿فِي بطونها﴾ لِأَن الضَّمِير فِي هَذِه السُّورَة يعود إِلَى الْبَعْض وَهُوَ الْإِنَاث لِأَن اللَّبن لَا يكون للْكُلّ فَصَارَ تَقْدِير الْآيَة\",1,\"1:162\"],\"K-269\":[\"وَفِي العنكبوت ﴿يكفرون﴾ بِغَيْر ﴿هم﴾ لِأَن فِي هَذِه السُّورَة اتَّصل ﴿وَالله جعل لكم من أَنفسكُم أَزْوَاجًا وَجعل لكم من أزواجكم بَنِينَ وحفدة ورزقكم من الطَّيِّبَات﴾ ثمَّ عَاد إِلَى الْغَيْبَة\",1,\"1:162\"],\"K-270\":[\"كرر ﴿إِن﴾ وَكَذَلِكَ فِي الْآيَة الْأُخْرَى ﴿ثمَّ إِن رَبك﴾ لِأَن الْكَلَام لما طَال بصلته أعَاد إِن وَاسْمهَا وَثمّ وَذكر الْخَبَر وَمثله ﴿أيعدكم أَنكُمْ إِذا متم وكنتم تُرَابا وعظاما أَنكُمْ مخرجون﴾ أعَاد أَن\",1,\"1:162\"],\"K-271\":[\"وَفِي النَّمْل ﴿وَلَا تكن﴾ بِإِثْبَات النُّون هَذِه الْكَلِمَة كثر دورها فِي الْكَلَام فَحذف النُّون مِنْهَا تَخْفِيفًا من غير قِيَاس بل تَشْبِيها بحروف الْعلَّة\",1,\"1:163\"],\"K-272\":[\"وخصت سُورَة الْكَهْف بقوله ﴿أجرا حسنا﴾ لِأَن الْأجر فِي السورتين الْجنَّة وَالْكَبِير وَالْحسن من أوصافها لَكِن خصت هَذِه السُّورَة بالكبير مُوَافقَة لفواصل الْآي قبلهَا وَبعدهَا وَهِي ﴿حَصِيرا﴾ أَلِيمًا عجولا وجلها\",1,\"1:163\"],\"K-273\":[\"وَقَوله ﴿وَلَا تجْعَل يدك مغلولة إِلَى عُنُقك وَلَا تبسطها كل الْبسط فتقعد ملوما محسورا﴾ وَقَوله ﴿وَلَا تجْعَل مَعَ الله إِلَهًا آخر فَتلقى فِي جَهَنَّم ملوما مَدْحُورًا﴾ فِيهَا بعض الْمُتَشَابه وَيُشبه التّكْرَار\",1,\"1:164\"],\"K-274\":[\"وَفِي آخر السُّورَة ﴿وَلَقَد صرفنَا للنَّاس فِي هَذَا الْقُرْآن﴾ إِنَّمَا لم يذكر فِي أول سُبْحَانَ ﴿للنَّاس﴾ لتقدم ذكرهم فِي السُّورَة وَذكرهمْ فِي آخر السُّورَة\",1,\"1:164\"],\"K-275\":[\"ثمَّ أَعَادَهَا فِي أخر السُّورَة بِعَينهَا من غير زِيَادَة وَلَا نُقْصَان لِأَن هَذَا لَيْسَ بتكرار فَإِن الأول من كَلَامهم فِي الدُّنْيَا حِين جادلوا الرَّسُول وأنكروا الْبَعْث\",1,\"1:165\"],\"K-276\":[\"وَفِي الْكَهْف ﴿ذَلِك جزاؤهم جَهَنَّم بِمَا كفرُوا﴾ اقْتصر فِي هَذِه السُّورَة على الْإِشَارَة لتقدم ذكر جَهَنَّم\",1,\"1:165\"],\"K-277\":[\"وَفِي سبأ ﴿ادعوا الَّذين زعمتم من دون الله﴾ لِأَنَّهُ يعود إِلَى الرب فِي هَذِه السُّورَة وَقد تقدم ذكره فِي الْآيَة الأولى وَهُوَ قَوْله ﴿وَرَبك أعلم﴾\",1,\"1:166\"],\"K-278\":[\"وَفِي غَيرهَا ﴿أَرَأَيْت﴾ لِأَن ترادف الْخطاب يدل على أَن الْمُخَاطب بِهِ أَمر عَظِيم وخطب فظيع وَهَكَذَا هُوَ فِي هَذِه السُّورَة لِأَنَّهُ لَعنه الله ضمن أخطال ذُرِّيَّة بني آدم عَن آخِرهم لَا قَلِيلا\",1,\"1:166\"],\"K-279\":[\"وَفِي الْكَهْف بِزِيَادَة ﴿ويستغفروا رَبهم﴾ لِأَن مَا فِي هَذِه السُّورَة مَعْنَاهُ مَا مَنعهم عَن الْإِيمَان بِمُحَمد ﷺ إِلَّا قَوْلهم ﴿أبْعث الله بشرا رَسُولا﴾ هلا بعث ملكا وجهلوا أَن التجانس يُورث التآنس\",1,\"1:166\"],\"K-280\":[\"وَفِي العنكبوت ﴿قل كفى بِاللَّه بيني وَبَيْنكُم شَهِيدا﴾ كَمَا فِي الْفَتْح ﴿وَكفى بِاللَّه شَهِيدا﴾\",1,\"1:167\"],\"K-281\":[\"وَفِي الْأَحْقَاف ﴿بِقَادِر﴾ وَفِي يس لِأَن مَا فِي هَذِه السُّورَة خبر أَن وَمَا فِي يس خبر لَيْسَ فَدخل الْبَاء الْخَبَر وَكَانَ الْقيَاس أَلا يدْخل فِي ﴿حم﴾ الْأَحْقَاف وَلكنه شابه لَيْسَ لما ترادف النَّفْي\",1,\"1:167\"],\"K-282\":[\"قَابل مُوسَى عليه السلام كل كلمة من فِرْعَوْن بِكَلِمَة من نَفسه فَقَالَ ﴿وَإِنِّي لأظنك يَا فِرْعَوْن مثبورا﴾\",0,\"1:168\"],\"K-284\":[\"وَفِي حم فصلت ﴿وَلَئِن رجعت إِلَى رَبِّي﴾ لِأَن الرَّد عَن الشَّيْء يتَضَمَّن كَرَاهَة الْمَرْدُود وَلما كَانَ فِي الْكَهْف تَقْدِيره\",1,\"1:169\"],\"K-285\":[\"وَفِي السَّجْدَة ﴿ثمَّ أعرض عَنْهَا﴾ لِأَن الْفَاء للتعقيب وَثمّ للتراخي وَمَا فِي هَذِه السُّورَة فِي الْأَحْيَاء من الْكفَّار إِذْ ذكرُوا فأعرضوا عقيب مَا ذكرُوا ونسوا ذنوبهم وهم بعد متوقع مِنْهُم أَن يُؤمنُوا\",1,\"1:169\"],\"K-286\":[\"وَفِي الْآيَة الثَّالِثَة ﴿وَاتخذ سَبيله﴾ لِأَن الْفَاء للتعقيب والعطف فَكَانَ اتِّخَاذ الْحُوت للسبيل عقيب النسْيَان فَذكر بِالْفَاءِ\",1,\"1:170\"],\"K-287\":[\"وَبعده ﴿لقد جِئْت شَيْئا نكرا﴾\",1,\"1:170\"],\"K-074b\":[\"وَبعده ﴿لقد جِئْت شَيْئا نكرا﴾\",1,\"1:170\"],\"K-288\":[\"وَبعده ﴿ألم أقل لَك إِنَّك﴾ لِأَن الْإِنْكَار فِي الثَّانِيَة أَكثر وَقيل أكد التَّقْدِير الثَّانِي بقوله لَك كَمَا تَقول لمن توبخه لَك أَقُول وَإِيَّاك أَعنِي\",1,\"1:170\"],\"K-289\":[\"وَفِي الثَّانِي ﴿فأردنا أَن يبدلهما ربهما﴾ وَفِي الثَّالِث ﴿فَأَرَادَ رَبك أَن يبلغَا أشدهما﴾ لِأَن الأول فِي الظَّاهِر إِفْسَاد فأسنده إِلَى نَفسه وَالثَّالِث إنعام مَحْض فأسنده إِلَى الله عز وجل\",1,\"1:170\"],\"K-289b\":[\"وَفِي الثَّانِي ﴿فأردنا أَن يبدلهما ربهما﴾ وَفِي الثَّالِث ﴿فَأَرَادَ رَبك أَن يبلغَا أشدهما﴾ لِأَن الأول فِي الظَّاهِر إِفْسَاد فأسنده إِلَى نَفسه وَالثَّالِث إنعام مَحْض فأسنده إِلَى الله عز وجل\",1,\"1:170\"],\"K-291\":[\"وَبعده ﴿وَلم يَجْعَلنِي جبارا شقيا﴾ لِأَن الأول فِي حق يحيى وَجَاء فِي الْخَبَر عَن النَّبِي ﷺ مَا من أحد من بني آدم إِلَّا أذْنب أَو هم بذنب إِلَّا يحيى ابْن زَكَرِيَّا عليهما السلام فنفى عَنهُ الْعِصْيَان\",1,\"1:171\"],\"K-292\":[\"فِي قصَّة يحيى ﴿وَالسَّلَام عَليّ﴾ فِي قصَّة عِيسَى فنكر فِي الأول وَعرف فِي الثَّانِي لِأَن الأول من الله تَعَالَى والقليل مِنْهُ كثير كَمَا قَالَ الشَّاعِر\",1,\"1:172\"],\"K-293\":[\"فِي قصَّة يحيى ﴿وَالسَّلَام عَليّ﴾ فِي قصَّة عِيسَى فنكر فِي الأول وَعرف فِي الثَّانِي لِأَن الأول من الله تَعَالَى والقليل مِنْهُ كثير كَمَا قَالَ الشَّاعِر\",1,\"1:172\"],\"K-294\":[\"وَفِي الْفرْقَان ﴿وَعمل عملا صَالحا﴾ لِأَن فِي هَذِه السُّورَة أوجز فِي ذكر الْمعاصِي فأوجز فِي التَّوْبَة وَأطَال هُنَاكَ فَأطَال\",0,\"1:173\"],\"K-295\":[\"﴿إِذْ رأى نَارا فَقَالَ لأَهله امكثوا إِنِّي آنست نَارا لعَلي آتيكم مِنْهَا بقبس أَو أجد على النَّار هدى﴾ وَفِي النَّمْل\",1,\"1:173\"],\"K-296\":[\"هُنَا وَفِي النَّمْل ﴿فَلَمَّا جاءها﴾ وَفِي الْقَصَص ﴿أَتَاهَا﴾ لِأَن أَتَى وَجَاء بِمَعْنى وَاحِد لَكِن كثر دور الْإِتْيَان فِي طه نَحْو ﴿فَأتيَاهُ﴾ ﴿فلنأتينك﴾ ﴿ثمَّ أَتَى﴾ ﴿ثمَّ ائْتُوا﴾ ﴿حَيْثُ أَتَى﴾\",1,\"1:174\"],\"K-297\":[\"وَفِي الْقَصَص ﴿فرددناه﴾ لِأَن الرجع إِلَى الشَّيْء وَالرَّدّ إِلَيْهِ بِمَعْنى وَالرَّدّ على الشَّيْء يَقْتَضِي كَرَاهَة الْمَرْدُود وَلَفظ الرجع ألطف فَخص بطه\",1,\"1:174\"],\"K-298\":[\"وَفِي الْقَصَص ﴿فرددناه﴾ لِأَن الرجع إِلَى الشَّيْء وَالرَّدّ إِلَيْهِ بِمَعْنى وَالرَّدّ على الشَّيْء يَقْتَضِي كَرَاهَة الْمَرْدُود وَلَفظ الرجع ألطف فَخص بطه\",1,\"1:174\"],\"K-299\":[\"وَفِي الشُّعَرَاء ﴿أَن ائْتِ الْقَوْم الظَّالِمين﴾ ﴿قوم فِرْعَوْن أَلا يَتَّقُونَ﴾ وَفِي الْقَصَص ﴿فذانك برهانان من رَبك إِلَى فِرْعَوْن وملئه﴾ لِأَن طه هِيَ السَّابِقَة وَفرْعَوْن هُوَ الأَصْل الْمَبْعُوث إِلَيْهِ\",1,\"1:175\"],\"K-300\":[\"صرح بالعقدة فِي هَذِه السُّورَة لِأَنَّهَا السَّابِقَة وَفِي الشُّعَرَاء ﴿وَلَا ينْطَلق لساني﴾ كِنَايَة عَن الْعقْدَة بِمَا يقرب من التَّصْرِيح وَفِي الْقَصَص ﴿وَأخي هَارُون هُوَ أفْصح مني لِسَانا﴾\",1,\"1:175\"],\"K-301\":[\"صرح بالعقدة فِي هَذِه السُّورَة لِأَنَّهَا السَّابِقَة وَفِي الشُّعَرَاء ﴿وَلَا ينْطَلق لساني﴾ كِنَايَة عَن الْعقْدَة بِمَا يقرب من التَّصْرِيح وَفِي الْقَصَص ﴿وَأخي هَارُون هُوَ أفْصح مني لِسَانا﴾\",1,\"1:175\"],\"K-302\":[\"﴿هَارُون أخي﴾ صرح بالوزير لِأَنَّهَا الأولى فِي الذّكر وكنى عَنهُ فِي الشُّعَرَاء حَيْثُ قَالَ ﴿فَأرْسل إِلَى هَارُون﴾ ليأتيني فَيكون لي وزيرا وَفِي الْقَصَص ﴿فَأرْسلهُ معي ردْءًا يصدقني﴾ أَي اجْعَلْهُ لي وزيرا\",1,\"1:176\"],\"K-303\":[\"وَبعده ﴿إِنَّا رَسُول رب الْعَالمين﴾ لِأَن الرَّسُول مصدر يُسمى بِهِ فَحَيْثُ وَحده حمله على الْمصدر وَحَيْثُ ثنى حمل على الِاسْم\",1,\"1:176\"],\"K-304\":[\"بِالْفَاءِ من غير ﴿من﴾ وَفِي السَّجْدَة بِالْوَاو وَبعده ﴿من﴾ لِأَن الْفَاء للتعقيب والاتصال بِالْأولِ فطال الْكَلَام فَحسن حذف ﴿من﴾ وَالْوَاو تدل على الِاسْتِئْنَاف وَإِثْبَات ﴿من﴾ مستثقل\",1,\"1:176\"],\"K-305\":[\"وَفِي الشُّعَرَاء ﴿وَمَا يَأْتِيهم من ذكر من الرَّحْمَن مُحدث﴾ خصت هَذِه السُّورَة\",1,\"1:176\"],\"K-306\":[\"وَبعده ﴿وَمَا أرسلنَا من قبلك﴾ كِلَاهُمَا لاستيعاب الزَّمَان الْمُتَقَدّم إِلَّا أَن ﴿من﴾ إِذا دخل دلّ على الْحصْر بَين الحدين وَضَبطه بِذكر الطَّرفَيْنِ وَلم يَأْتِ ﴿وَمَا أرسلنَا قبلك﴾ إِلَّا هَذِه\",1,\"1:177\"],\"K-307\":[\"وَفِي العنكبوت ﴿ثمَّ إِلَيْنَا ترجعون﴾ لِأَن ثمَّ للتراخي وَالرُّجُوع هُوَ الرُّجُوع إِلَى الْجنَّة أَو النَّار وَذَلِكَ فِي الْقِيَامَة فخصت سُورَة العنكبوت بِهِ\",1,\"1:177\"],\"K-208b\":[\"وَفِي العنكبوت ﴿ثمَّ إِلَيْنَا ترجعون﴾ لِأَن ثمَّ للتراخي وَالرُّجُوع هُوَ الرُّجُوع إِلَى الْجنَّة أَو النَّار وَذَلِكَ فِي الْقِيَامَة فخصت سُورَة العنكبوت بِهِ\",1,\"1:177\"],\"K-309\":[\"﴿قَالُوا وجدنَا آبَاءَنَا﴾ وَفِي الشُّعَرَاء ﴿قَالُوا بل وجدنَا﴾ بِزِيَادَة ﴿بل﴾ لِأَن قَوْله ﴿وجدنَا آبَاءَنَا﴾ جَوَاب لقَوْله ﴿مَا هَذِه التماثيل﴾\",1,\"1:178\"],\"K-310\":[\"وَفِي الصافات ﴿الأسفلين﴾ لِأَن فِي هَذِه السُّورَة كادهم إِبْرَاهِيم عليه السلام بقوله ﴿لأكيدن أصنامكم﴾ وكادوا هم إِبْرَاهِيم بقوله ﴿وَأَرَادُوا بِهِ كيدا﴾ فجرت بَينهم مكايده فغلهم إِبْرَاهِيم لِأَنَّهُ كسر أصنامهم\",1,\"1:178\"],\"K-311\":[\"بِالْفَاءِ سبق فِي يُونُس وَمثله فِي الشُّعَرَاء ﴿فنجيناه وَأَهله أَجْمَعِينَ﴾ ﴿إِلَّا عجوزا فِي الغابرين﴾\",0,\"1:179\"],\"K-312\":[\"ختم الْقِصَّة بقوله ﴿رَحْمَة من عندنَا﴾ وَقَالَ فِي ص ﴿رَحْمَة منا﴾ لِأَنَّهُ هُنَا بَالغ فِي التضرع بقوله ﴿وَأَنت أرْحم الرَّاحِمِينَ﴾ فَبَالغ سُبْحَانَهُ فِي الْإِجَابَة\",1,\"1:179\"],\"K-313\":[\"﴿وتقطعوا﴾ وَفِي الْمُؤمنِينَ ﴿فاتقون﴾ ﴿فتقطعوا﴾ لِأَن الْخطاب فِي هَذِه السُّورَة للْكفَّار فَأَمرهمْ بِالْعبَادَة الَّتِي هِيَ التَّوْحِيد ثمَّ قَالَ ﴿وتقطعوا﴾ بِالْوَاو لِأَن التقطع قد كَانَ مِنْهُم قبل هَذَا القَوْل\",1,\"1:179\"],\"K-314\":[\"وَفِي التَّحْرِيم\",1,\"1:180\"],\"K-316\":[\"فِي هَذِه السُّورَة وَفِي لُقْمَان ﴿وَلَا هدى وَلَا كتاب مُنِير﴾ لِأَن مَا فِي هَذِه السُّورَة وَافق مَا قبلهَا من الْآيَات وَهِي ﴿قدير﴾ ﴿الْقُبُور﴾ وَكَذَلِكَ فِي لُقْمَان وَافق مَا قبلهَا وَمَا بعْدهَا\",1,\"1:180\"],\"K-317\":[\"بِزِيَادَة ﴿من﴾ لقَوْله تَعَالَى ﴿من تُرَاب ثمَّ من نُطْفَة﴾ الْآيَة وَقد سبق فِي النَّحْل\",0,\"1:180\"],\"K-318\":[\"وَفِي غَيرهَا ﴿أَيْدِيكُم﴾ لِأَن هَذِه الْآيَة نزلت فِي النَّضر بن الْحَارِث وَقيل فِي أبي جهل فوحده وَفِي غَيرهَا نزلت فِي الْجَمَاعَة الَّتِي تقدم ذكرهم\",0,\"1:180\"],\"K-319\":[\"وَقَالَ فِي الْحَج ﴿وَالصَّابِئِينَ وَالنَّصَارَى﴾ وَقَالَ فِي الْمَائِدَة ﴿والصابئون وَالنَّصَارَى﴾ لِأَن النَّصَارَى مقدمون على الصابئين فِي الرُّتْبَة لأَنهم أهل كتاب فَقَدمهُمْ فِي الْبَقَرَة\",1,\"1:75\"],\"K-320\":[\"سبق فِي الرَّعْد\",0,\"1:181\"],\"K-321\":[\"وَفِي السَّجْدَة ﴿مِنْهَا أعيدوا فِيهَا﴾ لِأَن المُرَاد بالغم الكرب وَالْأَخْذ بِالنَّفسِ حَتَّى لَا يجد صَاحبه متنفسا وَمَا قبله من الْآيَات يَقْتَضِي ذَلِك\",1,\"1:181\"],\"K-322\":[\"وَفِي السَّجْدَة ﴿وَقيل لَهُم ذوقوا﴾ القَوْل هَهُنَا مُضْمر وَخص بالإضمار لطول الْكَلَام بِوَصْف الْعَذَاب وخصت السَّجْدَة بالإظهار مُوَافقَة لِلْقَوْلِ قبله فِي مَوَاضِع مِنْهَا ﴿أم يَقُولُونَ افتراه﴾\",1,\"1:181\"],\"K-323\":[\"مكررة وَمُوجب هَذَا التّكْرَار قَوْله ﴿هَذَانِ خصمان﴾ لِأَنَّهُ لما ذكر أحد الْخَصْمَيْنِ وَهُوَ ﴿فَالَّذِينَ كفرُوا قطعت لَهُم ثِيَاب من نَار﴾ لم يكن بُد من ذكر الْخصم الآخر فَقَالَ\",1,\"1:181\"],\"K-324\":[\"مكررة وَمُوجب هَذَا التّكْرَار قَوْله ﴿هَذَانِ خصمان﴾ لِأَنَّهُ لما ذكر أحد الْخَصْمَيْنِ وَهُوَ ﴿فَالَّذِينَ كفرُوا قطعت لَهُم ثِيَاب من نَار﴾ لم يكن بُد من ذكر الْخصم الآخر فَقَالَ\",1,\"1:181\"],\"K-325\":[\"كرر لِأَن الأول مُتَّصِل بِكَلَام إِبْرَاهِيم وَهُوَ اعْتِرَاض ثمَّ أَعَادَهُ مَعَ قَوْله ﴿وَالْبدن جعلناها لكم﴾\",0,\"1:182\"],\"K-326\":[\"وَبعده ﴿وكأين من قَرْيَة أمليت لَهَا﴾ خص الأول بِذكر الإهلاك لاتصاله بقوله ﴿فأمليت للَّذين كفرُوا ثمَّ أخذتهم﴾ أَي أهلكتهم\",1,\"1:182\"],\"K-327\":[\"وَفِي سُورَة لُقْمَان ﴿من دونه الْبَاطِل﴾ لِأَن فِي هَذِه السُّورَة وَقع بعد عشر آيَات كل آيَة مُؤَكدَة مرّة أَو مرَّتَيْنِ وَلِهَذَا أَيْضا زيد فِي السُّورَة اللَّام فِي قَوْله ﴿وَإِن الله لَهو الْغَنِيّ الحميد﴾\",1,\"1:182\"],\"K-328\":[\"بِالْجمعِ وبالواو وَفِي الزخرف فَاكِهَة ٧٣ على التَّوْحِيد ﴿مِنْهَا تَأْكُلُونَ﴾ بِغَيْر وَاو رَاعى فِي السورتين لفظ الْجنَّة فَكَانَت هَذِه جنَّات بِالْجمعِ فَقَالَ ﴿فواكه﴾ بِالْجمعِ\",1,\"1:183\"],\"K-329\":[\"وَبعده ﴿وَقَالَ الْمَلأ من قومه الَّذين كفرُوا وكذبوا بلقاء الْآخِرَة وأترفناهم فِي الْحَيَاة الدُّنْيَا﴾\",1,\"1:183\"],\"K-330\":[\"وَفِي حم فصلت ﴿لَو شَاءَ رَبنَا لأنزل مَلَائِكَة﴾ لِأَن فِي هَذِه السُّورَة تقدم ذكر الله وَلَيْسَ فِيهِ ذكر الرب\",1,\"1:184\"],\"K-331\":[\"وَفِي سبأ ﴿إِنِّي بِمَا تَعْمَلُونَ بَصِير﴾ كِلَاهُمَا من وصف الله سبحانه وتعالى وَخص كل سُورَة بِمَا وَافق فواصل الآى\",0,\"1:184\"],\"K-332\":[\"بِالْألف وَاللَّام وَبعده ﴿لقوم لَا يُؤمنُونَ﴾ لِأَن الأول لقوم صَالح فعرفهم بِدَلِيل قَوْله ﴿فَأَخَذتهم الصَّيْحَة﴾ وَالثَّانِي نكرَة وَقَبله ﴿قرونا آخَرين﴾ فَكَانُوا منكرين وَلم يكن مَعَهم قرينَة عرفُوا بهَا\",1,\"1:184\"],\"K-333\":[\"وَفِي النَّمْل ﴿لقد وعدنا هَذَا نَحن وآباؤنا من قبل﴾ لِأَن مَا فِي هَذِه السُّورَة على الْقيَاس فَإِن الضَّمِير الْمَرْفُوع الْمُتَّصِل لَا يجوز الْعَطف عَلَيْهِ حَتَّى يُؤَكد بالمنفصل\",1,\"1:184\"],\"K-334\":[\"وَبعده ﴿سيقولون لله﴾ وَبعده ﴿سيقولون لله﴾ الأول جَوَاب لقَوْله ﴿قل لمن الأَرْض وَمن فِيهَا﴾ جَوَاب مُطَابق لفظا وَمعنى لِأَنَّهُ قَالَ فِي السُّؤَال قل لمن فَقَالَ فِي الْجَواب لله\",1,\"1:185\"],\"K-335\":[\"وَقَبله ﴿قد كَانَت آياتي تتلى عَلَيْكُم﴾ لَيْسَ بتكرار لِأَن الأول فِي الدُّنْيَا عِنْد نزُول الْعَذَاب وَهُوَ الجدب عِنْد بَعضهم وَيَوْم بدر عِنْد بَعضهم وَالثَّانِي فِي الْقِيَامَة\",1,\"1:185\"],\"K-337\":[\"مَحْذُوف الْجَواب تَقْدِيره لفضحكم وَهُوَ مُتَّصِل بِبَيَان حكم الزَّانِيَيْنِ وَحكم الْقَاذِف وَحكم اللّعان وَجَوَاب لَوْلَا محذوفا أحسن مِنْهُ ملفوظا بِهِ\",1,\"1:186\"],\"K-339\":[\"وَبعده ﴿لقد أنزلنَا آيَات﴾ لِأَن اتِّصَال الأول بِمَا قبله أَشد فَإِن قَوْله ﴿وموعظة لِلْمُتقين﴾ مَحْمُول ومصروف إِلَى قَوْله ﴿وليستعفف﴾ وَإِلَى قَوْله ﴿فكاتبوهم﴾ ﴿وَلَا تكْرهُوا﴾\",1,\"1:187\"],\"K-341\":[\"ختم الْآيَة بقوله ﴿كَذَلِك يبين الله لكم آيَاته﴾ وَقبلهَا وَبعدهَا الْآيَات لِأَن الَّذِي قبلهَا وَالَّذِي بعْدهَا يشْتَمل على عَلَامَات يُمكن الْوُقُوف عَلَيْهَا\",1,\"1:187\"],\"K-342\":[\"هَذِه لَفْظَة لَا تسْتَعْمل إِلَّا لله وَلَا تسْتَعْمل إِلَّا بِلَفْظ الْمَاضِي وَجَاءَت فِي هَذِه السُّورَة فِي ثَلَاث مَوَاضِع ﴿تبَارك الَّذِي نزل الْفرْقَان على عَبده﴾ و﴿تبَارك الَّذِي إِن شَاءَ جعل﴾\",1,\"1:188\"],\"K-343\":[\"فِي هَذِه السُّورَة وَفِي مَرْيَم وَيس ﴿من دون الله﴾ لِأَن فِي هَذِه السُّورَة وَافق مَا قبله وَفِي السورتين لَو جَاءَ ﴿من دونه﴾ لخالف مَا قبله لِأَن مَا قبله فِي السورتين بِلَفْظ الْجمع تَعْظِيمًا فَصرحَ\",0,\"1:188\"],\"K-346\":[\"بِزِيَادَة ﴿عملا﴾ قد سبق\",0,\"1:189\"],\"K-347\":[\"وَمثلهَا فِي السَّجْدَة\",1,\"1:189\"],\"K-348\":[\"سبق فِي الْأَنْبِيَاء\",0,\"1:189\"],\"K-349\":[\"سبق فِي الْأَنْعَام وَكَذَا ﴿أَو لم يرَوا﴾ وَمَا يتَعَلَّق بِقصَّة مُوسَى وَفرْعَوْن سبق الْأَعْرَاف ﴿فِي﴾\",0,\"1:189\"],\"K-350\":[\"إِلَى آخر الْآيَة مَذْكُور فِي ثَمَانِيَة مَوَاضِع أَولهَا فِي مُحَمَّد ﷺ وَإِن لم يتَقَدَّم ذكره صَرِيحًا فقد تقدم كِنَايَة ووضوحا\",1,\"1:189\"],\"K-351\":[\"إِلَى قَوْله ﴿الْعَالمين﴾ مَذْكُور فِي خَمْسَة مَوَاضِع فِي قصَّة نوح وَهود وَصَالح وَلُوط وَشُعَيْب عليهم السلام ثمَّ كرر ﴿فَاتَّقُوا الله وأطيعون﴾ فِي قصَّة نوح وَهود وَصَالح فَصَارَ ثَمَانِيَة مَوَاضِع\",1,\"1:190\"],\"K-352\":[\"وَفِي الصافات ﴿مَاذَا تَعْبدُونَ﴾ لِأَن ﴿مَا﴾ لمُجَرّد الِاسْتِفْهَام فَأَجَابُوا فَقَالُوا ﴿نعْبد أصناما﴾ ﴿وماذا﴾ فِيهِ مُبَالغَة وَقد تضمن فِي الصافات معنى التوبيخ فَلَمَّا\",1,\"1:190\"],\"K-353\":[\"﴿وَالَّذِي هُوَ يطعمني ويسقين﴾ ﴿وَإِذا مَرضت فَهُوَ يشفين﴾ زَاد هُوَ فِي الْإِطْعَام والشفاء لِأَنَّهُمَا مِمَّا يَدعِي الْإِنْسَان أَن يَفْعَله فَيُقَال زيد يطعم وَعَمْرو يداوي\",1,\"1:190\"],\"K-354\":[\"بِغَيْر وَاو وَفِي قصَّة شُعَيْب ﴿وَمَا أَنْت﴾ لِأَنَّهُ فِي قصَّة صَالح بدل من الأولى وَفِي الثَّانِيَة عطف وخصت أولى بِالْبَدَلِ فِي الْخطاب فَأَكْثرُوا\",0,\"1:190\"],\"K-355\":[\"وَفِي الْقَصَص ٣٠ وطه ١١ ﴿فَلَمَّا أَتَاهَا نُودي﴾ لِأَنَّهُ قَالَ فِي هَذِه السُّورَة ﴿سآتيكم مِنْهَا بِخَبَر أَو آتيكم بشهاب قبس﴾ فكرر ﴿آتيكم﴾ فاستثقل الْجمع بَينهمَا وَبَين ﴿فَلَمَّا أَتَاهَا﴾\",1,\"1:191\"],\"K-356\":[\"وَفِي الْقَصَص ﴿وَأَن ألق عصاك﴾ لِأَن فِي هَذِه السُّورَة ﴿نُودي أَن بورك من فِي النَّار وَمن حولهَا وَسُبْحَان الله رب الْعَالمين﴾ ﴿يَا مُوسَى إِنَّه أَنا الله الْعَزِيز الْحَكِيم﴾ ﴿وألق عصاك﴾\",1,\"1:191\"],\"K-357\":[\"وَفِي الْقَصَص ﴿أقبل وَلَا تخف﴾ خصت هَذِه السُّورَة بقوله ﴿لَا تخف﴾ لِأَنَّهُ بنى على ذكر الْخَوْف كَلَام يَلِيق بِهِ وَهُوَ قَوْله ﴿إِنِّي لَا يخَاف لدي المُرْسَلُونَ﴾\",1,\"1:191\"],\"K-358\":[\"وَفِي الْقَصَص ﴿اسلك يدك﴾ خصت هَذِه السُّورَة بأدخل لِأَنَّهُ أبلغ من قَوْله ﴿اسلك﴾ لِأَن ﴿اسلك﴾ يَأْتِي لَازِما ومتعديا ﴿وَأدْخل﴾ مُتَعَدٍّ لَا غير\",1,\"1:192\"],\"K-359\":[\"وَفِي الْقَصَص ﴿إِلَى فِرْعَوْن وملئه﴾ لِأَن الْمَلأ أَشْرَاف الْقَوْم وَكَانُوا فِي هَذِه السُّورَة موصوفين بِمَا\",1,\"1:192\"],\"K-360\":[\"وَفِي حم فصلت ﴿ونجينا الَّذين آمنُوا وَكَانُوا يَتَّقُونَ﴾ نجينا وأنجينا بِمَعْنى وَاحِد وخصت هَذِه السُّورَة بأنجينا لموافقته لما بعده وَهُوَ ﴿فأنجيناه وَأَهله﴾\",1,\"1:192\"],\"K-362\":[\"فِي خمس آيَات وَختم الأولى بقوله\",1,\"1:193\"],\"K-363\":[\"وَفِي الزمر ﴿فَصعِقَ﴾ خصت هَذِه السُّورَة بقوله ﴿فَفَزعَ﴾ مُوَافقَة لقَوْله ﴿وهم من فزع يَوْمئِذٍ آمنون﴾ وخصت الزمر بقوله ﴿فَصعِقَ﴾ مُوَافقَة لقَوْله ﴿وَإِنَّهُم ميتون﴾ لِأَن مَعْنَاهُ مَاتَ\",0,\"1:193\"],\"K-364\":[\"أَي كمل أَرْبَعِينَ سنة وَقيل كمل قَوْله وَقيل خرجت لحيته وَفِي يُوسُف ﴿وَلما بلغ أشده آتيناه﴾ لِأَنَّهُ أوحى إِلَيْهِ فِي صباه\",0,\"1:194\"],\"K-365\":[\"وَفِي يس ﴿وَجَاء من أقْصَى الْمَدِينَة رجل يسْعَى﴾ اسْمه حزبيل من\",1,\"1:194\"],\"K-366\":[\"وَفِي يس ﴿وَجَاء من أقْصَى الْمَدِينَة رجل يسْعَى﴾ اسْمه حزبيل من\",1,\"1:194\"],\"K-367\":[\"وَبعده ﴿من جَاءَ﴾ بِغَيْر\",1,\"1:195\"],\"K-368\":[\"وَفِي الْمُؤمن ﴿لعَلي أبلغ الْأَسْبَاب﴾ ﴿أَسبَاب السَّمَاوَات فَأطلع إِلَى إِلَه مُوسَى﴾ لِأَن قَوْله ﴿أطلع إِلَى إِلَه مُوسَى﴾ فِي هَذِه السُّورَة خبر لعَلي\",1,\"1:195\"],\"K-369\":[\"وَفِي الْمُؤمن ﴿لعَلي أبلغ الْأَسْبَاب﴾ ﴿أَسبَاب السَّمَاوَات فَأطلع إِلَى إِلَه مُوسَى﴾ لِأَن قَوْله ﴿أطلع إِلَى إِلَه مُوسَى﴾ فِي هَذِه السُّورَة خبر لعَلي\",1,\"1:195\"],\"K-370\":[\"بِالْوَاو وَفِي الشورى ﴿فَمَا أُوتِيتُمْ﴾ بِالْفَاءِ لِأَنَّهُ لم يتَعَلَّق فِي هَذِه السُّورَة بِمَا قبله كَبِير تعلق فاقتصر على الْوَاو لعطف جملَة على جملَة\",1,\"1:196\"],\"K-371\":[\"وَفِي الشورى ﴿فمتاع الْحَيَاة الدُّنْيَا﴾ فَحسب لِأَن فِي هَذِه السُّورَة ذكر جَمِيع مَا بسط من الرزق وأعراض الدُّنْيَا كلهَا مستوعبة بِهَذَيْنِ اللَّفْظَيْنِ فالمتاع مَا لَا غنى عَنهُ فِي الْحَيَاة من الْمَأْكُول\",1,\"1:196\"],\"K-372\":[\"وَبعده ﴿إِن جعل الله عَلَيْكُم النَّهَار سرمدا﴾ قدم اللَّيْل على النَّهَار لِأَن ذهَاب اللَّيْل بِطُلُوع الشَّمْس أَكثر\",1,\"1:196\"],\"K-374\":[\"وَفِي لُقْمَان ﴿وَوَصينَا الْإِنْسَان بِوَالِديهِ حَملته﴾ وَفِي الْأَحْقَاف ﴿بِوَالِديهِ إحسانا﴾ الْجُمْهُور على أَن الْآيَات الثَّلَاث نزلت فِي سعد بن مَالك وَهُوَ سعد ابْن أبي وَقاص\",1,\"1:197\"],\"K-375\":[\"وَفِي لُقْمَان ﴿على أَن تشرك﴾ لِأَن مَا فِي هَذِه السُّورَة وَافق مَا قبله لفظا وَهُوَ قَوْله ﴿وَمن جَاهد فَإِنَّمَا يُجَاهد لنَفسِهِ﴾ وَفِي لُقْمَان مَحْمُول على الْمَعْنى لِأَن التَّقْدِير وَإِن حملاك على أَن تشرك\",0,\"1:198\"],\"K-377\":[\"وَفِي الشورى ﴿وَمَا أَنْتُم بمعجزين فِي الأَرْض﴾ لِأَنَّهُ فِي هَذِه السُّورَة خطاب لنمروذ حِين صعد الجو موهما أَنه يحاول السَّمَاء فَقَالَ إِبْرَاهِيم لَهُ\",1,\"1:198\"],\"K-378\":[\"وَقَالَ بعده ﴿خلق الله السَّمَاوَات وَالْأَرْض بِالْحَقِّ إِن فِي ذَلِك لآيَة للْمُؤْمِنين﴾ فَجمع الأولى ووحد الثَّانِيَة لِأَن الأولى إِشَارَة إِلَى إِثْبَات النُّبُوَّة\",1,\"1:199\"],\"K-379\":[\"جمع بَين استفهامين قد سبق فِي الْأَعْرَاف\",0,\"1:199\"],\"K-380\":[\"وَفِي هود ﴿وَلما جَاءَت﴾ بِغَيْر ﴿إِن﴾ لِأَن ﴿لما﴾ يَقْتَضِي جَوَابا وَإِذا اتَّصل بِهِ ﴿إِن﴾ دلّ على أَن الْجَواب وَقع فِي الْحَال من غير تراخ كَمَا فِي هَذِه السُّورَة وَهُوَ قَوْله ﴿سيء بهم وضاق بهم ذرعا﴾\",1,\"1:199\"],\"K-382\":[\"أَخّرهُ فِي هَذِه السُّورَة لما وصف وَقد سبق\",0,\"1:200\"],\"K-383\":[\"وَفِي الْقَصَص ﴿يبسط الرزق لمن يَشَاء من عباده وَيقدر﴾ وَفِي الرَّعْد والشورى ﴿لمن يَشَاء وَيقدر﴾ لِأَن مَا فِي هَذِه السُّورَة اتَّصل بقوله ﴿وكأين من دَابَّة لَا تحمل رزقها﴾ الْآيَة وفيهَا عُمُوم\",1,\"1:200\"],\"K-384\":[\"وَفِي الْبَقَرَة والجاثية وَالروم ﴿بعد مَوتهَا﴾ لِأَن فِي هَذِه السُّورَة وَافق مَا قبله وَهُوَ ﴿من قبله﴾ فَإِنَّهُمَا يتوافقان وَفِيه شَيْء آخر وَهُوَ أَن مَا فِي هَذِه السُّورَة سُؤال\",1,\"1:200\"],\"K-385\":[\"بِغَيْر وَاو لاتصاله بِالْأولِ أَشد اتِّصَال وَتَقْدِيره ذَلِك نعم أجر العاملين\",0,\"1:200\"],\"K-386\":[\"هُنَا وَفِي فاطر وَأول الْمُؤمن بِالْوَاو وَفِي غَيْرهنَّ بِالْفَاءِ لِأَن مَا قبلهَا فِي هَذِه السُّورَة ﴿أَو لم يتفكروا﴾ وَكَذَلِكَ بعْدهَا ﴿وأثاروا الأَرْض﴾ بِالْوَاو فَوَافَقَ مَا قبلهَا وَمَا بعْدهَا وَفِي\",1,\"1:201\"],\"K-387\":[\"﴿من قبلهم﴾ مُتَّصِل بِكَوْن آخر مُضْمر وَقَوله ﴿كَانُوا أَشد مِنْهُم قُوَّة﴾ إِخْبَار عَمَّا كَانُوا عَلَيْهِ قبل الإهلاك\",1,\"1:201\"],\"K-390\":[\"وَختم بقوله ﴿يسمعُونَ﴾ فَإِن من سمع أَن النّوم من صنع الله الْحَكِيم وَلَا يقدر أحد على إجتلابه إِذا امْتنع وَلَا على دَفعه إِذا ورد تَيَقّن أَن لَهُ صانعا مُدبرا\",1,\"1:202\"],\"K-392\":[\"وَفِي الزمر ﴿أولم يعلمُوا﴾ لِأَن بسط الرزق مِمَّا يُشَاهد وَيرى فجَاء فِي هَذِه السُّورَة على مَا يَقْتَضِيهِ اللَّفْظ وَالْمعْنَى وَفِي الزمر اتَّصل بقوله ﴿أُوتِيتهُ على علم﴾ وَبعده ﴿وَلَكِن أَكْثَرهم لَا يعلمُونَ﴾\",1,\"1:203\"],\"K-393\":[\"وَفِي الجاثية ﴿فِيهِ بأَمْره﴾ لِأَن فِي هَذِه السُّورَة تقدم ذكر الرِّيَاح وَهُوَ قَوْله ﴿أَن يُرْسل الرِّيَاح مُبَشِّرَات﴾ بالمطر وإذاقة الرَّحْمَة ﴿ولتجري الْفلك﴾ بالرياح بِأَمْر الله تَعَالَى\",1,\"1:203\"],\"K-394\":[\"وَفِي الجاثية ﴿كَأَن لم يسْمعهَا فبشره﴾ زَاد فِي هَذِه السُّورَة ﴿كَأَن فِي أُذُنَيْهِ وقرا﴾ جلّ الْمُفَسّرين على أَن الْآيَتَيْنِ نزلتا فِي النَّضر بن الْحَارِث وَذَلِكَ أَنه ذهب إِلَى فَارس فَاشْترى كتاب كليلة ودمنة\",1,\"1:204\"],\"K-395\":[\"وَفِي الزمر ﴿لأجل﴾ قد سبق شطر من هَذَا ونزيده بَيَانا أَن ﴿إِلَى﴾ مُتَّصِل بآخر الْكَلَام ودال على الِانْتِهَاء وَاللَّام مُتَّصِل بِأول الْكَلَام ودال على الصِّلَة وَالسَّلَام\",0,\"1:204\"],\"K-396\":[\"وَفِي المعارج ﴿خمسين ألف سنة﴾ مَوضِع بَيَانه التَّفْسِير والغريب فِيهِ مَا رُوِيَ عَن عِكْرِمَة فِي جمَاعَة أَن الْيَوْم فِي المعارج عبارَة عَن أول أَيَّام الدُّنْيَا إِلَى انْقِضَائِهَا\",1,\"1:204\"],\"K-398\":[\"وَفِي سبأ ﴿الَّتِي كُنْتُم﴾ لِأَن النَّار فِي هَذِه السُّورَة وَقعت موقع الْكِنَايَة لتقدم ذكرهَا والكنايات لَا تُوصَف فوصف الْعَذَاب\",1,\"1:205\"],\"K-399\":[\"بِالْوَاو ﴿من قبلهم﴾ بِزِيَادَة ﴿من﴾ سبق فِي طه\",0,\"1:205\"],\"K-401\":[\"وَبعده ﴿ليجزي الله الصَّادِقين بصدقهم﴾ لَيْسَ فِيهَا تشابه لِأَن الأول من لفظ السُّؤَال وصلته ﴿عَن صدقهم﴾ وَبعده ﴿وَأعد للْكَافِرِينَ﴾ وَالثَّانِي من لفظ الْجَزَاء وفاعله ﴿الله﴾ وصلته ﴿بصدقهم﴾ بِالْبَاء\",1,\"1:206\"],\"K-402\":[\"وَبعده ﴿ليجزي الله الصَّادِقين بصدقهم﴾ لَيْسَ فِيهَا تشابه لِأَن الأول من لفظ السُّؤَال وصلته ﴿عَن صدقهم﴾ وَبعده ﴿وَأعد للْكَافِرِينَ﴾ وَالثَّانِي من لفظ الْجَزَاء وفاعله ﴿الله﴾ وصلته ﴿بصدقهم﴾ بِالْبَاء\",1,\"1:206\"],\"K-403\":[\"وَبعده ﴿ليجزي الله الصَّادِقين بصدقهم﴾ لَيْسَ فِيهَا تشابه لِأَن الأول من لفظ السُّؤَال وصلته ﴿عَن صدقهم﴾ وَبعده ﴿وَأعد للْكَافِرِينَ﴾ وَالثَّانِي من لفظ الْجَزَاء وفاعله ﴿الله﴾ وصلته ﴿بصدقهم﴾ بِالْبَاء\",1,\"1:206\"],\"K-404\":[\"وَبعده ﴿ليجزي الله الصَّادِقين بصدقهم﴾ لَيْسَ فِيهَا تشابه لِأَن الأول من لفظ السُّؤَال وصلته ﴿عَن صدقهم﴾ وَبعده ﴿وَأعد للْكَافِرِينَ﴾ وَالثَّانِي من لفظ الْجَزَاء وفاعله ﴿الله﴾ وصلته ﴿بصدقهم﴾ بِالْبَاء\",1,\"1:206\"],\"K-405\":[\"وَبعده ﴿ليجزي الله الصَّادِقين بصدقهم﴾ لَيْسَ فِيهَا تشابه لِأَن الأول من لفظ السُّؤَال وصلته ﴿عَن صدقهم﴾ وَبعده ﴿وَأعد للْكَافِرِينَ﴾ وَالثَّانِي من لفظ الْجَزَاء وفاعله ﴿الله﴾ وصلته ﴿بصدقهم﴾ بِالْبَاء\",1,\"1:206\"],\"K-406\":[\"مرَّتَيْنِ بِتَقْدِيم السَّمَوَات خلاف يُونُس فَإِن فِيهَا ﴿مِثْقَال ذرة فِي الأَرْض وَلَا فِي السَّمَاء﴾ لِأَن فِي هَذِه السُّورَة تقدم ذكر السَّمَوَات فِي أول السُّورَة\",1,\"1:207\"],\"K-408\":[\"وَفِي سُبْحَانَ ﴿من دونه﴾ لِأَنَّهُ فِي هَذِه السُّورَة اتَّصَلت الْآيَة بِآيَة لَيْسَ فِيهَا لفظ الله فَكَانَ الصَّرِيح أحسن وَفِي سُبْحَانَ اتَّصل بآيتين فيهمَا بضعَة عشر مرّة ذكر الله صَرِيحًا وكناية\",1,\"1:208\"],\"K-409\":[\"وَبعده ﴿إِن فِي ذَلِك لآيَات لكل صبار شكور﴾ بِالْجمعِ لِأَن المُرَاد الأول لآيَة على إحْيَاء الْمَوْتَى فخصت بِالتَّوْحِيدِ وَفِي قصَّة سبأ جمع لأَنهم صَارُوا اعْتِبَارا يضْرب بهم الْمثل تفَرقُوا أيادي سبأ\",1,\"1:208\"],\"K-410\":[\"وَبعده ﴿لمن يَشَاء من عباده وَيقدر لَهُ﴾ سبق\",1,\"1:209\"],\"K-411\":[\"وَلم يقل ﴿من قبلك﴾ وَلَا ﴿قبلك﴾ خصت السُّورَة بِهِ لِأَنَّهُ فِي هَذِه السُّورَة إِخْبَار مُجَرّد وَفِي غَيرهَا إِخْبَار للنَّبِي ﷺ وتسلية لَهُ فَقَالَ ﴿قبلك﴾ و﴿من قبلك﴾\",0,\"1:209\"],\"K-412\":[\"وَفِي غَيرهَا ﴿عَمَّا كُنْتُم تَعْمَلُونَ﴾ لِأَن قَوْله ﴿أجرمنا﴾ بِلَفْظ الْمَاضِي أَي قبل هَذَا وَلم يقل نجرم فَيَقَع فِي مُقَابلَة تَعْمَلُونَ لِأَن من شَرط الْإِيمَان وَوصف الْمُؤمن أَن يعزم أَلا يجرم\",1,\"1:209\"],\"K-413\":[\"قد سبق\",0,\"1:209\"],\"K-414\":[\"بِلَفْظ الْمَاضِي مُوَافقَة لأوّل السُّورَة ﴿الْحَمد لله فاطر السَّمَاوَات وَالْأَرْض جَاعل الْمَلَائِكَة رسلًا﴾ لِأَنَّهُمَا للماضي لَا غير وَقد سبق\",0,\"1:209\"],\"K-415\":[\"بِتَقْدِيم ﴿ فِيهِ﴾ مُوَافقَة لتقدم ﴿وَمن كل تَأْكُلُونَ﴾ وَقد سبق\",0,\"1:209\"],\"K-416\":[\"بِزِيَادَة الباءات قد سبق\",0,\"1:210\"],\"K-417\":[\"وَبعده ﴿ألوانها﴾ ثمَّ ﴿ألوانه﴾ لِأَن الأول يعود إِلَى ﴿ثَمَرَات﴾ وَالثَّانِي يعود إِلَى ﴿الْجبَال﴾ وَقيل يعود إِلَى الْحمر وَالثَّالِث يعود إِلَى بعض الدَّال عَلَيْهِ ﴿من﴾ لِأَنَّهُ ذكر ﴿من﴾ وَلم يفسره كَمَا\",1,\"1:210\"],\"K-418\":[\"بِالصَّرِيحِ وَبِزِيَادَة اللَّام وَفِي الشورى ﴿إِنَّه بعباده خَبِير بَصِير﴾ لِأَن الْآيَة الْمُتَقَدّمَة فِي هَذِه السُّورَة لم يكن فِيهَا ذكر الله فَصرحَ باسمه سُبْحَانَهُ\",1,\"1:210\"],\"K-419\":[\"على الأَصْل قد سبق و﴿أَو لم يَسِيرُوا﴾ سبق و﴿على ظهرهَا﴾ سبق بَيَانه\",0,\"1:210\"],\"K-420\":[\"كرر وَقَالَ فِي الْفَتْح ﴿وَلنْ تَجِد لسنة الله تبديلا﴾ وَقَالَ فِي سُبْحَانَ ﴿وَلَا تَجِد لسنتنا تحويلا﴾ التبديل تَغْيِير الشَّيْء عَمَّا كَانَ عَلَيْهِ قيل مَعَ بَقَاء مَادَّة الأَصْل كَقَوْلِه تَعَالَى\",1,\"1:210\"],\"K-421\":[\"قد سبق\",0,\"1:211\"],\"K-422\":[\"مرَّتَيْنِ لَيْسَ بتكرار لِأَن الأولى هِيَ النفخة الَّتِي يَمُوت بهَا الْخلق وَالثَّانيَِة هِيَ الَّتِي يحيا بهَا الْخلق\",0,\"1:212\"],\"K-423\":[\"وَفِي يُونُس ﴿وَلَا يحزنك قَوْلهم إِن الْعِزَّة لله جَمِيعًا﴾ تشابها فِي الْوَقْف على ﴿قَوْلهم﴾ فِي السورتين لِأَن الْوَقْف عَلَيْهِ لَازم و﴿إِن﴾ فيهمَا مَكْسُورَة بِالِابْتِدَاءِ بِالْكِتَابَةِ\",1,\"1:212\"],\"K-424\":[\"وَفِي الصافات ﴿وَصدق الْمُرْسلين﴾ ذكر فِي الْمُتَشَابه وَمَا يتَعَلَّق بالإعراب لَا يعد فِي الْمُتَشَابه\",0,\"1:212\"],\"K-426\":[\"وَبعدهَا ﴿أئذا متْنا وَكُنَّا تُرَابا وعظاما أئنا لمدينون﴾ لِأَن الأول حِكَايَة كَلَام الْكَافرين وهم منكرون للبعث وَالثَّانِي قَول أحد الْفَرِيقَيْنِ لصَاحبه عِنْد وُقُوع الْحساب وَالْجَزَاء\",1,\"1:212\"],\"K-427\":[\"وَبعده ﴿فَأقبل﴾ بِالْفَاءِ وَكَذَلِكَ فِي ﴿ن والقلم﴾ لِأَن الأول لعطف جملَة على جملَة فَحسب وَالثَّانِي لعطف جملَة على جملَة بَينهمَا مُنَاسبَة والتئام لِأَنَّهُ حكى أَحْوَال أهل الْجنَّة\",1,\"1:212\"],\"K-428\":[\"وَفِي المرسلات ﴿كَذَلِك نَفْعل بالمجرمين﴾ لِأَن فِي هَذِه السُّورَة حيل بَين الضَّمِير وَبَين كَذَلِك بقوله ﴿فَإِنَّهُم يَوْمئِذٍ فِي الْعَذَاب مشتركون﴾ فَأَعَادَ\",1,\"1:213\"],\"K-429\":[\"وَفِي الْقِتَال ﴿فَاعْلَم أَنه لَا إِلَه إِلَّا الله﴾ بِزِيَادَة ﴿أَنه﴾ وَلَيْسَ لَهما فِي الْقُرْآن ثَالِث لِأَن مَا فِي هَذِه السُّورَة وَقع بعد القَوْل فَحكى الْمَقُول وَفِي الْقِتَال وَقع بعد الْعلم\",1,\"1:213\"],\"K-430\":[\"وَفِي الْقِتَال ﴿فَاعْلَم أَنه لَا إِلَه إِلَّا الله﴾ بِزِيَادَة ﴿أَنه﴾ وَلَيْسَ لَهما فِي الْقُرْآن ثَالِث لِأَن مَا فِي هَذِه السُّورَة وَقع بعد القَوْل فَحكى الْمَقُول وَفِي الْقِتَال وَقع بعد الْعلم\",1,\"1:213\"],\"K-431\":[\"وَفِي قصَّة إِبْرَاهِيم ﴿كَذَلِك﴾ لِأَنَّهُ تقدم فِي قصَّته ﴿إِنَّا كَذَلِك نجزي الْمُحْسِنِينَ﴾\",1,\"1:214\"],\"K-432\":[\"وَفِي الذاريات ﴿عليم﴾ وَكَذَلِكَ فِي الْحجر لِأَن التَّقْدِير بِغُلَام حَلِيم فِي صباه عليم فِي كبره\",1,\"1:214\"],\"K-433\":[\"ثمَّ قَالَ ﴿وَأبْصر فَسَوف يبصرون﴾ كرر وَحذف الضَّمِير من الثَّانِي لِأَنَّهُ لما نزل ﴿وأبصرهم﴾ قَالُوا مَتى هَذَا الْوَعْد الَّذِي توعدونا بِهِ فَأنْزل الله ﴿أفبعذابنا يستعجلون﴾ كرر تَأْكِيدًا\",1,\"1:215\"],\"K-434\":[\"بِالْوَاو وَفِي ق ﴿فَقَالَ﴾ بِالْفَاءِ لِأَن اتِّصَاله بِمَا قبله فِي هَذِه السُّورَة معنوي وَهُوَ أَنهم عجبوا من مَجِيء الْمُنْذر وَقَالُوا هَذَا الْمُنْذر سَاحر كَذَّاب واتصاله فِي ق معنوي ولفظي وَهُوَ أَنهم عجبوا\",1,\"1:216\"],\"K-435\":[\"وَفِي الْقَمَر ﴿أؤلقي الذّكر عَلَيْهِ من بَيْننَا﴾ لِأَن مَا فِي هَذِه السُّورَة حِكَايَة عَن كفار قُرَيْش يجيبون مُحَمَّدًا ﷺ حِين قَرَأَ عَلَيْهِم ﴿وأنزلنا إِلَيْك الذّكر لتبين للنَّاس﴾\",1,\"1:216\"],\"K-436\":[\"وَفِي الْأَنْبِيَاء ﴿رَحْمَة من عندنَا﴾ لِأَن الله سبحانه وتعالى ميز أَيُّوب بِحسن صبره على بلائه بَين أنبيائه فَحَيْثُ قَالَ لَهُم ﴿من عندنَا﴾ قَالَ لَهُ ﴿منا﴾ وَحَيْثُ لم يقل لَهُم من عندنَا قَالَ لَهُ ﴿من عندنَا﴾\",1,\"1:216\"],\"K-437\":[\"وَفِي ق ﴿كذبت قبلهم قوم نوح وَأَصْحَاب الرس وَثَمُود﴾ إِلَى قَوْله ﴿فَحق وَعِيد﴾\",1,\"1:217\"],\"K-438\":[\"قد سبق\",0,\"1:217\"],\"K-439\":[\"وَفِي هَذِه أَيْضا ﴿إِنَّا أنزلنَا إِلَيْك الْكتاب بِالْحَقِّ لتَحكم بَين النَّاس﴾ الْفرق بَين أنزلنَا إِلَيْك الْكتاب وأنزلنا عَلَيْك قد سبق فِي الْبَقَرَة ونزيده\",1,\"1:217\"],\"K-440\":[\"﴿وَأمرت لِأَن أكون أول الْمُسلمين﴾ زَاد مَعَ الثَّانِي لاما لِأَن الْمَفْعُول من الثَّانِي مَحْذُوف تَقْدِيره فَأمرت أَن أعبد الله لِأَن أكون فَاكْتفى بِالْأولِ\",0,\"1:218\"],\"K-441\":[\"بِالْإِضَافَة وَالْأول ﴿مخلصا لَهُ الدّين﴾ لِأَن قَوْله ﴿أعبد﴾ إِخْبَار صدر عَن الْمُتَكَلّم فَاقْتضى الْإِضَافَة إِلَى الْمُتَكَلّم وَقَوله ﴿أمرت أَن أعبد الله﴾ لَيْسَ بِإِخْبَار عَن الْمُتَكَلّم\",1,\"1:218\"],\"K-442\":[\"وَفِي النَّحْل ﴿ولنجزين الَّذين صَبَرُوا أجرهم بِأَحْسَن مَا كَانُوا يعْملُونَ﴾ وَكَانَ حَقه أَن يذكر هُنَاكَ\",1,\"1:218\"],\"K-443\":[\"وَفِي الجاثية ﴿مَا عمِلُوا﴾ عِلّة الْآيَة الأولى لِأَن مَا كسبوا فِي هَذِه السُّورَة وَقع بَين أَلْفَاظ الْكسْب وَهُوَ ﴿ذوقوا مَا كُنْتُم تكسبون﴾ وَفِي الجاثية وَقع بَين أَلْفَاظ الْعَمَل\",1,\"1:218\"],\"K-444\":[\"وَفِي الْحَدِيد ﴿ثمَّ يكون حطاما﴾ لِأَن الْفِعْل الْوَاقِع بعد قَوْله ﴿ثمَّ يهيج﴾ فِي هَذِه السُّورَة مُسْند إِلَى الله تَعَالَى وَهُوَ قَوْله ﴿ثمَّ يخرج بِهِ زرعا﴾ فَكَذَلِك الْفِعْل بعده ﴿ثمَّ يَجعله﴾\",1,\"1:219\"],\"K-445\":[\"وَبعده ﴿وَفتحت﴾ بِالْوَاو للْحَال أَي جاءوها وَقد فتحت أَبْوَابهَا وَقيل الْوَاو فِي ﴿وَقَالَ لَهُم خزنتها﴾ زَائِدَة وَهُوَ الْجَواب وَقيل الْوَاو وَاو الثَّمَانِية وَقد سبق فِي الْكَهْف\",0,\"1:219\"],\"K-446\":[\"وَفِي آخرهَا ﴿فَإِنَّمَا يَهْتَدِي لنَفسِهِ﴾ لِأَن هَذِه السُّورَة مُتَأَخِّرَة عَن تِلْكَ السُّورَة فَاكْتفى بِذكرِهِ فِيهَا\",0,\"1:219\"],\"K-447\":[\"مَا يتَعَلَّق بذكرها قد سبق\",0,\"1:219\"],\"K-448\":[\"وَفِي التغابن ﴿بِأَنَّهُ كَانَت﴾ لِأَن هَاء الْكِتَابَة إِذا زيدت لِامْتِنَاع ﴿ إِن﴾ عَن الدُّخُول على كَانَ فخصت هَذِه السُّورَة بكناية الْمُتَقَدّم ذكرهم مُوَافقَة لقَوْله ﴿كَانُوا هم أَشد مِنْهُم قُوَّة﴾\",1,\"1:219\"],\"K-450\":[\"وَفِي طه ﴿آتيه﴾ لِأَن اللَّام إِنَّمَا تزداد لتأكيد الْخَبَر وتأكيد الْخَبَر إِنَّمَا يحْتَاج إِلَيْهِ إِذا كَانَ الْمخبر بِهِ شاكا فِي الْخَبَر فالمخاطبون فِي هَذِه السُّورَة الْكفَّار فأكد وَكَذَلِكَ أكد\",1,\"1:220\"],\"K-451\":[\"وَفِي يُونُس ﴿وَلَكِن أَكْثَرهم لَا يشكرون﴾ وَقد سبق لِأَنَّهُ وَافق مَا قبله فِي هَذِه السُّورَة ﴿وَلَكِن أَكثر النَّاس لَا يعلمُونَ﴾ وَبعده ﴿أَكثر النَّاس لَا يُؤمنُونَ﴾ ثمَّ قَالَ ﴿وَلَكِن أَكثر النَّاس لَا يشكرون﴾\",0,\"1:220\"],\"K-452\":[\"أَي لَا يعلمُونَ أَن خلق الْأَكْبَر أسهل من خلق الْأَصْغَر ثمَّ قَالَ ﴿لَا يُؤمنُونَ﴾ بِالْبَعْثِ ثمَّ قَالَ ﴿لَا يشكرون﴾ أَي لَا يشكرون الله على فَضله فختم كل آيَة بِمَا اقْتَضَاهُ\",0,\"1:220\"],\"K-453\":[\"سبق\",0,\"1:220\"],\"K-454\":[\"مدح نَفسه سُبْحَانَهُ وَختم ثَلَاث آيَات على التوالي بقوله ﴿رب الْعَالمين﴾ وَلَيْسَ لَهُ فِي الْقُرْآن نَظِير\",0,\"1:220\"],\"K-455\":[\"وَختم السُّورَة بقوله ﴿وخسر هُنَالك الْكَافِرُونَ﴾ لِأَن الأول مُتَّصِل بقوله ﴿قضي بِالْحَقِّ﴾ ونقيض الْحق الْبَاطِل وَالثَّانِي مُتَّصِل بِإِيمَان غير مجد ونقيض الْإِيمَان الْكفْر\",0,\"1:221\"],\"K-456\":[\"أَي مَعَ الْيَوْمَيْنِ الَّذين تقدما قَوْله ﴿خلق الأَرْض فِي يَوْمَيْنِ﴾ لِئَلَّا يزِيد الْعدَد على سِتَّة أَيَّام فيتطرق إِلَيْهِ كَلَام الْمُعْتَرض\",1,\"1:221\"],\"K-457\":[\"أَي مَعَ الْيَوْمَيْنِ الَّذين تقدما قَوْله ﴿خلق الأَرْض فِي يَوْمَيْنِ﴾ لِئَلَّا يزِيد الْعدَد على سِتَّة أَيَّام فيتطرق إِلَيْهِ كَلَام الْمُعْتَرض\",1,\"1:221\"],\"K-458\":[\"وَمثله فِي الْأَعْرَاف لكنه ختم بقوله ﴿إِنَّه سميع عليم﴾ لِأَن الْآيَة فِي هَذِه السُّورَة مُتَّصِلَة بقوله ﴿وَمَا يلقاها إِلَّا الَّذين صَبَرُوا وَمَا يلقاها إِلَّا ذُو حَظّ عَظِيم﴾ فَكَانَ مؤكدا بالتكرار وبالنفي\",1,\"1:222\"],\"K-459\":[\"وَفِي ﴿حم عسق﴾ بِزِيَادَة قَوْله ﴿إِلَى أجل مُسَمّى﴾ وَزَاد فِيهَا أَيْضا ﴿بغيا بَينهم﴾ لِأَن الْمَعْنى تفرق قَول الْيَهُود فِي التَّوْرَاة وتفرق قَول الْكَافرين فِي الْقُرْآن\",1,\"1:222\"],\"K-460\":[\"وَفِي ﴿حم عسق﴾ بِزِيَادَة قَوْله ﴿إِلَى أجل مُسَمّى﴾ وَزَاد فِيهَا أَيْضا ﴿بغيا بَينهم﴾ لِأَن الْمَعْنى تفرق قَول الْيَهُود فِي التَّوْرَاة وتفرق قَول الْكَافرين فِي الْقُرْآن\",1,\"1:222\"],\"K-461\":[\"بِزِيَادَة ﴿منا﴾ و﴿من﴾ وَفِي هود ﴿وَلَئِن أذقناه نعماء بعد ضراء مسته﴾ لِأَن مَا فِي هَذِه السُّورَة بَين جِهَة الرَّحْمَة وبالكلام حَاجَة إِلَى ذكرهَا وَحذف فِي هود اكْتِفَاء بِمَا قبله\",1,\"1:223\"],\"K-462\":[\"وَفِي الْأَحْقَاف ﴿وكفرتم بِهِ﴾ بِالْوَاو لِأَن مَعْنَاهُ فِي هَذِه السُّورَة كَانَ عَاقِبَة أَمركُم بعد الْإِمْهَال للنَّظَر والتدبر الْكفْر فَحسن دُخُول ﴿ثمَّ﴾ وَفِي الْأَحْقَاف عطف عَلَيْهِ ﴿وَشهد شَاهد﴾\",1,\"1:223\"],\"K-463\":[\"وَفِي لُقْمَان ﴿من عزم الْأُمُور﴾ لِأَن الصَّبْر على وَجْهَيْن صَبر على مَكْرُوه ينَال الْإِنْسَان ظلما كمن قتل بعض بعض أعزته فالصبر على الأول أَشد والعزم عَلَيْهِ أوكد\",1,\"1:223\"],\"K-464\":[\"وَبعده ﴿وَمن يضلل الله فَمَا لَهُ من سَبِيل﴾\",1,\"1:224\"],\"K-466\":[\"وَفِي الْأَحْزَاب ﴿تكون قَرِيبا﴾ زيد مَعَه ﴿تكون﴾ مُرَاعَاة للفواصل وَقد سبق\",0,\"1:224\"],\"K-468\":[\"وَفِي الجاثية ﴿إِن هم إِلَّا يظنون﴾ لِأَن مَا فِي هَذِه السُّورَة مُتَّصِل بقوله ﴿وَجعلُوا الْمَلَائِكَة الَّذين هم عباد الرَّحْمَن إِنَاثًا﴾ وَالْمعْنَى أَنهم قَالُوا الْمَلَائِكَة بَنَات الله\",1,\"1:224\"],\"K-419b\":[\"وَفِي الجاثية ﴿إِن هم إِلَّا يظنون﴾ لِأَن مَا فِي هَذِه السُّورَة مُتَّصِل بقوله ﴿وَجعلُوا الْمَلَائِكَة الَّذين هم عباد الرَّحْمَن إِنَاثًا﴾ وَالْمعْنَى أَنهم قَالُوا الْمَلَائِكَة بَنَات الله\",1,\"1:224\"],\"K-470\":[\"وَفِي الشُّعَرَاء ﴿إِلَى رَبنَا منقلبون﴾ لِأَن مَا فِي هَذِه السُّورَة عَام لمن ركب سفينة أَو دَابَّة وَقيل مَعْنَاهُ إِلَى رَبنَا لمنقلبون على مركب آخر وَهُوَ الْجِنَازَة\",1,\"1:225\"],\"K-471\":[\"سبق\",0,\"1:225\"],\"K-472\":[\"مَرْفُوع وَفِي الصافات مَنْصُوب ذكر فِي الْمُتَشَابه وَلَيْسَ مِنْهُ لِأَن مَا فِي هَذِه السُّورَة مُبْتَدأ وَخبر وَمَا فِي الصافات اسْتثِْنَاء\",0,\"1:225\"],\"K-473\":[\"أَي على علم منا وَلم يقل فِي الجاثية وفضلناهم على علم بل قَالَ ﴿ وفضلناهم على الْعَالمين﴾ لِأَنَّهُ مُكَرر فِي ﴿وأضله الله على علم﴾\",0,\"1:225\"],\"K-477\":[\"بِالْيَاءِ مُوَافقَة لقَوْله ﴿ليجزي قوما بِمَا كَانُوا يَكْسِبُونَ﴾\",0,\"1:226\"],\"K-478\":[\"لتقدم ﴿كُنْتُم تَعْمَلُونَ﴾ ﴿وَعمِلُوا الصَّالِحَات﴾\",0,\"1:226\"],\"K-482\":[\"نزلت فِي الْيَهُود وَبعده ﴿من بعد مَا تبين لَهُم الْهدى لن يضروا الله شَيْئا﴾ نزلت فِي قوم ارْتَدُّوا وَلَيْسَ بتكرار\",0,\"1:227\"],\"K-483\":[\"وَبعده ﴿عَزِيزًا حكيما﴾ لِأَن الأول مُتَّصِل بإنزال السكينَة وازدياد إِيمَان الْمُؤمنِينَ فَكَانَ الْموضع مَوضِع علم وَحِكْمَة وَقد تقدم مَا اقْتَضَاهُ الْفَتْح عِنْد قَوْله ﴿وينصرك الله نصرا عَزِيزًا﴾\",1,\"1:227\"],\"K-484\":[\"وَفِي الْمَائِدَة ﴿فَمن يملك من الله شَيْئا إِن أَرَادَ أَن يهْلك الْمَسِيح﴾ زَاد فِي هَذِه السُّورَة ﴿لكم﴾ لِأَن مَا فِي هَذِه السُّورَة نزلت فِي قوم بأعيانهم وَهُوَ الْمُخَلفُونَ\",1,\"1:228\"],\"K-486\":[\"مَذْكُورَة فِي السُّورَة خمس مَرَّات والمخاطبون الْمُؤْمِنُونَ والمخاطب بِهِ أَمر وَنهي وَذكر فِي السَّادِس ﴿يَا أَيهَا النَّاس﴾ فَعم الْمُؤمنِينَ والكافرين والمخاطب بِهِ قَوْله\",1,\"1:228\"],\"K-487\":[\"بِالْفَاءِ سبق\",0,\"1:228\"],\"K-488\":[\"وَبعده ﴿قَالَ قرينه﴾ لِأَن الأول خطاب الْإِنْسَان من قرينه ومتصل بِكَلَامِهِ وَالثَّانِي اسْتِئْنَاف خطاب الله سُبْحَانَهُ بِهِ من غير اتِّصَال بالمخاطب الأول وَهُوَ قَوْله ﴿رَبنَا مَا أطغيته﴾\",1,\"1:228\"],\"K-489\":[\"وَفِي طه ﴿وَقبل غُرُوبهَا﴾ لِأَن فِي هَذِه السُّورَة رَاعى الفواصل وَفِي طه رَاعى الْقيَاس لِأَن الْغُرُوب للشمس كَمَا أَن الطُّلُوع لَهَا\",0,\"1:229\"],\"K-490\":[\"﴿آخذين﴾ وَفِي الطّور ﴿فِي جنَّات ونعيم﴾ ﴿فاكهين﴾ لَيْسَ بتكرار لِأَن مَا فِي هَذِه السُّورَة مُتَّصِل بِذكر مَا بِهِ يصل الْإِنْسَان إِلَيْهَا وَهُوَ قَوْله ﴿كَانُوا قبل ذَلِك محسنين﴾\",1,\"1:229\"],\"K-491\":[\"وَبعده ﴿إِنِّي لكم مِنْهُ نَذِير مُبين﴾ لَيْسَ بتكرار لِأَن كل وَاحِد مِنْهُمَا مُتَعَلق بِغَيْر مَا تعلق بِهِ الآخر فَالْأول مُتَعَلق بترك الطَّاعَة إِلَى الْمعْصِيَة وَالثَّانِي مُتَعَلق بالشرك بِاللَّه تَعَالَى\",0,\"1:229\"],\"K-492\":[\"أعَاد ﴿أم﴾ خمس عشرَة مرّة وَكلهَا إلزامات لَيْسَ للمخاطبين بهَا جَوَاب\",0,\"1:229\"],\"K-493\":[\"بِالْوَاو عطف على قَوْله ﴿ وأمددناهم﴾ وَكَذَلِكَ ﴿وَأَقْبل﴾ بِالْوَاو وَفِي الْوَاقِعَة ﴿يطوف﴾ بِغَيْر وَاو فَيحْتَمل أَن يكون حَالا أَو يكون خَبرا وَفِي الْإِنْسَان ﴿وَيَطوف﴾ عطف على ﴿وَيُطَاف﴾\",0,\"1:229\"],\"K-494\":[\"بِالْوَاو سبق\",0,\"1:230\"],\"K-495\":[\"وَبعده ﴿إِن يتبعُون إِلَّا الظَّن﴾ لَيْسَ بتكرار لِأَن الأول مُتَّصِل بعبادتهم اللات والعزى وَمَنَاة وَالثَّانِي بعبادتهم الْمَلَائِكَة ثمَّ ذمّ الظَّن فَقَالَ ﴿وَإِن الظَّن لَا يُغني من الْحق شَيْئا﴾\",0,\"1:230\"],\"K-496\":[\"فِي جَمِيع الْقُرْآن بِالْألف إِلَّا فِي الْأَعْرَاف وَقد سبق\",0,\"1:230\"],\"K-497\":[\"لِأَن الأولى فِي الدُّنْيَا وَالثَّانيَِة فِي العقبى كَمَا قَالَ فِي هَذِه الْقِصَّة ﴿لنذيقهم عَذَاب الخزي فِي الْحَيَاة الدُّنْيَا ولعذاب الْآخِرَة أخزى﴾ وَقيل الأول لتحذيرهم قبل إهلاكهم\",1,\"1:230\"],\"K-498\":[\"لِأَن الأولى فِي الدُّنْيَا وَالثَّانيَِة فِي العقبى كَمَا قَالَ فِي هَذِه الْقِصَّة ﴿لنذيقهم عَذَاب الخزي فِي الْحَيَاة الدُّنْيَا ولعذاب الْآخِرَة أخزى﴾ وَقيل الأول لتحذيرهم قبل إهلاكهم\",1,\"1:230\"],\"K-499\":[\"أَعَادَهُ ثَلَاث مَرَّات فَصرحَ وَلم يضمر لكَون كل وَاحِد قَائِما بِنَفسِهِ غير مُحْتَاج إِلَى الأول وَقيل لِأَن كل وَاحِد غير الآخر الأول ميزَان الدُّنْيَا وَالثَّانِي ميزَان الْآخِرَة وَالثَّالِث ميزَان الْعقل\",1,\"1:231\"],\"K-500\":[\"كرر الْآيَة إِحْدَى وَثَلَاثِينَ مرّة ثَمَانِيَة مِنْهَا ذكرت عقيب آيَات فِيهَا تعداد عجائب خلق الله وبدائع صنعه ومبدأ الْخلق ومعادهم ثمَّ سَبْعَة مِنْهَا عقيب آيَات فِيهَا ذكر النَّار\",1,\"1:231\"],\"K-501\":[\"أعَاد ذكرهَا وَكَذَلِكَ ﴿المشأمة﴾ ثمَّ قَالَ ﴿وَالسَّابِقُونَ﴾ لِأَن التَّقْدِير عِنْد بَعضهم وَالسَّابِقُونَ مَا السَّابِقُونَ فَحذف ﴿ مَا﴾ لدلَالَة مَا قبله عَلَيْهِ وَقيل تَقْدِيره أَزْوَاجًا أَزْوَاجًا ثَلَاثَة\",1,\"1:231\"],\"K-502\":[\"﴿أَفَرَأَيْتُم مَا تَحْرُثُونَ﴾ ﴿أَفَرَأَيْتُم المَاء الَّذِي تشربون﴾ ﴿أَفَرَأَيْتُم النَّار الَّتِي تورون﴾ بَدَأَ بِذكر خلق الْإِنْسَان ثمَّ ﴿ذكر﴾ مَالا غنى لَهُ عَنهُ وَهُوَ الْحبّ الَّذِي مِنْهُ قوامه\",1,\"1:232\"],\"K-503\":[\"وَكَذَلِكَ الْحَشْر والصف\",1,\"1:232\"],\"K-504\":[\"وَفِي السُّور الْخمس ﴿مَا فِي السَّمَاوَات وَمَا فِي الأَرْض﴾ إِعَادَة ﴿مَا﴾ هُوَ الأَصْل وخصت هَذِه السُّورَة بالحذف مُوَافقَة لما بعْدهَا وَهُوَ ﴿خلق السَّمَاوَات وَالْأَرْض﴾ وَبعدهَا\",1,\"1:232\"],\"K-505\":[\"وَبعده ﴿لَهُ ملك السَّمَاوَات وَالْأَرْض﴾ لَيْسَ بتكرار لِأَن الأولى ﴿فِي الدُّنْيَا﴾ يحيي وَيُمِيت وَالثَّانِي فِي العقبى لقَوْله ﴿وَإِلَى الله ترجع الْأُمُور﴾\",0,\"1:233\"],\"K-507\":[\"ابْتِدَاء الْكَلَام ﴿وَلَقَد أرسلنَا نوحًا﴾ عطف عَلَيْهِ\",0,\"1:233\"],\"K-508\":[\"سبق\",0,\"1:233\"],\"K-509\":[\"وَفِي التغابن ﴿من مُصِيبَة إِلَّا بِإِذن الله﴾ فصل فِي هَذِه السُّورَة وأجمل هُنَاكَ مُوَافقَة لما قبلهَا فِي هَذِه السُّورَة فَإِنَّهُ فصل أَحْوَال الدُّنْيَا\",1,\"1:233\"],\"K-510\":[\"وَبعده ﴿وَالَّذين يظاهرون من نِسَائِهِم﴾ لِأَن الأول خطاب للْعَرَب وَكَانَ طلاقهم فِي الْجَاهِلِيَّة الظِّهَار فقيده بقوله ﴿مِنْكُم﴾ وَبِقَوْلِهِ\",1,\"1:234\"],\"K-511\":[\"وَبعده ﴿وللكافرين عَذَاب مهين﴾\",1,\"1:234\"],\"K-513\":[\"بِالْفَاءِ لما فِيهِ من معنى التعقيب أَي بئس الْمصير مَا صَارُوا إِلَيْهِ وَهُوَ جَهَنَّم قَوْله ﴿من الله شَيْئا أُولَئِكَ﴾ بِغَيْر فَاء مُوَافقَة للجمل الَّتِي قبلهَا وموافقة لقَوْله ﴿أُولَئِكَ حزب الله﴾\",0,\"1:234\"],\"K-514\":[\"وَبعدهَا ﴿مَا أَفَاء﴾ بِغَيْر وَاو لِأَن الأول مَعْطُوف على قَوْله ﴿مَا قطعْتُمْ من لينَة﴾ وَالثَّانِي اسْتِئْنَاف كَلَام وَلَيْسَ لَهُ بِهِ تعلق وَقَول من قَالَ إِنَّه بدل من الأول مزيف عِنْد أَكثر الْمُفَسّرين\",0,\"1:235\"],\"K-515\":[\"وَبعده ﴿قوم لَا يعْقلُونَ﴾ لِأَن الأول مُتَّصِل بقوله ﴿لَأَنْتُم أَشد رهبة فِي صُدُورهمْ من الله﴾ لأَنهم يرَوْنَ الظَّاهِر وَلَا يفقهُونَ علم مَا استتر عَلَيْهِم وَالْفِقْه معرفَة ظَاهر الشَّيْء وغامضه بِسُرْعَة فطنة\",1,\"1:235\"],\"K-517\":[\"وَبعده ﴿تسرون إِلَيْهِم بالمودة﴾ الأول حَال من المخاطبين وَقيل أتلقون إِلَيْهِم والاستفهام مُقَدّر وَقيل خبر مُبْتَدأ أَي أَنْتُم تلقونَ وَالثَّانِي بدل من الأول على الْوُجُوه الْمَذْكُورَة\",1,\"1:235\"],\"K-518\":[\"بِالْألف وَاللَّام فِي غرها ﴿افترى على الله كذبا﴾ بالنكرة لِأَنَّهَا أَكثر اسْتِعْمَالا\",1,\"1:236\"],\"K-519\":[\"بِاللَّامِ لِأَن الْمَفْعُول مَحْذُوف وَقيل اللَّام زِيَادَة وَقيل مَحْمُول على الْمصدر\",0,\"1:236\"],\"K-520\":[\"جزم على جَوَاب الْأَمر فَإِن قَوْله ﴿تؤمنون﴾ مَحْمُول على الْأَمر أَي آمنُوا وَلَيْسَ بعده ﴿من﴾ وَلَا ﴿خَالِدين﴾\",0,\"1:236\"],\"K-521\":[\"وَفِي الْبَقَرَة ﴿وَلنْ يَتَمَنَّوْهُ﴾ سبق\",0,\"1:236\"],\"K-522\":[\"وَبعده ﴿لَا يعلمُونَ﴾ لِأَن الأول مُتَّصِل بقوله ﴿وَللَّه خَزَائِن السَّمَاوَات وَالْأَرْض﴾ وَفِي مَعْرفَتهَا غموض يحْتَاج إِلَى فطنة وَالْمُنَافِق لَا فطنة لَهُ وَالثَّانِي مُتَّصِل بقوله\",1,\"1:236\"],\"K-523\":[\"﴿يعلم مَا فِي السَّمَاوَات وَالْأَرْض وَيعلم مَا تسرون وَمَا تعلنون﴾ إِنَّمَا كرر ﴿مَا﴾ فِي أول السُّورَة لاخْتِلَاف تَسْبِيح أهل الأَرْض وتسبيح أهل اسْم السَّمَاء فِي الْكَثْرَة والقلة والبعد والقرب من الْمعْصِيَة\",1,\"1:237\"],\"K-524\":[\"وَمثله فِي الطَّلَاق سَوَاء لكنه زَاد هُنَا ﴿يكفر عَنهُ سيئاته﴾ لِأَن مَا فِي هَذِه السُّورَة جَاءَ بعد قَوْله ﴿أبشر يهدوننا﴾ الْآيَات فَأخْبر عَن الْكفَّار سيئات تحْتَاج إِلَى تفكير إِذا آمنُوا بِاللَّه\",1,\"1:237\"],\"K-525\":[\"أَمر بالتقوى فِي أَحْكَام الطَّلَاق ثَلَاث مَرَّات ووعد فِي كل مرّة نوعا من الْجَزَاء فَقَالَ أَولا ﴿يَجْعَل لَهُ مخرجا﴾ يُخرجهُ مِمَّا دخل فِيهِ وَهُوَ يكرههُ ويبيح لَهُ محبوبه من حَيْثُ لَا يأمل\",1,\"1:237\"],\"K-527\":[\"سبق\",0,\"1:238\"],\"K-528\":[\"وَبعده ﴿ثمَّ ارْجع الْبَصَر كرتين﴾ أَي مَعَ الكرة الأولى وَقيل هِيَ ثَلَاث مَرَّات أَي ارْجع الْبَصَر وَهَذِه مرّة ثمَّ أرجع الْبَصَر كرتين فمجموعهما ثَلَاث مَرَّات\",1,\"1:238\"],\"K-529\":[\"وَبعده ﴿ثمَّ ارْجع الْبَصَر كرتين﴾ أَي مَعَ الكرة الأولى وَقيل هِيَ ثَلَاث مَرَّات أَي ارْجع الْبَصَر وَهَذِه مرّة ثمَّ أرجع الْبَصَر كرتين فمجموعهما ثَلَاث مَرَّات\",1,\"1:238\"],\"K-533\":[\"بِالْفَاءِ وَبعده ﴿وَأما﴾ بِالْوَاو لِأَن الأول مُتَّصِل بأحوال الْقِيَامَة وأهوالها فَاقْتضى الْفَاء للتعقيب وَالثَّانِي مُتَّصِل بِالْأولِ فَأدْخل الْوَاو لِأَنَّهُ للْجمع\",0,\"1:239\"],\"K-534\":[\"﴿وَلَا بقول كَاهِن قَلِيلا مَا تذكرُونَ﴾ خص ذكر الشّعْر بقوله ﴿مَا تؤمنون﴾ لِأَن من قَالَ الْقُرْآن شعر وَمُحَمّد شَاعِر بعد مَا علم اخْتِلَاف آيَات الْقُرْآن فِي الطول وَالْقصر وَاخْتِلَاف حُرُوف مقاطعه فلكفره\",1,\"1:240\"],\"K-535\":[\"وعقيبه ذكر الْخِصَال الْمَذْكُورَة أول سُورَة الْمُؤمنِينَ وَزَاد فِيهَا ﴿وَالَّذين هم بشهاداتهم قائمون﴾ لِأَنَّهُ وَقع عقيب قَوْله ﴿لِأَمَانَاتِهِمْ وَعَهْدهمْ رَاعُونَ﴾\",1,\"1:240\"],\"K-536\":[\"بِغَيْر وَاو ثمَّ قَالَ ﴿وَقَالَ نوح﴾ بِزِيَادَة الْوَاو لِأَن الأول ابْتِدَاء دُعَاء وَالثَّانِي عطف عَلَيْهِ\",0,\"1:241\"],\"K-537\":[\"وَبعده ﴿إِلَّا تبارا﴾ لِأَن الأول وَقع بعد قَوْله ﴿وَقد أَضَلُّوا كثيرا﴾\",1,\"1:241\"],\"K-538\":[\"كرر ﴿إِن﴾ مَرَّات وَاخْتلف الْقُرَّاء فِي اثْنَتَيْ عشرَة مِنْهَا وَهِي من قَوْله ﴿وَأَنه تَعَالَى﴾ إِلَى قَوْله ﴿وَأَنا منا الْمُسلمُونَ﴾ فَفَتحهَا بَعضهم عطفا على ﴿أُوحِي إِلَيّ أَنه﴾\",1,\"1:241\"],\"K-540\":[\"﴿فَقتل كَيفَ قدر﴾ ﴿ثمَّ قتل كَيفَ قدر﴾ أعَاد ﴿كَيفَ قدر﴾ مرَّتَيْنِ وَأعَاد ﴿قدر﴾ ثَلَاث مَرَّات لِأَن التَّقْدِير إِنَّه أَي الْوَلِيد فكر فِي بَيَان مُحَمَّد ﷺ وَمَا أَتَى بِهِ وَقدر مَا يُمكنهُ أَن يَقُول فيهمَا\",1,\"1:242\"],\"K-541\":[\"أَي تذكير وَعدل إِلَيْهَا للفاصلة وَقَوله ﴿إِنَّه تذكرة﴾ ﴿فَمن شَاءَ ذكره﴾ وَفِي عبس ﴿إِنَّهَا تذكرة﴾ لِأَن تَقْدِير الْآيَة فِي هَذِه السُّورَة إِن الْقُرْآن تذكرة وَفِي عبس إِن آيَات الْقُرْآن تذكرة\",1,\"1:242\"],\"K-542\":[\"ثمَّ أعَاد فَقَالَ ﴿وَلَا أقسم بِالنَّفسِ اللوامة﴾ فِيهِ ثَلَاثَة أَقْوَال أَحدهَا أَنه سُبْحَانَهُ أقسم بهما وَالثَّانِي لم يقسم بهما وَالثَّالِث أقسم بِيَوْم الْقِيَامَة وَلم يقسم بِالنَّفسِ اللوامة\",1,\"1:243\"],\"K-543\":[\"وَكرر فِي الْآيَة الثَّانِيَة ﴿وَجمع الشَّمْس وَالْقَمَر﴾ لِأَن الأول عبارَة عَن بَيَاض الْعين بِدَلِيل قَوْله ﴿فَإِذا برق الْبَصَر﴾ وَفِيه قَول ثَان وَهُوَ قَول الْجُمْهُور إنَّهُمَا بِمَعْنى وَاحِد\",1,\"1:243\"],\"K-544\":[\"كررها مرَّتَيْنِ بل كررها أَربع مَرَّات فَإِن قَوْله ﴿أولي﴾ تَامّ فِي الذَّم بِدَلِيل قَوْله ﴿فَأولى لَهُم﴾ فَإِن جُمْهُور الْمُفَسّرين ذَهَبُوا إِلَى أَنه للتهديد وَإِنَّمَا كررها لِأَن الْمَعْنى أولى لَك الْمَوْت\",1,\"1:243\"],\"K-545\":[\"وَبعده ﴿وَيَطوف عَلَيْهِم﴾ إِنَّمَا ذكر الأول بِلَفْظ الْمَجْهُول لِأَن الْمَقْصُود مَا يُطَاف بِهِ لَا الطائفون وَلِهَذَا قَالَ ﴿بآنية من فضَّة﴾ ثمَّ ذكر الطائفين فَقَالَ ﴿وَيَطوف عَلَيْهِم ولدان مخلدون﴾\",0,\"1:244\"],\"K-546\":[\"وَبعدهَا ﴿زنجبيلا﴾ ﴿سلسبيلا﴾ لِأَن الثَّانِيَة غير الأولى وَقيل كافور اسْم علم لذَلِك المَاء وَاسم الثَّانِي زنجبيل وَقيل اسْمهَا سلسبيلا قَالَ ابْن الْمُبَارك سل من الله إِلَيْهِ سلسبيلا\",1,\"1:244\"],\"K-547\":[\"مُكَرر عشرات مَرَّات لِأَن كل وَاحِد مِنْهَا ذكرت عقيب آيَة غير الأولى فَلَا يكون تَكْرَارا مستهجنا وَلَو لم يُكَرر كَانَ متوعدا على بعض دون بعض وَقيل إِن من عَادَة الْعَرَب التّكْرَار\",1,\"1:244\"],\"K-548\":[\"﴿ثمَّ كلا سيعلمون﴾ قيل التّكْرَار للتَّأْكِيد وَقيل الأول للْكفَّار وَالثَّانِي للْمُؤْمِنين وَقيل الأول عِنْد النزع وَالثَّانِي فِي الْقِيَامَة وَقيل الأول ردع عَن الِاخْتِلَاف وَالثَّانِي عَن الْكفْر\",0,\"1:245\"],\"K-549\":[\"وَبعده ﴿جَزَاء من رَبك عَطاء حسابا﴾ لِأَن الأول للْكفَّار وَقد قَالَ الله تَعَالَى ﴿وَجَزَاء سَيِّئَة سَيِّئَة مثلهَا﴾ فَيكون جزاؤهم على وفْق أَعْمَالهم وَالثَّانِي للْمُؤْمِنين وجزائهم جَزَاء وافيا كَافِيا\",1,\"1:245\"],\"K-550\":[\"وَفِي غَيرهَا ﴿الصاخة﴾ لِأَن الطامة مُشْتَقَّة من طممت الْبِئْر إِذا كسبتها وَسميت الْقِيَامَة طامة لِأَنَّهَا تكبس كل شَيْء وتكسره وَسميت الصاخة\",1,\"1:245\"],\"K-551\":[\"وَفِي الإنفطار ﴿وَإِذا الْبحار فجرت﴾ لِأَن معنى سجرت عِنْد أَكثر الْمُفَسّرين أوقدت فَصَارَت نَارا من قَوْلهم سجرت التَّنور وَقيل هِيَ بحار جَهَنَّم تملأ حميما فيعاقب بهَا أهل النَّار\",1,\"1:246\"],\"K-552\":[\"وَفِي الانفطار ﴿مَا قدمت وأخرت﴾ لِأَن مَا فِي هَذِه السُّورَة مُتَّصِل بقوله ﴿وَإِذا الصُّحُف نشرت﴾ فقرأها أَرْبَابهَا فَعَلمُوا مَا أحضرت وَفِي الانفطار مُتَّصِل بقوله ﴿وَإِذا الْقُبُور بعثرت﴾\",1,\"1:246\"],\"K-553\":[\"تكْرَار أَفَادَ التَّعْظِيم ليَوْم الدّين وَقيل أَحدهمَا لِلْمُؤمنِ وَالثَّانِي للْكَافِرِ\",0,\"1:247\"],\"K-544b\":[\"﴿وَمَا أَدْرَاك مَا سِجِّين﴾ ﴿كتاب مرقوم﴾ وَبعده ﴿كلا إِن كتاب الْأَبْرَار لفي عليين﴾ ﴿وَمَا أَدْرَاك مَا عليون﴾ ﴿كتاب مرقوم﴾ التَّقْدِير فيهمَا\",1,\"1:247\"],\"K-555\":[\"مرَّتَيْنِ لِأَن الأول مُتَّصِل بالسماء وَالثَّانِي مُتَّصِل بِالْأَرْضِ وَمعنى أَذِنت سَمِعت وانقادت وَحقّ لَهَا أَن تسمع وتطيع وَإِذا اتَّصل بِغَيْر مَا اتَّصل بِهِ الآخر لَا يكون تَكْرَارا\",0,\"1:247\"],\"K-556\":[\"وَفِي البروج ﴿فِي تَكْذِيب﴾ رَاعى فواصل الْآي مَعَ صِحَة اللَّفْظ وجودة الْمَعْنى قَوْله ﴿ذَلِك الْفَوْز الْكَبِير﴾ ذَلِك مُبْتَدأ والفوز خَبره وَالْكَبِير صفته وَلَيْسَ فِي الْقُرْآن نَظِير\",0,\"1:247\"],\"K-559\":[\"﴿الَّذِي خلق فسوى﴾ وَفِي العلق ﴿اقْرَأ باسم رَبك الَّذِي خلق﴾ زَاد فِي هَذِه السُّورَة ﴿الْأَعْلَى﴾ مُرَاعَاة للفواصل وَفِي هَذِه السُّورَة ﴿الَّذِي خلق فسوى﴾ وَفِي العلق ﴿خلق الْإِنْسَان من علق﴾\",0,\"1:248\"],\"K-560\":[\"وَبعده ﴿وُجُوه يَوْمئِذٍ﴾ لَيْسَ بتكرار لِأَن الأول هم الْكفَّار وَالثَّانِي الْمُؤْمِنُونَ وَكَانَ الْقيَاس أَن يكون الثَّانِي بِالْوَاو للْعَطْف لكنه جَاءَ على وفَاق الْجمل قبلهَا وَبعدهَا وَلَيْسَ مَعَهُنَّ\",1,\"1:249\"],\"K-561\":[\"﴿ونمارق﴾ كلهَا قد سبق وَقَوله ﴿إِلَى السَّمَاء﴾ و﴿وَإِلَى الْجبَال﴾ لَيْسَ من الْجمل بل هِيَ أَتبَاع لما قبلهَا\",0,\"1:249\"],\"K-562\":[\"وَبعده ﴿وَأما إِذا مَا ابتلاه﴾ لِأَن التَّقْدِير فِي الثَّانِي أَيْضا وَأما الْإِنْسَان فَاكْتفى بِذكرِهِ فِي الأول وَالْفَاء لَازم بعده لِأَن الْمَعْنى مهما يكن من شَيْء\",1,\"1:249\"],\"K-563\":[\"ثمَّ قَالَ ﴿وَأَنت حل بِهَذَا الْبَلَد﴾ كَرَّرَه وَجعله فاصلا فِي الْآيَتَيْنِ وَقد سبق القَوْل فِي مثل هَذَا وَمِمَّا ذكر فِي هَذِه السُّورَة على الْخُصُوص أَن التَّقْدِير لَا أقسم بِهَذَا الْبَلَد وَهُوَ حرَام\",1,\"1:249\"],\"K-565\":[\"وَبعده ﴿فسنيسره للعسرى﴾ أَي نسهله للحالة الْيُسْرَى وَالْحَالة العسرى وَقيل الأولى الْجنَّة وَالثَّانيَِة النَّار وَلَفْظَة سنيسره وَجَاء فِي الْخَبَر اعْمَلُوا فَكل ميسر لما خلق لَهُ\",0,\"1:250\"],\"K-566\":[\"كرر ﴿أما﴾ ثَلَاث مَرَّات لِأَنَّهَا وَقعت فِي مُقَابلَة ثَلَاث آيَات أَيْضا وَهِي ﴿ألم يجدك يَتِيما فآوى ووجدك ضَالًّا فهدى﴾ ﴿ووجدك عائلا فأغنى﴾ ﴿ فَأَما الْيَتِيم فَلَا تقهر﴾\",1,\"1:250\"],\"K-567\":[\"﴿إِن مَعَ الْعسر يسرا﴾ لَيْسَ بتكرار لِأَن الْمَعْنى إِن مَعَ الْعسر الَّذِي أَنْت فِيهِ من مقاساة الْكفَّار يسرا فِي العاجل وَإِن مَعَ الْعسر الَّذِي أَنْت فِيهِ من الْكفَّار يسرا فِي الآجل فالعسر وَاحِد\",1,\"1:251\"],\"K-568\":[\"وَقَالَ فِي الْبَلَد ﴿لقد خلقنَا الْإِنْسَان فِي كبد﴾ وَلَا مناقضة بَينهمَا لِأَن مَعْنَاهُ عِنْد كثير من الْمُفَسّرين منتصب الْقَامَة معتدلها فَيكون فِي معنى أحسن تَقْوِيم\",1,\"1:251\"],\"K-569\":[\"وَبعده ﴿اقْرَأ وَرَبك﴾ وَكَذَلِكَ ﴿الَّذِي خلق﴾ وَبعده ﴿خلق﴾ وَمثله ﴿علم بالقلم﴾ ﴿علم الْإِنْسَان﴾ لِأَن قَوْله ﴿اقْرَأ﴾ مُطلق فقيده بِالثَّانِي وَالَّذِي خلق\",1,\"1:252\"],\"K-570\":[\"﴿وَمَا أَدْرَاك مَا لَيْلَة الْقدر﴾ ثمَّ قَالَ ﴿لَيْلَة الْقدر﴾ فَصرحَ بِهِ وَكَانَ حَقه الْكِنَايَة رفعا لمنزلتها فَإِن الِاسْم قد يذكر بالتصريح فِي مَوضِع الْكِنَايَة تَعْظِيمًا وتخويفا كَمَا قَالَ الشَّاعِر\",1,\"1:252\"],\"K-572\":[\"وَأَعَادَهُ مرّة أُخْرَى لَيْسَ بتكرار لِأَن الأول مُتَّصِل بقوله ﴿خيرا يره﴾ وَالثَّانِي مُتَّصِل بقوله ﴿شرا يره﴾\",0,\"1:253\"],\"K-573\":[\"أقسم بِثَلَاثَة أَشْيَاء ﴿وَالْعَادِيات﴾ ﴿فالموريات﴾ ﴿فالمغيرات﴾ وَجعل جَوَاب الْقسم أَيْضا ثَلَاثَة أَشْيَاء ﴿إِن الْإِنْسَان لرَبه لكنود﴾ ﴿وَإنَّهُ على ذَلِك لشهيد﴾ ﴿وَإنَّهُ لحب الْخَيْر لشديد﴾\",0,\"1:253\"],\"K-574\":[\"ثمَّ ﴿وَأما من خفت مَوَازِينه﴾ جمع ميزَان وَله كفان وعمود لِسَان وَإِنَّمَا جمع لاخْتِلَاف الموزونات وتجدد الْوَزْن وَكَثْرَة الْمَوْزُون لَهُم كَقَوْلِه ﴿عَن الْأَهِلّة﴾ وَإِنَّمَا هُوَ هِلَال وَاحِد\",1,\"1:253\"],\"K-575\":[\"فِي الْمَوَاضِع الثَّلَاثَة فِيهِ قَولَانِ أَحدهَا أَن مَعْنَاهُ الردع والزجر عَن التكاثر فَحسن الْوَقْف عَلَيْهِ والابتداء بِمَا بعده وَالثَّانِي أَنه يجْرِي مجْرى الْقسم وَمَعْنَاهُ\",0,\"1:253\"],\"K-576\":[\"وَبعده ﴿سَوف تعلمُونَ﴾ تكْرَار للتَّأْكِيد عِنْد بَعضهم وَعند بَعضهم هما فِي وَقْتَيْنِ الْقَبْر وَالْقِيَامَة فَلَا يكون تَكْرَارا وَكَذَلِكَ قَول من قَالَ الأول للْكفَّار وَالثَّانِي للْمُؤْمِنين\",0,\"1:254\"],\"K-577\":[\"﴿ثمَّ لترونها﴾ تَأْكِيد أَيْضا وَقيل الأول قبل الدُّخُول وَالثَّانِي بعد الدُّخُول وَلِهَذَا قَالَ بعده ﴿عين الْيَقِين﴾ أَي عيَانًا لَسْتُم عَنْهَا بغائبين وَقيل الأول من رُؤْيَة الْقلب وَالثَّانِي من رُؤْيَة الْعين\",0,\"1:254\"],\"K-580\":[\"فِيهِ اشْتِبَاه وَيحسن الْوَقْف على ﴿لُمزَة﴾ حَيْثُ لم يصلح أَن يكون ﴿الَّذِي﴾ وَصفا لَهُ وَلَا بَدَلا عَنهُ وَيجوز أَن يكون رفعا بِالِابْتِدَاءِ بِحَسب خَبره وَيجوز أَن يرْتَفع بالْخبر أَي هُوَ الَّذِي جمع\",1,\"1:255\"],\"K-581\":[\"أَتَى فِي مَوَاضِع وَهَذَا آخرهَا ومفعولاه محذوفان وَكَيف مفعول وَلَا يعْمل فِيهِ مَا قبله لِأَنَّهُ اسْتِفْهَام والاستفهام لَا يعْمل فِيهِ مَا قبله\",0,\"1:255\"],\"K-583\":[\"كرر وَلم يقْتَصر على مرّة وَاحِدَة لِامْتِنَاع عطف الْفِعْل على الِاسْم وَلم يقل الَّذين هم يمْنَعُونَ لِأَنَّهُ فعل فَحسن عطف الْفِعْل على الْفِعْل\",0,\"1:255\"],\"K-584\":[\"وَبعده ﴿إِن شانئك﴾ قيد الْخَبَرَيْنِ بِأَن تَأْكِيدًا وَالْخَبَر إِذا أكد بإن قَارب الْقسم\",0,\"1:256\"],\"K-585\":[\"فِي تكراره أَقْوَال جمة وَمَعَان كَثِيرَة ذكرت فِي موضعهَا قَالَ الشَّيْخ الإِمَام وَأَقُول هَذَا التّكْرَار اخْتِصَار وَهُوَ إعجاز لِأَن الله نفى عَن نبيه عبَادَة الْأَصْنَام فِي الْمَاضِي وَالْحَال والاستقبال\",1,\"1:256\"],\"K-588\":[\"﴿الله الصَّمد﴾ كرر لتَكون كل جملَة مِنْهُمَا مُسْتَقلَّة بذاتها غير محتاجة إِلَى مَا قبلهَا ثمَّ نفى سُبْحَانَهُ عَن نَفسه الْوَلَد والصاحبة بقوله ﴿وَلم يكن لَهُ كفوا أحد﴾\",0,\"1:257\"],\"K-589\":[\"أَربع مَرَّات لِأَن شَرّ كل وَاحِد مِنْهَا غير الآخر\",0,\"1:257\"],\"K-590\":[\"ثمَّ كرر النَّاس خمس مَرَّات قيل كرر تبجيلا لَهُم على مَا سبق وَقيل كرر لانفصال كل آيَة من الْأُخْرَى لعدم حرف الْعَطف وَقيل المُرَاد بِالْأولِ الْأَطْفَال وَمعنى الربوبية يدل عَلَيْهِ وَبِالثَّانِي الشبَّان\",1,\"1:257\"],\"I-005\":[\"والجواب عن ذلك: أن الآية الأولى في سورة البقرة خبر عن قوم عرفوا وعرفت أفعالهم ومضت أزمتهم وأحوالهم، فلما شهروا شهر فعلهم بوقوعه منهم.\",1,\"1:246\"],\"I-006\":[\"فالجواب أن يقال: إذا أورد الحكيم تقدست أسماؤه آية على لفظة مخصوصة ثم أعادها في موضع آخر من القرآن، وقد غير فيها لفظة عما كانت عليه في الأولى فلا بد من حكمة هناك تطلب، وإن أدركتموها فقد ظفرتم\",1,\"1:250\"],\"I-008\":[\"فالجواب أن يقال: إن الآية الأولى لما كانت مفتتحة بشرط علقت صحته بتمني الموت، ووقع هذا الشرط غاية ما يطلبه المطيع، ولا مطلوب وراءه على ما ادعوا لأنفسهم\",1,\"1:266\"],\"I-009\":[\"والجواب عن ذلك أن يقال: نبين أولا الفرق بين\\\" الذي\\\" وبين\\\" ما\\\"/ ليصح الفصل ويظهر موضع كل واحد منهما، والمعنى الذي يليق بهما.\",1,\"1:271\"],\"I-011\":[\"الجواب عن السؤال الأول وذكر فائدة الآية مع وضوح معناها لكل ذي معرفة فمن وجهين.\",1,\"1:289\"],\"I-013\":[\"فالجواب عنه أن يقال: إن قوله تعالى: (فول وجهك شطر المسجد الحرام)\",1,\"1:305\"],\"I-015\":[\"والجواب عن الموضع الأول وهو قوله: (ألفينا): أن (ألفينا) يقصد بها بعض الوجوه التي ستعمل عليها: (وجدنا)، لأنه يقال: وجدت الشيء، فلا يحتاج إلى مفعول ثان إذا وجدته عن عدم\",1,\"1:311\"],\"I-016\":[\"والجواب أن يقال: أما الموضع الأول فإنه جاء على الأصل الذي يقتضيه حكم اللفظ، لأن الباء التي يتعدى بها الفعل في هذا المكان من جملة الباءآت/ التي كحرف من نفس الفعل، تقول: ذهبت بزيد، ثم تقول: أذهبت زيدا\",1,\"1:317\"],\"I-017\":[\"والجواب أن يقال: قصد الله تعالى في المواضع الثلاثة أن يبين للمضطر ما له أن يتناوله من المحرم الذي يمسكه به رمقة\",1,\"1:320\"],\"I-018\":[\"الجواب أن يقال: الوعيد في كل مكان من المكانين حسب ما ذكر من عظيم الذنب وكبير الجرم، فقال في سورة: (إن الذين يكتمون ما أنزل الله من الكتاب) فوصفهم بأنهم خالفوا الله في أمره ونقضوا ما قدم إليهم من عهده\",1,\"1:324\"],\"I-019\":[\"الجواب أن يقال: الأول خرج على أغلظ الوعيد كما قال: (ولا تقربا هذه الشجرة..)، وإنما كان نهي عن أكلها لا عن الدنو منها، فخرج مخرج قول القائل- إذا نهى عن الشيئ وشدد الأمر فيه -: لا تقرب هذا الشيئ\",1,\"1:328\"],\"I-020\":[\"الجواب عن ذلك أن يقال: إن الآية الأولى من سورة البقرة جاءت في قتال أهل مكة، ألا ترى ما قبلها: (واقتلوهم حيث ثقفتموهم وأخرجوهم من حيث أخرجوكم..)\",1,\"1:331\"],\"I-021\":[\"الجواب أن يقال: بل لكل موضع معنى يقتضي اللفظ الذي خص به\",1,\"1:336\"],\"I-022\":[\"والجواب عن ذلك أن يقال: إن الكاف تجئ في الكلام اسما للمخاطب كقوله: رأيتك، وغلامك، والكاف هاهنا اسم للمخاطب، وموضعها نصب في رأيتك وجر في غلامك.\",1,\"1:342\"],\"I-023\":[\"فالجواب عن ذلك أن يقال: إن الأول تعلق بقوله\",1,\"1:347\"],\"I-024\":[\"والجواب أن يقال: أن يقال: إن الآية الأولى في الكفار الذين استحلوا ما حرم الله، وعارضوا ما أنزل الله فقالوا (إنما البيع مثل الربا) حتى قال: (فأولئك أصحاب لنار هم فيها خالدون)، فعظم الله تعالى كفرهم\",1,\"1:350\"],\"I-025\":[\"فالجواب عن هذا أن يقال: العدول عن النهج الأول المستمر في الإخبار عن النفس إلى لفظ ظاهر هو لفائدة تتضمنها هذه اللفظة من الإحتجاج، وليست هذه الفائدة في لفظةالإضمار\",1,\"1:358\"],\"I-025b\":[\"والجواب فيها أن يقال: يجوز أن تكون الكاف متعلقة بقوله: (.. لن تغني عنهم أموالهم ولا أولادهم..) فيكون موضع الكاف نصبا على معنى المصدر، كأنه قال: لن تغني عنهم أموالهم ولا أولادهم مثل ما لم تغن عن آل\",1,\"1:362\"],\"I-026\":[\"فالجواب أن يقال/ إن الأول الذي ذكر الضمير فيه؟\",1,\"1:372\"],\"I-027\":[\"والجواب أن يقال: إنما لم يجب في الأولين من التوكيد ما أوجبه اختيار الكلام الموضع الثالث\",1,\"1:379\"],\"I-028\":[\"والجواب أن يقال: إن الذي في سورة المائدة جاء على الأصل غير مخفف بالحذف، لأنه أول كلام الحواريين في هذا المعنى، ألا تراه خبرا عن الله تعالى أنه قال: (وإذ أوحيت إلى الحواررين أن آمنوا برسولي قالوا آمنا واشهد بأننا مسلمون)\",1,\"1:384\"],\"I-029\":[\"والجواب أن يقال: القصد إعلام المخاطبين أن النصر ليس من قبل الملائكة، ولا من جهة العدد والعدة وفضل القوة، ولكنه من القادر الذي لا يغلب ولا يمنع عما يريد فعله، والحكيم الذي يضع النصر موضعه.\",1,\"1:393\"],\"I-030\":[\"والجواب: أن الآية من هذه السورة مبنية على تداخل الأخبار، لأن أولها: (جزاؤهم مغفرة من ربهم وجنات تجري من تحتها الأنهار خالدين فيها ونعم أجر العاملين).\",1,\"1:396\"],\"I-031\":[\"والجواب أن يقال: إن الزبر والكتاب المنير في سورة آل عمران وقعا في كلام بني على الاختصار والاكتفاء بالقليل عن الكثير مع وضوح المعنى.\",1,\"1:401\"],\"I-032\":[\"وجوابه في الآية الثانية: (فقد ضل ضلالا بعيدا)؟\",1,\"1:404\"],\"I-033\":[\"والجواب عن الأولى: أن معناها: إن خافت امرأة من زوجها ترفعا ونبوا لملل أو إعراضا موجدة أو بدل فلا إثم في إثم في أن يتصالحا على أن تترك له من مهرها، أو بعض أياما ما يتراضيان به، والصلح خير من أن يقيما على التباعد\",1,\"1:409\"],\"I-034\":[\"والجواب عن المسألة الأولى- وهي التكرار- أنه: إذا أعيد الكلام لأسباب مختلفة لم يسم تكرارا، فالأول بعد الإذن للرجل وامرأته في أن يتفرقا بطلاق، وتسليتهما عن الوصلة بأنه هو الذي يغني المحتاج منهما\",1,\"1:415\"],\"I-035\":[\"والجواب أن يقال: إن الآية الأولى في الشهادة أمر الله عز وجل من عنده شهادة أن يقوم بالحق فيها\",1,\"1:419\"],\"I-036\":[\"والجواب أن يقال: إنما خص في هذا الموضع الخير بالإبداء لأنه بإزاء السوء الذي قال فيه: (لا يحب الله الجهر بالسوء من القول إلا من ظلم..)، والمعنى: لا يحب الله أن يجهر بالقول السيء غير المظلوم، وهو أن يدعوا على من ظلمه\",1,\"1:426\"],\"I-037\":[\"والجواب أن يقال: لقوله تعالى: (لهم) في الأولى، وقوله: (منهم) في الثانية فائدة، وذلك أنه\",1,\"1:429\"],\"I-038\":[\"والجواب أن يقال: إن الآية الأولى في اليهود الذين حرفوا ما أنزل الله تعالى من كلامه عما علموه تأويلا له، فيكون هذا تحريفا من جهة التأويل\",1,\"1:435\"],\"I-039\":[\"فالجواب يقال: إن قوله تعالى في الآية الأولى: يبين لكم كثيرا مما كنتم تخفون معناه، يبين لكم كثيرا مما في التوراة والإنجيل من وصف الرسول وسائر ما يدعوا إلى الدخول في الإسلام، ويترك كثيرا مما حرفتموه، فلا يبينه\",1,\"1:443\"],\"I-040\":[\"والجواب أن يقال: إن الآية في سورة الفتح نزلت في قوم تخلفوا عن رسول الله من غير عذر، وتأخروا عن الجهاد، وقالوا، شغلتنا أموالنا وأهلونا، ثم سألوه عليه السلام أن يستغفر لهم، يكتمون بذلك نفقاتهم ويظهرون وفاقهم\",1,\"1:445\"],\"I-041\":[\"والجواب أن يقال: إن الآية في سورة الفتح نزلت في قوم تخلفوا عن رسول الله من غير عذر، وتأخروا عن الجهاد، وقالوا، شغلتنا أموالنا وأهلونا، ثم سألوه عليه السلام أن يستغفر لهم، يكتمون بذلك نفقاتهم ويظهرون وفاقهم\",1,\"1:445\"],\"I-042\":[\"والجواب أن يقال: إن تسمية المخاطب بندائه مع إقبال عليه يفيد مبالغه في التنبيه له.\",1,\"1:453\"],\"I-043\":[\"والجواب أن يقال: إن الآية الأولى قوله تعالى: إنا أنزلنا التوراة فيها هدى ونور يحكم بها النبيون الذين أسلموا للذين هادوا والربانيون والأحبار استحفظوا من كتاب الله وكانوا عله شهداء فلا تخشوا الناس واخشون\",1,\"1:462\"],\"I-044\":[\"الجواب عن حذف أبدا في بعضها والاتيان في بعضها فهو أنها إنما حذفت عن أولى الآيتين اللتين في براءة آية في سورة المجادلة، لأنه ذكر قبل الآية التي في سورة براءة، وأولئك لهم الخيرات وأولئك هم المفلحون\",1,\"1:474\"],\"I-045\":[\"فالجواب أن يقال إن الآية والأولى قد وفي المعنى فيها حقه من اللفظ، لأنها سابقة للثانية وإن كانتا مكيتين فاشبعت ألفاظ الأولى مستوفية لمعناها.\",1,\"2:478\"],\"I-046\":[\"والجواب أن يقال: إن الألف تدخل على واو العطف في الاستخبار والإنكار والتقريع على تقدير أن تكون الجملة التي فيها الواو معطوفة على الكلام مثلها يقتضيها وذلك كقولك لقائل: هل رأيت زيدا ثمة؟\",1,\"2:482\"],\"I-047\":[\"فالجواب أن يقال: الفاء هاهنا أولى/ لأن قبلها: وقال الذين كفروا هل ندلكم على رجل ينبئكم إذا مزقتم كل ممزق إنكم لفي خلق جديد، أفترى على الله كذبا أم به جنة بل الذين لا يؤمنون بالآخرة في العذاب والضلال البعيد\",1,\"2:487\"],\"I-048\":[\"فالجواب أن يقال: الفاء هاهنا أولى/ لأن قبلها: وقال الذين كفروا هل ندلكم على رجل ينبئكم إذا مزقتم كل ممزق إنكم لفي خلق جديد، أفترى على الله كذبا أم به جنة بل الذين لا يؤمنون بالآخرة في العذاب والضلال البعيد\",1,\"2:487\"],\"I-049\":[\"والجواب عن ذلك أن يقال: إن قوله:...\",1,\"2:490\"],\"I-050\":[\"والجواب أن يقال: إن السورتين اللتين وقعت فيهما الآيتان مكيتان، والأولى منها قبل الثانية.\",1,\"2:493\"],\"I-051\":[\"والجواب عن الأول أن يقال: إن ما تقدم الآية الأولى من قوله: (قل أي شئ أكبر شهادة..) إلى قوله: (ومن أظلم..) جمل عطف صدور بعضها على بعض الواو، ولم تتعلق الثانية بالأولى تعلق ما هو من سببها، فأجرى قوله: (ومن أظلم) مجراها\",1,\"2:499\"],\"I-052\":[\"والجواب أن يقال: إن لكل من الموضعين ما يوجب اختصاصه باللفظ الذي جاء فيه فأما قوله تعالى: (ومنهم من يستمع إليك وجعلنا كل قلوبهم أكنة أن يفقهوه وفي آذانهم وقرا)\",1,\"2:503\"],\"I-053\":[\"فالجواب أن يقال: إن النحويين في قوله تعالى: (أريأتكم) على مذهبين: أحدهما: مذهب أهل البصرة، وهو أن الكاف في أرأيتك زيدا عاقلا للخطاب كالكاف في أرأيتك زيدا عاقلا للخطاب كالكاف في ذلك وليست باسم\",1,\"2:509\"],\"I-054\":[\"فالجواب أن يقال: إن الآية الأولى التي في سورة الأنعام في قوم من الكفار، كانوا إذا سمعوا آيات الله هزلوا عندها واستهزأوا بها، فهذا اتخاذهم دين الله لعبا\",1,\"2:517\"],\"I-055\":[\"والجواب أن يقال: إن أول هذه الآية ذكر بلفظ الاسم وهو (فالق الحب والنوى) فكان اللائق به أن يقال: ومخرج الحي من الميت ولكنه لما اجتمع ثلاثة حروف من حروف العلة دفعة واحدة\",1,\"2:527\"],\"I-056\":[\"فالجواب أن يقال: إن قوله تعالى: (قد فصلنا الآيات لقوم يعلمون) جاء بعد آيات نبهت على معرفة الله تعالى\",1,\"2:530\"],\"I-057\":[\"والجواب أن يقال: لأن ما في هذه السورة جاء بعد قوله تعالى: وجعلوا الله شركاء الجن وخلقكم وخرقوا له بنين وبنات بغير علم، فلما قال: ذلكم الله ربكم، أتى بعده بما يدفع قول من جعل لله شريكا، فقال: لا إله إلا هو\",1,\"2:535\"],\"I-058\":[\"والجواب أن يقال: إن الأولى قبلها: وكذلك جعلنا لكل نبي عدوا شياطين الإنس والجن يوحي بعضهم إلى بعض زخرف القول غرورا، أي: كا للأنبياء قبلك من قبل العدو من الإنس والجن\",1,\"2:537\"],\"I-059\":[\"والجواب أن يقال: إن مكان كل واحد يقتضي ما وقع فيه، وبين اللفظين فرق في المعنى يوجب اختصاص اللفظ الذي جاء له بمكانه.\",1,\"2:540\"],\"I-060\":[\"والجواب أن يقال: إن الأول قبله، أو من كان ميتا فأحييناه وجعلنا له نورا يمشي به في الناس كمن مثله في الظلمات ليس بخارج منها\",1,\"2:545\"],\"I-061\":[\"والجواب: إن ذلك إشارة إلى ما تقدم ذكره من العقاب في قوله: قال النار مثواكم خالدين فيهان الأنعام: وبعده: يا معشر الجن والإنس ألم يأتكم رسل منكم يقصون عليكم آياتي وينذرونكم لقاء يومكم هذا.\",1,\"2:548\"],\"I-062\":[\"والجواب أن يقال: أمر الله نبيه في سورة الأنعام بأن يخاطب الكفار على سبيل الوعيد: اعملوا على طريقتكم وجهتكم، أو على تمكنكم فسوف تعملون، أي: اعملوا فستجزون وتعملون وإساءتكم إلى أنفسكم.\",1,\"2:551\"],\"I-063\":[\"والجواب أن يقال: إن قوله: (ما أشركنا) مستغن عن ذكر المفعول به، وإن كان في الأصل متعديا إليه\",1,\"2:555\"],\"I-065\":[\"والجواب أن يقال: قدم الله تعالى الوصية بالأشرف الأعظم وهو الإيمان بدل الشرك، وفيه أداء حق أكبر المنعمين ثم الإحسان إلى الوالدين ونعمتهما على الولد أكبر النعم بعد نعمة الله تعالى، فحقها يتلو حقه\",1,\"2:564\"],\"I-066\":[\"والجواب ما قلته فيما قبله، وأقوله فيما بعده من أن اقتصاص ما مضى إذا لم يقصد به أداء الألفاظ بأعيانها، وإنما المقصود ذكر المعني، فإن الألفاظ إذا اختلفت وأدت المعنى المقصود كان اختلافها واتفاقها سواء.\",1,\"2:572\"],\"I-067\":[\"والجواب أن يقال: إن قوله: (أنظرني) في سورة الأعراف وقد مستأنفا، غير مقصود به عطف على ما يقع به هذا السؤال عقيبه فلم يحتج إلى الفاء.\",1,\"2:576\"],\"I-068\":[\"والجواب عن اختلاف الألفاظ المحكية ان يقال متى حملت الباء على القسم في قوله: (فبما أغويتني) و(رب بما أغويتني) في الآيتين بشهادة الآية الثالثة، وهي: (فبعزتك) لم يكن هناك اختلاف في المعنى\",1,\"2:581\"],\"I-069\":[\"والجواب أن يقال: إن الذي في سورة الأعراف جاء على أصله غير مزيد فيه ما يجري مجرى التوكيد، والذي في سورة هود جاء بعد قوله: (ويقول الأشهاد هؤلاء الذي كذبوا على ربهم) فأشير إليهم\",1,\"2:585\"],\"I-070\":[\"والجواب أن يقال: بل لكل ما يوجب في الإختيار اللفظ الذي جاء عليه، وإن كان وصف الله عز وجل بأنه أرسل الرياح فبسط بها السحاب فساقه فأنزل منه الأمطار فأحيا بها البلاد، كوصفه بأنه يفعل ذلك في المستقبل، لأنه قادر كما كان\",1,\"2:589\"],\"I-071\":[\"والجواب أن يقال إن الآيات التي تقدمت قوله تعالى: (لقد أرسلنا نوحا إلى قومه..) في سورة الأعراف إلى أن اتصلت به في وصف ما اختص الله عز وجل به من أحداث خلقه وبدائع فعله من حيث قال:\",1,\"2:593\"],\"I-072\":[\"والجواب أن يقال: إن للأنبياء صلوات الله عليهم مقامات مع أممهم يكرر فيها الإعذار والإنذار، ويرجع فيها عودا على بدء، الوعد والوعيد، ولا يكون دعاؤهم إلى الإيمان بالله\",1,\"2:598\"],\"I-073\":[\"والجواب أن يقال: إن الموضعين اللذين دخلتهما الفاء ما بعدهما مما اقتضاه كلام النبي مما رآه الكفار جوابا له، فكان بناء الجواب على الابتداء يوجب دخول الفاء.\",1,\"2:602\"],\"I-074\":[\"والجواب عن ذلك من وجهين: أحدهما أن يقال: إن المعنى كلام نوح عليه السلام ما نطق به القرآن، ومعنى كلام هود عليه السلام ما ذكره الله تعالى حاكيا عنه\",1,\"2:604\"],\"I-075\":[\"والجواب أن يقال: السورتان مكيتان جميعا، إلا الآية في سورة الأعراف، وقوله: أنجينا أصل في هذا الباب، لأن أفعلت في باب النقل أصل ل فعلت وهو أكثر، تقول: نجا، وأنجيته كما تقول: ذهب وأذهبته، ودخل وأدخلته.\",1,\"2:607\"],\"I-076\":[\"والجواب أن يقال: إن هؤلاء سألوا أن يخرج لهم من هضبة ملساء ناقة، فسأل الله تعالى صالح عليه السلام، وفي خبر آخر: أنه بدأهم بهذه الآية، لا عن مسألة كانت منهم، فانفرجت عن ناقة بعدما تمخضت تمخض المرأة، والناقة عشراء\",1,\"2:612\"],\"I-077\":[\"والجواب أن يقال: إذا كان الجمع والتوحيد جائزين كان وجه التوحيد على طريقين: أحدهما: أن يراد بدارهم بلدهم، فيوحد ذهابا إلى معنى البلد، وهو موحد.\",1,\"2:618\"],\"I-078\":[\"والجواب عن ذلك أن يقال: إن الذي نطق به القرآن من تحذير صالح عليه السلام قومه بعد أن أمرهم باتقاء الله تعالى وطاعته، وهو أمر الناقة، والمنع من التعرض لها\",1,\"2:623\"],\"I-080\":[\"فالجواب عنه أن يقال: إن السورتين مكيتان وموجب هذا الإضمار والإظهار ان يكون ما جاء فيه الإظهار نازلا قبل ما جاء فيه من الإضمار\",1,\"2:635\"],\"I-081\":[\"والجواب عن ذلك: أن سقوط (به) من قوله: (كذبوا) هو للبناء على ما جعل صدرا لهذه الآيات التي نزلت في الترغيب والترهيب\",1,\"2:641\"],\"I-082\":[\"والجواب أن يقال: إن قول الملأ فيما حكاه الله تعالى في سورة الأعراف قول فرعون، أداه عنه رؤساء قومه إلى عامة اصحابه، والدليل على أن ذلك قوله، وأنهم فيه مؤدو رسالة عنه قول العامة في جوابه: (أرجه وأخاه)\",1,\"2:648\"],\"I-083\":[\"والجواب أن يقال: لما أسند الفعل في سورة الشعراء إلى فرعون، وحكى ما قاله وأنه قال للملأ حوله من قومه (إن هذا لساحر عليم) وكان أشهدهم تمردا وأولهم تجبرا، وأبلغهم فيما يرد به الحق\",1,\"2:651\"],\"I-084\":[\"والجواب أن يقال: اللفظتان نظيرتان، تستعمل إحداهما مكان الأخرى، وقد جاء: بعث الرسول، وأرسله معا، إلا أن أرسل يختص بما لا يختص به بعث لأن البعث لا يتضمن ترتيبا، والإرسال أصله: تنفيذ من فوق إلى أسفل.\",1,\"2:654\"],\"I-085\":[\"والجواب ما دللنا عليه من أن ما في سورة الشعراء أشد ابتداء مبعثه إليه حيث قال: (وإذ نادى ربك موسى أن إئت القوم الظالمين* قوم فرعون ألا يتقون).\",1,\"2:656\"],\"I-086\":[\"والجواب أن يقال: لما تقدم في سورة الشعراء ما شرحه أكثر وما في سورة الأعراف أوجز وأخصر\",1,\"2:659\"],\"I-087\":[\"والجواب أن معنى قوله إذا جواب وجزاء، وكان من قول فرعون لهم: إن غلبتم فجزائي أن أجازيكم بإعلاء رتبتكم، وتقريب منزلتكم، لأنها موضع بني على فصل اقتصاص لما جرى، لم يبن غيرها عليه من نحو ما تقدم وما يجيء.\",0,\"2:661\"],\"I-088\":[\"والجواب أن يقال: أن المقصود معنى واحد\",1,\"2:663\"],\"I-090\":[\"والجواب أن يقال: إذا قيل: (رب العالمين) فقد دخل فيهم موسى وهارون وهما دعوا إلى رب العالمين لما قالا: (.. إنا رسول رب العالمين) إلا إنه كرر في السورتين:\",1,\"2:666\"],\"I-091\":[\"والجواب عن السؤال الأول، وهو إظهار اسم فرعون في سورة الأعراف، لأنه جاء في الآية العاشرة من الآيى التي أضمر فيها ذكره، وهي قوله: (قال نعم وإنكم لمن المقربين)\",1,\"2:668\"],\"I-092\":[\"والجواب أن يقال: إن قوله تعالى: (فسوف تعلمون) من الوعيد المبهم المعرض بأي: فعلت بجهل ما تعرف من بعد نتيجته، وطرحت بذر شر، عند حصده تعلم نهايته.\",1,\"2:674\"],\"I-093\":[\"والجواب أن يقال: إن السورتين اللتين اختصا بالواو هما المبنيتان على الاقتصاص الأكثر والبسط الأوسع، والواو أشبه بهذا المعنى، لأنه يجوز أن يكون ما بعدها ملاصقا لما قبلها كالتعقيب الذي يفاد بالفاء\",1,\"2:678\"],\"I-094\":[\"والجواب أن يقال: إنهم قابلوا وعيده بما يهونه ويزيل ألمه من انتقالهم إلى ثواب ربهم مع المتحقق من منقلب معذبهم، فجاء في سورة الشعراء وهي التي قصد بها الإقتصاص الأكبر: (لا ضرير) أي لا ضرر علينا\",1,\"2:680\"],\"I-095\":[\"والجواب أن يقال: إن الألى بعد قوله: (يسألونك عن الساعة أان مرساها قل إنما علمها عند ربي) وبعده: (قل إنما علمها عند الله ولكن أكثر الناس لا يعلمون) فكان معنى قوله: (قل لا أملك لنفسي نفعا ولا ضرا) أي: لا أملك تعجيل ثواب\",1,\"2:682\"],\"I-096\":[\"والجواب أن يقال: إن الأول وقع في فاصلة ما قبلها من الفواصل أفعال جماعة، واسماء مأخوذة من الأفعال نحو قوله تعالى (فتعالى الله عما يشركون).\",1,\"2:687\"],\"I-097\":[\"والجواب أن يقال: إن التي في سورة الأعراف خبر عن قوم ذكروا قبل هذه الآية في قوله تعالى:\",1,\"2:691\"],\"I-098\":[\"والجواب أن يقال: إن الآية الأولى في سورة الأنفال عقيب ما أنكره الله تعالى على من قال لهم: (تريدون عرض الدنيا والله يريد الآخرة والله عزيز حكيم)، وهم أصحاب النبي لما أسروا المشركين، ولم يقتلوهم طمعا في الفداء\",1,\"2:696\"],\"I-099\":[\"والجواب أن يقال: إن المراد ب، (الظالمين) في الآية الأولى مشركو العرب الذين أقاموا بسقايا الحاج، وأنفقوا\",1,\"2:700\"],\"I-100\":[\"والجواب أن يقال: إن الإرادة في الآية الأولى تعلقت بإطفاء نور الله بأفواههم، وإطفاء نور الله إنما يكون بما حاولوا من دفع الحق بالباطل فالحق يسمى نورا، لأن حججه وبراهينه تضيء لطالبه بها إليه، والباطل هو قوله بأفواههم\",1,\"2:704\"],\"I-101\":[\"والجواب أن يقال: لما كان الأول فيه إيجاب بعد نفي صار الخبر أوكد، وإلى أمارة التوكيد أو حج، ألا ترى أن قولك ما زيد إلا فاضل أوكد من قولك: زيد فاضل\",1,\"2:710\"],\"I-102\":[\"والجواب عن المسألة الأولى في الفاء والوار، ومجيء الآية الأولى على (فلا تعجبك) والآخرة على (ولا تعجبك) هو أن يقال: إن قبل الفاء قوله تعالى (ولا يأتون الصلاة إلا وهم كسالى ولا ينفقون إلا وهم كارهون).\",1,\"2:713\"],\"I-103\":[\"والجواب عن المسألة الأولى أن قوله تعالى: (وطبع) في آخر آية افتتحت بقوله تعالى: (وإذا أنزلت سورة) والمعنى: وإذا أنزل الله سورة، فلما صدرت الآية بفعل علم أن فاعله الله فيما لا يقتضي ذكر الفاعل به مزية\",1,\"2:719\"],\"I-104\":[\"والجواب عن الأولى أن يقال: إن المخاطبين في الآية الأولى هم المنافقون، والمخاطبون في الثانية هم المؤمنون\",1,\"2:724\"],\"I-105\":[\"والجواب عن المسألة الأولى هو أن في جملة ما ذكره تعالى مما أوجب لهم الأجر ليست من أعمالهم\",1,\"2:729\"],\"I-106\":[\"فالجواب ان يقال: إنما قدم: (ما لا يضرهم) على (لا ينفعهم) في الآية الأولى لأن العبادة تقام للمعبود خوفا من العقاب أولا، ثم رجاء للثواب ثانيا\",1,\"2:733\"],\"I-107\":[\"والجواب عن المسألة الأولى، وهي ترك الواو في هذا الموضع وإثباتها في سورة المؤمن: أن القصة بعد (كذلك) هي التي قبلها، فهي مرتبطة بها بعودها إليها، وبكاف التشبيه، فاستغنت بهذين\",1,\"2:737\"],\"I-108\":[\"فالجواب عن المسألة الأولى، واختصاص ما حيث اختصت، واختصاص من حيث اختصت، هو أن الأولى جاءت بعد قوله تعالى: (ولو أن لكل نفس ظلمت ما في الأرض لافتدت به..)\",1,\"2:743\"],\"I-109\":[\"والجواب أن يقال: أن قبل هذه الآية في سورة يونس قوله تعالى: (ثم ننجي رسلنا والذين آمنوا كذلك حقا علينا ننج المؤمنين) فقال بعده: وأمرت أن أكون منهم.\",1,\"2:748\"],\"I-110\":[\"والجواب أن يقال: إن الآية الأولى فإنه لما قال فيها: (فمن يهتدي لنفسه) أي منفعة اهتدائه له، وهي دوام النعمة والخلود في الجنة فاقتضى هذا في الضلال ضده، فقال: «ومن ضل فإنما يضل عليها) أي ضرر ضلاله عليه\",1,\"2:750\"],\"I-111\":[\"والجواب أن يقال: إن الآية التي في سورة هود قد تقدمها قوله: (... وما كان لهم من دون الله من أولياء يضاعف لهم العذاب ما كانوا يستطيعون السمع وما كانوا يبصرون)\",1,\"2:753\"],\"I-112\":[\"والجواب أن يقال: إن المعنيين واحد في الموضعين، وقول النبيين سواء لأمتيهما، وإنما اختلفا بإخبار الله تعالى في موضع خبر قدم فيه المفعول الثاني على الجار والمجرور، لإجراء هذا الفعل ومفعوليه على ما جرى عليه الفعل الذي قبله\",1,\"2:756\"],\"I-113\":[\"والجواب أن الاولى أتى فيها بالموصوف والصفة جميعا، وهو الأصل الأول، ثم الاكتفاء بالصفة عن الموصوف بعده لقيام الدلالة على الموصوف، فيجوز لذلك حذفه، وإقامة الصفة مقامه.\",1,\"2:759\"],\"I-114\":[\"والجواب أن يقال: أما (تدعونا) في الأولى و(تدعوننا) في الثانية، فلا يصح مكانهما غيرهما، فلا يجوز في الأولى إلا نون واحدة ولا يجوز في الثانية إلا نونان اثنتان، لأن الأولى خطاب\",1,\"2:760\"],\"I-115\":[\"والجواب أن يقال: إن مثل هذا إذا جاء في كلام العرب سهل الكلام فيه، لأنه يقال: حمل على المعنى، والصيحة بمعنى الصياح\",1,\"2:764\"],\"I-117\":[\"والجواب عن المسألة الأولى: أن الاستثناء في سورة الحجر أغنى منه قوله تعالى فيما حكى عن الرسل: (..إنا أرسلنا إلى قوم مجرمين* إلا آل لوط إنا لمنجوهم أجمعين* إلا امرأته إنها لمن الغابرين)\",1,\"2:770\"],\"I-118\":[\"والجواب أن يقال: إن مفتتح قصص الأنبياء عليهم السلام في سورة الأعراف قوله تعالى: (لقد أرسلنا نوحا إلى قومه) وبعده: (وإلى عاد أخاهم هودا) وبعده: (وإلى ثمود أخاهم صالحا)\",1,\"2:773\"],\"I-119\":[\"والجواب أن يقال: إن الآيات: الأمارات التي يكتفي بها في صدق الرسل عليهم السلام، وبها تقوم الحجة على من تبعث إليهم، والسلطان المبين هو الحجج القاهرة التي تقهر القوم، كأنواع العذاب\",1,\"2:778\"],\"I-120\":[\"والجواب عن ذلك أن يقال: إن هذه اللام تسمى لام الجحود، ولا تخلوا منه، وهي تخالف لام كي بأشياء.\",1,\"2:783\"],\"I-121\":[\"والجواب أن يقال: إن هذا الحرف في قصة هود بعد خروج من خبر عنه\",1,\"2:790\"],\"I-122\":[\"والجواب أن يقال: إن بلوغ الأشد مختلف فيه: قيل: هو أن يبلغ ثلاثا وثلاثين سنة، وقيل: خمسا وعشرين سنة، وقيل: عشرين سنة وإحدى عشرين، لأنه يقال: إن الصبي يثغر لسبع سنين، ويبلغ لسبع بعدها، ويتناهى طوله لسبع بعدها\",1,\"2:795\"],\"I-123\":[\"والجواب أن يقال: إن من لابتداء الغاية، وقبل اسم للزمان الذي تقدم زمانك، فإذا قال: (وما أرسلناك من قبلك) فكأنه قال: وما أرسلنا من ابتداء.\",1,\"2:799\"],\"I-124\":[\"والجواب أن يقال: كل موضع تقدم قوله تعالى: (أفلم يسيروا في الأرض) فإنه في موضع يقتضي الأول وقوع ما بعد الفاء.\",1,\"2:803\"],\"I-125\":[\"والجواب عن الأول أن قبله: (فخلف من بعدهم خلف ورثوا الكتاب يأخذون عرض هذا الأدنى)\",1,\"2:808\"],\"I-126\":[\"والجواب أن يقال: إن التفكر هو المؤدي إلى معرفة الشيء، والعلم بالآيات التي تدل على وحدانية الله تعالى، فهو قبل، فإذا استعمل على وجه عقل ما جعلت هذه الأشياء أمارة له ودلالة عليه.\",1,\"2:812\"],\"I-127\":[\"والجواب إن لكم في آخر الآية الأولى مذكورة، لأنه قال: (فأخرج به من الثمرات رزقا لكم) فأغنى ذكرها هناك عن ذكرها أولا\",1,\"2:815\"],\"I-128\":[\"والجواب أن يقال: إن القصة في سورة الحجر ابتدءت في المعتمد بالذكر\",1,\"2:816\"],\"I-129\":[\"والجواب أن يقال: ذلك في قوله: (إن في ذلك لآيات للمتوسمين) إشارة إلى ما قص من حديث لوط وضيف إبراهيم، وتعرض قوم لهم طمعا فيهم، وما كان من أمرهم آخرا من إهلاك الكفار وقلب المدينة على من فيها وإمطار الحجارة على من غاب عنها.\",1,\"2:818\"],\"I-130\":[\"والجواب أن يقال: إنما وحد في الأولى، لأن جميع ما أخبر عنه خلقه إنما هو في جنس من\",1,\"3:821\"],\"I-131\":[\"والجواب أن يقال: لما ذكر الله تعالى في سورة النحل النعم التي سخرها البحر من أجلها فقال: (وهو الذي سخر البحر) لكذا وكذا، فعد جملا ثلاثة من نيل سمكة، واستخراج حلية، وطلب فضله بركوبه، كان وجه، فعد جملا ثلاثة من نيل سمكة\",1,\"3:829\"],\"I-132\":[\"والجواب أن يقال: إن الآية من هذه السورة في ذكر قوم قد ضلوا في أنفسهم وأضلوا غيرهم، وهم الذين أخبر الله تعالى عن أتباعهم أنهم أنهم سألوهم عن القرآن فقالوا: ليس من عند الله، وإنما هو أساطير الأولين\",1,\"3:837\"],\"I-133\":[\"والجواب أن يقال: إن الآية الأولى افتتحت بخطاب الشاهد فأجرى قوله: (فتمتعوا) على هذا اللفظ، والآية الأخيرة افتتحت بالإخبار عن الغائب\",1,\"3:841\"],\"I-134\":[\"والجواب أن يقال: قد تقدّم في العشر التي تليها: (ولو يؤاخذ الله الناس بظلمهم) الخبرُ عن الذين نهوا عن أن يتخذوا إلهين اتنين وأن يشركوا الأصنام في عبادته، وأن يجعلوا لها نصيبا من أموالهم، ويدعوا الملائكة بنات ربّهم\",1,\"3:843\"],\"I-137\":[\"والجواب أن يقال: ذكر في سورة النحل الجملة التي فصّلت في سورة الحج، وكانت لفظة \\\"بعد\\\" لجملة الزمان المتأخر عن الشيء، قال: (والله خلقكم) فأجمل ما فصّله في السورة الأخرى\",1,\"3:854\"],\"I-138\":[\"والجواب أن يقال: إن الكلام في سورة النحل قد نقل عن الخطاب الذي\",1,\"3:857\"],\"I-139\":[\"والجواب أن يقال: إن الأولى جاءت بعد إخبار المتمرّدين من الكفار وعما\",1,\"3:859\"],\"I-140\":[\"والجواب أن يقال: إن الأولى بعد قوله: (أفأمنتم أن يخسف بكم جانب البر) وهو خطاب لمن ينجيهم من ضرّ البحر ويُسلمهم إلى البرّ فيعوضون عن ذكر ما كانوا فيه من المخافة عند الأمن، ويكفرون بما أنعم به عليهم من النجاة\",1,\"3:862\"],\"I-142\":[\"والجواب أن يقال: إن الأولى بقوله: (رُددت إلى ربّى) أولى، وذلك لما تقدّم\",1,\"3:874\"],\"I-143\":[\"والجواب أن يقال: إن «الفاء» و«ثم» مشتركان في أنّ ما بعدهما في اللفظ متأخر عمّا قبلها في المعنى، ومختلفان في أنّ \\\"الفاء\\\" قرُب ما بعدها ممّا قبلها، وفي \\\"ثم \\\" تراخ عنه وبُعْد، فكان استعمال الفاء في سورة الكهف أولى\",1,\"3:876\"],\"I-144\":[\"والجواب أن يقال: قيل: الإمر: إنه الداهية، وقيل: إنه العجب.\",1,\"3:878\"],\"I-145\":[\"والجواب أن يقال: إنه في الأولى لماّ قرّر موسى وذكر ما كان قدّم القول\",1,\"3:881\"],\"I-147\":[\"والجواب أن يقال: كلتا الآيتين في قصّة عيسى عليه السلام وتوعّد من\",1,\"3:885\"],\"I-148\":[\"والجواب أن يقال: أما الأول فإنه بعد قوله: (فَخَلَفَ مِنْ بَعْدِهِمْ خَلْفٌ أَضَاعُوا الصَّلَاةَ وَاتَّبَعُوا الشَّهَوَاتِ فَسَوْفَ يَلْقَوْنَ غَيًّا إِلَّا مَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا...)\",1,\"3:887\"],\"I-149\":[\"والجواب أن يقال: إن الله تعالى لم يخبر أنه خاطب موسى عليه السلام باللغة العربية بألفاظ إذا عدل عنها إلى غيرها ممّا يخالف معناها كان اختلافا في القرآن قادحًا فيه، بل معلوم أن الخطاب كان بغير هذه اللغة\",1,\"3:890\"],\"I-150\":[\"والجواب عن ذلك أن قوله: (ربّ اشرح لي صدري) طلب أمانٍ له من أن يقتَل بمن قتله\",1,\"3:894\"],\"I-151\":[\"الجواب بالمبتدأ، والجزاء بالشرط، فتكون جملة تمامها بجملةٍ قبلها تثقل فيختار لها التخفيف.\",1,\"3:897\"],\"I-152\":[\"والجواب أن يقال: إنّ ماقبل الآية في سورة الأنبياء:\",1,\"3:901\"],\"I-153\":[\"والجواب أن يقال: إن الآية الأولى وقع السؤال فيها على وجه لا يقتضى \\\"بل\\\" في الجواب، لأنه قال: ما هذه الأصنام التي نحتّموها تماثيل وعكفتم عليها، فكأنه سفّه آراءهم وقال لهم: لم تفعلون ذلك\",1,\"3:903\"],\"I-154\":[\"والجواب أن يقال: أمّا في سورة الأنبياء فإن الله تعالى أخبر فيها عن إبراهيم عليه السلام أنه قال: (وتالله لأكيدنّ أصنامكم..)\",1,\"3:905\"],\"I-155\":[\"والجواب أن يقال: أخبر الله تعالى في سورة الأنبياء عن أيوب عليه السلام بأنه نادى ربّه وشكا إليه ما مسّه من الضرّ وسوء الحال بالمرض الذي طالت به أياّمه حتى تآكّل جسمه وتساقط لحمه، ثم بالفقر الذي ناله واجتاح مالَه\",1,\"3:907\"],\"I-156\":[\"والجواب أن يقال: لما كان القصد في سورة الأنبياء إلى الإخبار عن حال مريم وابنها، وأنهما جُعلا آية للناس، وكان النفخ فيها ممّا جعلها حاملا، والحامل صفة للجملة، فكأنه قال: (والتي أحصنت فرجها) فصيّرها النفخُ حاملا حتى ولدت\",1,\"3:912\"],\"I-157\":[\"والجواب أن يقال: في قوله تعالى: (إن هذه أمتكم أمة واحدة) ثلاثة أقوال: أحدها: أن تكون الإشارة بـ \\\"هذه \\\" إلى أمم الأنبياء - صلوات الله عليهم وسلامه - ويكون المعنى: أمتكم في حال كونهم جماعة واحدة\",1,\"3:914\"],\"I-158\":[\"والجواب أن يقال: إنه تعالى لماّ وصف من أحوال أهل النار في هذه السورة\",1,\"3:921\"],\"I-159\":[\"والجواب أن يقال: إن قوله: (فَكَأَيِّنْ مِنْ قَرْيَةٍ أَهْلَكْنَاهَا...) جاء بعد قوله: (وَإِنْ يُكَذِّبُوكَ فَقَدْ كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ...)\",1,\"3:926\"],\"I-160\":[\"والجواب: أن الأول خبر عن حال القوم في الدنيا: (قل يا أيها الناس إنما أنا لكم نذير مبين)، ثم قال: (فَالَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ) وُعدوا بالغفران والرزق الكريم، ولم يجز هنا أن يقال: هم.\",1,\"3:928\"],\"I-161\":[\"والجواب أن يقال: إن الأولى وقعت في مكان تقدمت فيه توكيدات مترادفة في ستة مواضع، وهي: قوله: (وَالَّذِينَ هَاجَرُوا فِي سَبِيلِ اللَّهِ ثُمَّ قُتِلُوا أَوْ مَاتُوا لَيَرْزُقَنَّهُمُ اللَّهُ رِزْقًا حَسَنًا...)\",1,\"3:930\"],\"I-162\":[\"والجواب عن ذلك نحو الجواب الأول، وهو شاهد يحقّق ما أجبنا به من اختيار التوكيد، حيث يقصد بناؤه على الكلام المتقدم له\",1,\"3:932\"],\"I-163\":[\"والجواب أن يقال: لما انقطعت صفة الملأ في الآية الأولى إلى المحكي من قولهم\",1,\"3:935\"],\"I-164\":[\"والجواب أن يقال: إن قوله: (قُلْنَا احْمِلْ فِيهَا) إخبارٌ عمّا كان من الله تعالى\",1,\"3:937\"],\"I-165\":[\"والجواب أن يقال: إن القصة الأولى وإن خرجت على لفظ التنكير فقال: (ثُمَّ أَنْشَأْنَا مِنْ بَعْدِهِمْ قَرْنًا آخَرِينَ فَأَرْسَلْنَا فِيهِمْ رَسُولًا مِنْهُمْ...)، فإنه معلوم مَن المراد بالرسول، وبالمرسَل إليهم\",1,\"3:940\"],\"I-166\":[\"والجواب أن يقال: لما كان الأول في حكاية تظاهرت فيها أفعال أسندت إلى\",1,\"3:943\"],\"I-167\":[\"والجواب أن يقال: إنّ هذه الآي جاءت بعدما أخبر الله تعالى عن الكفار من إنكار البعث، وهو في الآية التى تكلمّنا فيها، واتصلت هذه بها، فأمر نبيّه - ﷺ - بأن يسألهم لمِن الأرض ومن فيها؟\",1,\"3:946\"],\"I-168\":[\"والجواب أن يقال: لما ذكر في أول السورة حدّ الزنا والقذف وختم ذلك بقذف الرجل امرأته، والحكم فيه اعتدّ عليهم بأن أمهلهم ليتوبوا ولم يعاجلهم بالعقوبة على ما قارفوا، فقال: (ولولا فضل الله...) فإنّه يرجع به لمن رجع إليه\",1,\"3:950\"],\"I-169\":[\"والجواب أن يقال: إن الأولى إشارة إلى ما تقدم ذكره فيما أوّله:\",1,\"3:954\"],\"I-170\":[\"والجواب أن يقال: أما في سورة الرعد فإنه قدّم فيها الأفضل على الأنقص\",1,\"3:957\"],\"I-171\":[\"والجواب أن يقال: أمّا في سورة يونس فإنه بدأ بما هو أبلغ إذا ابتدئ به، لأن امتلاك الضر أسهل من امتلاك النفع، فالواحد منّا يقدر لغيره من الضرّ على ما لايقدر عليه من النفع، ويتسهّل عليه ضرّه ما لايتسهّل عليه نفعه\",1,\"3:959\"],\"I-172\":[\"والجواب أنه إنما خصّ هذين الوصفين من صفات الله تعالى في هذين\",1,\"3:961\"],\"I-173\":[\"والجواب أن يقال: إن قوله: (ما تعبدون) معناه: أيّ شيء تعبدون، وقوله: \\\"ماذا\\\" في كلام العرب على وجهين: أحدهما: أن تكون \\\"ما\\\" وحدها اسما، و\\\" ذا\\\" بمعنى الذي، والمعنى: ما الذي تعبدون، و(تعبدون) صلة لها.\",1,\"3:965\"],\"I-174\":[\"والجواب أن يقال: لو جاء: والذي يطعمني ويسقين، وإذا مرضت يشفين، لَكان معلومًا أن مراده الله تعالى.\",1,\"3:967\"],\"I-175\":[\"والجواب أن يقال: إن قوم صالح في حال هذا الخطاب لم يدفعوا أمره، كما دفع أمر شعيب قومه كما حكى الله تعالى من قولهم لصالح عليه السلام.\",1,\"3:969\"],\"I-176\":[\"الجواب أن يقال: إنّ المحكيات ليس يشترط فيها إذا أدّيت معانيها دون ألفاظها استيعاب جميعها في مكان واحد، بل يجوز أن تفرق في أماكن كثيرة، فهذا وجه، ويكون معنى: (إنك من الآمنين) أي من المرسلين الذين لا يخافون\",1,\"3:975\"],\"I-177\":[\"والجواب أن يقال: إنّ قوله:\",1,\"3:979\"],\"I-178\":[\"والجواب عن ذلك أن يقال: إن هذه الآية جاءت بعد قوله:...\",1,\"3:987\"],\"I-179\":[\"والجواب عن ذلك أن يقال: إن نسخ الليل بالنير الأعظم أبلغ في المنافع وأضمن للمصالح من نسخ النهار بالليل ألا ترى أن الجنة نهارها دائم لا ليل معه\",1,\"3:993\"],\"I-180\":[\"والجواب أن يقال: أما موقع هذه الآية من سورة العنكبوت فمشبه مواقع الآيات التى قبلها والتى بعدها\",1,\"3:996\"],\"I-181\":[\"والجواب أن يقال: إن الآية التي في سورة العنكبوت تحكي قول إبراهيم عليه السلام لكفار قومه وفيهم نُمووذ بن كنعان الذى حاجه، وفي كثير عن الأخبار أنه رام الصعود إلى الجوّ يوهم أنه يحاول ربّ السماء\",1,\"3:1005\"],\"I-182\":[\"والجواب أن يقال: إذا أخبر الله تعالى عن المؤمنين في كتابه فهو متناول من\",1,\"3:1010\"],\"I-183\":[\"والجواب أن من جحد آيات الله فقد كفر نعمه، وهذا أول ما يفعله، لأن ذلك متعلّق بما قبله ممّن تولّى خلقه وأنعم عليه بما استوجب به شكره، فأول فعله كفر نعم الله، ثم إنه مسيء إلا نفسه\",1,\"3:1012\"],\"I-184\":[\"والجواب أن يقال: إن الآية في سورة آل عمران مبنيّة على تداخل الأخبار\",1,\"3:1014\"],\"I-185\":[\"والجواب عن ذلك أن يقال: أما الأولى في سورة العنكبوت فإنها جاءت بعد قوله:\",1,\"3:1019\"],\"I-186\":[\"والجواب أن يقال: إن التقرير يؤثَر فيه من تحقيق الكلام ما لا يوُثَر في غيره، والظروف إذا حدّت حقّقت، تقول سرت اليومَ، فإن قلت من أوله إلى آخره كان الجد تحقيقا لأنه قد يطلق لفظ اليوم وإن ذهبت ساعة أو ساعتان من أوله\",1,\"3:1024\"],\"I-187\":[\"والجواب أن يقال: إن الأول فى التنبيه على البعث والإحياء بعد الموت فاستعمل فيه: (لَا يَعْقِلُونَ) أى: لا يفهمون عن هذا الفعل مثله، وفي مثل هذا يقال: عقلت كلامه، إذا استدركت وفهمت\",1,\"3:1026\"],\"I-188\":[\"والجواب أن يقال: اقتران \\\"أنْ\\\" بـ \\\"لمّا\\\" في سورة العنكبوت تكملة لمعناها في نفسها ليدل بذلك على أنه قد قارن جوابها متصلا به ما يكمّله ويخلّصه لتحقيق أو بطلان، فالتي في سورة العنكبوت قد اتصل بجوابها\",1,\"3:1030\"],\"I-189\":[\"والجواب عن ذلك أن يقال: أما التى في سورة الروم فإنها وقعت في سورة أجملت فيها القصص في ذكر الآيات والمواعظ والفرائص، فبُنيت هذه الآية على ذلك\",1,\"3:1035\"],\"I-190\":[\"والجواب أن يقال: أما اختصاص الأولى بقوله: (يتفكرون) فلأن المراد بما\",1,\"3:1041\"],\"I-191\":[\"والجواب أن يقال: إنّ: قوله تعالى في سورة الروم: (أَوَلَمْ يَرَوْا) جاء عقيب قوله:\",1,\"3:1048\"],\"I-192\":[\"الجواب قريبا على مَن له أدنى معرفة، وهو أن الهاء في قوله: (فيه) عائدة إلى البحر، وقد ذكر في سورة الجاثية فعاد إليه الضمير، وهو قوله: «اللَّهُ الَّذِي سَخَّرَ لَكُمُ الْبَحْرَ لِتَجْرِيَ الْفُلْكُ فِيهِ بِأَمْرِهِ)\",1,\"3:1054\"],\"I-193\":[\"والجواب أن يقال: إن معنى قوله عزوْجل: (يجري لأجل مسمّى)\",1,\"3:1056\"],\"I-194\":[\"والجواب عن ذلك من وجوه: أحدها: أن يكون المعنى: أن الله تعالى يدبر أمر أهل الأرض في السماء من دعائهم إلى الطاعات، وتكليفهم أنواع العبادات، فينزل به مَن يأمر من ملائكته لميبعث بذلك رسله، ويضمّ إليه آياته وكتبه\",1,\"3:1060\"],\"I-195\":[\"والجواب أن يقال: إن النار في قوله في سورة السجدة\",1,\"3:1066\"],\"I-196\":[\"الجواب أن يقال: إن هذه النون فى قوله: (لَا تَكُنْ) لما أشبهت بسكونها حروف المد واللين ثم كثرت استجيز حذفها للسببين جميعا، فإن تحركت خرجت عن شبهها، نحو: لم يكن الرجل منطلقا، فلا يجوز أن تقول: لم يك الرجل منطلقا.\",1,\"3:1068\"],\"I-197\":[\"والجواب عنه أن يقال: إنما قدّم ذكر \\\"السموات \\\" على \\\"الأرض \\\" في سورة سبأ لأن هذه الآية مبنية على مفتتح السورة، وهو: (الْحَمْدُ لِلَّهِ الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ...)\",1,\"3:1075\"],\"I-198\":[\"والجواب أن يقال: إنما اختير الإضمار في سورة بني إسرائيل لقوة الذكر قبلُ، ألا ترى أنه تكرر في عشرة مواضع مضمرا ومظهرا لقوله: (رَبُّكُمْ أَعْلَمُ بِكُمْ إِنْ يَشَأْ يَرْحَمْكُمْ أَوْ إِنْ يَشَأْ يُعَذِّبْكُمْ) فربّكم واحد\",1,\"3:1077\"],\"I-199\":[\"والجواب أن الذي في سورة الأنعام أجرى مجرى المعرفة، لأنه بعد ذكر متكرّر وخطاب متردّد مبتدأ من مبتدأ قوله تعالى: (قُلْ تَعَالَوْا أَتْلُ مَا حَرَّمَ رَبُّكُمْ عَلَيْكُمْ)\",1,\"3:1080\"],\"I-200\":[\"والجواب أن يقال: إن الفاعل في الموضعين لما كان نكرة فالمعنى جاء جاءٍ وقد\",1,\"3:1083\"],\"I-201\":[\"والجواب عن ذلك أن يقال: إنه لما قال في سورة الفرقان فأخبر عن نفسه، لا\",1,\"3:1086\"],\"I-202\":[\"والجواب أن يقال\",1,\"3:1089\"],\"I-203\":[\"والجواب عن ذلك أن يقال: إن قوله: (إِنَّا كَذَلِكَ نَجْزِي الْمُحْسِنِينَ) لما جعل أمارة لانتهاء كل قصة، وكانت قصة إبراهيم عليه السلام متضمنة ذِكره وذكر ولده الذي رأى فى المنام ذبحه\",1,\"3:1093\"],\"I-204\":[\"والجواب أن يقال: إن هذا بعدما بشر الله تعالى به عباده حيث قال:\",1,\"3:1096\"],\"I-205\":[\"والجواب أن يقال: إن التى فى سورة \\\"ق\\\" خبر عن عجبهم فى أنفسهم واتصال قولهم به فقال:\",1,\"3:1100\"],\"I-206\":[\"والجواب أن يقال: إن سورة \\\"ص\\\" مبنيّة فواصلها على أن تُرْدَف أواخرها\",1,\"3:1102\"],\"I-209\":[\"والجواب أن يقال: قد تقدم قولنا فى الفرق بين: (أَنْزَلْنَا إِلَيْكَ) و(أَنْزَلْنَا عَلَيْكَ) وأنّ\",1,\"3:1105\"],\"I-210\":[\"والجواب أن يقال: إن القصد فى الأمر الثاني غير القصد فى الأمر الأول، وذلك أن الأول يتعدّى إلى العبادة، والثاني معناه: وأمرت أن أعبد الله لأن أكون أول المسلمين، أي: إنما أمرت بإخلاص العبادة لله تعالى\",1,\"3:1110\"],\"I-211\":[\"والجواب أن يقال: إنّ كل واحدة من الآيتين تقدّم فيها ما اقتضى حمل هذين المختلفين عليه أعنى \\\"الذي\\\"، و\\\"ما\\\" وهما إذا كانتا موصولتين بمعن، إلاّ فى قصور\\\"ما\\\" عمّا يتبع له \\\"الذى\\\" لأنك إذا قلت: رأيتُ ما عندك\",1,\"3:1112\"],\"I-212\":[\"والجواب أن يقال: إنما جاء قوله: (كسبوا) في هذه السورة بناء على ما وقع\",1,\"3:1117\"],\"I-213\":[\"والجواب عن ذلك ما ذهب إليه بعض المفسرين: أن في ذلك دلالة على أن أبواب جهنم كانت مغلقة ففتحت لماّ جاءوها، وأن أبواب الجنة كانت مفتوحة قبل مجىء المؤمنين إليها.\",1,\"3:1119\"],\"I-214\":[\"الجواب أن يقال: إن اللام التى تقع فى خبر\",1,\"3:1125\"],\"I-215\":[\"والجواب أن يقال: إنّ كل موضع يحتمل الإضمار لقرب الذكر ويحتمل الإظهار لتعظيم الأمر\",1,\"3:1128\"],\"I-216\":[\"والجواب أن يقال: إنّ مَن أقر بخلق السموات والأرض وأنكر الإعادة والبعث ثم نبّه على أن يعلم أنّ من قدر على الأكبر قادر على الأصغر\",1,\"3:1132\"],\"I-218\":[\"والجواب أن يقال: إنه إذ قصد توكيد معنى الشرط الذي تتضمنه \\\"إذا\\\" لقوة معنى الجزاء استعملت \\\"ما\\\" بعدها، وإذا لم يقصد ذلك لقرب معنى الجزاء من الشرط لم تستعمل، (ما) بعدها.\",1,\"3:1143\"],\"I-219\":[\"والجواب أن يقال: إن الذي في سورة السجدة لما كان بعد دعاء إلى ما يشق على الإنسان فعله\",1,\"3:1145\"],\"I-220\":[\"والجواب أن خبر الله تعالى عما آتاه موسى عليه السلام عن التوراة يدل على أن أولئك القوم اختلفوا فيه كاختلاف مَن في عصر النبي - ﷺ -\",1,\"3:1150\"],\"I-221\":[\"والجواب: أن يقال: إن قوله (منا) مما بالكلام إلى ذكره حاجة، وقد أستغنى عنها في سورة هود عليه السلام لتقدم ذكرها في الآية التي قبلها، وهي: (ولئن أذقنا الإنسان منا رحمة ثم نزعْناها منه إنه ليئوس كَفور).\",1,\"3:1153\"],\"I-222\":[\"والجواب: أن يقال: إن معنى قوله:\",1,\"3:1155\"],\"I-223\":[\"والجواب أن يقال: إنّ ما رغب الله تعالى فيه عبده من الصبر على ما آلم قلبه من جناية جان عليه حتى يغفر لمن ظلمه ويهب له من القصاص حقه ترغيب فيما يشق على الإنسان فعله، إلا أن الله حسّنه.\",1,\"3:1158\"],\"I-224\":[\"والجواب أن يقال: إن قوله تعالى: (فأقم وجهك للدين القيم) معناه: استقم أنت ومن معك من المؤمنين على الدين المستقيم من قبل أن مجيء يوم لا ينفع فيه الإيمان فكأنه خاطب الناس بالاجتماع على الإيمان\",1,\"3:1161\"],\"I-225\":[\"والجواب أن يقال: لمّا نبّه الله تعالى العباد على ما يشاهدون خلْقه لهم\",1,\"3:1165\"],\"I-226\":[\"والجواب أن يقال: إن\",1,\"3:1171\"],\"I-227\":[\"والجواب أن يقال: إن قبل الآية من سورة الزخرف:\",1,\"3:1173\"],\"I-228\":[\"الجواب أن يقال: إن الأولى حكاية قول الكفار الذين حادوا النبي - ﷺ - فقال مخبرا عنهم (أَمْ آتَيْنَاهُمْ كِتَابًا مِنْ قَبْلِهِ) أي من قبل القرآن فهم به\",1,\"3:1175\"],\"I-229\":[\"والجواب أن يقال: لما قال الله تعالى قبلُ خَلق السموات والأرض بالحق إن في ذلك لآية للمؤمنين\",1,\"3:1178\"],\"I-230\":[\"والجواب: أن هذا الكافر لما أخبر الله تعالى عنه في سورة لقمان أنه، يعرض عن القرآن إذا سمعه غير منتفع به حتى كأنه لم يسمعه، وتستمر به هذه الحال كما تستمر لمن به صَمَم\",1,\"3:1184\"],\"I-231\":[\"والجواب أن يقال: إن سورة الجاثية لم يذكر فيها عن قصة بني إسرائيل غير هاتين الآيتين\",1,\"3:1186\"],\"I-233\":[\"والجواب أن يقال: إن هذه الآية في قوم تخلّفوا عن رسول الله - ﷺ -\",1,\"3:1195\"],\"I-234\":[\"والجواب أن يقال: لأن الأولى في ذكر ما أسرّه المنافقون من نفاقهم، لأنهم أضمروا خلاف ما أظهروا، وطلبوا الاستغفار لهم، ولا إرادة فيه منهم، فكأنه قال: بل الله يخبُر باطنكم.\",1,\"3:1197\"],\"I-235\":[\"والجواب أن يقال: إن القرين الأول فيه وجهان: أحدهما: أن يراد به الملك الشهيد عليه، وهو المشاهد لمِا يعمله الإنسان فيكتبه عليه، فيقول له يوم القيامة: (هذا ما لدىّ عتيد) أي: معدّ محفوظ عليك.\",1,\"3:1199\"],\"I-236\":[\"والجواب قريب وهو أن فواصل أكثر الآيات في سورة طه أواخرها ألف\",1,\"3:1202\"],\"I-237\":[\"والجواب أن يقال: إنه تعالى أخبر عنهم في (الذايات) أنهم صاروا إلى الجنة بأعمال عدّدها ودعا العباد إليها ليفعلوا فِعلهم لها فقال: (إِنَّ الْمُتَّقِينَ فِي جَنَّاتٍ)\",1,\"3:1204\"],\"I-238\":[\"والجواب أن يقال: إن قوله تعالى قبل هاتين الآيتين:\",1,\"3:1209\"],\"I-239\":[\"والجواب أن يقال: إن عبدة الأوثان من قريش مع إدعائهم أنهم أهل الحِجَى وأولو النّهى\",1,\"3:1211\"],\"I-240\":[\"والجواب أن يقال: لماّ قال قبل الأولى:\",1,\"3:1222\"],\"I-241\":[\"والجواب عن ذلك من وجهين: أحدهما: إن عاد اختص ما نزل فيها من كتاب الله تعالى بذكر عذابين لها\",1,\"3:1227\"],\"I-242\":[\"والجواب الذي يعتمد عليه هو أن يجعل لكل واحد معنى غير الآخر، يريد: والسماء رفعها ووضع الميزان أي: وضع البِنية المعدّلة، وهي بنية الإنسان التي خلق من أمشاج ومن تأليفات مختلفات على اعتدال من حرارة وبرودة ورُطوبة ويبوسة.\",1,\"3:1231\"],\"I-243\":[\"والجواب أن يقال: نبه الله تعالى على ما خلق من نعم الدنيا المختلفة في\",1,\"3:1237\"],\"I-244\":[\"والجواب أن يقال الأول هو خلقُ الإنسان من نطفة؟\",1,\"3:1248\"],\"I-246\":[\"والجواب أن يقال: إنه لما كان هذا الكلام مسوقا إلى كلمات ثلاث عقدت في كل واحدة منها السموات والأرص في عقدة واحدة، جمع المخلوق فيها تحت لفظة واحدة، فكان معنى قوله: (سبح لله ما في السموات والأرض): سبح لله الخلق في المكانين\",1,\"3:1250\"],\"I-247\":[\"والجواب أن يقال: إن المعنى: له الملك أولا وآخرا، فالأول في الدنيا، وهو وقت الإحياء والإماتة والآخر في الآخرة حين ترجع الأمور إليه، ولا يملك أحد سواه لا ملكا وملكا\",1,\"3:1253\"],\"I-248\":[\"والجواب أن يقال: إن الأفعال التى نسق هذا الفعل عليها في سورة الزمر\",1,\"3:1255\"],\"I-249\":[\"والجواب أن يقال: لما قال في الأولى: (... ذَلِكَ لِتُؤْمِنُوا بِاللَّهِ وَرَسُولِهِ...) أي: يبين لكم ذلك لِتُؤْمِنُوا بِاللَّهِ وَرَسُولِهِ وذكر الحدود التي حدّها لعباده، ثم سمَّى من لم يؤمن كافرا باسمه\",1,\"3:1257\"],\"I-250\":[\"والجواب أن يقال: إن الاصل في ذلك: إذا قويت الحركة فى القاف أن تدغم ألا ترى أن من جوّز (اردد)، مكان (ردّ) وكانت لغته الإظهار متى حرك الدال الأخيرة في قولك للاثنين: (ردا)، وقولك للجمع: (ردوا) لم ير إلاّ الإدغام\",1,\"3:1261\"],\"I-251\":[\"والجواب أن يقال: لما قال: (لَأَنْتُمْ أَشَدُّ رَهْبَةً فِي صُدُورِهِمْ مِنَ اللَّهِ)\",1,\"3:1264\"],\"I-252\":[\"والجواب أن يقال: إن الاسلام بُني أوله على التبرىء من الآلهة ومن عبدتها ومن الأصنام، وعبدتها\",1,\"3:1267\"],\"I-253\":[\"والجواب أن يقال: إن الكذب مصدر يسمى به الكلام المكذوب فيه، وهو فى قوله تعالى: (أفترى على الله كذبا) على أصله، مصدر غير منقول، والمصدر إذا عرف\",1,\"3:1270\"],\"I-254\":[\"الجواب أن يقال: إن معنى قوله: (هم الذين يقولون لا تنفقوا على مَن عند رسول الله) أي: يأمرونهم بالإضرار بهم وحبس النفقات عنهم، ولا يفطون\",1,\"3:1276\"],\"I-255\":[\"والجواب أن يقال: لما كان تسبيح ما في السموات على خلاف تسبيح ما في الأرض كثرة وقلة وخلوصا من غير مقارنة المعاصي واختلاطها بها أعيدت لفظة، (ما) لهذا الاختلاف.\",1,\"3:1278\"],\"I-256\":[\"والجواب أن يقال: إن الآية الأولى جاءت بعد قوله مخبرا عن الكفار:\",1,\"3:1281\"],\"I-257\":[\"والجواب أن يقال: إنما اقترن بالطلاق والعدة هذا الوعظ لأن الطلاق رفض حال متمهدة\",1,\"3:1283\"],\"I-258\":[\"الجواب أن يقال: لما كانت الأرض التى خلقها الله تعالى لهم ومهدها لاستقرارهم يعبدون عليها غير خالقها، ويعظمون فيها الأصنام التي هي من شجرها وحجرها، خوّفهم بما هو أقرب إليهم من الأشياء التي أهلك بها من كان قبلهم.\",1,\"3:1289\"],\"I-259\":[\"الجواب أن يقال: إن الموصوف في الآية الأولى موصوف بجامعة لخصال الذم فاضحة، وهي الحلف بالكذب الذي يورث الضعة والمهانة والوقيعة في الناس.\",1,\"3:1291\"],\"I-260\":[\"والجواب أن يقال: من نسب إلى النبى - ﷺ - إلى أنه شاعر وأن ما أتى به شعر فهو جاحد كافر، لأنه يعلم أن القرآن ليس بشعر لا في أوزان آياته ولا في تشاكل مقاطعه إذ منه آية طويلة\",1,\"3:1294\"],\"I-261\":[\"والجواب عن ذلك أن يقال: لما أخبر الله تعالى في هذه السورة عن طبائع البشر فقال:\",1,\"3:1298\"],\"I-262\":[\"الجواب أن يقال: إن الأول جاء بعد قوله...\",1,\"3:1305\"],\"I-263\":[\"والجواب أن يقال: كان الوليد بن المغيرة لما سئل عن النبي قدر ما أتى به من من ذلك الفرآن، فقال: إق قلنا شاعر كذّبتنا العرب، إذا قدرت، ما أتى به على الشعر ولم يكن إياه\",1,\"3:1307\"],\"I-264\":[\"الجواب أن يقال: إن التذكرة مصدر من: ذكرت أذكر تذكيرا وتذكرة\",1,\"3:1310\"],\"I-265\":[\"الجواب أن يقال: لماّ قال: (برق البصر) أي: تلألأ ولمع لهول ما شاهد، وهذا يلحق العيون عند شدة الأمر، والقمرُ يجوز أن يراد به بياض العين\",1,\"3:1312\"],\"I-266\":[\"الجواب أن يقال: اللفظة مششقة من\",1,\"3:1314\"],\"I-267\":[\"الجواب أن يقال: إن القصد في الأولى إلى وصف ما يطاف به من الأواني دون وصف الطائفين بها، فلماّ كان المعتمد بالافادة ذاك بني الفعل مقصودا به ذكر المفعول به لا الفاعل\",1,\"3:1315\"],\"I-268\":[\"الجواب أن يقال: إنّ هذه السورة مقصورة على إثبات ما أنكره الكفاّر من البعث والإحياء بعد الموت، والحساب، والثواب والعقاب، وتخويف المكذبين به، ليرجعوا عنه، ويتمسّكوا بالحقّ دونه، فأقسم- تعالى- في أول السورة.\",1,\"3:1319\"],\"I-269\":[\"الجواب أن يقال: إن الأول وعيد بما يرونه في الدنيا عند فراقها من مقرّهم، والثاني وعيد بما يَلقونه في الآخرة من عذاب ربهم، وإذا لم يرد بالثانىِ ما أريد بالأول لم يكن تكرارا وقيل الأول توعّد بالقيامة وهولها\",1,\"3:1328\"],\"I-270\":[\"الجواب أن يقال: إن الله تعالى قال: (مَنْ جَاءَ بِالْحَسَنَةِ فَلَهُ عَشْرُ أَمْثَالِهَا)\",1,\"3:1329\"],\"I-271\":[\"الجواب أن يقال: إن الطاّمة تستعمل في الشديدة التى تنسى عندها الشدائد، فتَطم على ما تقدّمها، أىِ تستره وتغطيه، ومنه يقال: طَم البئرَ إذا كَبَسَها، والطِّم: الكبْس، والقيامة: الطاّمّة الكبرى\",1,\"3:1331\"],\"I-272\":[\"والجواب أن يقال: إن الأول فى التنبيه على البعث والإحياء بعد الموت فاستعمل فيه: (لَا يَعْقِلُونَ) أى: لا يفهمون عن هذا الفعل مثله، وفي مثل هذا يقال: عقلت كلامه، إذا استدركت وفهمت\",1,\"3:1026\"],\"I-273\":[\"والجواب أن يقال: إنّ الأول لما جاء بعد ذكر النار والجنة، وهو قوله: (وإذا الجحيمُ سُعِّرت وإذا الجنّةُ أزْلفتْ علمت نفس ما أحضرت)، أي عملت عملا تستحق به الجنة، أم عملًا تستحقّ به النار\",1,\"3:1338\"],\"I-274\":[\"الجواب أن يقال: قوله: في سجِّين فسّر على وجوه؟\",1,\"3:1341\"],\"I-275\":[\"والجواب أن يقال: إن قوله: ويل لهم كلمة تقال في كلْ من وقع في هلكة لا يُرجى خلاصه منها، وهى في سورة المرسلات قد بيّنّا وجه الفائدة فيما أعيد منها، وهي في هذه السورة مذكورة مرة واحدة\",1,\"3:1349\"],\"I-276\":[\"الجواب أن يقال إن الأول للسماء والثاني للأرض، أمرت بالانصداع فسمعت وانقادت لأمر الله تعالى وانصدعت، وحق لها أن تسمع وتطيع..\",1,\"3:1351\"],\"I-277\":[\"الجواب أن يقال: إنّ معنى قوله:\",1,\"3:1353\"],\"I-278\":[\"الجواب أن يقال: إذا عنى بالثانى غير المقصود بالأول من وصف، يوجب له حكما غير حكم الأول كان من مختار الكلام، فالبلد الأول قصد به وصف لم يحصل في الثانى وهو مكة، لأن معناه: أقسم بالبلد المحرم الذي جبلت على تعظيمه قلوب العرب\",1,\"3:1356\"],\"I-279\":[\"والجواب أن\",1,\"3:1358\"],\"I-280\":[\"والجواب أن يقال: إن الله تعالى وعد في عسر أن يعقبه بيسرين، وأن من كان في شدة قطعها عنه إلى نعمة بعد نعمة\",1,\"3:1364\"],\"I-281\":[\"والجواب أن يقال: إنّ قوله\",1,\"3:1366\"],\"I-282\":[\"والجواب أن يقال: إن أحدهما توعد غير ما توعّد به الآخر، فالأول توعّد بما ينالهم في الدنيا، والثانى توعّد بما أعدّ لهم في الأخرى.\",1,\"3:1368\"],\"I-283\":[\"فالجواب أن يقال: قد أجبنا في (جامع التفسير) عن ذلك بأجوبة كثيرة\",1,\"3:1370\"],\"I-284\":[\"والجواب عن ذلك\",1,\"3:1372\"],\"G-001\":[\"والجواب عن السؤال الأول: بعد تمهيده وهو أن نقول أن قوله تعالى: \\\"الحمد لله \\\" مبتدأ وخبر وكذلك قوله: \\\"فلله الحمد \\\" وتأخر في هذه الثانية المبتدأ، والحاصل في الموضعين معنى واحد وهو حمده سبحانه بما هو أصله.\",1,\"1:12\"],\"G-002\":[\"والجواب عن السؤال الأول: بعد تمهيده وهو أن نقول أن قوله تعالى: \\\"الحمد لله \\\" مبتدأ وخبر وكذلك قوله: \\\"فلله الحمد \\\" وتأخر في هذه الثانية المبتدأ، والحاصل في الموضعين معنى واحد وهو حمده سبحانه بما هو أصله.\",1,\"1:12\"],\"G-003\":[\"والجواب عن السؤال الأول: بعد تمهيده وهو أن نقول أن قوله تعالى: \\\"الحمد لله \\\" مبتدأ وخبر وكذلك قوله: \\\"فلله الحمد \\\" وتأخر في هذه الثانية المبتدأ، والحاصل في الموضعين معنى واحد وهو حمده سبحانه بما هو أصله.\",1,\"1:12\"],\"G-006\":[\"والجواب: إن الآيات الثلاث حاصل منها ما ذكر أنه مقصود من أنه سبحانه ملك مالك\",1,\"1:20\"],\"G-008\":[\"والجواب: أن الملائم المناسب ما ورد وأن عكسه غير ملائم ولا مناسب ووجه ذلك أن الكتاب المشار إليه هو الكتاب العزيز على ما فى مآخذ المفسرين من التفصيل وهو مما خصت به هذه الأمة\",1,\"1:24\"],\"G-009\":[\"والجواب عن ذلك: إن الشعور راجع إلى معنى الإحساس مأخوذ من الشعار وهو ما يلى الجسد ويباشره فيدرك ويحس من غير افتقار إلى فكر أو تدبر\",1,\"1:24\"],\"G-010\":[\"والجواب عنه: أنه لما مثل حال المنافقين بحال مستوقد النار لطلب الإضاءة وأنه لما أضاءت ما حولها أذهبها الله وطفيت فلم يكن له ما يستضئ به ويرجع إليه فنفى عنهم وجود ما يرجعون إليه من ضياء يدفع حيرتهم وهذا بين.\",1,\"1:25\"],\"G-011\":[\"والجواب عن السؤال الأول: أن المراد إراءتهم ما يرفع شكهم فى نبوة محمد ﷺ فكأن قد قيل: إن شككتم فى نبوته وتخصيصنا إياه بذلك فلتأتوا برجل منكم غيره يصدر عنه أو يأتى بسورة واحدة من نمط طا سمعتم من محمد ﷺ\",1,\"1:27\"],\"G-012\":[\"والجواب عن السؤال الأول: والله أعلم أن الوارد فى الآيتين مختلف فى الموضعين أما الوارد فى البقرة فقصد به الإخبار والإعلام لرسول الله ﷺ بما جرى فى قصة آدم صلوات الله وسلامه عليه وابتداء خلقه وأمر الملائكة بالسجود له\",1,\"1:28\"],\"G-013\":[\"والجواب عن ذلك: أنه لم يرد ذلك هنا اكتفاء بما فى الآية قبلها وهو قوله: \\\"وقلنا اهبطوا بعضكم لبعض عدو \\\".\",1,\"1:30\"],\"G-014\":[\"والجواب عنه والله أعلم: أن تبع واتبع محصلان للمعنى على الوفاء\",1,\"1:30\"],\"G-015\":[\"والجواب: ان قوله تعالى\",1,\"1:32\"],\"G-016\":[\"ووجه ذلك والله أعلم أنه لما تقدم فى الآية الأولى قوله تعالى: \\\"أتأمرون الناس بالبر وتنسون أنفسكم \\\" والمأمور بالبر قد يأخذ به ويتمسك بموجبه فيسلم من العصيان وتكون فى ذلك نجاته وإذا أمكن هذا فقد\",1,\"1:33\"],\"G-017\":[\"والجواب عن الأول: ان الوارد فى سورة البقرة مقصود به تعداد وجوه الإنعام على بنى إسرائيل وتوالى الامتنان ليبين شنيع مرتكبهم فى مقابلة ذلك الإنعام بالكفر ولنقدم لذلك تمهيدًا فنقول: أنه تعالى بدأ عباده بالنعم\",1,\"1:33\"],\"G-018\":[\"والجواب عن الأول: ان أمرهم بدخول القرية مغاير من حيث المعنى لأمرهم بسكناها وان كان الامر بدخولهم قد يشير بما نسق معه إلى سكناها لكن ليس نصا بل ولا هو ظاهر فبينت آية الأعراف ذلك وأوضحت المقصود\",1,\"1:36\"],\"G-019\":[\"والجواب والله أعلم ان الفعلين وان اجتمعا فى المعنى فليسا على حد سواء بل الانبجاس ابتداء الانفجار والانفجار بعدة غاية له قال القرطبى: \\\"الانحباس أول الانفجار \\\"\",1,\"1:40\"],\"G-020\":[\"ووجهه والله أعلم أنهم لما سألوا فى البقرة عن مأكلهم ما فيه خسة وما يستلزم الذلة والصغار والمهنة فى التوصل إلى الانتفاع به وذلك ما طلبوه فى قولهم\",1,\"1:40\"],\"G-021\":[\"والجواب عن الأول والله أعلم\",1,\"1:41\"],\"G-022\":[\"والجواب عنه أنه لما ورد مرفوعا تنبيها على الغرض المذكور وتأكيدا للتسوية فى الحكم وإذا اتفقوا فى الموافاة على الإيمان فنبه التقديم على هذا كما تقدم\",1,\"1:44\"],\"G-023\":[\"والجواب: أنه لا يناسب كل آية منهما إلا ما به أعقبت\",1,\"1:45\"],\"G-025\":[\"ووجه ذلك والله أعلم أن آية البقرة لما كان الوارد فيها جوابا لحكم أخراوى يستقبل وليس فى الحال منه إلا ما زعم مجرد واعتقاد أن الأمر يكون كذلك ناسبه النفى بما وضعه من الحروف لنفى المستقبل لأن لن يفعل جواب سيفعل\",1,\"1:47\"],\"G-026\":[\"والجواب عن ذلك والله أعلم بما أراد: ان الوارد فى سورة الرعد لم يتقد قبله من متكبات أهل الكتاب فى كفرهم وعنادهم مثل ما تقدم قبل الآية الأولى من سورة البقرة ألا ترى أنه لم يذكر قيل آية الرعد من أمرهم\",1,\"1:48\"],\"G-027\":[\"والجواب عن ذلك والله أعلم ان المراد بالقائمين هنا ذوو الاقامة والملازمة على صفة مخصوصة وإذا أريد بالقائمين هذا فهو\",1,\"1:49\"],\"G-028\":[\"ووجهه والله أعلم أن اسم الإشارة الذى هو \\\"هذا \\\"فى سورة البقرة لم يقصد تبعيته اكتفاء بالواقع قبله من قوله تعالى: \\\"وإذ جعلنا البيت مثابة للناس وأمنا \\\"\",1,\"1:50\"],\"G-029\":[\"والجواب عنه - والله أعلم - أنه لما كانت دعوة إبراهيم عليه السلام قبل وجود الضلال فى الذرية المدعو لها وانما تحصل لهم من تزكيتهم ورفع ضلالهم المتوقع وقوعه بما يمنحونه من التعليم\",1,\"1:51\"],\"G-030\":[\"ووجه ذلك والله أعلم انهم لما تعلقوا بأسلافهم ممن كان على سنة إبراهيم واسماعيل ومن كان فيهم من الأنبياء عليهم السلام وظنوا أن تعلقهم بهم نافع لهم قيل لهم لن ينفعكم الا عملكم وأما التعلق بأولئك من غير اقتداء بهم\",1,\"1:52\"],\"G-031\":[\"والجواب عن الأول: إن قوله تعالى \\\"قولوا \\\" أمر لجميع المخاطبين المقصودين بهذا وأما قوله \\\"قل \\\" فأمر للنبى عليه السلام فلحق ضمير الجمع أولا لخطابهم ولم يلحق ضمير فى الثانى لإفراد الخطاب وضمير الواحد لا يبرز.\",1,\"1:52\"],\"G-032\":[\"والجواب عن ذلك والله أعلم: إن كل قضية تكليفية إذا كانت مما يتأكد فانها ترد ملحوظة الجهات منبها على ما يحرز مطلوبها على الكمال مدفوعا عنها\",1,\"1:53\"],\"G-033\":[\"والجواب عن الأول: أن زيادة \\\"من \\\" فى قوله فى العنكبوت: \\\"من بعد موتها \\\" زيادة بيان وتأكيد نوسب به ما تقدم من قوله \\\"من نزل \\\" فإن بنية فعل للمبالغة والتكثير وذلك مما يستجر البيان والتأكيد فنوسب بينهما ولما لم يقع\",1,\"1:55\"],\"G-034\":[\"والجواب: أنه لا يقال ألفى بمعنى وجد التى فى قولهم: وجدت الضالة فتتعدى إلى واحد ولا يقال ألفى بمعنى وجد التى بمعنى علم متعديا إلى اثنتين وما يقع منتصبا بعد مفعوله فى مثل قولك: ألفيت زيدا عالما\",1,\"1:56\"],\"G-035\":[\"والجواب عن الأول: أن العرب مهما اعتنت بشئ أو قصدت به قصد زيادة من تأكيد أو تشريف قدمته أو قدمت ضميره وليس من كلامهم إجراء هذه الاغراض مجرى غيرها فلكل مقام مقال ألا ترى قول قائلهم: إياك أعنى وقول مجاوبه: وعنك أعرض\",1,\"1:57\"],\"G-036\":[\"والجواب عن الآيتين الأوليين والله أعلم أنه لما تقدم قبلهما فى السورة نفسها قوله تعالى: \\\"ولا تلبسوا الحق بالباطل وتكتموا الحق وأنتم تعلمون \\\".\",1,\"1:59\"],\"G-038\":[\"والجواب عنهما معا أن آية البقرة نزلت لعداوة رسول الله ﷺ وتعرض بالظلم والتنكيل لمن آمن به ﷺ وطردوهم كل مطرد فأذن الله لرسوله فى قتالهم لظلمهم إياهم فقال تعالى: \\\"أذن للذين يقاتلون بأنهم ظلموا \\\".\",1,\"1:63\"],\"G-039\":[\"والجواب عن جميعها على الجملة أن وجه اختلافهما والله أعلم ورودها أعقاب قصص مختلفة وقضايا متغايرة فآية البقرة واردة على ما تقدمها من خطاب المؤمنين على العموم والتسوية فى قوله تعالى\",1,\"1:64\"],\"G-040\":[\"والجواب والله أعلم أن آية البقرة قد اكتنفها النهى عن مضارة النساء وتحريم أخذ شئ منهن ما لم يكن منهن ما يسوغ ذلك من ألا يقيما حدود الله\",1,\"1:67\"],\"G-041\":[\"ووجه ذلك والله أعلم: أن آية البقرة ترتبت على تصنيف المضرين بالزوجات واحتيالهم على أخذ أموالهن بغير حق\",1,\"1:67\"],\"G-042\":[\"والجواب عن الأول: أن الواقع فى الآية الأولى من قوله تعالى: \\\" والذين يتوفون منكم ويذرون أزواجا يتربصن فى أنفسهن أربعة أشهر وعشرا \\\" ثم قال \\\"فإذا بلغن أجلهن \\\" أى باستيفائهن أربعة أشهر والعشر\",1,\"1:68\"],\"G-043\":[\"والجواب: أن آية البقرة مبنية على ما أعد الله للمنفق فى سبيله وما يضاعف له من أجر إنفاقه وان ذلك ينتهى إلى سبعمائة ضعف وقوله \\\"والله يضاعف لمن يشاء \\\" قد يفهم الزيادة على ما نص عليه من العدد كما أشارت إليه آيات وأحاديث\",1,\"1:70\"],\"G-044\":[\"والجواب عن الأول: أن وجه اختصاص كل آية منها بما ورد فيها من الوصف الموجب لكونه تعالى لا يحب المتصف به مناسبة كل آية منها لما تقدمها.\",1,\"1:71\"],\"G-045\":[\"والجواب عنه والله أعلم: أن ابداء الشئ واخفاء خلافه فى المعتقدات صفة المنافقين وبها امتيازهم من غيرهم من الكفرة قال تعالى: \\\"يخفون ما فى أنفسهم ما لا يبدون لك \\\"\",1,\"1:72\"],\"G-046\":[\"والجواب عنه والله أعلم أن هذه الآية لما تقدمها قوله تعالى\",1,\"1:74\"],\"G-047\":[\"والجواب عن ذلك أن لفظ نزل يقتضى التكرير لأجل التضعيف تقول ضرب مخففا لمن وقع ذلك عليه مرة واحدة ويحتمل الزيادة والتقليل أنسب وأقوى.\",1,\"1:76\"],\"G-047c\":[\"ووجه ذلك على ما ذكرته ثم اعترض على ذلك بقوله تعالى: \\\"الحمد لله الذى أنزل على عبده الكتاب \\\" ولم يفصل وقال إنه مشكل وقد بينا أنه لا إشكال فى ذلك على ما تقعد قبل والحمد لله.\",0,\"1:77\"],\"G-048\":[\"والجواب عن الأول: أن آية آل عمران لما تقدم قبلها ذكر تنزيل الكتب الثلاثة والإشارة إلى ما تضمنته من الهدى والفرقان وإنما أتى على من كفر بصده عنها وتكذيبه ناسب ذلك قوله تعالى: \\\"كذبوا بآياتنا \\\" ولما لم يقع\",1,\"1:78\"],\"G-049\":[\"ووجه ذلك والله أعلم: أن بناء آية الأنعام على آية بنيت على اسم الفاعل وان كان خبرا وهو قوله تعالى: \\\"إن الله فالق الحب والنوى \\\" ثم أعقب ذلك بقوله \\\"فالق الإصباح وجاعل الليل سكنا \\\"\",1,\"1:80\"],\"G-050\":[\"والجواب عن ذلك والله أعلم أنه لما تقدم قبل الأولى قوله تعالى: \\\"لا يتخذ المؤمنون الكافرين أولياء من دون المؤمنين \\\" فنهاهم سبحانه عن ذلك ثم أردف بالتحذير بقوله\",1,\"1:81\"],\"G-051\":[\"والجواب عن ذلك والله أعلم: أن المعنى وإن كان فى السورتين واحدا وفى قضية واحدة فإن مقاطع آى وسورة مريم وفواصلها استدعت ما يجرى على حكمها ويناسبها من لدن قوله تعالى\",1,\"1:82\"],\"G-052\":[\"والجواب والله أعلم: أنه لما كان الإخبار مقصودا به التعريف بمنعه الكلام ثلاثة أيام بليالهن منصوصا على ذلك حتى لا يقع احتمال أن يكون المنع فى الليالى دون الأيام أو الأيام دون الليالى\",1,\"1:82\"],\"G-053\":[\"والجواب عن السؤال الأول بعد تمهيد الجواز فى تذكير الضمير فى قوله \\\"فأنفخ فيه \\\" فى الآية الأولى وتأنيثه فى الآية الثانية \\\"فأنفخ فيها \\\" مع اتحاد ما يعود عليه.\",1,\"1:83\"],\"G-054\":[\"والجواب والله أعلم: أن آية مريم لما تضمنت مقالة عيسى عليه السلام وآية كلامه فى المهد مخبرا عن حاله النبوية وما منحه الله من الخصائص الاصطفائية فقال\",1,\"1:85\"],\"G-055\":[\"والجواب عن ذلك والله أعلم أن آية المائدة لما ورد فيها التفصيل فيما يجب الإيمان به وذلك قوله: \\\"أن آمنوا بى وبرسولى \\\" فجاء على أتم عبارة فى المطلوب وأوفاها ناسب ذلك ورود \\\"أننا \\\" على أوفى الحالين وهو الورود على الأصل\",1,\"1:87\"],\"G-056\":[\"والجواب أن ذلك لاختلاف حال من عنى بهما وقد ذكر المفسرون أن آية آل عمران نزلت فى الحارث بن سويد الأنصارى وكان قد أسلم ثم ارتد ولحق بالكفار ثم ندم فأرسل إلى قومه ليسألوا رسول الله ﷺ هل له من توبة فسألوا فنزلت الآية\",1,\"1:88\"],\"G-057\":[\"والجواب عن ذلك والله أعلم أن آية آل عمران إنما نزلت فى المعاصرين لرسول الله ﷺ الحاضرين عند نزول الآية فورد الاخبار مساوقا لحالهم فى وقت نزول الآية وما يلى ذلك متصلا به من الزمان فلم يكن لدخول كان التى تقتضى\",1,\"1:88\"],\"G-058\":[\"والجواب عم الأول والثانى والله أعلم: أن آية آل عمران لما تقدم فيها قوله تعالى: \\\"ويأتوكم من فورهم \\\" والإخبار عن عدوهم فاختلط ذكر الطائفتين وضمهما كلام واحد فجردت البشارة لمن هدى منهما وانها لأولياء الله المؤمنين\",1,\"1:89\"],\"G-059\":[\"والجواب عن الأول والله أعلم: أن المسارعة إلى الشئ قبل مسابقته قال تعالى: \\\"أولئك يسارعون فى الخيرات وهم لها سابقون \\\" وقد أوضحنا فى كتاب البرهان أن ترتيب السور بتوقيف على أصح المأخذين وأما ترتيب الآى فلا توقف فيه\",1,\"1:90\"],\"G-060\":[\"ووجه ذلك والله أعلم أن الآية الأولى لما وقع فيها ذكر الجزاء مفصلا معطوفا فقيل: \\\" أولئك جزاؤهم مغفرة من ربهم وجنات تجرى من تحتها الأنهار خالدين فيها \\\" ناسبه أن عطفت الجملة الممدوح بها الجزاء فقيل: \\\"ونعم أجر العاملين \\\"\",1,\"1:92\"],\"G-061\":[\"والجواب عن ذلك: أن قولك فلان من أنفس القوم أوقع فى القرب من قولك فلان منهم فإن هذا قد يراد للنوعية فلا يتخلص لتقريب المنزلة والشرف إلا بقرينة\",1,\"1:93\"],\"G-062\":[\"والجواب عن ذلك والله أعلم أن قوله فى الأولى \\\"بأفواههم \\\" ينبئ عن مبالغة واستحكام وتمكن فى اعتقاد أو قصد لا يحصل من قوله \\\"بألسنتهم \\\" ألا ترى قولهم: تكلم بملء فيه حين يريدون المبالغة وقال تعالى: \\\"اليوم نختم على أفواههم \\\"\",1,\"1:94\"],\"G-063\":[\"والجواب عن ذلك والله أعلم أن كلا الآيتين مراعى فيه ما يلى تابعا للمرفوع من الوصف فى الأولى وما عطف فى الثانية.\",1,\"1:95\"],\"G-064\":[\"والجواب والله أعلم اختلاف ما وقع الحض على الصبر عليه فى هذه الآيات وأشير إليه بذلك وأنه من عزم الأمور أما الأولى فإن قبلها\",1,\"1:95\"],\"G-065\":[\"والجواب عن الأول أن العبارة بخلق واردة على ما ينبغى وطابقة للمعنى المقصود وهو المراد بجعل إلا أن جعل ثانية عنها لتوقف الجعل على ما يتقدمه لأن العبارة بخلق تكون عند المتسرعين عن عدم سابق حيث لا تتقدم مادة ولا سبب محسوس\",1,\"1:97\"],\"G-066\":[\"والجواب: ان قوله تعالى \\\"ولا تؤتوا السفهاء أموالكم \\\" إنما المراد به السفيه المتصير إليه المال بإرث ولا يحسن القيام عليه فيحجر عليه ماله إبقاء عليه ولا يمكن منه الا بقدر ما يأكله ويلبسه\",1,\"1:99\"],\"G-067\":[\"والجواب عنه: أن وجه اتفاق أكثرها على ما ذكر أن كل نعيم ينقطع فليس بنعيم فى الحقيقة وكذلك العذاب وهذا واضح فلولا الخلود لما كان نعيما فلهذا كثر ترداده مع ضروب الجزاء.\",1,\"1:101\"],\"G-068\":[\"والجواب عن ذلك: أن نقول: أن المقت هو النقص والاستحقار ومتزوج امرأة أبيه فاعل رذيلة يمقت فاعلها ويشنأ وتستخسه الطباع السليمة فوسمت فعلته بالمقت وساوت الزنا فيما وراء ذلك فلهذا زيد فى آية النساء قوله \\\"ومقتا \\\".\",0,\"1:102\"],\"G-070\":[\"والجواب عن ذلك: والله أعلم أن آية النحل تقدمها قوله تعالى: \\\"ويوم نبعث فى كل شهيدا عليهم من أنفسهم \\\" فتقدم اسم الشهيد على المشهود عليه\",1,\"1:103\"],\"G-071\":[\"والجواب عن الأول منها: أن زيادة \\\"منه \\\" فى آية المائدة زيادة بيان ألا ترى أن قوله تعالى: \\\"فامسحوا بوجوهكم وأيديكم \\\".\",1,\"1:105\"],\"G-072\":[\"والجواب: أنه لما وقع قبل الآية الكريمة ذكر أهل الكتاب وذكر اعتدائهم وتحريفهم من لدن قوله تعالى\",1,\"1:106\"],\"G-074\":[\"والجواب أن التعبير الثانى مبنى على ما يجب ربطه به من قوله \\\"وعد الله حقا \\\" وقيل \\\"ومن أصدق من الله قيلا \\\" وأنيب مناب وعدا فكأن قد قيل: ومن أصدق من الله وعدا وهو ما وعدهم به تعالى من النعيم وعظيم الإحسان\",1,\"1:108\"],\"G-075\":[\"الجواب أن الإدغام تخفيف وليس بالأصل فورد فى النساء على الأصل ولم يقترن به ما يستدعى تخفيفه ولا سؤال فى ذلك ولما تقدم فى سورة الحشر قوله تعالى: \\\" ذلك بأنهم شاقوا الله ورسوله \\\"وتقد الماضى مدغما ولم يسمع\",1,\"1:108\"],\"G-076\":[\"والجواب والله أعلم: أن الآية الأولى فيما بين المرأة وزوجها فإذا خافت منه وأرادت تآلفه وبقاءه وكينونتها فى عصمته فلا جناح عليهما أن تعطى شيئا من نفسها وتترك بعض حقها كأن تؤثر ضرتها فى القسمة أو تترك هى حظها كما\",1,\"1:109\"],\"G-077\":[\"والجواب عن الأول: إنه لما قال سبحانه فى الزوجين عند عدم انقيادهما لحسن المعاشرة \\\"وإن يتفرقا يغن الله كلا من سعته \\\" قال الزمخشرى: \\\"يرزقه زوجا خيرا من زوجته وعيشا أهنأ من عيشه \\\"\",1,\"1:110\"],\"G-078\":[\"والجواب عنه والله أعلم: أن الآيات المتصلة بآية سورة النساء مبنية على الأمر بالعدل والقسط قال تعالى\",1,\"1:111\"],\"G-079\":[\"والجواب والله أعلم: أن السبيل والطريق وإن استويا واتحد معناهما فيما ذكر فبينهما فرق واضح عن حيث أن مواضع السبيل أكثر ترددا فى الكلام ففى إطلاق لفظه توسعه وعموم ليست فى إطلاق لفظ طريق فقد ورد ذكر السبيل\",1,\"1:112\"],\"G-080\":[\"والجواب عن الأول: إن قوله تعالى \\\"إن تبدوا خيرا أو تخفوه \\\" مقصود به خصوص طرف الخير وعمل البر جريا على ما دارت عليه سورة النساء وتردد فيها من إصلاح ذات البين والندب إلى العفو\",1,\"1:113\"],\"G-081\":[\"والجواب عنه والله أعلم: أن المقصود فى الآيتين مختلف فوردت الألفاظ بما يحرز ذلك وبيانه أن اسم الأنعام إنما يقع على ما ذكر فى آية سورة الأنعام من الأزواج الثمانية حين تفسرت مفصلة فقال تعالى\",1,\"1:116\"],\"G-082\":[\"والجواب والله أعلم أن آية المائدة مبنية على تأنيس وتقريب واستلطاف وقد أحرز قوله \\\"من ربهم \\\" هذه المعانى الثلاثة حسبما يتبين بعد.\",1,\"1:117\"],\"G-083\":[\"والجواب عن ذلك والله أعلم: أن الآية الأولى ورد فيها الإفصاح بعلة البغضاء الحاملة على الانتصار والانتقام وهى صدهم عن البيت الحرام عام الحديبية وذلك قوله تعالى: \\\"أن صدوكم \\\" أى من أجل أن صدوكم أى منعوكم\",1,\"1:119\"],\"G-084\":[\"والجواب والله أعلم: أن آية المائدة خطاب للمؤمنين بما يجب عليهم من الطهارة لصلاتهم وتعليم لهم كيفية عملهم فى ذلك وإنعام عليهم برخصة التيمم إذا عدموا الماء وكل هذا مستوجب للشكر لله سبحانه فقيل\",1,\"1:119\"],\"G-085\":[\"والجواب عنه والله أعلم: أن آية المائدة لما قدمتها خطاب المؤمنين فى قضيتين: الأولى منهما\",1,\"1:120\"],\"G-086\":[\"والجواب عن ذلك والله أعلم أن الفرق بين الموضعين أن الآية الأولى تضمنت إخبار الله سبحانه لنبيه عليه السلام مرتكب من تقدم من كفار بنى إسرائيل حين أخذ عليهم الميثاق فيما عرفه سبحانه فى قوله\",1,\"1:122\"],\"G-087\":[\"والجواب والله أعلم: أنه لما تقدم قوله تعالى\",1,\"1:123\"],\"G-088\":[\"والجواب عن ذلك: أن فى آية المائدة عموم يستدعى الإطلاق وعدم التقييد بالمخاطبين وفى سورة الفتح خصوص يستدعى التخصيص بآية الخطاب للمواجهين به وذلك أن الاخبار\",1,\"1:124\"],\"G-089\":[\"والجواب عن ذلك: أنه سبحانه لما ذكر فى الأولى قدرته وعظيم سلطانه فى قوله: \\\"قل من يملك لكم من الله شيئا إن أراد أن يهلك المسيح ابن مريم وأمه ومن فى الأرض جميعا \\\" وعرف سبحانه أنه لا معاند له\",1,\"1:125\"],\"G-090\":[\"والجواب عن ذلك: أنه لما اعتمد فى آية المائدة تذكيرهم بضروب من الآلاء والنعم الجسام من جعل الأنبياء فيهم وجعلهم ملوكا وإعطائهم ما لم يعط غيرهم كا ذلك تعريفا باعتنائه سبحانه بهم وتفضيلهم على من عاصرهم\",1,\"1:126\"],\"G-091\":[\"والجواب عن الأول: أنه لما تقدم آية المائدة قوله تعالى\",1,\"1:126\"],\"G-092\":[\"والجواب عنه جواب عن السؤال الأول.\",1,\"1:129\"],\"G-093\":[\"والجواب والله أعلم: ان آية المائدة ورد الكلام فيما تقدمها فى بنى إسرائيل من لدن قوله تعالى\",1,\"1:135\"],\"G-094\":[\"والجواب عن ذلك والله أعلم: أن آية المائدة لما أعقب بها آية الأمر باجتناب الخمر وما ذكر معها\",1,\"1:137\"],\"G-095\":[\"والجواب عن ذلك والله أعلم: يتفصل فى الآيتين: أما آية المائدة فمبنية على التسليم لله سبحانه وأنه المالك للكل يفعل فيهم ما يشاء فلو ورد هنا عقب آية المائدة: \\\"وإن تغفر لهم فأنت الغفور الرحيم \\\" لكان تعريضا بطلب المغفرة\",1,\"1:138\"],\"G-096\":[\"والجواب والله أعلم: أن آية الأنعام لما ترتبت على إطناب وبسط آيات من حمده سبحانه وانفراده بالخلق والاختراع فقال تعالى: \\\"الحمد لله الذى خلق السماوات والأرض وجعل الظلمات والنور ثم الذين كفروا بربهم يعدلون \\\"\",1,\"1:140\"],\"G-097\":[\"والجواب عن ذلك: إن آية الأنعام لم يتقدم قبلها التنبيه على ما به التذكار والاعتبار مفصحا به تنبيها مع تخويف وتهديد متأكد مكرر يستدعى التقريع والتوبيخ بمقتضى الهمزة الداخلة على واو العطف كما فى سورة الشعراء\",1,\"1:141\"],\"G-098\":[\"والجواب والله أعلم: أن \\\"من \\\" إنما تزاد فى هذه الآى حيث يراد تأكيده ضمن الآى من المعطيات ولإشارة إلى الوعيد وهى أبدا فى أمثال هذه المواضع محرزة معنى التأكيد لا تنفك عن ذلك ثم إن حذفها أوجز من إثباتها ولكل مقام مقال\",1,\"1:142\"],\"G-099\":[\"الجواب عما وقع به التعقيب فى كل واحدة من هذه الآى تفصل إلى أربعة أسئلة والسؤال الثانى: اختلاف حرف العطف.\",1,\"1:144\"],\"G-101\":[\"والجواب عن الأول والله أعلم أن مدار الأية الأولى وهى آية الأنعام على أنه سبحانه المنفرد بالخلق والاختراع والمتصرف فى عباده بما يشاء والقدير على كل شئ ونفى هذه الصفات عمن سواه سبحانه\",1,\"1:147\"],\"G-102\":[\"والجواب عن الأول: أن الأولى تقدمها قوله: \\\"فقد كذبوا بالحق لما جاءهم فسوف يأتيهم أنباء ما كانوا يستهزئون \\\" ثم قال تعالى بعد: \\\"ولو أنزلنا عليك كتابا فى قرطاس فلمسوه بأيديهم لقال الذين كفروا إن هذا إلا سحر مبين \\\"\",1,\"1:149\"],\"G-103\":[\"والجواب والله أعلم: أن نقول \\\"من \\\" لفظ مفرد ويصلح للاثنين والجميع.\",1,\"1:151\"],\"G-104\":[\"فالجواب عن ذلك والله أعلم: أن آية الأنعام لم يرد فيما تقدمها زيادة على ما أخبروا به من حالهم فى إنكارهم البعث ألا ترى أن بنيت الآية على ما تقدمها من قوله تعالى\",1,\"1:155\"],\"G-106\":[\"والجواب عن الأول: أن آية الأنعام تقدمها قوله تعالى معرفا بحال الدنيا \\\"وما الحياة الدنيا إلا لعب ولهو \\\" ومعنى التأكيد فى هذا حاصل من جرى الكلام وسياقه لأنك إذا قلت: ما المال إلا الإبل\",1,\"1:157\"],\"G-107\":[\"ووجه ذلك والله أعلم أن لولا فى الآيتين تحضيض وإنما يجرى فى كلامهم عندما يراه المتكلم به أولى أو أهم فى مقصود ما أو أتم فى مطلب ما إلى أشباه هذا مما يستدعى التحضيض ولما تقدم قبل آية الأنعام ذكر دلائل من خلق السماوات\",1,\"1:158\"],\"G-108\":[\"والجواب عن الأول: أنه إنما أعيد لفظ التنبيه لتسويغ معتبرات كل منها كاف فى الدلالة لمن وفق ونظير هذا ما ورد فى قوله تعالى: \\\"قل الحمد لله وسلام على عباده الذين اصطفى الله خير أما يشركون \\\" ثم قال\",1,\"1:160\"],\"G-109\":[\"والجواب والله أعلم: أن العرب تراعى مجاورة الألفاظ فتحمل اللفظ على مجاوره لمجرد المضارعة اللفظية وان اختلف المعنى ومنه الاتباع فى ينوؤك ويسوؤك قال سيبويه رحمه الله وقد ذكر بعض ما تتبع فيه العرب\",1,\"1:161\"],\"G-110\":[\"والجواب والله سبحانه أعلم أن الوارد فى سورة هود إنما هو حكاية قوله نوح عليه السلام متلطفا ومشفقا من حال قومه ألا ترى استفتاح خطابه لهم بقوله\",1,\"1:161\"],\"G-111\":[\"والجواب عنه والله أعلم أن آية التكوير لما تقدمها القسم على القرآن بقوله تعالى: \\\"فلا أقسم بالخنس \\\" إلى ما وقع القسم به ثم ورد ضمير المقسم عليه فى قوله: \\\"إنه لقول رسول كريم \\\" أى أن القرآن لقول رسول كريم\",1,\"1:162\"],\"G-112\":[\"والجواب عنه والله أعلم: أن ذلك مناسب لما اكتنف هذا الوصف فى آية سورة المؤمنون لما كان ذكر محافظتهم على صلاتهم قد اكتنفه ما تقدمه وما تأخر عنه من تفخيم الوصف فى المتقدم وتفخيم الجزاء\",1,\"1:163\"],\"G-113\":[\"والجواب والله أعلم: أن ذلك مراعى فيه فى آية الأنعام ما أعقبت به من قوله: \\\"وتركتم ما خولناكم وراء ظهوركم \\\" أى ما أعطيناكم فى الدنيا مما شغلكم عن آخرتكم\",1,\"1:164\"],\"G-114\":[\"والجواب: أنه لما تقدم الآية الأولى قوله جل وتعالى: \\\"وهو الذى جعل لكم النجوم لتهتدوا بها فى ظلمات البر والبحر \\\" فذكر سبحانه من المعتبرات التى يتوصل بالنظر فيها إلى معرفته وحدانيته تعالى ما يحصل الاطلاع عليه تعقلا\",1,\"1:164\"],\"G-115\":[\"والجواب عن الأول: أن مشتبها ومتشابها لا فرق بينهما إلا ما لا يعد فارقا إذ الافتعال والتفاعل متقاربان، أصولهما: الشين والباء والهاء من قوله أشبه هذا هذا إذا قاربه وماثله\",1,\"1:166\"],\"G-116\":[\"والجواب عن ذلك: أن آية الأنعام لما تقدم فيها قوله تعالى: \\\"وجعلوا لله شركاء الجن وخلقهم وخرقوا له بنين وبنات بغير علم \\\"\",1,\"1:167\"],\"G-117\":[\"والجواب عن ذلك والله أعلم: أنه لما تقدم الآية الأولى قوله تعالى: \\\"ولو أننا نزلنا إليهم الملائكة وكلمهم الموتى وحشرنا عليهم كل شئ قبلا ما كانوا ليؤمنوا إلا أن يشاء الله \\\"، فعرف سبحانه نبيه\",1,\"1:168\"],\"G-118\":[\"والجواب عن الأول أن سقوط الباء الداخلة على \\\"من \\\" فى آية الأنعام إنما ذلك والله أعلم لاستثقال زيادتها مع الزيادة اللازمة للمضارع مع التقارب إيثارا للإيجاز أما آيتا النجم والقلم فلا زيادة فى الفعل لكونه ماضيا\",1,\"1:169\"],\"G-119\":[\"والجواب أنه لما تقدم قبل آية الأنعام قوله تعالى: \\\"أو من كان ميتا فأحييناه وجعلنا له نورا يمشى به فى الناس \\\" والمراد أو من كان ميتا فى غمرات الجهل والكفر فأحييناه بنور الإيمان والعلم كمن مثله فى الظلمات أى ظلمات الجهل\",1,\"1:169\"],\"G-120\":[\"والجواب والله أعلم أنه لما تقدم هنا قوله تعالى: \\\"يا معشر الجن والإنس ألم يأتكم رسل منكم يقصون عليكم آياتى وينذرونكم لقاء يومكم \\\"\",1,\"1:171\"],\"G-121\":[\"والجواب عن ذلك والله أعلم: أن هذه الآيات الثلاث وعيد لمن كفر وكذب وآية الأنعام وآية الزمر منها أريد بهما كفار العرب من هذه الأمة وقد افتتحنا بأمره سبحانه نبيه عليه السلام بوعيدهم فى قوله سبحانه\",1,\"1:171\"],\"G-122\":[\"والجواب عن ذلك والله أعلم أنه لما تقدم آية الأنعام قوله تعالى: \\\"وعلى الذين هادوا حرمنا كل ذى ظفر \\\" وهذا إخبار عن بنى إسرائيل فيما حرم عليهم ثم ورد بعدها قوله تعالى: \\\"قل هلم شهدائكم الذين يشهدون أن الله حرم هذا \\\"\",1,\"1:172\"],\"G-123\":[\"والجواب عن ذلك والله أعلم أن المخاطبين بآية الأنعام إنما كان فعلهم ذلك من أجل الفقر الحاصل حال قتلهم فقيل من إملاق أى من أجل الاملاق الحاصل ثم قيل لهم \\\"نحن نرزقكم وإياهم \\\"فقد رزقه تعالى لهم لحصول فقرهم\",1,\"1:172\"],\"G-124\":[\"والجواب عن ذلك والله أعلم: أنه لما كانت الخلل الخمس فى الآية الأولى وهى: الشرك والعقوق وقتل الأولاد لأجل الفقر وارتكاب الفواحش وقتل النفس التى حرم الله بغير الحق، خمستها مما يدرك العقل ابتداء قبحها\",1,\"1:173\"],\"G-125\":[\"والجواب والله أعلم: أن هذه الآية لما تقدمها قوله تعالى: \\\"قل إننى هدانى ربى إلى صراطى مستقيم دينا قيما ملة إبراهيم حنيفا \\\" وقد قال فى سورة آل عمران\",1,\"1:174\"],\"G-126\":[\"والجواب عنه والله أعلم: أنه لما تقدم قبل آية الأعراف قوله سبحانه لنبيه عليه السلام \\\"قل إننى هدانى ربى إلى صراط مستقيم \\\" واستمر الخطاب له معرفا عن حاله وواضح طريقه إلى قوله: \\\"قل أغير الله أبغى ربا وهو رب كل شئ \\\"\",1,\"1:175\"],\"G-127\":[\"والجواب والله أعلم أن آية الأنعام لما تقدمها قوله تعالى: \\\"قل إننى هدانى ربى إلى صراط مستقيم \\\" ثم استمر ما بعد على خطابه ﷺ لما منحه الله تعالى إلى قوله\",1,\"1:176\"],\"G-129\":[\"الجواب منزل على الترتيب الثابت، والله سبحانه أعلم بما أراد.\",0,\"1:179\"],\"G-129b\":[\"الجواب منزل على الترتيب الثابت، والله سبحانه أعلم بما أراد.\",0,\"1:179\"],\"G-131\":[\"والجواب عن ذلك والله أعلم: أن المذكورين قبل آية الأعراف المقول لهم فذوقوا العذاب قد خالفت حالهم حال المذكورين فى آية الأنفال وذلك أن آية الأنفال فى قوم بأعيانهم وهم كفار قريش من أهل مكة\",1,\"1:181\"],\"G-132\":[\"وجوابه والله أعلم: أن ابتداء الإخبار فى الأعراف بحال هؤلاء الملعونين فى الآيتين هو قوله تعالى فى الأولى: \\\"فأذن مؤذن بينهم أن لعنة الله على الظالمين \\\" وابتداء الاخبار عنهم فى سورة هود قوله تعالى\",1,\"1:181\"],\"G-133\":[\"والجواب عن السؤال الأول: \\\" أن آية الأعراف لما تقدمها قوله تعالى: \\\"إن ربكم الله الذى خلق السماوات والأرض فى ستة أيام ثم استوى على العرش\",1,\"1:182\"],\"G-134\":[\"الجواب عن الأول: أن آية الأعراف لم يتقدمها ذكر إرسال ولا أمر بدعاء الخلق ولا جملة يناسبها عطف إرسال الرسل إلى الأمم\",1,\"1:189\"],\"G-135\":[\"والجواب عن الأول والله أعلم: إن تقول: أن تخصيص الواقع من الملأ من قوم نوح عليه السلام جوابا له عند دعائهم فى سورة الأعراف إلى عبادة الله مناسب لما تقدم فيها من قول مكذبى الرسل حين تتوفاهم الملائكة قال تعالى\",1,\"1:193\"],\"G-136\":[\"والجواب عنهما معا: أن قوم نوح عليه السلام لما رموه بالضلال وأكدوا ذلك وزعموا استحكامه بالوصف فى قولهم له عليه السلام: \\\"إنا لنراك فى ضلال مبين \\\" فزعموا أن ضلاله غير خاف وهو الذهاب عن طريق الصواب\",1,\"1:196\"],\"G-138\":[\"والجواب عن هذين السؤالين والله أعلم: أنا قد وضحنا فى كتاب البرهان أن ترتيب السور مراعى وترتيب الآى فى هذا الحكم أولى وأبين\",1,\"1:199\"],\"G-139\":[\"والجواب: مثل هذا ليس بخلاف ولا مشكل لأن وصف العذاب بالإيلام لا ينافى وصفه بالقرب وإنما وصف فى سورة هود بالقرب ليجرى مع قوله بعد: \\\"تمتعوا فى داركم ثلاثة أيام \\\" فجرى فى الوصف رعى هذا ولا ينافى ذلك الإيلام وأما الوصف\",1,\"1:200\"],\"G-140\":[\"والجواب ناسبه اللفظ الأخص رعيا لإحراز النظم الجليل وعلى تناسبه مع أن لا كبير اختلاف فى المعنى الحاصل عن العبارتين والله أعلم.\",1,\"1:201\"],\"G-141\":[\"والجواب: أن العرب تراعى فى أجوبتها ما نيتها عليه من سؤال أو غيره\",1,\"1:202\"],\"G-143\":[\"والجواب عنه: أنه لم يقع فى سورة العنكبوت من ذكر إرسال الرسل ما بنى على أرسلنا ظاهرا ومقدرا منوطا به ذكر المرسل إليهم بحرف الغاية الذى هو \\\"إلى \\\" غير قوله تعالى: \\\" لقد أرسلنا نوحا إلى قومه \\\"وقوله: \\\"وإلى مدين أخاهم شعيبا \\\"\",1,\"1:211\"],\"G-144\":[\"والجواب عن الأول: أنه لما تقدم فى سورة الأعراف قوله تعالى: \\\" وتصدون عن سبيل الله من آمن به \\\" وقوله: \\\"وإن كان طائفة منكم آمنوا بالذى أرسلت به وطائفة لم يؤمنوا \\\" ثم قال بعد: \\\"فما كانوا ليؤمنوا بما كذبوا \\\"\",1,\"1:212\"],\"G-145\":[\"والجواب عن الأول أنه لا توقف فى أن موسى عليه السلام خاطب فرعون وملأه وأنه أمر بخطابهم وإليهم أرسل قال تعالى: \\\"ولقد أرسلنا موسى بآياتنا وسلطان مبين إلى فرون وملئه \\\" وإنه لما دعاهم لتصديقه والإيمان به جاوب فرعون\",1,\"1:214\"],\"G-146\":[\"والجواب عن الأول: أن \\\"إذا \\\" تقع جوابا وجزاء والمعنى فى السورتين مقصود به الجزاء فوقع الاكتفاء فى الأعراف بقوله تعالى \\\"نعم \\\"والمعنى: نعم لكم ما أردتم من الأجر وزيادة التقريب والحظوة ولا شك ان المعنى: إن غلبتم فلكم ذلك\",1,\"1:217\"],\"G-147\":[\"والجواب عن الأول: أن لا يلزم من الآية أن كلام السحرة هذا كان فى موطن واحد بل لعله كان فى موطنين أو لعله قد تكرر منهم وإن كان فى موطن واحد أو لعل بعضهم قال هذا وقال بعضهم هذا أو لعل المعنى الذى حكى عنهم تعطيه العبارتان\",1,\"1:218\"],\"G-148\":[\"الجواب كالجواب من غير فرق.\",0,\"1:219\"],\"G-149\":[\"والجواب عن الأول: أنه لما تقدم فى الأعراف قوله: \\\"قال الملأ من قوم فرعون \\\" فعرفت هذه الآية انهم كانوا المتولين للجريمة من تكذيب الآية ورد ما جلء به موسى عليه السلام ولم يجر هنا ذكر لفرعون ولا فيما تلى الآية\",1,\"1:219\"],\"G-150\":[\"والجواب عن الأول منهما: أن زيادة اللام فى الشعراء مناسب لما تضمنته من الاستيفاء الجارى فى هذه القصة وقد تقدمت الإشارة إلى ذلك وذلك أن هذه اللام مقربة من زمان الحال وتحقيق الوقوع ولم يكن تقدم فى الأعراف ولا\",1,\"1:220\"],\"G-151\":[\"والجواب أن ثم للتباين والتراهى فى الزمان ويعبر النحويون عن ذلك بالمهلة وتكون للتباين فى الصفات والأحكام وغير ذلك مما يحمل به ما بعدها على ما قبلها من غير قصد مهلة زمانية بل ليعلم موقع ما يعطف بها وحاله\",1,\"1:221\"],\"G-152\":[\"والجواب عنه أن قوله \\\"لاضير \\\" مقابل به ما تقدم من قوله: \\\"وقالوا بعزة فرعون \\\"لما اعتقدوه أولا أن له عزة ونسبوها إليه فظنوا أنه يقدر على ما يريده ويستبد بفعله ثم لما وضح لهم الحق ورجعوا عن اعتقادهم وظنوا وعلموا أن القدرة\",1,\"1:222\"],\"G-153\":[\"والجواب عن الأول: أنه لما تقدم سؤالهم عن الساعة وتكرر فى قوله: \\\"يسألونك كأنك حفى عنها \\\"أى عالم بها وكان ظاهر السياق يشير إلى أنهم كانوا يظنون أنه عليه السلام يعلمها فطلبوا تعريفهم بها وأن يخصهم بذلك\",1,\"1:222\"],\"G-154\":[\"والجواب عن السؤالين: أن سورة الأعراف تقدم فيها قبل الآية وصف آلهتهم المنحوتة من الحجارة والخشب التى وبخوا بعبادتها فى قوله فى موضع آخر: \\\"أتعبدون ما تنحتون \\\" فوصفت هنا بأنها لا تخلق شيئا\",1,\"1:223\"],\"G-155\":[\"والجواب عن ذلك أن آية الأنفال مقصود فيها مع المدحة تعظيم الواقع منهم من الإيمان والهجرة والجهاد بالأموال والأنفس وتغبيطهم بما من الله عليهم به من ذلك وتفخيم فعلهم الموجب لموالاة بعضهم بعضا فقدم ذكر الأموال\",1,\"1:225\"],\"G-156\":[\"ووجه ذلك والله أعلم أن الآية الأولى أعقب بها ما تقدمها متصلا بها من الآى فى كفار مكة وفعلهم مع رسول الله ﷺ وأصحابه من التضييق والاحراج وبدئهم بالقتال يوم بدر ونقضهم العهد فى قصة خزاعة فى صلح الحديبة وهذا كله مبسوط\",1,\"1:226\"],\"G-157\":[\"والجواب أن كل وصف منها إنما جرى على ما تقدمه لداع مناسب من المعنى أما الآية الأولى فإن قبلها قوله تعالى: \\\" أجعلتم سقاية الحاج وعمارة المسجد الحرام كمن آمن بالله واليوم الآخر وجاهد فى سبيل الله لا يستوون عند الله \\\"\",1,\"1:227\"],\"G-158\":[\"والجواب عنه والله أعلم: أن زيادة آية براءة مقابل بها ما ورد من الطول فى المحكى فى هذه السورة من قول الطائفتين من اليهود والنصارى قال تعالى حاكيا عنهم: \\\"وقالت اليهود عزير ابن الله وقالت النصارى المسيح ابن الله \\\" فوقع\",1,\"1:228\"],\"G-159\":[\"والجواب والله أعلم: أن الاستطاعة وعدمها حكم لا يطلع عليه فى الغالب بل ينفرد كل بحاله فى ذلك إلا أن يعلم ذلك بقرينة فقول المنافقين فى إخبار الله تعالى عنهم: \\\"لو استطعنا لخرجنا معكم \\\" غير مشاهد من ظاهرهم\",1,\"1:229\"],\"G-160\":[\"والجواب: أنك إذا قلت مثلا المانع من تقريب زيد نفاقه فإنك لم تزد على أن أخبرت عن علة منع تقريب زيد شيئا فإذا قلت أن المانع من تقريب زيد نفاقه فقد زدت على الاخبار بالمانع من تقريب زيد أنه نفاقه\",1,\"1:230\"],\"G-161\":[\"والجواب عن الأول: أنه لما وصف تعالى أقوال المنافقين فى كفرهم وشتى مرتكباتهم وقرر ما هم عليه فى آيات إلى قوله\",1,\"1:231\"],\"G-162\":[\"والجواب عن الأول: أن مطلع الآية قبلها قوله تعالى: \\\" وإذا أنزلت سورة \\\" على بناء الفعل للمفعول فجاء قوله \\\"وطبع على قلوبهم \\\" على ذلك ونوسب بختام هذه الآية بداءة ما قبلها وأما الثانية فلم يقع قبلها فعل بنى للمفعول\",1,\"1:233\"],\"G-163\":[\"والجواب عنها على الجملة أن الآية الأولى فى المنافقين لم يخالطهم سواهم والثانية فى طائفة من المؤمنين كان فيهم تقصير ولهم إيمان فأنسوا وقوى رجاؤهم قال الطبرى: \\\"هى فيمن تاب من المخلفين \\\" قلت\",1,\"1:233\"],\"G-164\":[\"ووجه ذلك والله أعلم ان الأواه الكثير التأوه وفى كتاب ابن عطية أن التأوه التفجع فالمراد بالآية أن إبراهيم عليه السلام مع غلظة أبيه وقساوته حتى قال له \\\"لئن لم تنته لأرجمنك \\\" وابراهيم عليه السلام مع ذلك يتأوه تأسفا\",1,\"1:236\"],\"G-165\":[\"والجواب والله أعلم ان سورتى يونس ولقمان تردد فيهما من الآيات المعتبر بها المطلعة على عظيم حكمته تعالى واتقانه للأشياء ما لم يرد فى سورة يوسف كقوله تعالى: \\\"إن ربكم الله الذى خلق السماوات والأرض فى ستة أيام \\\"\",1,\"1:237\"],\"G-166\":[\"والجواب عن ذلك - والله أعلم - ان سورة لقمان تضمنت من التنبيه والتحريك والاعتبار إفصاحا وإيماء للمؤمن والكافر مالم تتضمن سورة يونس على طولها وان كانت آيها كلها آى اعتبار الا انها ليست كالوارد من ذلك فى سورة لقمان\",1,\"1:238\"],\"G-167\":[\"والجواب عنه - والله أعلم - ان الموجب لتأخير \\\"ولا ينفعهم \\\" فى سورة يونس ما وصل به من قولهم: \\\"ويقولون هؤلاء شفعاؤنا عند الله \\\" فكأن قد قيل: ويعدبون من دون الله مالا يضرهم ولا ينفعهم\",1,\"1:240\"],\"G-168\":[\"والجواب عنه ان الافراد الوارد فى آية يونس محصل للمعنى مع الإيجاز فورد هنا على ما يجب وأما الوارد فى سورة سبأ على الجمع فروعى فيه ما تقدم من قوله تعالى\",1,\"1:241\"],\"G-169\":[\"والجواب: أنه لما تقدم فى سورة يونس قوله تعالى: \\\" قل من يرزقكم من السماء والأرض أمن يملك السمع والأبصار \\\" إلى قوله: \\\"فأنى تصرفون \\\" فذكر سبحانه عباده بما لا يجدون محيصا عن إضافة ذلك كله\",1,\"1:241\"],\"G-170\":[\"والجواب عن السؤال الأول: أنه تقدم قبل الآية قوله تعالى: \\\" ولو أن لكل نفس ظلمت ما فى الأرض لافتدت به \\\" وهذه الآية مبنية عليها ومجموع الآيتين فى قوة أن لو قيل: \\\"ولو أن لكل نفس ظلمت ما فى الأرض لافتدت به \\\"\",1,\"1:243\"],\"G-171\":[\"ووجه ذلك والله أعلم أن القسط يراد به العمل والتسوية فى الحكم فمظنة وروده حيث يراد موازنة الجزاء بالأعمال من غير زيادة كما قال تعالى فى جزاء الكافرين: \\\"جزاء وفاقا \\\" أى موازنا لأعمالهم موافقا لها: \\\"ولا يظلم ربك أحدا \\\"\",1,\"1:245\"],\"G-172\":[\"والجواب والله أعلم أن آية غافر لما تقدمها قوله تعالى: \\\" لخلق السماوات والأرض أكبر من خلق الناس ولكن أكثر الناس لا يعلمون \\\" ومقصود هذه الآية تحريك الخلق للاعتبار ةالتذكير بما نصب سبحانه من الدلائل والآيات\",1,\"1:246\"],\"G-173\":[\"والجواب عن ذلك والله أعلم: أن آية يونس مقصود فيها من تأكيد الاستيفاء والاستغراق مالم يقصد فى الأخريين وإن كان العموم مراد فى الجميع إلا أن آية يونس قضت بزيادة التأكيد\",1,\"1:247\"],\"G-174\":[\"والجواب عن ذلك والله أعلم: أن آية يونس تقدم قبلها دعاء موسى عليه السلام على فرعون وملئه بقوله\",1,\"1:249\"],\"G-175\":[\"والجواب أن الآية الأولى قد ورد قبلها قوله تعالى: \\\" ولو شاء ربك لآمن من فى الأرض جميعا أفأنت تكره الناس حتى يكونوا مؤمنين وما كان لنفس أن تموت إلا بإذن الله \\\" وبعد هذا: \\\"وما تغنى الآيات والنذر عن قوم لا يؤمنون \\\"\",1,\"1:251\"],\"G-176\":[\"والجواب أن آية يونس مرتبطة بقوله تعالى فيما قبلها: \\\"ولو شاء ربك لآمن من فى الأرض كلهم جميعا أفأنت تكره الناس حتى يكونوا مؤمنين \\\" فلما تقدمها هذا ومعناه هو المعنى المراد فى قوله تعالى\",1,\"1:252\"],\"G-177\":[\"والجواب عن ذلك، والله أعلم: أنه لم يرد في هود ما يستدعي تلك الزيادة، وأما سورة السجدة فتدم فيها قوله: (وَيَوْمَ يُنَادِيهِمْ أَيْنَ شُرَكَائِي) قطعا بهم وتنبيهًا على سوء مرتكبيهم، وقد عاينوا الحق\",1,\"2:253\"],\"G-178\":[\"والجواب عنه، والله أعلم: أن العرب تصرفت في يكون عند دخول الجازم تصرفًا لم تفعله في نظائرها وما يشبهها، وبسط هذا في مظانه، فيكون الوجه في يكون عند دخول الجازم تسكين النون\",1,\"2:253\"],\"G-179\":[\"والجواب: أن آية هود تقدمها (ما يفهم) المفاضلة، ألا ترى أن قوله تعالى: (أَفَمَنْ كَانَ عَلَى بَيِّنَةٍ)، الآية يفهم من سياقها أن المراد: أفمن كان على بينة من ربه كمن كفر وجحد (وكذب) الرسل؟\",1,\"2:254\"],\"G-180\":[\"والجواب على ذلك: أن قوم صالح، عليه السلام، بالغوا في أساءت الجواب حين قالوا: (قَدْ كُنتَ فِينَا مَرْجُوًّا قَبْلَ هَذَا)، أي قد كنت مرجوًا أن تسود فينا حتى نقطع عن رأيك ونرجع إليك من أمورنا\",1,\"2:255\"],\"G-181\":[\"والجواب عن ذلك، والله أعلم: أن لفظ احملأوسع مواقع في اللغة وأكثر تصرفًا في الكلام تقول: حملت الشيء إلى فلان، وحملته على كاهلي، وحملت العلم عن فلان، وحمل فلان الأمانة، وحمله الغضب على كذا، وحمِل الفارس على صاحبه\",1,\"2:256\"],\"G-182\":[\"والجواب عن ذلك، والله أعلم: أن آيتي صالح وهود ورد فيهما ما يقتضي معناه أن يربط بالفاء المقتضية التعقيب، أما قصة صالح منهما فتقدمها قوله تعالى: (فَعَقَرُوهَا فَقَالَ تَمَتَّعُوا فِي دَارِكُمْ ثَلَاثَةَ أَيَّامٍ)\",1,\"2:258\"],\"G-183\":[\"والجواب عن ذلك: أن الوارد عليه كلا من الآيتين لا يحسن خلافه ولا يناسب، وذلك لوجهين: أحدهما أن قصة هود، عليه السلام، في هذه السورة أكثر استيفاء من قصة موسي عليه السلام، بكثير فناسب الطول الطول والإيجاز الإيجاز\",1,\"2:258\"],\"G-184\":[\"والجواب عن ذلك: أن «إننا» الواردة في سورة هود المضموم فيها إلى أن المشددة الناصبة للإسم والرافعة للخبر نون الضمير المنصوب وارده على ما يجب وعلى الأصل في إتصال الضمير المنصوب\",1,\"2:259\"],\"G-185\":[\"والجواب عن ذلك: أن التأنيث على ضربين حقيقي وغير حقيقي، فالحقيقي لا تحذف تاء التأنيث من فعله غالبًا إلا أن يقع فصل نحو قام اليوم هند، وكلما كثر الفصل حسن الحذف، ومن كلامهم حضر القاضي اليوم امرأة\",1,\"2:259\"],\"G-187\":[\"الجواب عنه، والله أعلم: أن (أن) هذه الخفيفة كثيرًا ما تزاد، وزيادتها على ضربين بقياس وغير قياس، فالذي بغير قياس نحو قوله: كأن الظبية تعطو إلى وارث السلم\",1,\"2:261\"],\"G-188\":[\"والجواب عن الأول: أن آية الحجر ورد قبلها قوله في قصة إيراهيم عليه السلام:\",1,\"2:262\"],\"G-189\":[\"والجواب عن ذلك، والله أعلم: أن كلا من الموضوعين مراعي فيه مناسبة ما تقدمه، ولما تقدم آية الحجر قوله تعالى: (قَالُوا إِنَّا أُرْسِلْنَا إِلَى قَوْمٍ مُجْرِمِينَ)\",1,\"2:262\"],\"G-190\":[\"والجواب عنه، والله أعلم: أنه حيث يذكر سوء رد المرسل اليهم وقبح جوابهم يقابل ابدا تأيده بأخيه أو عضده بالآيات مما يقتضي القهر والإرغام وهو المعبر عنه بالسلطان المبين فيكون ذلك مقابلة لشنيع مجاوبتهم وسوء ردهم بالجملة\",1,\"2:263\"],\"G-191\":[\"والجواب: أن آية هود تقدمها قوله تعالى (لَوْلَا كَانَ مِنَ الْقُرُونِ مِنْ قَبْلِكُمْ أُولُو بَقِيَّةٍ يَنْهَوْنَ عَنِ الْفَسَادِ فِي الْأَرْضِ إِلَّا قَلِيلًا مِمَّنْ أَنْجَيْنَا مِنْهُمْ)\",1,\"2:264\"],\"G-192\":[\"والجواب عنه، والله أعلم: أن آية (سورة) يوسف لما كانت توطئة لذكر قصصه، عليه السلام، ولم تتضمن السورة غير ذلك إلا ما أعقب به في آخرها مما يعرف بعجيب ما تضمنته ما كان غيبًا عند قريش والعرب\",1,\"2:266\"],\"G-193\":[\"والجواب عن ذلك: أن الأشد مختلف فيه من البلوغ إلى استكمال أربعين سنة، وقد قيل بالزيادة على الأربعين، وظاهر القرآن أن الأشد يقع على دون الأربعين لقوله تعالى: (حَتَّى إِذَا بَلَغَ أَشُدَّهُ وَبَلَغَ أَرْبَعِينَ سَنَةً)\",1,\"2:267\"],\"G-194\":[\"والجواب عن ذلك، والله أعلم: أن آية يوسف قد تقدمها قوله تعالى: (وَمَا يُؤْمِنُ أَكْثَرُهُمْ بِاللَّهِ إِلَّا وَهُمْ مُشْرِكُونَ)، وقوله: (وَسُبْحَانَ اللَّهِ وَمَا أَنَا مِنَ الْمُشْرِكِينَ)\",1,\"2:268\"],\"G-195\":[\"والجواب عن الضرب الأول: أما آية يوسف فقوله تعالى: (أَفَلَمْ يَسِيرُوا فِي الْأَرْضِ) مربوط بما قبله ومبني على ما تقدم كحال في جواب مبني على ما قبله، ألا ترى أن قبل الآية آيات تخويف وترهيب\",1,\"2:269\"],\"G-196\":[\"والجواب عن الأول\",1,\"2:272\"],\"G-197\":[\"والجواب عن الأول\",1,\"2:272\"],\"G-198\":[\"والجواب: أن معتبرات الآية الأولى من مد الأرض (وما ذكر) بعد ذلك أوضح للاعتبار، ومعتبرات الثانية أغمض، ألا ترى أن تجاوز قطع الأرض وتقاربها في الصفات والهيئات من سهل وحزن\",1,\"2:278\"],\"G-199\":[\"والجواب عن الأول: أن ورود «من» في سورةة الرعد لا سؤال فيه، فإن قبول الأوامر وامتثال الطاعات بالقصد والاختيار بمشيئة الله سبحانه إنما يكون من أصحاب العقول وهو الملائكة والإنس والجن، وهم المقصودون في الآية\",1,\"2:278\"],\"G-200\":[\"والجواب عن ذلك، والله أعلم: أن آية الفرقان قد عطف عليها بالواو المشركة في الإعراب والمعنى قوله تعالى: (وَلَا يَمْلِكُونَ مَوْتًا وَلَا حَيَاةً وَلَا نُشُورًا)\",1,\"2:279\"],\"G-201\":[\"والجواب عنه، والله أعلم: أن آية العنكبوت لما تقدم قبلها في قصة إبراهيم، عليه السلام\",1,\"2:280\"],\"G-202\":[\"والجواب، والله أعلم: أن العقاب أشد موقعًا من النكيير لأن الإنكار يقع على ما لا عقاب فيه بالفعل وعلى ما فيه العقاب بالفعل، وأما مسمى العقاب فإنما يراد به في الغالب أخذ بعذاب مناسب لحال المجرم إثر معصيته وعقيب جريمته\",1,\"2:281\"],\"G-203\":[\"والجواب، والله أعلم: أن سورة الرعد لم يتقدم فيها شيء من القصص الإخبارية وإنما المتقدم فيها تفاصيل أحكام مرجعها بجملتها إلى اختلاف أحوال المكلفين جريًا على ما سبق من قضائه فيهم\",1,\"2:282\"],\"G-204\":[\"والجواب عن ذلك: أن المتقرر في الكتاب العزيز أنه إذا ورد اسم نبينا محمد ﷺ مع غيره من الرسل، عليهم السلام، مفصحًا بأسمائهم في آية واحدة فإنه يتقدن اسمه ظاهرًا كان أو مضمرًا، ثم يذكر بعده من تضمنته الآية منهم، عليه السلام\",1,\"2:283\"],\"G-205\":[\"والجواب عنه، والله أعلم: أن آية إبراهيم، عليه السلام، لما ورد فيها قوله تعالى لنبيه، عليه السلام: (لِتُخْرِجَ النَّاسَ مِنَ الظُّلُمَاتِ إِلَى النُّورِ)، وكان السابق من مفهوم هذا أن ذلك الأمر بيده، عليه السلام\",1,\"2:285\"],\"G-206\":[\"والجواب: أن آية إبراهيم قد تقدمها قوله تعالى: (قُلْ لِعِبَادِيَ الَّذِينَ آمَنُوا يُقِيمُوا الصَّلَاةَ)، وقد علم المؤمنون أن الله غني عن العالمين، وأن المنزل من ماء السماء إنما هو رحمة للعباد وإحياء للأرض بعد موتها\",1,\"2:286\"],\"G-207\":[\"والجواب عنه، والله أعلم: أن آية إبراهيم تقدمها قوله تعالى: (أَلَمْ تَرَ إِلَى الَّذِينَ بَدَّلُوا نِعْمَتَ اللَّهِ كُفْرًا وَأَحَلُّوا قَوْمَهُمْ دَارَ الْبَوَارِ)\",1,\"2:287\"],\"G-208\":[\"والجواب، والله أعلم: أن كلا الموضعين حاصل فيه التناسب\",1,\"2:288\"],\"G-209\":[\"والجواب عن هذا، قد تقدم في سورة الرعد.\",0,\"2:289\"],\"G-210\":[\"والجواب، والله أعلم: أنه لما تقدم في آية الزخرف لفظ الخبرية وهي للتكثير ناسب ذلك ذكر من يوحي إليه من نبي مرسل أو نبي غير مرسل، فورد هنا ما يعم الصنفين، عليهم السلام.\",1,\"2:289\"],\"G-211\":[\"ووجه ذلك، والله أعلم: أنه تقدم في آية الحجر قوله تعالى: (وَقَالُوا يَا أَيُّهَا الَّذِي نُزِّلَ عَلَيْهِ الذِّكْرُ إِنَّكَ لَمَجْنُونٌ)\",1,\"2:289\"],\"G-212\":[\"والجواب عنه، والله أعلم: أن آية الحجر وردت بالألف واللام، وهي الأداة المقتضية الحصر الجنسي حيث لا عهد، وذلك وارد على ما ينبغي لما قصد هنا من المبالعة، ولا سؤال فيه.\",1,\"2:290\"],\"G-214\":[\"والجواب: أن المتقدم في ذكر ضيف إبراهيم ووجله، عليه السلام، منهم مع أنه كان لا يهاب كثرة الرجال لما منح من النبوة والأيد، إلى حال النبوة، وتخصيص الخِلة، ثم بشارة الملائكة له بالولد مع بلوغ الكبر\",1,\"2:291\"],\"G-215\":[\"والجواب عن ذلك: إنه لما لم يتقدم آية الحجر تخصيص بمدعو بل تقدمها خطابه، عليه السلام، بالتأنيس والتسلية عمن أعرض والرفق بمن آمن فقال تعالى: (وَلَا تَحْزَنْ عَلَيْهِمْ وَاخْفِضْ جَنَاحَكَ لِلْمُؤْمِنِينَ)\",1,\"2:292\"],\"G-216\":[\"والجواب عن السؤال الأول: أن الإشارة بقوله: (إِنَّ فِي ذَلِكَ) في الآية الأولى إلى المنزل من السماء في قوله: (هُوَ الَّذِي أَنْزَلَ مِنَ السَّمَاءِ مَاءً لَكُمْ مِنْهُ شَرَابٌ وَمِنْهُ شَجَرٌ فِيهِ تُسِيمُونَ)\",1,\"2:294\"],\"G-217\":[\"والجواب عن الآول: أن أية النحل بنيت على تاخير المجرورات عما تعلقت به، وجرى الكلام جريا واحدا للتناسب والتشاكل، فقيل: لتأكلوا منه، وتستخرجوا منه، ومواخرفيه.\",1,\"2:296\"],\"G-218\":[\"والجواب عن ذلك: أن أية النحل تقدمها ثمانى أيات أو نحوها فى ذكر هؤلاء المقول لهم: (فَادْخُلُوا أَبْوَابَ جَهَنَّمَ) وفى\",1,\"2:297\"],\"G-219\":[\"ووجه ذلك، والله اعلم: استدعاء التناسب في كل من الموضعين\",1,\"2:298\"],\"G-220\":[\"والجواب: أن هذه اللام فى قولة تعالى: «ليكفروا»، «وليتمتعوا» لام مقصود به التهديد والوعيد كقوله تعالى: (اعْمَلُوا مَا شِئْتُمْ) و(اعْمَلُوا عَلَى مَكَانَتِكُمْ) وقوله (وَمَنْ شَاءَ فَلْيَكْفُرْ).\",1,\"2:299\"],\"G-221\":[\"والجواب أن ذلك إنما جرى بحسب مقتضى المقصود في كل من الآيتين، أما آية النحل فقد تقدمها قوله تعالى: (لِلَّذِينَ لَا يُؤْمِنُونَ بِالْآخِرَةِ مَثَلُ السَّوْءِ)\",1,\"2:300\"],\"G-222\":[\"والجواب: أن آية النحل تقدمها قوله تعالى:\",1,\"2:300\"],\"G-223\":[\"والجواب عن السؤال الأول أن قوله: (لَآيَةً لِقَوْمٍ يَعْقِلُونَ)، راجع إلى قوله: (ومن ثمرات النخيل والاعناب)..\",1,\"2:301\"],\"G-224\":[\"والجواب عن السؤال الأول أن قوله: (لَآيَةً لِقَوْمٍ يَعْقِلُونَ)، راجع إلى قوله: (ومن ثمرات النخيل والاعناب)..\",1,\"2:301\"],\"G-225\":[\"والجواب: أن سبب ذلك - والله أعلم - التناسب وتشاكل النظم ومراعاة اللفظ ألا ترى إلى تكرر «من» في قوله:\",1,\"2:302\"],\"G-226\":[\"والجواب، والله أعلم: أن الوارد في آية لانخل راجع إلى من قدم ذكرهم في قوله: (وَيَجْعَلُونَ لِمَا لَا يَعْلَمُونَ نَصِيبًا مِمَّا رَزَقْنَاهُمْ)\",1,\"2:303\"],\"G-227\":[\"والجواب، والله أعلم: أن آية النحل مبتدأة بقوله تعالى: (وَاللَّهُ أَخْرَجَكُمْ مِنْ بُطُونِ أُمَّهَاتِكُمْ لَا تَعْلَمُونَ شَيْئًا)\",1,\"2:305\"],\"G-228\":[\"والجواب، والله أعلم: أن آية سورة الملك لما انطوت على ذكر حالين للطائر من صفة جناحية وقبضهما، وهما حالتان يستريح إليهما الطائر، فتارة يصف جناحية كأنه لا حركة به، وتارة يقبضهما إلى جنبيه حتى يلزقهما بهما\",1,\"2:305\"],\"G-230\":[\"والجواب عن ذلك أن الأولى مقصود بها بشارة وإنعام لا يشوبه غيره، وقد تبين ذلك، أما الثانية فوارده مورد الزجر والتعنيف لمن لم يؤمن مع البشارة للمؤمنين\",1,\"2:309\"],\"G-231\":[\"والجواب عنه، والله أعلم: أن آية النحل الأولى لما افتتحت بما الموصولة في قوله تعالى: (مَا عِنْدَكُمْ يَنْفَدُ)، والمراد بها الإطلاق والعموم، كانت في هذا الموضوع أولى من لفظ «الذي» وإن اشتركا في الموصولية\",1,\"2:309\"],\"G-232\":[\"والجواب عنه، والله أعلم: أن الأولى وقع قبلها: (أَفَأَصْفَاكُمْ رَبُّكُمْ بِالْبَنِينَ وَاتَّخَذَ مِنَ الْمَلَائِكَةِ إِنَاثًا إِنَّكُمْ لَتَقُولُونَ قَوْلًا عَظِيمًا)، وهذا خطاب مراد به كفار العرب\",1,\"2:311\"],\"G-233\":[\"والجواب: أن آية سبأ تقدم قبلها تعالى مخبرًا عن الكافرين: (وَلَقَدْ صَدَّقَ عَلَيْهِمْ إِبْلِيسُ ظَنَّهُ فَاتَّبَعُوهُ)، ثم قال بعد آية من تمام الآية التي قبلها: (قُلِ ادْعُوا الَّذِينَ زَعَمْتُمْ مِنْ دُونِ اللَّهِ)\",1,\"2:313\"],\"G-234\":[\"والجواب: أن معنى كل آية منها استدعى تعقيبها بما به أعقبت، فأما الأولى فلما تقدمها قوله تعالى: (وَإِذَا مَسَّكُمُ الضُّرُّ فِي الْبَحْرِ ضَلَّ مَنْ تَدْعُونَ إِلَّا إِيَّاهُ)\",1,\"2:314\"],\"G-235\":[\"والجواب، والله أعلم: أن الآية الأولى تقدمها قوله تعالى: (وَلَقَدْ صَرَّفْنَا لِلنَّاسِ فِي هَذَا الْقُرْآنِ مِنْ كُلِّ مَثَلٍ فَأَبَى أَكْثَرُ النَّاسِ إِلَّا كُفُورًا)\",1,\"2:315\"],\"G-236\":[\"والجواب، والله أعلم: أن قوله في الأولى: (ذَلِكَ جَزَاؤُهُمْ) إلى ما اتصل به من قوله: (وَنَحْشُرُهُمْ يَوْمَ الْقِيَامَةِ عَلَى وُجُوهِهِمْ عُمْيًا وَبُكْمًا وَصُمًّا مَأْوَاهُمْ جَهَنَّمُ)، ثم قال (ذَلِكَ جَزَاؤُهُمْ).\",1,\"2:316\"],\"G-238\":[\"والجواب عن ذلك، والله أعلم، أن الآيتين وإن اتحدتا في الغاية الحاصل منها وصف حال الكافر المنكر للبعث الوارد في كل\",1,\"2:318\"],\"G-239\":[\"والجواب عن ذلك، والله أعلم: أن سورة الكهف مكية، والخطاب فيها من أولها إلى الآية المتكلم فيها لم يخرج إلى غير العرب، أعني أنه لم يتعرض فيها إلى إخبار بحال غيرهم، إلا ما عرفوه من قصة أهل الكهف وخبرهم\",1,\"2:320\"],\"G-240\":[\"والجواب، والله أعلم: أن خرق السفينة لم يبلغ بحيث يتلفها، وإنما قصد به الخضر عيبها ليزهد فيها مريد غصبها بدليل قوله بعد: (فَأَرَدْتُ أَنْ أَعِيبَهَا وَكَانَ وَرَاءَهُمْ مَلِكٌ يَأْخُذُ كُلَّ سَفِينَةٍ غَصْبًا)\",1,\"2:322\"],\"G-241\":[\"والجواب: أن الخضر قد كان قال ملوسى حين قال له موسى\",1,\"2:322\"],\"G-243\":[\"والجواب عن ذلك: أنه لما تقدم في أول سورة الأنبياء إثبات كون الرسل، عليهم السلام، من البشر، فيما حكاه تعالى من قول الكفار بعضهم لبعض: (هَلْ هَذَا إِلَّا بَشَرٌ مِثْلُكُمْ)، ثم قال تعالى رادًا لقولهم\",1,\"2:324\"],\"G-244\":[\"والجواب عنه - والله أعلم - أن الله سبحانه وصف يحيى، عليه السلام، بعظم التقوى في قوله تعالى: (وَكَانَ تَقِيًّا)، وتقي فعيل من التقوى، وهو من أبنية المبالغة\",1,\"2:325\"],\"G-245\":[\"والجواب عن الأول منها: أن الكفر بالله سبحانه أعظم من كل خطيئة، والذي لا ينفع معه شيء من أعمال البر، فهو أعظم من الظلم، ثم قد يوصف الكافر بالظلم إشارة إلى الصفة اللازمة له من ظلمه نفسه بكفره وشنيع مرتكبه\",1,\"2:326\"],\"G-246\":[\"والجواب عن ذلك، والله أعلم: أن اليوم المشار إليه يشتمل على موقف ومواطن مهولة وأحوال مختلفة، وبحسب ذلك تختلف العبارة والأخبار لاختلاف المقاصد والمواطن\",1,\"2:327\"],\"G-247\":[\"والجواب عنه، والله أعلم: محصل طي تمهيد وهو أن السور المتردد فيها ذكر الرسل، عليهم السلام، منوطًا فيها ذكرهم بذكر أممهم، وما كان من معاندة الأمم وتكذيبهم، وأخذ المكذبين بمرتكباتهم\",1,\"2:329\"],\"G-248\":[\"والجواب: أن الآية الأولى ورد قبلها بعد ذكر المنعم عليهم ومن اهتدى بهديهم قوله: (فَخَلَفَ مِنْ بَعْدِهِمْ خَلْفٌ أَضَاعُوا الصَّلَاةَ وَاتَّبَعُوا الشَّهَوَاتِ فَسَوْفَ يَلْقَوْنَ غَيًّا)، وهذا قول موجز مجمل\",1,\"2:330\"],\"G-249\":[\"الجواب عما تقدم ما لا يفتقر فيه إلى بنائه على ما مهدناه.\",1,\"2:333\"],\"G-250\":[\"والجواب عن الأول منهما: أن آية طه خطاب للنبي ﷺ، يتضمن تأنيسه وتسليته عن حال كفار قريش في (توقفهم عن) الإيمان، فافتتحت السورة بأجل التأنيس وهو قوله تعالى مبشرًا لنبيه، عليه السلام\",1,\"2:335\"],\"G-251\":[\"والجواب عن السؤال الأول: أن قول موسى، عليه السلام، لا توقف في أنه لم ترد حكايته إلا بالمعنى لاختلاف اللسانين كما تقدم، وإذا تقرر كونها بالمعنى، والترادف فيما بين اللغتين في كل لفظتين يراد بهما معنى واحد غير مطرد\",1,\"2:337\"],\"G-252\":[\"والجواب عن الأول: ما تقدم من أن الإخبار عن ذلك كله في كتابنا معتمد فيه المعنى، وقد تقدم بيان ذلك مستوفى، وأما وجه التخصيص\",1,\"2:338\"],\"G-253\":[\"والجواب عن ذلك: أن العبارتين في السورتين معناهما متقارب وهو ما هيأه سبحانه لعباده من المذكور في قوله: (هُوَ الَّذِي جَعَلَ لَكُمُ الْأَرْضَ ذَلُولًا فَامْشُوا فِي مَنَاكِبِهَا)\",1,\"2:340\"],\"G-254\":[\"والجواب عن الأول: أن قوله: (ومن يعمل) بواو النسق ورد في مقابلة ما تقدمه من المعنى الحاصل من قوله: (وَعَنَتِ الْوُجُوهُ لِلْحَيِّ الْقَيُّومِ) وقد خاب من حمل ظلمًا لأن عنت الوجوه ذلتها في القيامة\",1,\"2:341\"],\"G-255\":[\"والجواب عن ذلك، والله أعلم: أن قوله في الآية الأولى: (أَفَلَمْ يَهْدِ لَهُمْ) كلام لم يتقدمه ما يكون هذا معطوفًا عليه، وإنما هو كلام مستأنف مبتدأ\",1,\"2:342\"],\"G-256\":[\"والجواب أن ذلك، والله أعلم: لرعي الفواصل ومقاطع الآي، ألا ترى ما تقدم قبل آية ق من قوله: (وَلَقَدْ خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا فِي سِتَّةِ أَيَّامٍ وَمَا مَسَّنَا مِنْ لُغُوبٍ)\",1,\"2:343\"],\"G-257\":[\"والجواب، والله أعلم: أن هذين الاسمين العظيمين وهما: الرب والرحمان تواردا في الكتاب العزيز كثيرًا، أول ذلك في الفاتحة\",1,\"2:345\"],\"G-258\":[\"والجواب عن الأول، والله أعلم: أن الكفار المعاصرين لرسول الله ﷺ لم يتقدم قبل آية الأنبياء أو فيما يليها من آي السورة أو يقرب منها خطاب يعنيهم ويخصهم من غيرهم\",1,\"2:346\"],\"G-259\":[\"والجواب، والله أعلم: أن آية الأنبياء قد تقدمها أمره، عليه السلام، بخطاب حاضريه، وإنذارهم بما أوحي إليه، وإعلامهم بأن إنذاره إياهم لا يجدي عليهم، تسلية له، عليه السلام، وإعلامًا بما سبق لهم أزلًا\",1,\"2:347\"],\"G-260\":[\"والجواب عن الأول، والله أعلم: أن جوابهم في الموضعين ليس جوابًا لسؤال واحد، وإنما ورد (جوابًا) لسؤالين، فاختلف بحسبهما، فسؤاله في آية الأنبياء سؤال مطلع على معبوداتهم ما هي؟\",1,\"2:348\"],\"G-261\":[\"والجواب عن السؤالين معًا: أن الخاسر عندنا من فقد ما بيده من مال أو سبب كان يعتمده لدنياه ومعاشه، أو محاولة فسدت عليه فساءت حاله، لذلك ومهما استحكمت حاله في ذلك كان أخسر\",1,\"2:349\"],\"G-262\":[\"والجواب على الجملة، والله أعلم: أنه لما ورد في الأنبياء تلطف أيوب عليه السلام بقوله: (وَأَيُّوبَ إِذْ نَادَى رَبَّهُ أَنِّي مَسَّنِيَ الضُّرُّ وَأَنْتَ أَرْحَمُ الرَّاحِمِينَ)، فلما تلطف في سؤاله، ولم يفصح، عليه السلام\",1,\"2:350\"],\"G-263\":[\"والجواب عن الأول، والله أعلم: بعد تسلمي اتحاد المعنى الواقع به البناء، إن الضمير في الأولى عائد إلى ما أشير إليه بالموصول الذي هو التي، وهي مريم ابنة عمران المفتتح باسمها في آية التحريم\",1,\"2:351\"],\"G-264\":[\"الجواب (فنقول: الجواب) عن الأول أن سورة الأنبياء لم يرد فيها ذكر لفظ التقوى في أمر ولا خبر من أولها إلى آخرها\",1,\"2:353\"],\"G-265\":[\"والجواب، والله أعلم: أن آية سورة الحج مقصود فيها إقامة البرهان على البعث الأخراوي وبسط الدلالات على كيفية وإرغام منكرية، ألا ترى أن هذه الأحوال والانتقالات على ما وضح من التدريج لا تكون إلا من فاعل قادر مختار عليم حكيم\",1,\"2:357\"],\"G-266\":[\"الجواب عن الأول: أن زيادة قوله: (من غم) في الآية الأولى مناسب لما ورد قبله وبعده من تفصيل الجزاء في الطرفين بعد ذكر الحالين من نعيم أو عذاب لما قال تعالى:\",1,\"2:358\"],\"G-268\":[\"والجواب: أن الآية الأولى تنزلت على ما ذكر قبلها ممن أهلك من القرون والأمم السالفة بتكذيبهم للرسل، ممن قال فيهم بعد تفصيل ذكرهم: (وَأَصْحَابُ مَدْيَنَ وَكُذِّبَ مُوسَى فَأَمْلَيْتُ لِلْكَافِرِينَ ثُمَّ أَخَذْتُهُمْ)\",1,\"2:360\"],\"G-269\":[\"والجواب عنه، والله أعلم: أن المراد تبيين أفعال سبحانه، وأنه لا تكلف فيها ولا معالجة: (إِنَّمَا أَمْرُهُ إِذَا أَرَادَ شَيْئًا أَنْ يَقُولَ لَهُ كُنْ فَيَكُونُ)، فكأن قد قيل لهم: إذا شاء هذابكم كان\",1,\"2:360\"],\"G-270\":[\"والجواب عنه أن الآية الأولى إخبار لهم عند دعائهم قبل: أن «آمنوا»، ألا ترى أن قبله أمر الله سبحانه رسوله ﷺ بما يقول لهعم في قوله تعالى: (قُلْ يَا أَيُّهَا النَّاسُ إِنَّمَا أَنَا لَكُمْ نَذِيرٌ مُبِينٌ)\",1,\"2:361\"],\"G-271\":[\"ووجه ذلك، والله أعلم: أن سورة الحج ورد فيها ما يستدعي هذا التأكيد بالضمير المنفصل ويناسبه، وهو تكرر الإشارة إلى آلهتهم والإفصاح بذكرهم تعريفًا بوهن مرتكبهم وشنيع حالهم\",1,\"2:362\"],\"G-272\":[\"والجواب: أن الزيادتين معًا للتأكيد، لا تدخل اللام الخبرَ لغير ذلك، وتكرار الموصول أيضًا لذلك فدخلتا في آية الحج لما قدرت الآية قبلها من السورة من بنائها على مقصود التأكيد فجواب هذين السؤالين حاصل مما تقدم.\",1,\"2:363\"],\"G-273\":[\"والجواب عن الأول: أن حفظ الفروج أحد الأصول الخمسة التي اتفقت فيها الشرائع، ولم يخالف فيها أحد من العقلاء، وهي: حفظ النفوس، والأموال، والفروج، والعقول، والأعراض.\",1,\"2:364\"],\"G-274\":[\"والجواب عن الأول: أن المجرور الذي هو: (من قومه) رافع إمكان أن يكون القائلون غيرهم.\",1,\"2:367\"],\"G-275\":[\"والجواب، أن الآية الأولى في أمة معينة، قد بين حالها وقبيح مرتكبها، وتحصل العلم بكفرهم وظلمهم أنفسهم، فقيل: (فَبُعْدًا لِلْقَوْمِ الظَّالِمِينَ)، ووقوع اسم الظلم عليهم على أتم ما يقع عليه، من عدم الإيمان\",1,\"2:369\"],\"G-276\":[\"والجواب عنه، والله أعلم: أنه لما تقدم قبل آية المؤمنون قوله تعالى: (أَفَلَمْ يَدَّبَّرُوا الْقَوْلَ أَمْ جَاءَهُمْ مَا لَمْ يَأْتِ آبَاءَهُمُ الْأَوَّلِينَ)، فتقدم التعريف في هذه الآية أن آباءهم قد جاءتهم الرسل\",1,\"2:369\"],\"G-277\":[\"والجواب عن ذلك بوجهين: أحدهما.\",1,\"2:370\"],\"G-278\":[\"والجواب أن الآية الأولى لما اتبنت على آية التلاعن، وفيها من الستر على المسلمين ممن امتحن بتلك البلية، ومن إخفاء الحكمة في حكم التلاعن وشرعيته على ما استقر (عليه) أمره، مما يعجز عن فهمه كل معتبر\",1,\"2:372\"],\"G-279\":[\"والجواب أنه لما تقارب اللفظ الواحد عدل عن تكراره بلفظ واحد فيما تقارب، على عادة العرب في استثقالها تكرر اللفظ الواحد بعينه في بيت واحد من الشعر أو ما تقارب من الكلام، ما لم يحمل على ذلك حامل من المعنى\",1,\"2:373\"],\"G-280\":[\"والجواب عنه: أن آية الفرقان تقدم قبلها اسمه سبحانه مكنيًا عنه جل وتعالى في قوله:\",1,\"2:374\"],\"G-281\":[\"والجواب: أنه لما كان قول السحرة (لَا ضَيْرَ إِنَّا إِلَى رَبِّنَا مُنْقَلِبُونَ)\",1,\"2:375\"],\"G-282\":[\"والجواب عن ذلك أن قصص الرسل، عليهم السلام، مع أممهم لم تأت في القرآن العظيم على نهج واحد في الدعاء والجواب والمراجعة والمحاورة، ولا يمكن ذلك لاختلاف طباع الأمم وأغراضهم واختلاف الحالات، ولكل مقام مقال\",1,\"2:376\"],\"G-283\":[\"والجواب: أن أمر الإماتة والإحياء لا مطمع فيه لأحد بخلاف أمر الإطعام والسقي، إذ قد يتوهم من ضعف نظره أن ذلك مما تصح فيه النسبة لغيره تعالى إذ يقال: أطعمني فلان وسقاني، ويسبق إلى الوهم الاستقلال، وإنما ذلك على المجاز\",1,\"2:377\"],\"G-284\":[\"والجواب عنه - والله أعلم - أن ذلك لرعي المناسبة\",1,\"2:377\"],\"G-286\":[\"والجواب، والله أعلم: أن الآية الأولى لما نبهوا فيها ذكروا بما تشهد العقول بديهيًا وتعترف بدلالته - إذ لا إشكال فيه - من أن السماوات والأرض تشهد بإحكام منعتها، وإتقان خلقها\",1,\"2:381\"],\"G-287\":[\"والجواب عن ذلك، بعد تسليم أن وروده في سورة القصص متقدمًا فقيل: (وَجَاءَ رَجُلٌ) وارد فلى ما يجب، لأن مرتبة الفاعل التقديم، ولا يتأخر عن ولايته الفعل إلا لعارض من جهة اللفظ أو من جهة المعنى أو اتساعًا\",1,\"2:383\"],\"G-288\":[\"والجواب عن الأول: أن سورة القصص تضمنت ذكر قارون وما أتيه من المال الذي هو زينة الجياة الدنيا، قال تعالى: (وَآتَيْنَاهُ مِنَ الْكُنُوزِ مَا إِنَّ مَفَاتِحَهُ لَتَنُوءُ بِالْعُصْبَةِ أُولِي الْقُوَّةِ)\",1,\"2:384\"],\"G-289\":[\"والجواب عن الأول أن تقديم الليل على النهار جار على ما بنت العرب عليه حساب شهورها من تقديم الليل وجعل النهار تابعًا له، ولم يرد في كتاب الله تعالى على كثرة ترداده إلا ذلك.\",1,\"2:386\"],\"G-290\":[\"والجواب عن الأول: أن بناء آية العنكبوت على قص سعد بن أبي وقاص وما كان من فعل أمة وحلفها على ألا تأكل ولا تشرب ولا تستظل حتى يرجع سعد إلى دينها، والقصة مشهورة، فنزلت الآية\",1,\"2:387\"],\"G-291\":[\"والجواب عنه، والله أعلم: أنه لما تقدم فيها قوله تعالى: (أَمْ حَسِبَ الَّذِينَ يَعْمَلُونَ السَّيِّئَاتِ أَنْ يَسْبِقُونَا سَاءَ مَا يَحْكُمُونَ)\",1,\"2:389\"],\"G-292\":[\"والجواب عنه، والله أعلم: أن الإشارة في الآية الأولى بقوله: (إِنَّ فِي ذَلِكَ لَآيَاتٍ) ليست لقصة إبراهيم، عليه السلام، وإنجائه من النار فقط بل الإشارة لمجموع معتبرات، منها لبث نوح، عليه السلام\",1,\"2:390\"],\"G-293\":[\"والجواب: أن الظلم وإن كان يطلق على الكفر وعلى ما دونه قال تعالى: (وَالْكَافِرُونَ هُمُ الظَّالِمُونَ)، فإنه إذا ذكر بعد الكفر ووصف به من قد وصف بالكفر أفهم زيادة مرتكب على الكفر\",1,\"2:391\"],\"G-294\":[\"والجواب عن الأول: أن المقصود فيها ليس واحدًا، أما الثلاث آيت الأول فالمراد منها استدلال بهذا الخلق العظيم، وما هو عليه من جليل التناسب، وإتقان الصنعة وإحكامها من غير تفاوت ولا فطور، على واحدانية تعالى\",1,\"2:391\"],\"G-295\":[\"والجواب عن السؤالين معًا: أن هذه الآيات لم يختلف المقصود بها وهو التنبيه على الاعتبار بحال من تقدم من القرون ما يلائم ما جرى في تلك السورة قبل ذلك الموضع أو بعده من إشارة أو تعريف إخبارًا من غير تنبيه أو تحريك إلى\",1,\"2:394\"],\"G-296\":[\"والجواب عن ذلك، والله أعلم: أن الآية الأولى لما انطوت من حكمته سبحانه في سبب التناسل والتكاثر على ما أبداه تعالى في خلق الأزواج منا ليحصل السكن وعدم التنافر\",1,\"2:398\"],\"G-297\":[\"والجواب، والله أعلم: أن سورة الروم لما تقدم فيها قوله تعالى: (أَوَلَمْ يَتَفَكَّرُوا فِي أَنْفُسِهِمْ مَا خَلَقَ اللَّهُ السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ)\",1,\"2:399\"],\"G-298\":[\"والجواب عن ذلك، والله أعلم: أن آية الروم إنما أعقبت بقوله: (يَوْمَئِذٍ يَصَّدَّعُونَ) تمهيدًا لما اتصل بها من تفصيل الأحوال في قوله: (مَنْ كَفَرَ فَعَلَيْهِ كُفْرُهُ وَمَنْ عَمِلَ صَالِحًا فَلِأَنْفُسِهِمْ يَمْهَدُونَ)\",1,\"2:400\"],\"G-299\":[\"والجواب، أن هذا لا إشكال فيه، لأن البحر لم يجر له ذكر في آية الروم، فلم يكن للضمير ما يرجع إليه، فلم يؤت به بهذا، ولو قصد محل جري الفلك ألزم الإتيان بالظاهر (ولقيل): ولتجري الفلك في البحر، وهو مفهوم من السياق\",1,\"2:401\"],\"G-300\":[\"والجواب عن ذلك، والله أعلم: أن آية الجاثية لما تقدم فيها: (وَيْلٌ لِكُلِّ أَفَّاكٍ أَثِيمٍ * يَسْمَعُ آيَاتِ اللَّهِ تُتْلَى عَلَيْهِ ثُمَّ يُصِرُّ مُسْتَكْبِرًا)\",1,\"2:402\"],\"G-301\":[\"والجواب عن ذلك، والله أعلم: أن آية الشورى، لما دخلها معنى القسم، وكانت على تقديره، إذ اللام في قوله: (وَلَمَنْ صَبَرَ وَغَفَرَ) توطئة له ودالة على تضمين الآية معناه، وناسب ذلك زيادة لام التأكيد في خبر إن\",1,\"2:402\"],\"G-302\":[\"والجواب\",1,\"2:403\"],\"G-303\":[\"والجواب: أنهم يكذبون بالنار وبعذابها، وقد ورد العذاب مضافًا إليها في السورتين، والعذاب مذكر والنار مؤنثة، وعودة الضمير إلى كل من المضافين تحصل المقصود على السواء\",1,\"2:404\"],\"G-304\":[\"والجواب، والله أعلم: أاختلاف العقيب مرعي فيه ما تقدم قبل كل واحدة من الآيتين، أما الأولى فالمتقدم قبلها قوله تعالى: (وَلَا تُطِعِ الْكَافِرِينَ وَالْمُنَافِقِينَ)\",1,\"2:405\"],\"G-305\":[\"ووجه ذلك، والله أعلم: أن الآية الأولى معقب (بها) قصة زينب أم المؤمنين وزيد بن حارثة، رضي الله عنهما وما جرى في ذلك إلى أن تزوجها رسول الله ﷺ (فهذه الآية تأنيس لرسول الله ﷺ)\",1,\"2:406\"],\"G-306\":[\"والجواب عنه\",1,\"2:408\"],\"G-307\":[\"والجواب: أن االموضع الأول لم يتقدمه شيء يوجد عدولهم عن التعبير عن معتقاداتهم (في إنكار الإحياء بعد الموت فورد على ما يطابق معتقادهم)، وأما الآية الأخرى فقد تمهد قبلها ذكر الجزاء الأخراوي وذكر السؤال\",1,\"2:410\"],\"G-311\":[\"والجواب - والله أعلم - أن آية ص وردت مورد الإخبار بمرتكبات من أفعال كفار العرب وأقوالهم فجيء بتلك الجمل منسوقًا بعضها على بعض، فأخبر تعالى أنهم في عزة وشقاق\",1,\"2:414\"],\"G-312\":[\"والجواب عن ذلك - والله أعلم: عن الجملة أن الوارد في السور الثلاث مقصود فيه إخبار الله تعالى نبيه ﷺ بما كان من الرسل المذكورين مع أممهم تثبيتًا لفؤاده ﷺ وتأنيسًا\",1,\"2:415\"],\"G-313\":[\"والجواب عن السؤال، والله أعلم: أن تكرر أمره، عليه السلام، بالصبر في الآيات المترددة على كثرتها أدل دليل على الاعتناء به ﷺ لعظم أمر الصبر وشدة الحاجة إليه في كل مطلب ديني من أخذ أو ترك، ولهذا قال ﷺ في صفته: \\\" الصبر ضياء\\\"\",1,\"2:419\"],\"G-314\":[\"والجواب: أن (إليك)\",1,\"2:424\"],\"G-315\":[\"والجواب عن ذلك: أن العرب تقول: أمرتك الخير وأمرتك بالخير، فعدي هذا الفعل بنفسه وبحرف الجر، وهو الأصل فيه، والحذف فصيح كثير، ويلحق إذ ذاك بباب أعطى وكسا في أحكامه\",1,\"2:425\"],\"G-316\":[\"والجواب، والله أعلم: أنه لا يناسب كلا من الموضعين إلا ما ورد فيه، ولا يجوز على رعي التناسب اللازم رعيه في الكتاب العزيز غير ما ورد عليه الموضعان، ووجه ذلك أن آية الزمر وردت مورد التنبيه على الاعتبار\",1,\"2:426\"],\"G-317\":[\"والجواب عنه، أن العمل أعم من الكسب لأن الكسب واقع على ما للإنسان فيه تعمل وعلاج، وقد يطلق على غير الإنسان إذا كان الواقع منه ذلك حيوانًا يصح منه القصد كالجوارح المعلمة وشبهها\",1,\"2:427\"],\"G-318\":[\"والجواب، والله أعلم: أن (إذا) في مثل هذا االكلام جارية مجرى أدوات الشرط في احتياج الفعل بعدها إلى الجواب، إلا أن جوابها في قول البصريين لا ينجزم إلا في الشعر، وأهل الكوفة يرون أنها تجزم في الكلام\",1,\"2:428\"],\"G-319\":[\"والجواب، والله أعلم: أن ذلك جار بحسب المناسبة، ولما تقدم الآية الأولى فيما ختمت به سورة الزمر من ذكر المتقين في قوله تعالى: (وَسِيقَ الَّذِينَ اتَّقَوْا رَبَّهُمْ إِلَى الْجَنَّةِ زُمَرًا)\",1,\"2:431\"],\"G-320\":[\"والجواب عن ذلك مجملًا، والله أعلم: أن المخاطبين ممن عقل لو نظروا واعتبروا لعملوا، ولو علموا لآمنوا، ولو آمنوا واستوضحوا النعم لشكروا\",1,\"2:432\"],\"G-321\":[\"والجواب، والله أعلم: أن (إذا) تزاد بعدها (ما) كثيرًا فصيحًا، وقد لا تزاد، وكلا المرتكبين فصيح.\",1,\"2:434\"],\"G-322\":[\"والجواب عن ذلك، والله أعلم: أن آية الشورى تقدم قبلها ذكر تلك الغاية والأجل في قوله: (وَتُنْذِرَ يَوْمَ الْجَمْعِ لَا رَيْبَ فِيهِ فَرِيقٌ فِي الْجَنَّةِ وَفَرِيقٌ فِي السَّعِيرِ)، فهذا هو الوقت الموعود والأجل المسمى\",1,\"2:435\"],\"G-323\":[\"والجواب عن ذلك، والله أعلم: أن ثم للترتيب الزماني واقتضاء المهلة فيه، وتأتي أيضًا لبيان رتبة ما يعطف بها، وأن له موقعًا وخطرًا وبه اعتناء، وقد مر بيان ذلك.\",1,\"2:435\"],\"G-324\":[\"والجواب عن ذلك، والله أعلم: أن الآية الأولى لما تضمنت الإعلام بانفراده سبحانه بملك السماوات والأرض وقهره جميع (من) فيهن، وأنه الخالق لكل شيء فلا اختيار لمخلوق ولا مشيئة، وكل صادر منه إحسان، فيهب لمن يشاء إناثًا\",1,\"2:437\"],\"G-325\":[\"والجواب عن ذلك، والله أعلم: أنهم لما قالوا: (لَوْ شَاءَ الرَّحْمَنُ مَا عَبَدْنَاهُمْ) فتعلقوا في احتجاجهم بقول الحق، وهو أنه سبحانه لا يجري في ملكه إلا ما يريده ويشاؤه\",1,\"2:439\"],\"G-326\":[\"ووجه ذلك، والله أعلم: أن ما تقدم الآية الأولى خكاية قول كفار العرب المعاصرين لرسول الله ﷺ والسامعين منه القرآن المسمى هدى في غير موضع كقوله سبحانه: (هُدًى لِلْمُتَّقِينَ)، وقوله: (هَذَا هُدًى)\",1,\"2:440\"],\"G-327\":[\"والجواب عن ذلك، والله أعلم: أن خلق السماوات والأرض للمعتبر المنصف كاف في التصديق بحدوثهما وافتقارهما من حيث إن وجودهما أو عدمهما من قبيل الجائز، والتخصيص بأحد الجائزين لا يكون إلا بمخصص مقتض هذا الجائز الواقع\",1,\"2:441\"],\"G-328\":[\"والجواب، والله أعلم: أن ذلك مفهوم مما تقدم في (أول) سورة آل عمران باعتبار ما يخص هذه السورة\",1,\"2:443\"],\"G-330\":[\"والجواب عن ذلك، والله أعلم: أن\",0,\"2:445\"],\"G-331\":[\"ووجه ذلك أن المخبر عنهم من المخلفين طلبوا منه ﷺ الاستغفار لهم لتخلفهم عنه، وأفردوه بخطابهم إذ ليس ذلك من مطلوبهم لغيره فوردت العبارة عن ذلك بإفراد الخطاب.\",1,\"2:446\"],\"G-332\":[\"والجواب عنه: أنه قد تقدم قبل الآية الأولى قوله تعالى: (سَيَقُولُ لَكَ الْمُخَلَّفُونَ مِنَ الْأَعْرَابِ شَغَلَتْنَا أَمْوَالُنَا وَأَهْلُونَا فَاسْتَغْفِرْ لَنَا يَقُولُونَ بِأَلْسِنَتِهِمْ مَا لَيْسَ فِي قُلُوبِهِمْ)\",1,\"2:446\"],\"G-333\":[\"والجواب عن ذلك: أن الآية معطوفة على ما قبلها من آيات هي إخبار عما يلقاه الإنسان المتقدم ذكره من الأهوال والشدائد في المواقف الأخراوية وما بين يديها، أولها قوله: (وَجَاءَتْ سَكْرَةُ الْمَوْتِ بِالْحَقِّ)\",1,\"2:447\"],\"G-334\":[\"والجواب\",1,\"2:448\"],\"G-335\":[\"والجواب عن ذلك، والله أعلم: أن هاتين السورتين اتحدتا في القصد من وعيد كفار قريش والعرب ذوي العناد والتكذيب والإخبار بجزائهم الأخراوي، فعلى هذا مبنى السورتين، ولهذا افتتحتا بالقسم على ذلك كما تقدم\",1,\"2:449\"],\"G-336\":[\"والجواب، والله أعلم: أن آية المعارج قد تقدمها متصلًا بها قوله تعالى: (إِلَّا الْمُصَلِّينَ)، والمراد بالصلاة هنا المكتوبة، وأيضًا يقرن بها في آي الكتاب الزكاة المفروضة، وبها فسر المفسرون الحق المعلوم في آية المعارج.\",1,\"2:450\"],\"G-337\":[\"والجواب: أنه سبحانه لما قدم من المعتبرات الدالة على وجوده تعالى\",1,\"2:451\"],\"G-338\":[\"والجواب، والله أعلم: يترتب على تمهيد، وهو أن الغلام هو الطار الشارب، وقيل باستصحابه هذا الاسم إلى أن يشيب، والجمع غلمان.\",1,\"2:453\"],\"G-339\":[\"والجواب عن ذلك، والله أعلم: أنه جل وتعالى أرغم معاندي رسول الله ﷺ، وقطع تعلقهم، وأوضح عجزهم، وأوقفهم على قبيح تكذيبهم وشنيع مرتكبهم في بضع وعشرين آية من سورة الطور وسورة القلم، وفي سورة الطور أكثرها\",1,\"2:454\"],\"G-340\":[\"والجواب، والله أعلم: أنه لما قال تعالى قبل هذا: (أَفَرَأَيْتُمُ اللَّاتَ وَالْعُزَّى * وَمَنَاةَ الثَّالِثَةَ الْأُخْرَى) فذكر أصنامهم وتسميتهم إياها آلهة واتخاذها معبودات\",1,\"2:457\"],\"G-341\":[\"والجواب عن ذلك، والله أعلم: أن عادًا لما كذبوا هودًا، عليه السلام، امتحنوا بالقحط ثلاث سنين، واشتد الأمر عليهم حتى بعثوا وجوههم إلى مكة ليستسقوا لهم، وقد اشتد الأمر عليهم، وهذا أشد تخويف لو وفقوا للتذكر\",1,\"2:459\"],\"G-342\":[\"والجواب عن ذلك - والله أعلم - أن المراد بذكر الميزان إعلام العباد بما به قوام أحوالهم واستقامة أديانهم من إجراء أمورهم على العدل الذي أمر سبحانه في قوله:\",1,\"2:461\"],\"G-344\":[\"والجواب عن هذه أن ذكر المتنعم متقدم في الرتبة على ما ذكر من النعم، لأن النعم إنما خلقت للمتنعم بها ومن أجله، فذكره أولًا بين اللزوم، فلهذا تقدم ذكر خلق الإنسان المتنعم بالنعم فقال تعالى: (أَفَرَأَيْتُمْ مَا تُمْنُونَ)\",1,\"2:466\"],\"G-346\":[\"والجواب عن الأول، والله أعلم: أن كون \\\" ما \\\" لم تتكرر في هذه السورة إنما ذلك ليطابق بالكلام ما اتصل به من قوله تعالى: (لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ)\",1,\"2:467\"],\"G-347\":[\"والجواب الأول: أن إعادة قوله: \\\" له ملك السموات والأرض \\\" إنما أعيد ليبني عليه قوله: \\\" وإلى الله ترجع الأمور\\\".\",1,\"2:467\"],\"G-348\":[\"ووجه ذلك، والله أعلم: أن قوله في سورة التحريم (الَّذِينَ آمَنُوا مَعَهُ) يفهم من حيث المعية قرب المنزلة وعلو الحال فتقدم ثبوته، فناسب ذلك ورود الجملة الاسمية هنا لما تقتضيه من الثبات وتقدمه واستحكامه.\",1,\"2:468\"],\"G-350\":[\"والجواب عن ذلك، والله أعلم: أن الآية الأولى لما تقدمها ذكر الظهار، وقد سماه سبحانه منكرًا من القول وزورًا، وشرع الكفارة فيه رحمة وتداركًا للواقع فيه إذا اتعظ وأناب، وجعلها (على التدرج) من تحرير رقبة للواجد القادر عليها\",1,\"2:470\"],\"G-351\":[\"والجواب عن ذلك، والله أعلم: أن الله تعالى لما أخبر عن يهود والمنافقين بسوء أحوالهم وأن الرعب قد سكن قلوبهم حتى كأن خوفهم من أصحاب رسول الله صلي الله عليه وسلم أشد من خوفهم من الله\",1,\"2:471\"],\"G-352\":[\"والجواب عن ذلك، والله أعلم: أنه تعالى لما أمر المؤمنين ألا يتخذوا أعداءه وأعداءهم أولياء بإلقاء أسباب المودة والنصيحة لهم، وسبب نزول هذه السورة قصة حاطب بن أبي بلتعة، رحمه الله\",1,\"2:472\"],\"G-353\":[\"والجواب، والله أعلم: أن الاعتزار بالدين والاطلاع على تشريف المؤمن به واعتزازه بسببه أمر لا يوصل إليه إلا بعلم ويقين لا طريق لمنافق إليه ما دام على نفاقه\",1,\"2:474\"],\"G-354\":[\"والجواب عن ذلك، والله أعلم: أن الآيتين معًا قصد بهما الاستيفاء والإحاطة بكل المسبحين وبما أحاط به علمه سبحانه، وقد اقترن ب\",0,\"2:475\"],\"G-355\":[\"والجواب عنه، والله أعلم: أنه لما تقدم في سورة التغابن قوله تعالى مخبرًا عن المكذبين: (زَعَمَ الَّذِينَ كَفَرُوا أَنْ لَنْ يُبْعَثُوا)\",1,\"2:475\"],\"G-357\":[\"والجواب: والله أعلم: أنه لما تقدم ما اتصل به التوعد من قوله تعالى: (هُوَ الَّذِي جَعَلَ لَكُمُ الْأَرْضَ ذَلُولًا فَامْشُوا فِي مَنَاكِبِهَا) فحضر في النفوس عند ذلك وتقرر تذكرة هذه النعمة\",1,\"2:479\"],\"G-358\":[\"والجواب عن ذلك، والله أعلم: أن آية القلم نزلت في شخص بعينه، قيل هو الأخنس بن شريق، وقيل الوليد بن المغيرة وكان مظهرًا لعداوة رسول الله صلي الله عليه وسلم، وهو القائل: سأنزل مثل ما أنزل الله، وكان من أكثر قريش مالًا وولدا\",1,\"2:480\"],\"G-359\":[\"والجواب عن ذلك\",1,\"2:482\"],\"G-361\":[\"والجواب\",1,\"2:484\"],\"G-362\":[\"والجواب عن ذلك، والله أعلم: أن الله سبحانه أمرنا في كتابه العزيز بتعزيز نبينا ﷺ وتوقيره، ونهانا أن نجري في خطابه على حد تخاطبنا فقال تعالى: (لَا تَجْعَلُوا دُعَاءَ الرَّسُولِ بَيْنَكُمْ كَدُعَاءِ بَعْضِكُمْ بَعْضًا)\",1,\"2:491\"],\"G-363\":[\"والجواب، والله أعلم: أن قوله: (إِنَّهُ فَكَّرَ وَقَدَّرَ) إخبار عن حال الوليد المنزل فيه هذا حين قال لقريش: إن الناس يريدون الموسم فليكم قولكم في محمد واحدًا، وفكر في أقرب ما يمكن أن تستمال به العرب وتصدق قريشًا\",1,\"2:492\"],\"G-364\":[\"والجواب، أن هذا مما لا إشكال فيه لأن المذكر به عظة أو موعظة وهو أيضا وعظ وتنبيه.\",1,\"2:493\"],\"G-365\":[\"والجواب عنه أن ذلك لبيان أهوال القيامة وتعظيمها، والعرب تستعمل هذا فيما تقصد به التهويل والتعظيم، ومنه لا أري الموت يسبق الموت شئ نغص الموت ذا الغنى والفقير فكررت المو ثلاث مرات تعظيمًا لأمره\",1,\"2:495\"],\"G-366\":[\"والجواب عن ذلك: والله أعلم: أنه لما تقدم وصف المجرم المكذب بقوله: (فَلَا صَدَّقَ وَلَا صَلَّى وَلَكِنْ كَذَّبَ وَتَوَلَّى ثُمَّ ذَهَبَ إِلَى أَهْلِهِ يَتَمَطَّى) - أي يختال في مشيته ويتبختر عضدًا لتكذيبه\",1,\"2:495\"],\"G-367\":[\"والجواب عن ذلك أن بناء الآيتين في هذه السورة على تعظيم حال أهل الجنة وما أعد الله لهم، فذكر فيها ما يطاف (به) عليهم من أواني الفضة والأكواب بالطعام والشراب، وما يمزج به شرابهم من الزنجبيل والعين التي تسمى سلسبيلا\",1,\"2:497\"],\"G-368\":[\"والجواب عن الأول: أن سورة الإنسان لما تضمنت التعريف بحال الفريقين ذوي السعادة وأهل الشقاء، وابتدئت بذكر حال المكذبين فقال تعالى: (إِنَّا أَعْتَدْنَا لِلْكَافِرِينَ سَلَاسِلَ وَأَغْلَالًا وَسَعِيرًا)\",1,\"2:498\"],\"G-369\":[\"والجواب عن ذلك: قد تقدم أن العرب متى تهممت بشئ أرادته لتحققه وقرب وقوعه أو قصدت الدعاء عليه كررته توكيدًا، وكأنها تقيم تكرارها مكان القسم عليه والاجتهاد في الدعاء عليه حيث يقصد الدعاء\",1,\"2:500\"],\"G-370\":[\"والجواب عن ذلك، والله أعلم: أن الله سبحانه أعلمنا أنه يجازي على الحسنة بعشرة أمثالها إلى سبعمائة ضعف، على ما لا عين رأي ولا أن سمعت ولا خطر على قلب بشر، قال تعالى: (مَنْ جَاءَ بِالْحَسَنَةِ فَلَهُ عَشْرُ أَمْثَالِهَا)\",1,\"2:500\"],\"G-375\":[\"والجواب عن ذلك، والله أعلم: أن آية الانشقاق تقدمها وعيد أخراوي كله لم يقع بعد وهم مكذبون بجميعه، فجئ هنا باللفظ المقول على الاستقبال - وإن كان يصلح للحال - ليطابق الإخبار، لأنه عما يأتى ولم يقع بعد\",1,\"2:505\"],\"G-376\":[\"والجواب أنه قد تقدم أن العرب مهما اعتنت بشئ وتهممت به كررته، وإن ذلك منفصيح كلامهم، وإن منه قولهم.\",1,\"2:506\"],\"G-378\":[\"والجواب عنه: أن هذه السورة تضمنت ذكر إنعامه سبحانه على نبيه صلي الله عليه وسلم، ثم اتبعت تلك المنح الجليلة بما تشركه فيه أمته من التأنيس بتيسير ما عرض فيه عسر للمؤمن في أمر دينه ودنياه، فقال تعالى: (فإن مع العسر يسرا)\",1,\"2:508\"],\"G-379\":[\"والجواب عنه: أنهما قصدان، فالمراد أولًا خلق المخلوقات وشتى العوالم، والمراد ثانيًا تخصيص خلق الإنسان وأنه خلقه من علق، ولا تكرير على هذا.\",1,\"2:509\"],\"G-380\":[\"الجواب: أنه تهديد ووعيد فناسبه التكرير تحقيقًا وتثبيتًا كقوله: (الْحَاقَّةُ مَا الْحَاقَّةُ)، و(الْقَارِعَةُ مَا الْقَارِعَةُ) وما أتى من مثل هذا\",1,\"2:510\"],\"G-381\":[\"والجواب أنها لم تتكرر فيها آية واحدة إذا اعتبرت أن كل آية منها تفيد من المعنى وتحرر ما لا تفيده الأخرى بذلك التحرير، فكأنها متباينة الألفاظ لتباين معانيها مع جليل التشاكل وعلي التلاؤم والتناسب.\",1,\"2:511\"],\"G-383\":[\"والجواب عن ذلك، والله أعلم: أن قوله سبحانه في سورة: (وَلَا يُفْلِحُ السَّاحِرُ حَيْثُ أَتَى)، إطلاق حاكم بتماديه وتمادي حكمه على تلك الصفة المذمومة\",1,\"2:517\"],\"K-002\":[\"كرر ﴿إياك﴾ وَقدمه وَلم يقْتَصر على ذكره مرّة كَمَا اقْتصر على ذكر أحد المفعولين فِي آيَات كَثِيرَة مِنْهَا ﴿مَا وَدعك رَبك وَمَا قلى﴾ أَي مَا قلاك وَكَذَلِكَ الْآيَات الَّتِي بعْدهَا مَعْنَاهَا فآواك فهداك\",1,\"1:65\"],\"K-004\":[\"لَيْسَ بتكرار لِأَن كل وَاحِد مِنْهُمَا مُتَّصِل بِفعل غير الآخر وَهُوَ الإنعام وَالْغَضَب وكل وَاحِد مِنْهُمَا يَقْتَضِيهِ اللَّفْظ وَمَا كَانَ هَذَا سَبيله فَلَيْسَ بتكرار وَلَا من الْمُتَشَابه\",0,\"1:66\"],\"K-008\":[\"لَيْسَ فِي الْقُرْآن غَيره لَيْسَ لِأَن الْعِبَادَة فِي الْآيَة التَّوْحِيد والتوحيد أول مَا يلْزم العَبْد من المعارف فَكَانَ هَذَا أول خطاب خَاطب الله بِهِ النَّاس فِي الْقُرْآن\",1,\"1:67\"],\"K-023\":[\"وَفِي غَيرهَا ﴿لَا يعْقلُونَ﴾ ﴿لَا يعلمُونَ﴾ لأَنهم بَين نَاقض عهد وجاحد حق إِلَّا الْقَلِيل مِنْهُم عبد الله بن سَلام وَأَصْحَابه\",1,\"1:76\"],\"K-045\":[\"أَجمعُوا على تخفيفه إِلَّا شاذا وَمَا فِي عير هَذِه السُّورَة قرئَ بِالْوَجْهَيْنِ لِأَن قبله ﴿فأمسكوهن﴾ وَقبل ذَلِك ﴿فإمساك﴾ فَاقْتضى ذَلِك التَّخْفِيف\",0,\"1:85\"],\"K-048\":[\"كرر هُنَا تَأْكِيدًا وَقيل لَيْسَ بتكرار لِأَن الأول للْجَمَاعَة وَالثَّانِي للْمُؤْمِنين وَقيل كرر تَكْذِيبًا لمن زعم أَن ذَلِك لم يكن بِمَشِيئَة الله تَعَالَى\",0,\"1:87\"],\"K-049\":[\"فِي هَذِه السُّورَة بِزِيَادَة ﴿من﴾ مُوَافقَة لما بعْدهَا لِأَن بعْدهَا ثَلَاث آيَات فِيهَا ﴿من﴾ على التوالي وَهِي قَوْله ﴿وَمَا تنفقوا من خير﴾ ثَلَاث مَرَّات\",0,\"1:87\"],\"K-052\":[\"كَانَ الْقيَاس فأخذناهم لَكِن لما عدل فِي الْآيَة الأولى إِلَى قَوْله ﴿إِن الله لَا يخلف الميعاد﴾ عدل فِي هَذِه الْآيَة أَيْضا لتَكون الْآيَات على مَنْهَج وَاحِد\",0,\"1:88\"],\"K-053\":[\"ثمَّ كرر فِي هَذِه\",1,\"1:88\"],\"K-069\":[\"لَيْسَ غَيره أَي عليم بالمضارة حَلِيم عَن المضادة\",0,\"1:95\"],\"K-091\":[\"ذكر فِي هَذِه السُّورَة هَذِه الْخلال جملَة ثمَّ فصل لِأَنَّهَا أول مَا ذكرت\",0,\"1:104\"],\"K-124\":[\"لَيْسَ فِي الْقُرْآن غَيره لِأَنَّهُ سُبْحَانَهُ لما بَالغ فِي الْحِكَايَة عَنهُ بقوله ﴿لأقعدن لَهُم﴾ الْآيَة بَالغ فِي ذمه فَقَالَ ﴿اخْرُج مِنْهَا مذؤوما مَدْحُورًا﴾ والذأم أَشد الذَّم\",0,\"1:119\"],\"K-181\":[\"بِالْألف وَاللَّام لِأَنَّهُ إِشَارَة إِلَى مَا تقدم من الشَّرّ فِي قَوْله ﴿وَلَو يعجل الله للنَّاس الشَّرّ﴾ فَإِن الضّر وَالشَّر وَاحِد وَجَاء الضّر فِي هَذِه السُّورَة بِالْألف وَاللَّام وبالإضافة وبالتنوين\",0,\"1:139\"],\"K-191\":[\"فِي هَذِه الْآيَة فَحسب لِأَن قَوْله قبله ﴿وَيَوْم نحشرهم جَمِيعًا﴾ وَقَوله ﴿إِلَيْهِ مرجعكم جَمِيعًا﴾ يدلان على ذَلِك فَاكْتفى بِهِ\",0,\"1:140\"],\"K-218\":[\"فِي موضِعين فِي هَذِه السُّورَة لِأَنَّهُ اتَّصل بالصيحة وَكَانَت من السَّمَاء فازدادت على الرجفة لِأَنَّهَا الزلزلة وَهِي تخْتَص بِجُزْء من الأَرْض فَجمعت مَعَ الصَّيْحَة\",1,\"1:146\"],\"K-221\":[\"لَيْسَ فِي الْقُرْآن غَيره\",1,\"1:148\"],\"K-238\":[\"لَيْسَ بتكرار لِأَن التَّقْدِير كَذَلِك يضْرب الله الْحق وَالْبَاطِل الْأَمْثَال فَلَمَّا اعْترض بَينهمَا ﴿فَأَما﴾ ﴿وَأما﴾ وَأطَال الْكَلَام أعَاد فَقَالَ ﴿كَذَلِك يضْرب الله الْأَمْثَال﴾\",0,\"1:152\"],\"K-249\":[\"وَفِي غَيرهَا ﴿لَوْلَا﴾ لِأَن ﴿لَوْلَا﴾ تَأتي على وَجْهَيْن أَحدهمَا امْتنَاع الشَّيْء لوُجُود غَيره وَهُوَ الْأَكْثَر وَالثَّانِي بِمَعْنى هلا وَهُوَ للتحضيض وَيخْتَص بِالْفِعْلِ وَلَوْلَا بِمَعْنَاهُ\",1,\"1:154\"],\"K-283\":[\"بِغَيْر وَاو ﴿وَيَقُولُونَ سَبْعَة وثامنهم كلبهم﴾ بِزِيَادَة وَاو\",1,\"1:168\"],\"K-290\":[\"اخْتَار التَّخْفِيف فِي الأول لِأَن مَفْعُوله حرف وَفعل وفاعل ومفعول فَاخْتَارَ فِيهِ الْحَذف وَالثَّانِي مَفْعُوله اسْم وَاحِد وَهُوَ قَوْله ﴿نقبا﴾\",1,\"1:171\"],\"K-315\":[\"وَبعده ﴿وَترى النَّاس سكارى﴾ محول على أَيهَا الْمُخَاطب كَمَا سبق فِي قَوْله ﴿وَترى الْفلك﴾\",0,\"1:180\"],\"K-336\":[\"مَحْذُوف الْجَواب تَقْدِيره لفضحكم وَهُوَ مُتَّصِل بِبَيَان حكم الزَّانِيَيْنِ وَحكم الْقَاذِف وَحكم اللّعان وَجَوَاب لَوْلَا محذوفا أحسن مِنْهُ ملفوظا بِهِ\",1,\"1:186\"],\"K-338\":[\"مُتَّصِل بآيَات الغض وَلَيْسَ لَهُ نَظِير\",0,\"1:187\"],\"K-340\":[\"إِنَّمَا زَاد ﴿مِنْكُم﴾ لأَنهم الْمُهَاجِرُونَ وَقبل عَام و﴿من﴾ للتبيين\",0,\"1:187\"],\"K-344\":[\"قدم الضّر مُوَافقَة لما قبله وَمَا بعده فَمَا قبله نفي وَإِثْبَات وَمَا بعده موت وحياة وَقد سبق\",0,\"1:189\"],\"K-345\":[\"قدم النَّفْع مُوَافقَة لقَوْله ﴿هَذَا عذب فرات وَهَذَا ملح أجاج﴾ وَقد سبق\",0,\"1:189\"],\"K-361\":[\"قد سبق\",0,\"1:193\"],\"K-373\":[\"﴿ويكأنه﴾ لَيْسَ بتكرار لِأَن كل وَاحِد مِنْهُمَا مُتَّصِل بِغَيْر مَا اتَّصل بِهِ الآخر قَالَ ابْن عَبَّاس وى صلَة وَإِلَيْهِ ذهب سِيبَوَيْهٍ فَقَالَ وى كلمة يستعملها النادم بِإِظْهَار ندامته\",1,\"1:197\"],\"K-376\":[\"بِتَقْدِيم الْعَذَاب على الرَّحْمَة فِي هَذِه السُّورَة فَحسب لِأَن إِبْرَاهِيم خَاطب بِهِ نمروذ وَأَصْحَابه وَأَن الْعَذَاب وَقع بهم فِي الدُّنْيَا\",0,\"1:198\"],\"K-381\":[\"وَفِي هود ﴿وَلما جَاءَت﴾ بِغَيْر ﴿إِن﴾ لِأَن ﴿لما﴾ يَقْتَضِي جَوَابا وَإِذا اتَّصل بِهِ ﴿إِن﴾ دلّ على أَن الْجَواب وَقع فِي الْحَال من غير تراخ كَمَا فِي هَذِه السُّورَة وَهُوَ قَوْله ﴿سيء بهم وضاق بهم ذرعا﴾\",1,\"1:199\"],\"K-388\":[\"وَختم الْآيَة بقوله ﴿يتفكرون﴾ لِأَن الْفِكر يُؤَدِّي إِلَى الْوُقُوف على الْمعَانِي الَّتِي خُلِقْنَ لَهَا من التآنس والتجانس وَسُكُون كل وَاحِد مِنْهُمَا إِلَى الآخر\",0,\"1:202\"],\"K-389\":[\"وَختم بقوله ﴿للْعَالمين﴾ لِأَن الْكل تظلهم السَّمَاء وتقلهم الأَرْض وكل وَاحِد مُنْفَرد بلطيفة فِي صَوته يمتاز بهَا عَن غَيرهَا حَتَّى لَا ترى اثْنَيْنِ فِي ألف يتشابه صوتاهما ويلتبس كَلَامهمَا وَكَذَلِكَ ينْفَرد كل\",1,\"1:202\"],\"K-391\":[\"أَي انه يريكم وَقيل تَقْدِيره ويريكم من آيَاته الْبَرْق وَقيل أَن يريكم فَلَمَّا حذف ﴿إِن﴾ سكن الْيَاء وَقيل من آيَاته كَلَام كَاف كَمَا تَقول مِنْهَا كَذَا وَمِنْهَا كَذَا وَمِنْهَا وتسكت تُرِيدُ الْكَثْرَة\",0,\"1:203\"],\"K-397\":[\"﴿ثمَّ﴾ هَهُنَا تدل على الْإِعْرَاض عقب التَّذْكِير\",0,\"1:205\"],\"K-400\":[\"لَيْسَ غَيره لِأَنَّهُ لما ذكر الْقُرُون والمساكن بِالْجمعِ حسن جمع الْآيَات وَلما تقدم ذكر الْكتاب وَهُوَ مسموع حسن ذكر لفظ السماع فختم الْآيَة بِهِ\",0,\"1:205\"],\"K-407\":[\"بِالْفَاءِ لَيْسَ غَيره زيد الْحَرْف لِأَن الِاعْتِبَار فِيهَا بِالْمُشَاهَدَةِ على مَا ذَكرْنَاهُ وخصت بِالْفَاءِ لشدَّة اتصالها بِالْأولِ لِأَن الضَّمِير يعود إِلَى الَّذين قسموا الْكَلَام فِي النَّبِي ﷺ\",1,\"1:208\"],\"K-449\":[\"فِي هَذِه السُّورَة فَحسب لِأَن الْفِعْل لمُوسَى وَفِي سَائِر الْقُرْآن الْفِعْل للحق\",0,\"1:220\"],\"K-465\":[\"لَيْسَ لَهُ نَظِير وَالْمعْنَى تَعَالَى أَن يكلم أَو يتناهى حَكِيم فِي تَقْسِيم وُجُوه التكليم\",0,\"1:224\"],\"K-467\":[\"قد سبق\",0,\"1:224\"],\"K-474\":[\"أَي الْبَحْر وَقد سبق\",0,\"1:226\"],\"K-475\":[\"نزلت فِي الْيَهُود وَقد سبق\",0,\"1:226\"],\"K-476\":[\"قيل فِيهِ تَقْدِيم ﴿نموت﴾ وَتَأْخِير ﴿نحيا﴾ قيل يحيا الْبَعْض وَيَمُوت الْبَعْض وَقيل هُوَ كَلَام من يَقُول بالتناسخ\",0,\"1:226\"],\"K-479\":[\"تَعْظِيمًا لإدخال الله الْمُؤمنِينَ فِي رَحمته\",0,\"1:226\"],\"K-480\":[\"أَي لم يجْتَمع فِي الْقُرْآن همزتان مضمومتان فِي غَيرهَا\",0,\"1:226\"],\"K-481\":[\"نزل وَأنزل كِلَاهُمَا مُتَعَدٍّ وَقيل نزل للتعدي وَالْمُبَالغَة وَأنزل للتعدي وَقيل نزل دفْعَة مجموعا وَأنزل مُتَفَرقًا\",1,\"1:227\"],\"K-485\":[\"بِلَفْظ الْجمع وَلَيْسَ لَهُ نَظِير وَهُوَ خطاب للمضمرين فِي قَوْله ﴿لن تتبعونا﴾\",0,\"1:228\"],\"K-506\":[\"بِزِيَادَة ﴿هُوَ﴾ لِأَن ﴿بشراكم﴾ مُبْتَدأ وجنات خَبره ﴿تجْرِي من تحتهَا﴾ صفة لَهَا ﴿خَالِدين فِيهَا﴾ حَال ﴿ذَلِك﴾ إِشَارَة إِلَى مَا قبله و﴿هُوَ﴾ تَنْبِيه على عظم شَأْن الْمَذْكُور ﴿الْفَوْز الْعَظِيم﴾ خَبره\",0,\"1:233\"],\"K-512\":[\"بِالْفَاءِ لما فِيهِ من معنى التعقيب أَي بئس الْمصير مَا صَارُوا إِلَيْهِ وَهُوَ جَهَنَّم قَوْله ﴿من الله شَيْئا أُولَئِكَ﴾ بِغَيْر فَاء مُوَافقَة للجمل الَّتِي قبلهَا وموافقة لقَوْله ﴿أُولَئِكَ حزب الله﴾\",0,\"1:234\"],\"K-516\":[\"وَبعده ﴿تسرون إِلَيْهِم بالمودة﴾ الأول حَال من المخاطبين وَقيل أتلقون إِلَيْهِم والاستفهام مُقَدّر وَقيل خبر مُبْتَدأ أَي أَنْتُم تلقونَ وَالثَّانِي بدل من الأول على الْوُجُوه الْمَذْكُورَة\",1,\"1:235\"],\"K-526\":[\"ذكر الْجَمِيع بِغَيْر وَاو ثمَّ ختم بِالْوَاو فَقَالَ ﴿وأبكارا﴾ لِأَنَّهُ اسْتَحَالَ الْعَطف على ثيبات فعطفها على أول الْكَلَام وَيحسن الْوَقْف على ثيبيات لما اسْتَحَالَ عطف أَبْكَارًا عَلَيْهَا\",1,\"1:238\"],\"K-539\":[\"وَبعده ﴿فاقرؤوا مَا تيَسّر مِنْهُ﴾ لِأَن الأول فِي الْفَرْض وَقيل فِي النَّافِلَة وَقيل خَارج الصَّلَاة ثمَّ ذكر سَبَب التَّخْفِيف فَقَالَ ﴿علم أَن سَيكون مِنْكُم مرضى﴾ ثمَّ أَعَادَهُ\",1,\"1:242\"],\"K-557\":[\"وَفِي البروج ﴿فِي تَكْذِيب﴾ رَاعى فواصل الْآي مَعَ صِحَة اللَّفْظ وجودة الْمَعْنى قَوْله ﴿ذَلِك الْفَوْز الْكَبِير﴾ ذَلِك مُبْتَدأ والفوز خَبره وَالْكَبِير صفته وَلَيْسَ فِي الْقُرْآن نَظِير\",0,\"1:247\"],\"K-558\":[\"هَذَا تكْرَار وَتَقْدِيره مهل مهل مهل لكنه عدل فِي الثَّانِي إِلَى أَن أمْهل لِأَنَّهُ من أَصله وَبِمَعْنَاهُ كَرَاهَة التّكْرَار\",1,\"1:248\"],\"K-564\":[\"قيل هما رجلَانِ قدار ابْن سالف ومصدع بن يزدهر فَوحد لروى الْآيَة\",0,\"1:250\"],\"K-578\":[\"إِنَّه أَبُو جهل ﴿إِلَّا الَّذين آمنُوا﴾ أَبُو بكر ﴿وَعمِلُوا الصَّالِحَات﴾ عمر ﴿وَتَوَاصَوْا بِالْحَقِّ﴾ عُثْمَان ﴿وَتَوَاصَوْا بِالصبرِ﴾ على رضى الله عَن الْخُلَفَاء الْأَرْبَع وَلعن أَبَا جهل\",0,\"1:254\"],\"K-582\":[\"كرر لِأَن الثَّانِي بدل من\",1,\"1:255\"],\"I-116\":[\"والجواب أن يقال: الأول بالصرف أولى، والثاني بالامتناع منه أحق، لأنه في الأول ينحي به نحو الأب والأقربين من أولادهم في الكفر، وإذا قصد هذا القصد انصرف هذا الاسم.\",1,\"2:768\"],\"I-141\":[\"فالجواب عن ذلك من وجهين: أحدهما أن يقال: إن الفرقة التي قالت: كانوا ثلاثة كانت بعدها فرقتان أخريان، وكذلك الثانية التي قالت: خمسة سادسهم كلبهم، وأما السبعة فانتهت عندها العدة، وانقطعت بها القصة\",1,\"3:868\"],\"I-146\":[\"والجواب أن يقال: إن الثانية تعدّت إلى اسم، وهو قوله عز وجل: (نقبًا) فخفّ متعلقُها فاحتملت بأن يتمّ لفظها، فأمّا الأولى فإنها تعلّق مكانُ مفعولها بـ \\\"أن \\\" والفعل بعدها، وهي أربعة أشياء: أنْ، والفعل، والفاعل\",1,\"3:883\"],\"G-242\":[\"والجواب أنه يقال: أستطاع واستاع واسطاع، والأول الأصل، ثم يحذفون أحد الحرفين تخفيفًا، فجيء أولًا بالفعل مخففًا عند إرادة نفي قدرتهم على الظهور على السدّ والصعود فوقه\",1,\"2:323\"],\"G-329\":[\"ووجه ذلك، والله أعلم: أن المؤمنين هم الذين يودون نزول السورة، وطلبهم نزلوها إنما هو على ما اعتادوه جاريًا في غيرها من التنجيم وتفصيل النزول، فالملائم هنا عبارة التضعيف.\",1,\"2:443\"]}");
